#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the ConnectionState enum
typedef enum {
    DISCONNECTED,
    CONNECTING,
    ACTIVE,
    INACTIVE
} ConnectionState;

// Define the NetworkConnectionStatus structure
typedef struct {
    char ipAddress[16];
    int portNumber;
    ConnectionState connectionState;
    time_t lastActivityTimestamp;
} NetworkConnectionStatus;

// Initialize and maintain a dynamic list of NetworkConnectionStatus structures
void initializeNetworkConnections() {
    // Create a linked list to store connections
    typedef struct Node {
        NetworkConnectionStatus *connection;
        struct Node *next;
    } Node;

    Node *head = NULL;
    Node *current = NULL;

    // Load initial connections from external configuration file
    FILE *file = fopen("config.txt", "r");
    if (file) {
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            NetworkConnectionStatus *connection = (NetworkConnectionStatus *)malloc(sizeof(NetworkConnectionStatus));
            sscanf(line, "%15s %d %d", connection->ipAddress, &connection->portNumber, &connection->lastActivityTimestamp);
            connection->connectionState = DISCONNECTED;
            Node *node = (Node *)malloc(sizeof(Node));
            node->connection = connection;
            node->next = NULL;

            if (!head) {
                head = node;
                current = node;
            } else {
                current->next = node;
                current = node;
            }
        }
        fclose(file);
    }
}

// Add a new network connection
void addNetworkConnection(NetworkConnectionStatus *connection) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->connection = connection;
    node->next = NULL;

    if (!head) {
        head = node;
        current = node;
    } else {
        current->next = node;
        current = node;
    }
}

// Update the state of an existing network connection
void updateNetworkConnectionStatus(NetworkConnectionStatus *connection, ConnectionState state) {
    // Find and update the corresponding connection in the list
    Node *currentNode = head;
    while (currentNode && currentNode->connection != connection) {
        currentNode = currentNode->next;
    }

    if (currentNode) {
        currentNode->connection->connectionState = state;
        currentNode->connection->lastActivityTimestamp = time(NULL);
    }
}

// Retrieve the number of active connections
int getActiveConnectionCount() {
    int count = 0;
    Node *currentNode = head;
    while (currentNode) {
        if (currentNode->connection->connectionState == ACTIVE) {
            count++;
        }
        currentNode = currentNode->next;
    }
    return count;
}

// Demonstrate the system's functionality
int main() {
    initializeNetworkConnections();

    NetworkConnectionStatus *newConn1 = (NetworkConnectionStatus *)malloc(sizeof(NetworkConnectionStatus));
    strcpy(newConn1->ipAddress, "192.168.0.100");
    newConn1->portNumber = 8080;
    newConn1->connectionState = CONNECTING;

    addNetworkConnection(newConn1);

    NetworkConnectionStatus *newConn2 = (NetworkConnectionStatus *)malloc(sizeof(NetworkConnectionStatus));
    strcpy(newConn2->ipAddress, "192.168.0.101");
    newConn2->portNumber = 8081;
    newConn2->connectionState = ACTIVE;

    addNetworkConnection(newConn2);

    updateNetworkConnectionStatus(newConn1, ACTIVE);

    printf("Active connections: %d\n", getActiveConnectionCount());

    return 0;
}
