#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

Record **records = NULL;
long *offsets = NULL;
int *keys = NULL;
size_t record_size = 0;
size_t capacity = 0;
size_t current_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int init(size_t capacity_) {
    pthread_mutex_init(&lock, NULL);

    record_size = sizeof(Record);
    capacity = capacity_;
    current_size = 0;

    offsets = allocate(sizeof(long) * capacity_);
    keys = allocate(sizeof(int) * capacity_);
    records = allocate(record_size * capacity_);

    if (!offsets || !keys || !records) {
        return -1;
    }

    for (size_t i = 0; i < capacity_; i++) {
        Record* record = (Record*) (records + i);
        record->value = rand() % 100;
    }
    return 0;
}

void deinit() {
    pthread_mutex_destroy(&lock);

    free(offsets);
    free(keys);
    free(records);
}

int add_record(int key, long offset) {
    pthread_mutex_lock(&lock);

    if (current_size >= capacity) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    Record* record = (Record*) (records + current_size);
    record->value = rand() % 100;

    offsets[current_size] = offset;
    keys[current_size++] = key;

    pthread_mutex_unlock(&lock);

    return 0;
}

int get_record(int key) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < current_size; i++) {
        if (keys[i] == key) {
            Record* record = (Record*) (records + i);
            pthread_mutex_unlock(&lock);
            return record->value;
        }
    }

    pthread_mutex_unlock(&lock);
    return -1;
}
