#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

#define MAX_LINE_COUNT 1000000

typedef struct {
    int line_count;
} file_info;

int main(int argc, char **argv) {
    int verbose = 0;
    char *output_file = NULL;
    FILE *output_stream = NULL;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("Usage: %s [-v] [-o output_file] [input_files]\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
            i++;
        }
    }

    // Open output file
    if (output_file != NULL) {
        output_stream = fopen(output_file, "w");
        if (!output_stream) {
            perror("Failed to open output file");
            return 1;
        }
    } else {
        output_stream = stdout;
    }

    // Initialize line count aggregation data structure
    file_info *file_list = NULL;
    int num_files = 0;

    // Parse input files and concatenate their line counts
    for (int i = 1; i < argc; i++) {
        char *input_file = argv[i];

        if (strcmp(input_file, "-") == 0) {
            FILE *file_stream = stdin;
            file_info new_file;
            new_file.line_count = 0;

            // Read from stdin and update line count
            for (int j = 1; ; j++) {
                char line[MAX_LINE_COUNT];
                if (!fgets(line, sizeof(line), file_stream)) {
                    break;
                }
                new_file.line_count++;

                if ((j % 100 == 0) && verbose) {
                    printf("Processed %d lines.\n", j);
                }
            }

            // Add file info to the list
            file_list = realloc(file_list, sizeof(file_info) * (num_files + 1));
            file_list[num_files].line_count = new_file.line_count;
            num_files++;
        } else {
            int file_fd;
            struct stat file_stat;

            if ((file_fd = open(input_file, O_RDONLY)) == -1) {
                perror("Failed to open input file");
                return 1;
            }

            if (fstat(file_fd, &file_stat) == -1) {
                close(file_fd);
                perror("Failed to get file status");
                return 1;
            }

            file_info new_file;
            new_file.line_count = 0;

            // Map the input file into memory
            char *file_map = mmap(NULL, file_stat.st_size, PROT_READ, MAP_SHARED, file_fd, 0);
            if (file_map == MAP_FAILED) {
                close(file_fd);
                perror("Failed to map input file");
                return 1;
            }

            // Read from the mapped file and update line count
            for (int j = 1; ; j++) {
                char line[MAX_LINE_COUNT];
                if (!fgets(line, sizeof(line), file_map)) {
                    break;
                }
                new_file.line_count++;

                if ((j % 100 == 0) && verbose) {
                    printf("Processed %d lines.\n", j);
                }
            }

            // Unmap the input file
            munmap(file_map, file_stat.st_size);

            // Add file info to the list
            file_list = realloc(file_list, sizeof(file_info) * (num_files + 1));
            file_list[num_files].line_count = new_file.line_count;
            num_files++;
        }
    }

    // Print line count summary report
    if (output_stream != stdout) {
        fclose(stdout);
        dup2(fileno(output_stream), fileno(stdout));
    }

    for (int i = 0; i < num_files; i++) {
        fprintf(stdout, "File %s: %d lines\n", argv[i + 1], file_list[i].line_count);
    }

    // Close output stream
    if (output_file != NULL) {
        fclose(output_stream);
    }

    return 0;
}
