int find_largest_int(int* nums, int len, int case_sensitive) {
    int max_num = nums[0];
    for (int i = 1; i < len; i++) {
        if ((case_sensitive && nums[i] > max_num) || (!case_sensitive && (nums[i] <= 'z' && nums[i] >= 'a') && nums[i] > max_num)) {
            max_num = nums[i];
        }
    }
    return max_num;
}

void process_data(int sockfd, int max_size, char case_sensitive) {
    int* buffer = NULL;
    int len = 0;

    while (1) {
        // Read data from the network socket
        int bytes_read = read(sockfd, &len, sizeof(len));
        if (bytes_read < 0) {
            perror("read");
            return;
        }
        else if (bytes_read == 0) {
            break; // End of transmission
        }

        // Check if the received data exceeds the maximum size limit
        if (len > max_size) {
            printf("Received data is too large. Ignoring.\n");
            len = 0;
            continue;
        }

        // Dynamically allocate memory for the array of integers
        buffer = realloc(buffer, (len + len % 4 + 1) * sizeof(int));
        if (!buffer) {
            perror("realloc");
            return;
        }

        // Fill the buffer with the received data
        bytes_read = read(sockfd, buffer, len * sizeof(int));
        if (bytes_read < 0) {
            perror("read");
            free(buffer);
            return;
        }
        else if (bytes_read == 0) {
            break; // End of transmission
        }

        int max_num = find_largest_int(buffer, len, case_sensitive);
        printf("Largest integer: %d\n", max_num);

        // Reset the buffer for the next data chunk
        memset(buffer + len, 0, (max_size - len) * sizeof(int));
    }

    free(buffer);
}
