    char* message = malloc(len);
    if (!message) {
        // handle memory allocation failure here
        return -1;
    }

    va_start(args, format);
    vsnprintf(message, len, format, args);
    va_end(args);

    printf("%s\n", message); // log the message

    free(message);
    return 0; // successfully logged the message
