import hashlib
import os
import tqdm

def compute_sha256_hash(file_path, encoding='hex'):
    BLOCK_SIZE = 65536
    hash_object = hashlib.sha256()

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File '{file_path}' not found")

    try:
        with open(file_path, 'rb') as file:
            for chunk in tqdm.chunked_file_iterator(file, BLOCK_SIZE):
                hash_object.update(chunk)
    except OSError as e:
        print(f"Error reading file: {e}")
        return None

    return hash_object.hexdigest() if encoding == 'hex' else hash_object.encode('utf-8').decode('utf-8')

def chunked_file_iterator(file, block_size):
    while True:
        chunk = file.read(block_size)
        if not chunk:
            break
        yield chunk

