#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct _file {
    char* name;
    void* metadata;
    struct _file* next;
} File;

typedef struct {
    int size;
    int capacity;
    File** files;
} FileList;

FileList* file_list_create() {
    FileList* list = (FileList*) malloc(sizeof(FileList));
    if (!list) return NULL;
    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->files = (File**) calloc(list->capacity, sizeof(File*));
    if (!list->files) {
        free(list);
        return NULL;
    }
    return list;
}

void file_list_insert(FileList* list, File* file) {
    if (list->size == list->capacity) {
        // Increase capacity
        int new_capacity = list->capacity * 2;
        list->files = (File**) realloc(list->files, new_capacity * sizeof(File*));
        list->capacity = new_capacity;
    }
    // Check for duplicate file names
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(file->name, list->files[i]->name)) {
            free(file);
            return; // File with same name already exists
        }
    }
    list->files[list->size] = file;
    list->size++;
}

File* file_list_remove(FileList* list, char* name) {
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(name, list->files[i]->name)) {
            File* temp = list->files[i];
            // Shift files to the left and remove the last one
            memmove(&list->files[i], &list->files[i + 1], (list->size - i - 1) * sizeof(File*));
            list->size--;
            free(temp);
            return temp;
        }
    }
    return NULL; // File not found
}

FileList* file_list_query_by_name(FileList* list, char* name) {
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(name, list->files[i]->name)) {
            return list->files[i]; // Found a matching file
        }
    }
    return NULL; // File not found
}

// Cache invalidation mechanism
void file_list_invalidate_cache(FileList* list) {
    // Implement cache invalidation strategy here
}

// Example usage:
int main() {
    FileList* list = file_list_create();

    // Add files to the list
    File* file1 = (File*) malloc(sizeof(File));
    file1->name = "file1.mp4";
    file1->metadata = "Metadata 1";
    file_list_insert(list, file1);

    File* file2 = (File*) malloc(sizeof(File));
    file2->name = "file2.avi";
    file2->metadata = "Metadata 2";
    file_list_insert(list, file2);

    // Remove a file
    file_list_remove(list, "file1.mp4");

    // Query files by name
    File* found_file = file_list_query_by_name(list, "file2.avi");
    printf("File metadata: %s\n", (char*) found_file->metadata);

    return 0;
}
