package com.pokemon.service;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.CacheManager;
import org.springframework.cache.caffeine.CaffeineCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpMethod;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.pokemon.model.PokemonData;
import com.pokemon.util.ApiClient;
import com.pokemon.util.CachingStrategy;

@SpringBootApplication
@RestController
public class PokemonService {

    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final String API_ENDPOINT = "https://pokeapi.co/api/v2/pokemon/{id}/";
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Value("${pokemon.service.api-key}")
    private String apiKey;

    @Value("${pokemon.service.cache-time-to-live}")
    private long cacheTtl;

    private ConcurrentHashMap<String, PokemonData> pokemonCache;
    private ExecutorService executorService;
    private CacheManager cacheManager;

    public static void main(String[] args) {
        SpringApplication.run(PokemonService.class, args);
    }

    @Bean
    public CaffeineCacheManager caffeineCacheManager() {
        return new CaffeineCacheManager(CachingStrategy.getCacheName(), CachingStrategy.getCacheTtlSeconds());
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    }

    @GetMapping("/pokemon/{id}")
    public PokemonData getPokemonData(@PathVariable String id) throws Exception {
        ApiClient apiClient = new ApiClient(apiKey, API_ENDPOINT);

        try (PokemonData pokemonData = apiClient.fetchPokemonData(id)) {
            if (!pokemonData.isCached()) {
                // Cache the data for a specified time-to-live
                cacheManager.getCache(CachingStrategy.getCacheName()).put(CachingStrategy.getKey(id), pokemonData);
            }
            return pokemonData;
        } catch (Exception e) {
            // Handle errors and exceptions
            throw new Exception("Failed to fetch Pokémon data: " + e.getMessage());
        }
    }

}
