// Function to manage the pool of cipher objects
Cipher* managePool(const char* directory, pthread_mutex_t* mutex) {
    Cipher* pool[10];  // Allocate space for a limited number of cipher objects
    int count = 0;

    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char filePath[1024];
            sprintf(filePath, "%s/%s", directory, ent->d_name);

