            char** config = NULL;  // TO DO: implement loading and validation logic
            if (validateConfig(filePath, &config)) {
                Cipher* cipher = initCipher(filePath, config);
                pthread_mutex_lock(mutex);  // Acquire mutex for thread safety
                pool[count++] = cipher;
                pthread_mutex_unlock(mutex);  // Release mutex

                free(config);  // Free memory allocated for the configuration
            }
        }
        closedir(dir);
    }

    Cipher* head = NULL;
    Cipher* current = NULL;

    for (int i = 0; i < count; i++) {
