#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
public:
    Node* head;

    DoublyLinkedList() : head(nullptr) {}

    void insert(int val1, int val2);

    bool search(Node*& current, int target);
};

void DoublyLinkedList::insert(int val1, int val2) {
    if (head == nullptr) { // empty list
        Node* newNode = new Node;
        newNode->data = val2;
        head = newNode;
        return;
    }

    if (!sortList()) {
        cout << "Sorting failed. Cannot continue." << endl;
        return;
    }

    Node* current = head;
    while (current != nullptr) {
        if (search(current, val1)) {
            Node* temp = new Node;
            temp->data = val2;
            temp->next = current->next;
            temp->prev = current;
            current->next = temp;

            if (temp->next != nullptr)
                temp->next->prev = temp;
            else
                head = temp; // if inserted at the end

            return;
        }
        current = current->next;
    }

    // insert at the end, val1 not found
    Node* newNode = new Node;
    newNode->data = val2;
    newNode->next = nullptr;

    if (head == nullptr) {
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next != nullptr)
            temp = temp->next;
        temp->next = newNode;
        newNode->prev = temp;
    }
}

bool DoublyLinkedList::search(Node*& current, int target) {
    while (current != nullptr) {
        if (current->data == target)
            return true;
        current = current->next;
    }
    return false;
}

bool DoublyLinkedList::sortList() {
    Node* prev = nullptr;
    Node* current = head;

    if (head == nullptr)
        return true; // already sorted

    while (current != nullptr) {
        Node* next = current->next;
        while (next != nullptr && next->data < current->data) {
            int temp = next->data;
            Node* tempPrev = next->prev;

            next->prev = current->prev;
            current->prev = next;

            next->next = current;
            current->next = next;

            next = tempPrev != nullptr ? tempPrev->next : nullptr;
        }
        current = next;
    }
    return true;
}
