using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using RabbitMQ.Client;
using RabbitMQ.Client.Exchange;

public class TransactionProcessor
{
    private readonly IConnection _connection;
    private readonly Func<Transaction, Task<PaymentResponse>> _paymentGateway;

    public TransactionProcessor(IConnection connection, Func<Transaction, Task<PaymentResponse>> paymentGateway)
    {
        _connection = connection;
        _paymentGateway = paymentGateway;
    }

    public async Task<BatchProcessingResult> ProcessTransactions(List<Transaction> transactions)
    {
        var results = new List<PaymentResponse>();
        var batchResults = new BatchProcessingResult();

        // Asynchronously enqueue each transaction
        var tasks = transactions.Select(async transaction =>
        {
            await _connection.BasicPublish(exchange: "transactions", routingKey: transaction.Id, body: Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(transaction)));

            try
            {
                var paymentResponse = await _paymentGateway(transaction);
                results.Add(paymentResponse);

                if (paymentResponse.IsSuccess)
                {
                    batchResults.SuccessCount++;
                }
                else
                {
                    batchResults.FailedTransactions.Add(transaction.Id);
                }
            }
            catch (Exception ex) when (!ex.IsTransientError())
            {
                // Handle non-transient errors gracefully
                batchResults.ErrorCount++;
            }
        });

        await Task.WhenAll(tasks);

        return batchResults;
    }

    public class BatchProcessingResult
    {
        public int SuccessCount { get; set; }
        public List<string> FailedTransactions { get; set; } = new List<string>();
        public int ErrorCount { get; set; }
    }
}
