public bool ProcessXmlAndSetupEnvironment(string xmlFile, string elementName)
{
    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.Load(xmlFile);
    XmlElement xPathQuery = xmlDoc.CreateElement("query");
    XmlNodeList nodeList = xmlDoc.SelectNodes("//" + elementName);

    if (nodeList.Count != 1)
    {
        System.Diagnostics.Logger.LogError("Failed to find exactly one element with name " + elementName);
        return false;
    }

    string directoryName = nodeList[0].InnerText;

    try
    {
        Directory.CreateDirectory(directoryName);
    }
    catch (Exception e)
    {
        System.Diagnostics.Logger.LogWarning("Failed to create directory: " + e.Message);
    }

    if (!Environment.GetEnvironmentVariable("PROCESS_PATH").Equals(directoryName))
    {
        Environment.SetEnvironmentVariable("PROCESS_PATH", directoryName);
    }

    return true;
}']

