import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.codec.digest.DigestUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationListener;
import org.springframework.context.event.ContextRefreshEvent;
import org.springframework.core.io.Resource;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.concurrent.atomic.AtomicLong;

@RestController
public class Md5Service {

    private final ObjectMapper mapper = new ObjectMapper();
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final CopyOnWriteArraySet<String> recentRequests = new CopyOnWriteArraySet<>();
    private final AtomicLong requestCount = new AtomicLong();

    @Autowired
    private ApplicationListener<ContextRefreshEvent> refreshEventListener;

    @PostMapping("/md5")
    public JsonNode processMd5Request(@RequestBody String json) throws IOException {
        long start = System.currentTimeMillis();
        try {
            JsonNode inputJson = mapper.readTree(json);
            String inputString = inputJson.asText();

            if (inputString.length() > 1024) {
                return mapper.createObjectNode().put("error", "Input string exceeds 1024 characters");
            }

            String md5Hash = DigestUtils.md5Hex(inputString);

            cache.put(md5Hash, json);
            recentRequests.add(md5Hash);
            if (recentRequests.size() > 1000) {
                recentRequests.remove(recentRequests.poll());
            }
            requestCount.incrementAndGet();

            return mapper.createObjectNode().put("md5", md5Hash)
                    .put("processingTime", System.currentTimeMillis() - start);
        } catch (Exception e) {
            refreshEventListener.onApplicationEvent(new ContextRefreshEvent(null));
            return mapper.createObjectNode().put("error", "Error processing request: " + e.getMessage());
        }
    }

    @PostMapping("/clear-cache")
    public JsonNode clearCache(@RequestBody Map<String, Object> params) {
        cache.clear();
        recentRequests.clear();
        return mapper.createObjectNode().put("message", "Cache cleared successfully");
    }
}
