const fs = require('fs');
const path = require('path');
const { validate } = require('jsonschema');

class FileProcessor {
  constructor(schema) {
    this.schema = schema;
    this.cache = {};
  }

  async processFiles(directory, callback) {
    const files = await this.getFiles(directory);
    const results = [];

    for (const file of files) {
      try {
        const data = JSON.parse(await fs.readFile(file.path));
        if (!this.cache[file.path]) {
          this.cache[file.path] = true; // cache the processed file
        }
        const result = validate(data, this.schema);
        if (!result.errors.length) {
          results.push({ file: file.name, data: data });
        } else {
          console.error(`Invalid JSON in ${file.name}:`, result.errors);
        }
      } catch (error) {
        console.error(`Error processing ${file.name}:`, error);
      }
    }

    callback(results);
  }

  async getFiles(directory) {
    const files = [];
    const readDir = await fs.promises.readdir(directory);
    for (const file of readDir) {
      if (path.extname(file) === '.json') {
        const filePath = path.join(directory, file);
        files.push({ name: file, path: filePath });
      }
    }
    return files;
  }
}

module.exports = FileProcessor;
