const { Worker } = require('worker_threads');
const blueSlip = require('blueslip');
const { performance } = require('perf_hooks');
const log = console.log;
const monitoringSystem = require('monitoring-system');

function testModule(label, f, concurrencyLevel) {
  concurrencyLevel = concurrencyLevel || 5;

  function runTest(testName) {
    const worker = new Worker(`
      try {
        ${require.toString()}.call(null, 'module');
        ${f.toString()}();
      } catch (error) {
        console.error(error);
      } finally {
        blueSlip.reset();
      }
    `, {
      stdio: ['ipc']
    });

    worker.on('message', () => {
      performance.clearMarks();
      performance.clearMeasurements();
      performance.clearObservers();
    });
  }

  function runTests() {
    const tests = [];
    for (let i = 0; i < concurrencyLevel; i++) {
      tests.push(runTest(`test ${i + 1}`));
    }
    return tests;
  }

  function monitorTests() {
    monitoringSystem.report('test suite started');
    performance.mark('start');
    runTests();
    performance.mark('end');
    console.log({
      start: performance.getMarkers().start,
      end: performance.getMarkers().end
    });
  }

  function testSuite(label, f) {
    log(`Testing ${label}`);
    try {
      const tests = runTests();
      performance.mark('start');
      for (const test of tests) {
        test.then(() => {
          performance.mark('done');
        }).catch((error) => {
          console.error(error);
          performance.mark('failed');
        });
      }
      performance.measure('test suite', 'start', 'end');
      monitoringSystem.report('test suite completed');
    } catch (error) {
      console.error(error);
      performance.mark('failed');
    }
  }

  testSuite(label, f);
}

