const fs = require('fs');
const natural = require('natural');
const sentiment = require('sentiment');

function processFeedbackDocument(text, sensitivityLevel = 0.5) {
  const posRe = /\b(great|love|awesome)\b/i;
  const reqRe = /\b(would|should|can't)\b/i;
  const issueRe = /\b(bug|issue|problem)\b/i;

  const tokenizer = new natural.WordPlex(text, 'ltr');
  const tokens = tokenizer.tokenize();

  let positiveFeedback = [];
  let featureRequests = [];
  let issues = [];

  for (const token of tokens) {
    if (sensitivityLevel >= 0.5 && posRe.test(token)) {
      positiveFeedback.push(token);
    } else if (reqRe.test(token)) {
      featureRequests.push(token);
    } else if (issueRe.test(token)) {
      issues.push(token);
    }
  }

  const sentimentResult = sentiment.analyze(text);
  if (sentimentResult.score > 0.5) {
    positiveFeedback.push('Overall Sentiment: Positive');
  } else if (sentimentResult.score < -0.5) {
    issues.push('Overall Sentiment: Negative');
  } else {
    featureRequests.push('Overall Sentiment: Neutral');
  }

  return { positiveFeedback, featureRequests, issues };
}

module.exports = processFeedbackDocument;
