function generateFooterScripts(scripts) {
  const footer = document.createElement('footer');
  let dependencies = {};

  scripts.forEach(script => {
    if (script.dependencies) {
      script.dependencies.forEach(dep => {
        dependencies[dep] = (dependencies[dep] || []).concat(script.id);
      });
    }

    const scriptTag = document.createElement('script');
    scriptTag.src = generateScriptSrc(script);
    footer.appendChild(scriptTag);
  });

  return footer.outerHTML;
}

function generateScriptSrc(script) {
  let src = `${script.type}://${script.code}`;

  if (script.dependencies) {
    src += '?';
    script.dependencies.forEach(dep => src += `${dep}=1&`);
  }

  return src;
}
