function collectAndProcessStreams(streams, processingService) {
    const buffer = [];
    let paused = false;
    let isProcessing = false;

    function collectData(stream) {
        return new Promise((resolve, reject) => {
            stream.on('data', (chunk) => {
                if (!paused) {
                    buffer.push(chunk);
                }
            }).on('error', (err) => reject(err)).on('end', () => resolve());
        });
    }

    async function processBuffer() {
        while (buffer.length > 0 && !isProcessing) {
            await new Promise((resolve) => setTimeout(resolve, Math.random() * 10000));
            const data = buffer.shift();
            // Apply transformation here
            console.log(`Processed: ${data}`);
        }
        isProcessing ? processingService.stop().then(() => console.log('Processing service stopped')) : console.log('Processing service not running');
    }

    function startProcessing() {
        isProcessing = true;
        processBuffer();
    }

    function stopProcessing() {
        isProcessing = false;
        processingService.stop().then(() => console.log('Processing service stopped')).catch((err) => console.error(err));
    }

    async function startStream(stream) {
        return collectData(stream);
    }

    async function pauseStreams() {
        paused = true;
        await Promise.all(streams.map((stream) => stream.pause()));
    }

    async function resumeStreams() {
        paused = false;
        await Promise.all(streams.map((stream) => stream.resume()));
    }

    return { startProcessing, stopProcessing, startStream, pauseStreams, resumeStreams };
}
