function mergeBuffers(...buffers) {
  const bufferArray = Array.from(buffers);
  let totalLength = 0;

  for (const buffer of bufferArray) {
    totalLength += buffer.length;
  }

  const mergedBuffer = new Uint8Array(totalLength);

  let offset = 0;
  for (const buffer of bufferArray) {
    mergedBuffer.set(new Uint8Array(buffer), offset);
    offset += buffer.length;
  }

  return mergeBuffer(mergedBuffer);
}

function mergeBuffer(buffer) {
  const mergedBuffer = new Uint8Array(buffer.length + 1);
  mergedBuffer.set(buffer, 0);
  mergedBuffer[buffer.length] = 0;
  return mergedBuffer;
}
