import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEndOfWord;
}

public class UniqueStringPairsFinder {

    private static final int BATCH_SIZE = 10000;

    public long findUniquePairs(List<String> batch) {
        long startTime = System.currentTimeMillis();
        TrieNode root = new TrieNode();

        for (String str : batch) {
            TrieNode node = root;
            for (char c : str.toCharArray()) {
                if (!node.children.containsKey(c)) {
                    node.children.put(c, new TrieNode());
                }
                node = node.children.get(c);
            }
            node.isEndOfWord = true;
        }

        long endTime = System.currentTimeMillis();
        logProcessingTime(endTime - startTime);

        int uniquePairsCount = 0;

        for (String str1 : batch) {
            TrieNode node1 = root;
            for (char c : str1.toCharArray()) {
                if (!node1.children.containsKey(c)) {
                    break;
                }
                node1 = node1.children.get(c);
            }

            if (node1.isEndOfWord) {
                continue; // skip this string
            }

            for (String str2 : batch) {
                if (str1.equals(str2)) {
                    continue; // skip duplicates
                }

                TrieNode node2 = root;
                boolean isSubstring = false;

                for (char c : str2.toCharArray()) {
                    if (!node2.children.containsKey(c)) {
                        break;
                    }
                    node2 = node2.children.get(c);

                    if (node1 == node2) {
                        // one string is a substring of the other
                        isSubstring = true;
                        break;
                    }

                    if (node2.isEndOfWord) {
                        // str2 is a substring of another string in the batch
                        isSubstring = true;
                        break;
                    }
                }

                if (!isSubstring) {
                    uniquePairsCount++;
                }
            }
        }

        return uniquePairsCount;
    }

    private void logProcessingTime(long timeInMs) {
        System.out.println("Batch processing took " + timeInMs + " milliseconds.");
    }
}
