use std::sync::{Arc, Mutex};
use std::thread;
use tokio::net::TcpStream;
use tokio::time;

mod client {
    use reqwest::{blocking::get, post};
    use log::info;

    pub async fn get(url: &str) -> Result<String, reqwest::Error> {
        let response = get(url).await?;
        Ok(response.text().await?)
    }

    pub async fn post(url: &str, body: String) -> Result<String, reqwest::Error> {
        let response = post(url)
            .body(body)
            .send()
            .await?
        .text()
        .await?;
        Ok(response)
    }
}

mod client_async {
    use reqwest::{get, post};
    use tokio::time;

    pub async fn get(url: &str) -> Result<String, reqwest::Error> {
        let response = get(url).send().await?;
        Ok(response.text().await?)
    }

    pub async fn post(url: &str, body: String) -> Result<String, reqwest::Error> {
        let response = post(url)
            .body(body)
            .send()
            .await?
        .text()
        .await?;
        Ok(response)
    }
}

mod retry {
    use std::time::{Duration, Instant};
    use futures::future;

    pub async fn retry<T>(f: T) -> Result<T::Output, Box<dyn std::error::Error>>
    where
        T: Fn() -> Result<T::Output, Box<dyn std::error::Error>>,
    {
        let mut delay = Duration::from_millis(100);
        loop {
            match f().await {
                Ok(result) => return Ok(result),
                Err(err) => {
                    if delay.as_secs() > 3600 {
                        return Err(err.into());
                    }
                    thread::sleep(delay);
                    delay *= 2;
                }
            }
        }
    }

    pub async fn retry_with_backoff<T>(max_attempts: u32, f: T) -> Result<T::Output, Box<dyn std::error::Error>>
    where
        T: Fn() -> Result<T::Output, Box<dyn std::error::Error>>,
    {
        let mut attempts = 0;
        loop {
            match f().await {
                Ok(result) => return Ok(result),
                Err(err) => {
                    if attempts >= max_attempts {
                        return Err(err.into());
                    }
                    thread::sleep(time::sleep(std::time::Duration::from_millis(100)).await);
                    attempts += 1;
                }
            }
        }
    }
}

mod rate_limiter {
    use std::sync::{Arc, Mutex};
    use tokio::time;

    pub struct RateLimiter {
        limit: u32,
        remaining: u32,
        reset_time: time::Instant,
    }

    impl RateLimiter {
        pub fn new(limit: u32) -> Self {
            RateLimiter {
                limit,
                remaining: limit,
                reset_time: time::Instant::now(),
            }
        }

        async fn check(&mut self) -> Result<(), Box<dyn std::error::Error>> {
            if self.remaining > 0 {
                self.remaining -= 1;
                Ok(())
            } else if let Some(diff) = self.reset_time.elapsed().as_millis() % (1000 * 60) {
                thread::sleep(time::sleep(std::time::Duration::from_millis(diff)).await);
                self.remaining = self.limit - 1;
                self.reset_time = time::Instant::now();
            } else {
                Err("Rate limit exceeded".into())
            }
        }

        pub async fn acquire(&mut self) -> Result<(), Box<dyn std::error::Error>> {
            while let Err(err) = self.check().await {
                return Err(err);
            }
            Ok(())
        }
    }
}

pub mod config {
    use serde::{Deserialize, Serialize};

    #[derive(Debug, Deserialize, Serialize)]
    pub struct ClientConfig {
        timeout: u64,
        retries: u32,
        backoff_time: u64,
        rate_limit: Option<u32>,
        logging_level: log::Level,
    }

    impl Default for ClientConfig {
        fn default() -> Self {
            ClientConfig {
                timeout: 3000,
                retries: 3,
                backoff_time: 1000,
                rate_limit: Some(5),
                logging_level: log::info(),
            }
        }
    }
}

pub mod logger {
    use log::{info, warn};
    use tokio::log;

    pub fn init() {
        let mut logger = log::SimpleLogger::new(log::LevelFilter::Info);
        if let Err(err) = logger.set_logger() {
            warn!("Failed to set up logger: {}", err);
        }
    }

    pub fn log_request_info(method: &str, url: &str, result: Result<String, reqwest::Error>) {
        match result {
            Ok(response) => info!("{} request to {} successful. Response: {}", method, url, response),
            Err(err) => warn!("{} request to {} failed with error: {}", method, url, err),
        }
    }

    pub fn log_retry_info(method: &str, url: &str, attempt: u32, max_attempts: u32) {
        if attempt < max_attempts {
            info!("{} request to {} retried. Attempt {}/{}", method, url, attempt + 1, max_attempts);
        } else {
            warn!("Maximum retries reached for {} request to {}. Giving up.", method, url);
        }
    }

    pub fn log_rate_limit_info(url: &str) {
        info!("Rate limit exceeded for {}", url);
    }
}

pub mod client_impl {
    use std::sync::{Arc, Mutex};
    use reqwest;
    use tokio::time;

    pub struct ClientImpl {
        config: Arc<Mutex<config::ClientConfig>>,
        rate_limiter: Option<Arc<Mutex<rate_limiter::RateLimiter>>>,
        logger: log::Level,
    }

    impl ClientImpl {
        pub async fn get(&self, url: &str) -> Result<String, reqwest::Error> {
            let config = self.config.clone();
            let rate_limiter = self.rate_limiter.as_ref().map(|rate_limiter| rate_limiter.clone());
            let logger = self.logger;
            let mut attempts = 0;

            loop {
                if let Some(rate_limiter) = &mut rate_limiter {
                    rate_limiter.acquire().await?;
                }

                match client::get(url).await {
                    Ok(response) => return Ok(response),
                    Err(err) => {
                        if attempts >= config.get().retries {
                            warn!("Maximum retries reached for GET request to {}. Giving up.", url);
                            return Err(err.into());
                        }
                        info!("GET request to {} failed. Retrying...", url);
                        thread::sleep(time::sleep(std::time::Duration::from_millis(100)).await);
                        attempts += 1;
                    }
                }
            }
        }

        pub async fn post(&self, url: &str, body: String) -> Result<String, reqwest::Error> {
            let config = self.config.clone();
            let rate_limiter = self.rate_limiter.as_ref().map(|rate_limiter| rate_limiter.clone());
            let logger = self.logger;
            let mut attempts = 0;

            loop {
                if let Some(rate_limiter) = &mut rate_limiter {
                    rate_limiter.acquire().await?;
                }

                match client::post(url, body).await {
                    Ok(response) => return Ok(response),
                    Err(err) => {
                        if attempts >= config.get().retries {
                            warn!("Maximum retries reached for POST request to {}. Giving up.", url);
                            return Err(err.into());
                        }
                        info!("POST request to {} failed. Retrying...", url);
                        thread::sleep(time::sleep(std::time::Duration::from_millis(100)).await);
                        attempts += 1;
                    }
                }
            }
        }

        pub async fn new(config: config::ClientConfig) -> Self {
            let client_config = Arc::new(Mutex::new(config));
            let rate_limiter = if let Some(limit) = config.rate_limit {
                Some(Arc::new(Mutex::new(rate_limiter::RateLimiter { limit, remaining: limit, reset_time: time::Instant::now() })))
            } else {
                None
            };
            Self {
                config,
                rate_limiter,
                logger: log::Level::Info,
            }
        }
    }

    impl Drop for ClientImpl {
        fn drop(&mut self) {
            if let Some(rate_limiter) = &self.rate_limiter {
                *rate_limiter.lock().unwrap() = rate_limiter::RateLimiter { limit: 0, remaining: 0, reset_time: time::Instant::now() };
            }
        }
    }
}
