use std::process::{Command, Stdio};
use std::fs;
use std::env;

struct Logger {
    enabled: bool,
}

impl Logger {
    fn new() -> Self {
        let enabled = env::var("LOG_ENABLED").is_ok();
        Logger { enabled }
    }

    fn log(&self, msg: &str) {
        if self.enabled {
            println!("{}", msg);
        }
    }

    fn error(&self, err: &std::io::Error) {
        if self.enabled {
            println!("Error: {}", err);
        }
    }
}

fn compile_crate(crate_name: &str, config: &str) -> i32 {
    let mut logger = Logger::new();

    match Command::new("rustc")
        .arg("--crate-name")
        .arg(crate_name)
        .arg("-o")
        .arg(format!("{}-compiled", crate_name))
        .arg(config)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
    {
        Ok(output) => {
            let exit_code = output.status().as_raw_union();
            logger.log(&format!("Compilation exited with code {}", exit_code));
            exit_code as i32
        }
        Err(err) => {
            logger.error(&err);
            -1
        }
    }
}

fn main() {
    // usage example:
    let crate_name = "my_crate";
    let config = "--out-dir ./compiled --opt-level 3";
    println!("{}", compile_crate(crate_name, config));
}
