import requests
import logging
from functools import wraps
from time import sleep
from cachetools import TTLCache, cached

logging.basicConfig(level=logging.INFO)

API_URL = 'https://api.example.com'
API_KEY = 'your_api_key'

@cached(TTLCache(maxsize=1000, ttl=60))  # implement caching with TTL
def get_user_profile(user_id: int, api_key: str) -> dict:
    def retry(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(3):  # retry up to 3 times on failure
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RequestException as e:
                    logging.error(f'API request failed: {e}')
                    if _ >= 2:  # permanent failure, raise exception
                        raise
                    sleep(1)  # wait for a second before retrying
            return {}  # return empty dict on permanent failure

        return wrapper

    @retry
    def api_request(user_id: int, api_key: str) -> dict:
        headers = {'API-Key': api_key}
        response = requests.get(f'{API_URL}/users/{user_id}', headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            raise requests.exceptions.RequestException('API request failed')

    user_data = api_request(user_id, api_key)
    if not user_data:
        return {}
    # validate and process user data here
    return user_data

def main():
    try:
        profile = get_user_profile(123, API_KEY)  # replace with actual user ID
        print(profile)
    except requests.exceptions.RequestException as e:
        logging.error(f'Failed to retrieve user profile: {e}')

if __name__ == '__main__':
    main()
