const fs = require('fs');
const path = require('path');

function readConfigFile(filename) {
    try {
        const configBuffer = fs.readFileSync(path.join(__dirname, '..', filename));
        const configFile = JSON.parse(configBuffer.toString());
        // caching mechanism to reduce repeated reads
        const cacheKey = `config:${filename}`;
        if (window[cacheKey]) {
            return window[cacheKey];
        }
        window[cacheKey] = configFile;
        return configFile;
    } catch (err) {
        console.error(`Error reading config file: ${err}`);
        // log error without exposing sensitive information
        return null;
    }
}

module.exports = readConfigFile;
