["```
function fetchAndCombineCerts(oauthRequest) {
  const { privateKeyUrl, certificateUrl, retries = 3 } = oauthRequest;

  async function getCertFromUrl(url) {
    return new Promise((resolve, reject) => {
      const client = new XMLHttpRequest();
      client.open('GET', url);
      client.onload = () => {
        if (client.status === 200) resolve(client.responseText);
        else reject(new Error(`Failed to retrieve certificate from ${url}`));
      };
      client.onerror = () => reject(new Error(`Network error while retrieving certificate from ${url}`));
      client.send();
    });
  }

  async function combineCerts(privateKey, cert1, cert2) {
    return `-----BEGIN CERTIFICATE-----
${cert1}
-----END CERTIFICATE-----
-----BEGIN CERTIFICATE-----
${cert2}
-----END CERTIFICATE-----
-----BEGIN RSA PRIVATE KEY-----
${privateKey}
-----END RSA PRIVATE KEY-----`;
  }

  async function fetchAndCombine() {
    try {
      const privateKey = await getCertFromUrl(privateKeyUrl);
      const cert1 = await getCertFromUrl(certificateUrl);
      const combinedCerts = await combineCerts(privateKey, cert1, cert1); // assume same certificate for simplicity
      return combinedCerts;
    } catch (error) {
      if (retries > 0 && error.name === 'NetworkError') {
        console.log(`Retrying failed operation: ${error.message}`);
        return new Promise((resolve, reject) => setTimeout(() => fetchAndCombine().then(resolve).catch(reject), Math.pow(2, retries--) * 1000));
      }
      console.error(error);
      return Promise.reject(error);
    }
  }

  return fetchAndCombine();
}
