#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16

typedef struct {
    int timeout;
    int retries;
} dns_config;

dns_config* get_dns_config();

int resolve_hostname(char* hostname, char** ip_address) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return -1; // error creating socket
    }

    struct hostent* host;
    host = gethostbyname(hostname);
    if (!host) {
        close(sockfd); // release resources
        return -2; // error resolving hostname
    }

    *ip_address = (char*)malloc(MAX_IP_ADDRESS);
    sprintf(*ip_address, "%s", inet_ntoa(*((struct in_addr*)host->h_addr)));

    close(sockfd);

    return 0; // success
}

int main() {
    char* hostname = "example.com";
    char* ip_address;
    if (resolve_hostname(hostname, &ip_address) != 0) {
        printf("Error resolving %s: %d\n", hostname, resolve_hostname(hostname, NULL));
    } else {
        printf("%s resolved to %s\n", hostname, ip_address);
    }

    free(ip_address);

    return 0;
}

dns_config* get_dns_config() {
    dns_config* config = (dns_config*)malloc(sizeof(dns_config));
    config->timeout = 100; // default timeout in milliseconds
    config->retries = 3;   // default number of retries

    return config;
}
