#include <stdlib.h>
#include <string.h>

typedef struct State {
    int value;
    struct State* next;
    int ref_count;
} State;

State* create_state(int value) {
    State* state = (State*)malloc(sizeof(State));
    if (!state) {
        return NULL;
    }
    state->value = value;
    state->next = NULL;
    state->ref_count = 1;
    return state;
}

void free_state(State** state) {
    if (*state) {
        (*state)->ref_count--;
        if ((*state)->ref_count == 0) {
            free(*state);
            *state = NULL;
        }
    }
}

State* create_linked_list(int* states, int num_states, FSA* fsa, int last_state) {
    State* head = NULL;
    State* current = NULL;
    for (int i = 0; i < num_states; i++) {
        if (!fsa->states[i]) continue;
        State* state = create_state(states[i]);
        if (!state) return NULL;
        if (!head) {
            head = state;
            current = head;
        } else {
            current->next = state;
            current = current->next;
        }
    }
    return head;
}
