class GameCharacter {
public:
    enum class Attack { ATTACK1, ATTACK2 };

    void selectAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        if (cooldown_[Attack::ATTACK1] <= now && resourceAvailable_) {
            attack_ = Attack::ATTACK1;
            cooldown_[attack_] = now + 9;
            log_(std::cout << "Attack: ATTACK1\n");
        } else if (cooldown_[Attack::ATTACK2] <= now && resourceAvailable_) {
            attack_ = Attack::ATTACK2;
            cooldown_[attack_] = now + 9;
            log_(std::cout << "Attack: ATTACK2\n");
        } else {
            // No attack available, skip this turn
        }
    }

    void updateCooldown() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cooldown_.find(attack_) != cooldown_.end()) {
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            if (cooldown_[attack_] <= now) {
                cooldown_.erase(attack_);
            }
        }
    }

private:
    Attack attack_;
    std::map<Attack, double> cooldown_;
    bool resourceAvailable_ = true;
    std::mutex mutex_;

    template <typename T>
    void log_(T&& msg) {
        // Implement logging mechanism to track frequency of each attack used and resource consumption
    }
};

