using System;
using System.Collections.Concurrent;
using System.Threading;

public class RandomValueGeneratorService
{
    private readonly ConcurrentDictionary<string, RandomValueGenerator> _generators = new();
    private readonly object _lock = new();
    private readonly int _maxGenerationsPerSecond;

    public RandomValueGeneratorService(int maxGenerationsPerSecond)
    {
        _maxGenerationsPerSecond = maxGenerationsPerSecond;
    }

    public void AddGenerator(string generatorName, int seed = 0)
    {
        lock (_lock)
        {
            if (_generators.TryGetValue(generatorName, out var generator))
                throw new InvalidOperationException("Generator already exists.");
            _generators[generatorName] = new RandomValueGenerator(seed);
        }
    }

    public void RemoveGenerator(string generatorName)
    {
        lock (_lock)
        {
            _generators.TryRemove(generatorName, out _);
        }
    }

    public void ResetGenerator(string generatorName)
    {
        lock (_lock)
        {
            if (_generators.TryGetValue(generatorName, out var generator))
                generator.Reset();
        }
    }

    public int GenerateInt(string generatorName, int min, int max)
    {
        lock (_lock)
        {
            return _generators[generatorName].GenerateInt(min, max);
        }
    }

    public float GenerateFloat(string generatorName, float min, float max)
    {
        lock (_lock)
        {
            return _generators[generatorName].GenerateFloat(min, max);
        }
    }

    public double[] GenerateStats(string generatorName, int count)
    {
        lock (_lock)
        {
            var values = new double[count];
            for (int i = 0; i < count; i++)
                values[i] = _generators[generatorName].GenerateFloat(0f, 1f);
            return values;
        }
    }

    public void MonitorAndLog(string generatorName)
    {
        lock (_lock)
        {
            var generator = _generators[generatorName];
            // Implement logging and monitoring logic here
        }
    }

    private class RandomValueGenerator
    {
        private readonly Random _random;

        public RandomValueGenerator(int seed)
        {
            _random = new Random(seed);
        }

        public void Reset()
        {
            _random.Next();
        }

        public int GenerateInt(int min, int max)
        {
            return _random.Next(min, max + 1);
        }

        public float GenerateFloat(float min, float max)
        {
            return (float)_random.NextDouble() * (max - min) + min;
        }
    }
}
