async function reduceStreams(streams) {
  const results = [];

  for (const stream of streams) {
    let sum = 0;
    let errors = 0;

    const promises = [];
    for (const item of stream) {
      if (typeof item === 'number') {
        promises.push(new Promise((resolve, reject) => {
          setTimeout(() => {
            sum += item;
            resolve();
          }, 1);
        }));
      } else {
        errors++;
      }
    }

    const timeout = new Promise((resolve, reject) => {
      setTimeout(() => {
        if (promises.length > 0) {
          promises.forEach(p => p.reject(new Error('Timeout')));
        }
        resolve();
      }, 5000);
    });

    await Promise.all([...promises, timeout]);

    results.push({ sum: sum, errors: errors });
  }

  return Promise.all(results.map(result => {
    if (result.errors > 0) {
      throw new Error(`Error processing stream with ${result.errors} non-numeric items`);
    } else {
      return result;
    }
  }));
}
