#include <stdlib.h>
#include <string.h>

char* expandPathWithSlash(char* path, int maxLength, int strictMode) {
    if (*path == '\0' || strlen(path) <= 1) return strdup(path);
    if (strlen(path) > 0 && path[strlen(path)-1] == '/' && !strictMode) return strdup(path);
    char* result = malloc((maxLength > 0 ? maxLength : 128));
    int len = 0;
    for (int i = 0; i < strlen(path); i++) {
        if (path[i] != '/') continue;
        len += path[i+1] == '/' ? 2 : 1;
        if (len >= maxLength - 1) break;
        if (i < strlen(path) - 1 && path[i+1] == '/') i++;
    }
    memcpy(result, path, len);
    result[len] = '\0';
    free(path);
    return result;

    if (strlen(path) + 1 > maxLength) {
        char* truncatedPath = malloc(maxLength);
        int j = 0;
        for (int i = 0; i < strlen(path); i++) {
            truncatedPath[j++] = path[i];
            if (j >= maxLength - 1) break;
        }
        truncatedPath[j] = '\0';
        free(result);
        return truncatedPath;
    }

    if (!strictMode && path[strlen(path)-1] != '/') {
        char* appendedPath = malloc(strlen(path) + 2);
        memcpy(appendedPath, path, strlen(path));
        appendedPath[strlen(path)] = '/';
        appendedPath[strlen(path)+1] = '\0';
        free(result);
        return appendedPath;
    }

    return strdup(path);
}
