#define MAX_LINE_LENGTH 1024
#define CACHE_DIR "cache"

void process_file(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) return;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        int num_fields = 0;
        double sum = 0.0;

        char* token = strtok(line, ", ");
        while (token && ++num_fields < 2) {
            if (!strpbrk(token, ".0123456789-+")) continue; // skip non-numerical fields
            sum += atof(token);
            token = strtok(NULL, ", ");
        }

        if (num_fields >= 2) {
            double avg = sum / num_fields;
            printf("%.2f\n", avg);
        } else {
            printf("Invalid data type or fewer than two numerical fields.\n");
        }

        free(line); // dynamically allocated memory for each line
    }

    fclose(file);
}

int main() {
    DIR* dir = opendir(CACHE_DIR);
    if (!dir) {
        printf("Error opening cache directory.\n");
        return 1;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        char file_path[1024];
        sprintf(file_path, "%s/%s", CACHE_DIR, ent->d_name);
        process_file(file_path);
    }

    closedir(dir);

    return 0;
}
