// C function to dynamically rename files
int rename_files(char* dir_path, char* filename) {
    // Initialize variables
    int digit_count = 0;
    Extension* config_extensions = NULL;
    char new_filename[256];
    DIR* dir;
    struct dirent* ent;

    // Parse configuration file
    FILE* config = fopen("config.txt", "r");
    if (config == NULL) {
        log_error("Failed to open configuration file", __FILE__);
        return -1;  // Failure
    }
    config_extensions = parse_config_file(config);
    free_extension_list(config_extensions);  // Free parsed list

    // Open directory for iteration
    dir = opendir(dir_path);
    if (dir == NULL) {
        log_error("Failed to open directory", __FILE__);
        return -1;  // Failure
    }

    // Iterate through files and directories in the directory
    while ((ent = readdir(dir)) != NULL) {
        char* file_path = strcat(ent->d_name, dir_path);
        if (strlen(file_path) > 256) {
            log_error("File name too long", __FILE__);
            continue;  // Skip long file names
        }

        int i;
        for (i = 0; i < strlen(filename); i++) {
            digit_count += 1;  // Count digits to ensure unique naming
        }

        // Dynamically rename files based on the filename length and sequence of digits
        asprintf(&new_filename, "%s_%d.%s", file_path, digit_count++, get_file_extension(config_extensions));
        rename(file_path, new_filename);

        free(new_filename);  // Free allocated memory
    }
    closedir(dir);
}
