import OpenSSL
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

class ModularCryptoExtension:
    def __init__(self):
        self.config = {}

    def load_openssl_components(self):
        OpenSSL.add_ssl_functions()
        OpenSSL.load_config('path_to_openssl_config_file')

    def initialize_aes(self):
        if 'AES' not in self.config or self.config['AES']:
            OpenSSL.AES()

    def initialize_camellia(self):
        if 'Camellia' not in self.config or self.config['Camellia']:
            OpenSSL.Camellia()

    def initialize_md5(self):
        if 'MD5' not in self.config or self.config['MD5']:
            OpenSSL.MD5()

    def initialize_sha(self):
        if 'SHA' not in self.config or self.config['SHA']:
            OpenSSL.SHA()

    def initialize_rsa_with_sha1(self):
        if 'RSA-with-SHA1' not in self.config or self.config['RSA-with-SHA1']:
            OpenSSL.RSAwithSHA1()

    def configure_crypto_primitives(self, config):
        self.config = config

    def encrypt_data(self, data, key, algorithm='AES'):
        if algorithm == 'AES':
            return OpenSSL.AES().encrypt(data, key)
        elif algorithm == 'Camellia':
            return OpenSSL.Camellia().encrypt(data, key)
        # Add more encryption algorithms as needed
        else:
            raise ValueError('Unsupported encryption algorithm')

    def decrypt_data(self, data, key, algorithm='AES'):
        if algorithm == 'AES':
            return OpenSSL.AES().decrypt(data, key)
        elif algorithm == 'Camellia':
            return OpenSSL.Camellia().decrypt(data, key)
        # Add more decryption algorithms as needed
        else:
            raise ValueError('Unsupported decryption algorithm')

    def sign_data(self, data, key, algorithm='RSA-with-SHA1'):
        if algorithm == 'RSA-with-SHA1':
            return OpenSSL.RSAwithSHA1().sign(data, key)
        # Add more signing algorithms as needed
        else:
            raise ValueError('Unsupported signing algorithm')

    def verify_signature(self, data, signature, key, algorithm='RSA-with-SHA1'):
        if algorithm == 'RSA-with-SHA1':
            return OpenSSL.RSAwithSHA1().verify(data, signature, key)
        # Add more verification algorithms as needed
        else:
            raise ValueError('Unsupported verification algorithm')

    def serialize_private_key(self, private_key):
        return serialization.dump_pem(private_key, default_backend())

    def deserialize_private_key(self, pem_data):
        return serialization.load_pem_private_key(pem_data, default_backend())

# Example usage:
extension = ModularCryptoExtension()
config = {'AES': True, 'Camellia': False}
