AES_CTX* init_aes_cipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    SHA256_CTX sha256_ctx;
    unsigned char password_hash[SHA256_DIGEST_LENGTH];
    int password_len = strlen(password);

    // Set the IV length to 16 bytes
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL, 1, (unsigned char*) "your iv", 16);

    // Derive the encryption key from the password using SHA-256
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, password, password_len);
    SHA256_Final(password_hash, &sha256_ctx);

    // Set the key length to 32 bytes (AES-256)
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, password_hash, sizeof(password_hash), 1, NULL, 0);

    return ctx;
}

void cleanup_aes_cipher(AES_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
