#include <sys/wait.h>

void handle_sigint(int signum) {
    printf("SIGINT received, terminating tasks...\n");
    for (int i = 0; i < 10; i++) {
        kill(getpid(), SIGTERM);
    }
}

int manage_background_tasks(const char **commands, int num_commands, unsigned int timeout) {
    sigset_t signal_set;
    pthread_sigmask(SIG_SETMASK, &signal_set, NULL);

    for (int i = 0; i < num_commands; i++) {
        pid_t task_pid = fork();
        if (task_pid == -1) {
            return -1; // Fork failed
        } else if (task_pid > 0) {
            int status;
            waitpid(task_pid, &status, timeout ? WNOHANG : 0);
            if (WIFEXITED(status)) {
                if (status != 0) {
                    printf("Task %d failed with exit code %d.\n", i, status);
                    return -1; // Task failed
                }
            } else if (timeout && WIFSIGNALED(status)) {
                printf("Task %d timed out and was terminated by signal.\n", i);
                return -2; // Task timed out
            }
        } else {
            dup2(STDIN_FILENO, STDIN_FILENO);
            dup2(STDOUT_FILENO, STDOUT_FILENO);

            if (setuid(geteuid()) != 0) {
                perror("setuid");
                exit(1);
            }

            system(commands[i]);
            _exit(0);
        }
    }

    return 0;
}

int main() {
    const char *commands[] = {"task1", "task2", ...}; // Replace with your commands
    int num_commands = sizeof(commands) / sizeof(commands[0]);
    unsigned int timeout = 60; // Default timeout in seconds

    int result = manage_background_tasks(commands, num_commands, timeout);
    if (result == -1) {
        printf("Failed to execute tasks.\n");
    } else if (result == -2) {
        printf("One or more tasks timed out.\n");
    } else {
        printf("All tasks completed successfully.\n");
    }

    return 0;
}
