public class BatchCompiler {
    private final File tempDir;
    private final ExecutorService executor;

    public BatchCompiler(File tempDir) {
        this.tempDir = tempDir;
        this.executor = Executors.newFixedThreadPool(5);
    }

    public void compileAndRun(String[] sourceFiles) throws IOException, InterruptedException {
        List<Future<?>> futures = new ArrayList<>();

        for (String sourceFile : sourceFiles) {
            File source = new File(sourceFile);
            File compiledClass = new File(tempDir, source.getName() + ".class");
            Callable<Void> task = () -> {
                try {
                    compile(source, compiledClass);
                    execute(compiledClass);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            };
            futures.add(executor.submit(task));
        }

        for (Future<?> future : futures) {
            future.get();
        }

        // Clean up unused temporary directories and their contents
        cleanUp(tempDir, 30); // retain temp files for 30 minutes

        executor.shutdown();
    }

    private void compile(File source, File compiledClass) throws IOException {
        // Use Java Compiler API to compile the source file
        // ...
