    private void execute(File compiledClass) throws IOException {
        // Use Java Runtime to execute the compiled class
        // ...
    }

    private void cleanUp(File dir, long retentionMinutes) throws IOException {
        File[] files = dir.listFiles();
        for (File file : files) {
            if (file.isFile() && !isRecentlyAccessed(file, retentionMinutes)) {
                file.delete();
            } else if (file.isDirectory()) {
                cleanUp(file, retentionMinutes);
                if (file.list().length == 0) {
                    file.delete();
                }
            }
        }
