        return -3; // Callback function not provided
    }

    // Verify encrypted message integrity and format
    char *message = config->encrypted_message;
    int len = strlen(message);
    if (len == 0 || !Base64_is_valid(message, len)) {
        return -4; // Invalid or empty Base64-encoded string
    }

    // Decrypt the message using Triple DES encryption
    unsigned char decrypted[1024];
    size_t decrypted_len;
    int status = triple_des_decrypt(config->password, config->connection, message, len, decrypted, &decrypted_len);
    if (status != 0) {
        return -5; // Decryption failed
    }

    // Validate the decrypted message against connection's expected format
    void *expected_format = (void *)config->connection + sizeof(void *);
    size_t expected_len = *(size_t *)expected_format;
    char *decrypted_msg = decrypted;
    if (decrypted_len != expected_len || memcmp(decrypted, (char *)expected_format, decrypted_len) != 0) {
