// Caching mechanism for frequent file checks
#define MAX_CACHE_SIZE 10
int cache_size = 0;
char *cache[MAX_CACHE_SIZE];

bool check_config(const json_object *config) {
    // Check server_name
    if (!json_object_object_get_ex(config, "server_name", NULL) ||
        !json_string_length(json_object_get_string(json_object_object_get(config, "server_name"))) ||
        is_duplicate_server_name(get_local_network_segment())) {
        return false;
    }

    // Check port
    int port = json_object_get_int(json_object_object_get(config, "port"));
    if (port < 443 || port > 65535) {
        return false;
    }
    // Check if the chosen port is blocked by firewall rules
    if (is_port_blocked("client", port) && is_port_blocked("server", port)) {
        return false;
    }

    // Check cert_path, key_path and optionally ca_cert_path
    char *cert_path = json_object_get_string(json_object_object_get(config, "cert_path"));
    char *key_path = json_object_get_string(json_object_object_get(config, "key_path"));
    if (ca_cert_path) {
        char *ca_cert_path = json_object_get_string(json_object_object_get(config, "ca_cert_path"));
        // Validate the paths
        if (!validate_file_path(cert_path) || !validate_file_path(key_path)) {
            return false;
        }
        if (ca_cert_path) {
            if (!validate_file_path(ca_cert_path)) {
                return false;
            }
        }
    } else {
        // Validate only cert_path and key_path
        if (!validate_file_path(cert_path) || !validate_file_path(key_path)) {
            return false;
        }
    }

    // Dynamically check the validity of the files
    int cache_index = -1;
    for (int i = 0; i < MAX_CACHE_SIZE && i < cache_size; i++) {
        if (!strcmp(cache[i], cert_path) || !strcmp(cache[i], key_path)) {
            cache_index = i;
            break;
        }
    }
    if (cache_index != -1) {
        // File is cached, check for file updates
        int updated = check_file_updates(cert_path);
        if (updated) {
            // Update the caching mechanism and the file status
            cache[cache_index] = cert_path;
            update_cache_size();
        }
    } else {
        // Check if files are available
        if (!are_files_available(cert_path, key_path)) {
            return false;
        }
    }

    return true;
}
