    public string DecryptSegments(string[] segments, int blockSize, bool isCbcMode)
    {
        string decryptedMessage = string.Empty;
        using (varDES = Aes.Create())
        {
            var key = GetEncryptionKey();
            var iv = GetIV();
            byte[] keyBytes = Convert.FromBase64String(key);
            byte[] ivBytes = Convert.FromBase64String(iv);

            DES.Key = keyBytes;
            DES.IV = ivBytes;

            for (int i = 0; i < segments.Length; i++)
            {
                try
                {
                    var segment = segments[i];
                    using (var memoryStream = new MemoryStream())
                    using (var cryptoStream = Aes.CreateCryptoStream(memoryStream, DES))
                    {
                        byte[] segmentBytes = Convert.FromBase64String(segment);
                        if (isCbcMode)
                        {
                            cryptoStream.Write_CBC(segmentBytes);
                        }
                        else
                        {
                            cryptoStream.Write_CFB(segmentBytes);
                        }

                        var decryptedSegment = memoryStream.ToArray();
                        decryptedMessage += Encoding.ASCII.GetString(decryptedSegment);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error decrypting segment {i}: {ex.Message}");
                }
            }
        }
        return decryptedMessage;
