using System.Threading.Tasks;

public class LogProcessor
{
    public async Task<IEnumerable<string>> ProcessLogAsync(string logFilePath, int maxLinesToProcess)
    {
        var results = new List<string>();

        using (var httpClient = new HttpClient())
        {
            for (int i = 0; i < Math.Min(maxLinesToProcess, 100); i++)
            {
                try
                {
                    var response = await httpClient.GetAsync(logFilePath);
                    if (!response.IsSuccessStatusCode)
                    {
                        // Handle error
                        return null;
                    }

                    using (var stream = await response.Content.ReadAsStreamAsync())
                    {
                        using (var reader = new StreamReader(stream))
                        {
                            string line;
                            while ((line = await reader.ReadLineAsync()) != null)
                            {
                                if (!string.IsNullOrEmpty(line) && !line.Contains(" "))
                                {
                                    results.Add(line.ToUpper().Trim());
                                }
                            }
                        }
                    }
                }
                catch (HttpRequestException ex)
                {
                    // Handle error
                    return null;
                }
            }
        }

        return results;
    }
}
