using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;

public class DecryptionService
{
    private readonly ILogger _logger;
    private readonly int _timeoutMilliseconds;

    public DecryptionService(ILogger logger, int timeoutMilliseconds)
    {
        _logger = logger;
        _timeoutMilliseconds = timeoutMilliseconds;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = encryptionKey;
            aes.IV = initializationVector;

            var decryptor = aes.CreateDecryptor();

            using (var ms = new MemoryStream(ciphertext))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var buffer = new byte[4096];
                    int bytesRead;
                    byte[] decryptedBytes = null;

                    while ((readBytes = cs.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        if (decryptedBytes == null)
                            decryptedBytes = new byte[readBytes + buffer.Length - 1];
                        Array.Copy(buffer, 0, decryptedBytes, decryptedBytes.Length - readBytes, readBytes);
                    }

                    cs.Close();
                    ms.Close();

                    return decryptedBytes;
                }
            }
        }
    }
}
