const axios = require('axios');
const geolocator = require('geolocator');
const cache = require('memory-cache');
const moment = require('moment');

function getWeatherData(city) {
  const ipCity = geolocator.cityFromIP();
  if (city) {
    city = city.toLowerCase();
  } else {
    city = ipCity.name;
  }

  function fetchWeatherData() {
    const apiList = ['api.weather1.com', 'api.weather2.com', 'api.weather3.com'];
    const cachedResponse = cache.get(`weather-${city}`);
    if (cachedResponse) {
      return Promise.resolve(cachedResponse);
    }

    let data = null;
    for (const api of apiList) {
      try {
        const response = await axios.get(`https://${api}/weather/${city}`);
        data = response.data;
        break;
      } catch (error) {
        if (error.response.status === 429) {
          // Handle rate limit
          await new Promise(resolve => setTimeout(() => resolve(), 1000));
        }
      }
    }

    cache.put(`weather-${city}`, data, moment().add(10, 'minutes').unix());
    return Promise.resolve(data);
  }

  function parseWeatherData(data) {
    const weatherData = {};
    for (const api in data) {
      if (data.hasOwnProperty(api)) {
        const jsonData = JSON.parse(data[api]);
        for (const key in jsonData) {
          if (jsonData.hasOwnProperty(key)) {
            weatherData[key] = jsonData[key];
          }
        }
      }
    }
    return weatherData;
  }

  async function main() {
    try {
      const data = await fetchWeatherData();
      const parsedData = parseWeatherData(data);
      console.log(parsedData);
    } catch (error) {
      console.error(error);
    }
  }

  main();
}

