use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use log::{info, warn, error};
use crossbeam_utils::scope;

fn create_or_update_directory(directory_name: &str) -> Result<String, String> {
    let mut current_dir = env::current_dir().unwrap();
    let dir_path = current_dir.join(directory_name);

    if !dir_path.exists() {
        // Ensure the parent directory exists
        if let Some(parent_dir) = dir_path.parent() {
            if !parent_dir.exists() {
                create_dir_recursive(&parent_dir)?;
            }
        }

        // Create or update the directory
        fs::create_dir_all(&dir_path)?;

        info!("Directory '{}' created successfully", directory_name);
    } else {
        info!("Directory '{}' already exists, no action taken", directory_name);
    }

    Ok(dir_path.to_str().unwrap_or("").to_string())
}

fn create_dir_recursive(path: &Path) -> Result<(), String> {
    if let Err(e) = fs::create_dir_all(path) {
        error!("Failed to create directory '{}': {}", path.display(), e);
        warn!("Parent directory does not exist, trying to create it");
        scope(|s| s.spawn(move || create_dir_recursive(path.parent().unwrap()))).join();
        fs::create_dir_all(path)?;
    }
    Ok(())
}

fn main() {
    let dir_name = "my_directory";
    match create_or_update_directory(dir_name) {
        Ok(dir_path) => {
            env::set_var("MY_DIRECTORY", dir_path);
            println!("Directory path set: {}", dir_path);
        },
        Err(err) => error!("Error creating or updating directory: {}", err),
    };
}
