    int sentinel = -1; // sentinel value
    while (scanf("%d", &(*list)[0]) && (*list)[0] != sentinel) {
        for (int i = 1; i < 10; i++) { // assuming a list of length 10, adjust as needed
            scanf("%d", &((*list)[i]));
        }
        *max = *(*list);
        for (int i = 1; i < 10; i++) {
            if ((**list)[i] > *max) {
                *max = (**list)[i];
            }
        }
    }
}

void generate_nfa_pi_crc_indication_pdu(int **nfa_pi_crc_indication_pdu, int n) {
