    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = (*nfa_pi_crc_indication_pdu) + i;
        p->RX_UE_INFORMATION_TAG = rand() % 10000000;
        p->RNTI = rand() % 1000;
