#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000000
#define GARbage_COLLECTION_THRESHOLD 30 // seconds

typedef enum {
    ConnectionState_OPEN,
    ConnectionState_CLOSED,
    ConnectionState_FAULTY
} ConnectionState;

typedef struct {
    char ipAddress[17]; // assuming IPv6 address
    int portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

NetworkConnectionStatus* connections = NULL;
int connectionsCount = 0;

pthread_mutex_t connectionsMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t connectionsCondVar = PTHREAD_COND_INITIALIZER;

void* garbageCollectorThread(void* arg) {
    while (1) {
        pthread_mutex_lock(&connectionsMutex);
        sleep(GARbage_COLLECTION_THRESHOLD); // adjust to desired threshold
        NetworkConnectionStatus* inactiveConnection = NULL;
        for (int i = 0; i < connectionsCount; i++) {
            if (connections[i].connectionState == ConnectionState_CLOSED || 
                connections[i].connectionState == ConnectionState_FAULTY) {
                inactiveConnection = &connections[i];
                break;
            }
        }
        if (inactiveConnection != NULL) {
            memmove(&connections[inactiveConnection - connections], 
                    &connections[inactiveConnection + 1], 
                    sizeof(NetworkConnectionStatus*) * (connectionsCount - i));
            connectionsCount--;
            free(inactiveConnection);
        }
        pthread_mutex_unlock(&connectionsMutex);
    }
}

void initializeConnections() {
    connections = malloc(MAX_CONNECTIONS * sizeof(NetworkConnectionStatus));
    connectionsCount = 0;
    pthread_create(NULL, NULL, garbageCollectorThread, NULL);
}

void addConnection(char* ipAddress, int portNumber, ConnectionState connectionState) {
    NetworkConnectionStatus* newConnection = &connections[connectionsCount];
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;
    newConnection->connectionState = connectionState;
    connectionsCount++;
}

void updateConnection(int index, ConnectionState connectionState) {
    pthread_mutex_lock(&connectionsMutex);
    if (index >= 0 && index < connectionsCount) {
        connections[index].connectionState = connectionState;
        pthread_cond_signal(&connectionsCondVar);
    }
    pthread_mutex_unlock(&connectionsMutex);
}

int getActiveConnections() {
    return connectionsCount;
}
