import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.List;

public class Main {

    public static String processDataAndEvaluateNetworkDependencies(String data, List<int[][]> networkArrays) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            long startTime = System.currentTimeMillis();
            byte[] hashBytes = md.digest(data.getBytes());
            long endTime = System.currentTimeMillis();
            String hashValue = bytesToHex(hashBytes);
            long timeTakenForHash = endTime - startTime;
            System.out.println("Computed MD5 hash: " + hashValue + ", Time taken: " + timeTakenForHash + " ms");

            for (int[][] networkArray : networkArrays) {
                long startTime1 = System.currentTimeMillis();
                UnionFind uf = new UnionFind(networkArray[0].length);
                int disjointPairs = 0;
                for (int[] array : networkArray) {
                    for (int i = 0; i < array.length; i++) {
                        uf.makeSet(array[i]);
                    }
                    for (int i = 0; i < array.length - 1; i++) {
                        if (!uf.find(array[i], array[i + 1])) {
                            disjointPairs++;
                        }
                    }
                }
                long endTime1 = System.currentTimeMillis();
                long timeTakenForNetwork = endTime1 - startTime1;
                System.out.println("Number of disjoint pairs: " + disjointPairs + ", Time taken: " + timeTakenForNetwork + " ms");

                // Simulate network latency
                for (int[] array : networkArray) {
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        throw new RuntimeException(e);
                    }
                }

            }
        } catch (NoSuchAlgorithmException e) {
            System.out.println("Error: " + e.getMessage());
        }
        return "";
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

class UnionFind {

    int[] parent;
    int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            makeSet(i);
        }
    }

    private void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}']

