        'driver' => 'mysql',
        'host' => 'localhost',
        'port' => 3306,
        'username' => 'default_username',
        'password' => 'default_password',
        'dbname' => 'default_database'
    );

    // Load override configuration from file
    if ($overrideFile) {
        $overrideConfig = json_decode(file_get_contents($overrideFile), true);
        if (!is_array($overrideConfig)) {
            throw new Exception('Invalid override configuration file');
        }
        foreach ($config as $key => $value) {
            if (isset($overrideConfig[$key])) {
                $config[$key] = array_replace_recursive($value, $overrideConfig[$key]);
            }
        }
    }

    // Load environment variables
    if (getenv('DB_HOST')) {
        $config['database']['host'] = getenv('DB_HOST');
    }
    if (getenv('DB_PORT')) {
        $config['database']['port'] = getenv('DB_PORT');
    }
    if (getenv('DB_USERNAME')) {
        $config['database']['username'] = getenv('DB_USERNAME');
    }
    if (getenv('DB_PASSWORD')) {
        $config['database']['password'] = getenv('DB_PASSWORD');
    }
    if (getenv('DB_NAME')) {
        $config['database']['dbname'] = getenv('DB_NAME');
    }

    // Load command-line arguments
    if ($argc > 1) {
        foreach ($argv as $key => $value) {
            if (preg_match('/^--(db_host|db_port|db_username|db_password|db_name)$/', $value)) {
                $setting = str_replace('--', '', $value);
                switch ($setting) {
                    case 'db_host':
                        $config['database']['host'] = $argv[$key + 1];
                        break;
                    case 'db_port':
                        $config['database']['port'] = (int)$argv[$key + 1];
                        break;
                    case 'db_username':
                        $config['database']['username'] = $argv[$key + 1];
                        break;
                    case 'db_password':
                        $config['database']['password'] = $argv[$key + 1];
                        break;
                    case 'db_name':
                        $config['database']['dbname'] = $argv[$key + 1];
                        break;
                }
            }
        }
    }

    // Fetch environment-specific configuration values from external API
    $apiConfig = json_decode(file_get_contents('https://example.com/api/config'), true);
    if ($apiConfig) {
        foreach ($config as $key => $value) {
            if (isset($apiConfig[$key])) {
                $config[$key] = array_replace_recursive($value, $apiConfig[$key]);
            }
        }
    }

    // Write configuration file
    file_put_contents('config.php', '<?php return ' . var_export($config, true) . ';');

    echo "Configuration file generated successfully.\n";
}

