function oauthAuthenticate($client_id, $client_secret, $redirect_uri, $code) {
    // Implement OAuth 2.0 client authentication using a library likeleague/oauth2-server
    require_once 'League/OAuth2/Server.php';
    $server = new League\OAuth2\Server\AuthorizationServer();

    $client = $server->getClient($client_id);
    if (!$client) {
        // Handle invalid client ID
        return false;
    }

    try {
        $token = $server->validateVerificationCode($code, $redirect_uri);
        session_start();
        $_SESSION['access_token'] = $token->getToken();
    } catch (League\OAuth2\Server\Exception\OAuthServerException $e) {
        // Handle authentication errors
        return false;
    }

    // Retrieve user profile information from external API using the access token
    require_once 'ExternalAPI.php';
    $api = new ExternalAPI();
    try {
        $profile = $api->getProfileInformation($_SESSION['access_token']);
    } catch (Exception $e) {
