// C function for background execution using fork and wait
#include <sys/types.h>
#include <sys/wait.h>
#include <stdlib.h>
#include <unistd.h>

void* backgroundExecute(char* command) {
    pid_t child_pid = fork();
    if (child_pid == 0) { // Child process
        execlp(command, NULL);
    } else if (child_pid > 0) { // Parent process
        int status;
        wait(&status);
        if (!WIFEXITED(status)) {
            // Handle command execution failure
            return NULL;
        }
    } else {
        // Handle fork error
        return NULL;
    }

    // Implement retry logic for transient errors like network issues
    for (int i = 0; i < 3; i++) {
        child_pid = fork();
        if (child_pid == 0) { // Child process
            execlp(command, NULL);
        } else if (child_pid > 0) { // Parent process
            wait(&status);
            if (WIFEXITED(status)) {
                return NULL;
            }
        } else {
            // Handle fork error
            return NULL;
        }
    }

    // Clean up resources
    if (child_pid < 0) {
        close(child_pid); // Close file descriptors and other resources
    }

    return NULL;
}
