int loadResourceBundle(const char *path, int *numItems) {
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        return -1; // error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    // dynamically allocate memory for the bundle and its items
    int *bundleItems = (int *)malloc((numItems != NULL ? *numItems : 0) * sizeof(int));
    if (bundleItems == NULL) {
        fclose(file);
        return -2; // error allocating memory
    }

    int bytesRead = 0;
    while ((bytesRead += fread(bundleItems + bytesRead, sizeof(int), 1, file)) > 0 && bytesRead <= fileSize) {
        // process loaded items using callbacks if provided
        // for demonstration purposes, just print the item values
        printf("%d\n", bundleItems[bytesRead - 1]);
    }

    fclose(file);
    free(bundleItems);

    *numItems = bytesRead;
    return 0; // successful load
}

int loadResourceBundleAsync(const char *path, int *numItems, void (*onItemLoaded)(int), void (* onError)(const char *)) {
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        onError("Failed to open file");
        return -1; // error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    // dynamically allocate memory for the bundle and its items
    int *bundleItems = (int *)malloc((numItems != NULL ? *numItems : 0) * sizeof(int));
    if (bundleItems == NULL) {
        fclose(file);
        onError("Failed to allocate memory");
        return -2; // error allocating memory
    }

    int bytesRead = 0;
    while ((bytesRead += fread(bundleItems + bytesRead, sizeof(int), 1, file)) > 0 && bytesRead <= fileSize) {
        onItemLoaded(bundleItems[bytesRead - 1]);
    }

    fclose(file);
    free(bundleItems);

    *numItems = bytesRead;
    return 0; // successful load
}
