        do {
            rnti = rand() % 0xFFFF + 1;
        } while (rnti <= 0 || rnti > 0xFFFF); // Ensure RNTI falls within valid range

        list[i].RX_UE_INFORMATION_TAG = i; // Assign a unique value for RX_UE_INFORMATION_TAG
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? rand() : 0; // Randomly set CRCFLAG

        if (rnti == list[i-1].RNTI && i > 0) {  // Check for consecutive duplicates
            // Adjust random seed to balance between randomness and consistency
            srand((unsigned int)(time(NULL) + i));
            rnti = rand() % 0xFFFF + 1;
            while (rnti <= 0 || rnti > 0xFFFF); // Ensure RNTI falls within valid range

            list[i].RNTI = rnti; // Update current structure's RNTI
        }

        if (list[i].RNTI < 0 || list[i].RNTI > 0xFFFF) { // Log invalid RNTI values
