#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    CONNECTED,
    DISCONNECTED,
    TIMEOUT
} ConnectionState;

typedef struct {
    char ip[16];
    int port;
    ConnectionState state;
} NetworkConnectionStatus;

NetworkConnectionStatus** connections = NULL;
int connectionCount = 0;
int maxConnections = 100; // Initial capacity

void initializeConnections() {
    connections = (NetworkConnectionStatus**)malloc(maxConnections * sizeof(NetworkConnectionStatus*));
}

void addConnection(char* ip, int port) {
    if (connectionCount >= maxConnections) {
        maxConnections *= 2;
        connections = (NetworkConnectionStatus**)realloc(connections, maxConnections * sizeof(NetworkConnectionStatus*));
    }
    connections[connectionCount] = malloc(sizeof(NetworkConnectionStatus));
    strcpy(connections[connectionCount]->ip, ip);
    connections[connectionCount]->port = port;
    connections[connectionCount]->state = CONNECTED;
    connectionCount++;
}

void updateConnection(int index, ConnectionState state) {
    if (index < 0 || index >= connectionCount)
        return; // Connection not found
    connections[index]->state = state;
}

int getActiveConnections() {
    int activeCount = 0;
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i]->state == CONNECTED)
            activeCount++;
    }
    return activeCount;
}

void cleanupDisconnectedConnections(int timeout) {
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i]->state == DISCONNECTED && connections[i]->timeout < timeout) {
            free(connections[i]);
            connections[i] = NULL;
            connectionCount--;
            i--; // Decrement the index because we just removed an element
        }
    }
}

void serializeConnections(FILE* file) {
    fwrite(&connectionCount, sizeof(int), 1, file);
    for (int i = 0; i < connectionCount; i++) {
        fwrite(connections[i], sizeof(NetworkConnectionStatus), 1, file);
    }
}

void deserializeConnections(FILE* file) {
    int count;
    fread(&count, sizeof(int), 1, file);
    connections = realloc(connections, count * sizeof(NetworkConnectionStatus*));
    connectionCount = count;
    for (int i = 0; i < count; i++) {
        NetworkConnectionStatus* conn = malloc(sizeof(NetworkConnectionStatus));
        fread(conn, sizeof(NetworkConnectionStatus), 1, file);
        connections[i] = conn;
    }
}

void freeConnections() {
    for (int i = 0; i < connectionCount; i++)
        free(connections[i]);
    free(connections);
}
