    // Find maximum record value
    int maxVal = records[0].value;
    for (int i = 1; i < *numRecords; i++) {
        if (records[i].value > maxVal) {
            maxVal = records[i].value;
        }
    }

    printf("Maximum record value: %d\n", maxVal);

    // Free memory
    free(records);

    return NULL;
}

