    int totalLatency = stats->latencies;
    int totalSuccesses = stats->successes;
    int totalErrors = stats->errors;

    stats->averageLatency = totalLatency / (totalSuccesses + totalErrors);
    stats->successRate = (double)totalSuccesses / (totalSuccesses + totalErrors);
    stats->errorRate = (double)totalErrors / (totalSuccesses + totalErrors);

    return stats;
}

