void init_arrays(int num_records) {
    records = (Record*)allocate_memory(num_records * sizeof(Record));
    offsets = (long*)allocate_memory(num_records * sizeof(long));
    keys = (int*)allocate_memory(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        long offset = i;
        int key = rand() % RECORD_FIELD_RANGE;
        record->value = key;

        offsets[i] = offset;
        keys[i] = key;
