    int start_index = *(int*)arg;
    int end_index = start_index + MAX_RECORDS;

    for (int i = start_index; i < end_index; i++) {
        Record* record = &records[i];
        long offset = offsets[i];
        int key = keys[i];

        // Access the record fields here
    }

    return NULL;
}

void manage_memory(int num_records) {
    pthread_mutex_init(&mutex, NULL);
    sem_init(&sem, 0, 1);

    init_arrays(num_records);

    int num_threads = num_records / MAX_RECORDS + (num_records % MAX_RECORDS > 0);
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; i++) {
        int start_index = i * MAX_RECORDS;
        int end_index = (i == num_threads - 1) ? num_records : (i + 1) * MAX_RECORDS;

        pthread_create(&threads[i], NULL, thread_func, &start_index);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&sem);
    pthread_mutex_destroy(&mutex);

    free(records);
    free(offsets);
    free(keys);
}

int main() {
    int num_records = 10000;
    manage_memory(num_records);
    return 0;
