#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    int *keys;
    long *offsets;
    Record **records;
    int numRecords;
    int status;
} AllocationResult;

AllocationResult* allocateArrays(int numRecords) {
    AllocationResult* result = (AllocationResult*)malloc(sizeof(AllocationResult));

    if (!result) {
        return NULL; // memory allocation failed
    }

    result->numRecords = numRecords;
    result->status = 0; // initial status: success

    result->keys = (int*)malloc(numRecords * sizeof(int));

    if (!result->keys) {
        free(result);
        return NULL; // keys allocation failed
    }

    result->offsets = (long*)malloc(numRecords * sizeof(long));

    if (!result->offsets) {
        free(result->keys);
        free(result);
        return NULL; // offsets allocation failed
    }

    result->records = (Record**)malloc(numRecords * sizeof(Record*));

    if (!result->records) {
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL; // records allocation failed
    }

    for (int i = 0; i < numRecords; i++) {
        result->records[i] = (Record*)malloc(sizeof(Record));

        if (!result->records[i]) {
            // handle partial data set gracefully
            // ...
            for (int j = 0; j <= i; j++) {
                free(result->keys);
                free(result->offsets);
                free(result->records[j]);
            }
            free(result->records);
            free(result->keys);
            free(result->offsets);
            free(result);
            return NULL; // partial data set failure
        }

        result->records[i]->value = i;
        result->records[i]->offset = (long)i;
    }

    return result;
}

void freeArrays(AllocationResult* allocation) {
    for (int i = 0; i < allocation->numRecords; i++) {
        free(allocation->records[i]);
    }
    free(allocation->records);
    free(allocation->keys);
    free(allocation->offsets);
    free(allocation);
}

// example usage
int main() {
    AllocationResult* result = allocateArrays(10);

    if (!result) {
        printf("Memory allocation failed.\n");
    } else {
        // process the allocated arrays
        for (int i = 0; i < result->numRecords; i++) {
            printf("%d: %d, %ld\n", i, result->keys[i], result->offsets[i]);
        }
        freeArrays(result);
    }

    return 0;
}
