    record data;
    struct Node* next;
} Node;

// Function to initialize and insert a new record into the linked list
void insertRecord(record *newRecord, Node** head) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *newRecord;
    newNode->next = (*head);
    (*head) = &newNode;
}

// Function to remove a record from the linked list by key
void removeRecord(int key, Node** head) {
    if ((*head)->data.value == key) {
        Node* temp = (*head);
        (*head) = (*head)->next;
        free(temp);
    } else {
        Node* current = *head;
        while (current->next && current->next->data.value != key) {
            current = current->next;
        }
        if (current->next) {
            current->next = current->next->next;
        }
    }
}

// Function to update a record in the linked list by key
void updateRecord(int key, int newValue, Node** head) {
    Node* current = *head;
    while (current && current->data.value != key) {
        current = current->next;
    }
    if (current) {
        current->data.value = newValue;
    }
}

// Function to traverse the linked list and perform some operation on each record
void traverseList(Node* head, void (*operation)(record)) {
    Node* current = head;
    while (current) {
        operation(current->data);
        current = current->next;
    }
}

