// Dynamic array of file metadata
FileMetadata** files = NULL;
int files_size = 0;

// Function to add a new file to the dynamic array
void add_file(FileMetadata* new_file) {
    // Double the size of the array if it's full or increasing capacity by one block at a time.
    int new_capacity = files_size + (files_size > 0 ? 1 : 4);
    FileMetadata** new_files = realloc(files, sizeof(*new_files) * new_capacity);

    if (!new_files) {
        // Handle memory allocation failure
    }

    // Copy the previous contents to the new array.
    for (int i = 0; i < files_size; i++) {
        new_files[i] = files[i];
    }

    // Add the new file at the end of the array.
    new_files[files_size++] = new_file;

    files = new_files;
}

// Function to update the metadata of an existing file
void update_file(char* path, size_t new_size) {
    for (int i = 0; i < files_size; i++) {
        if (!strcmp(files[i]->FilePath, path)) {
            // Update the file size and modification time.
            files[i]->FileSize = new_size;
            files[i]->ModificationTime = time(NULL);
            return;
        }
    }
}

// Function to retrieve the total number of files accessed within a specified time window
int get_accessed_files(time_t start_time, time_t end_time) {
    int count = 0;

    for (int i = 0; i < files_size; i++) {
        if (files[i]->ModificationTime >= start_time && files[i]->ModificationTime <= end_time) {
            count++;
        }
    }

    return count;
}

// Function to free up resources by garbage collecting infrequently accessed files
void gc(time_t current_time, int threshold_accesses) {
    for (int i = 0; i < files_size; i++) {
        if (files[i]->AccessFrequency <= threshold_accesses && current_time - files[i]->ModificationTime > 3600 * 24) { // Assuming 1 day as the threshold
            free(files[i]->FilePath);
            free(files[i]);
            for (int j = i; j < files_size - 1; j++) {
                files[j] = files[j + 1];
            }
            files_size--;
        }
    }
}

