#include <stdlib.h>
#include <time.h>

typedef enum {
    SESSION_ACTIVE,
    SESSION_INACTIVE,
    SESSION_TIMED_OUT
} SessionState;

typedef struct {
    int UserID;
    int SessionID;
    time_t LastActiveTime;
    SessionState State;
} UserSession;

// Dynamic array to store user sessions
UserSession** sessionArray = NULL;
int sessionArraySize = 0;
time_t timeout = 3600; // default timeout in seconds

void initSessions(int initialCapacity) {
    sessionArray = (UserSession**)malloc(initialCapacity * sizeof(UserSession*));
    sessionArraySize = initialCapacity;
}

int addSession(int userID, int sessionID) {
    for (int i = 0; i < sessionArraySize; i++) {
        if (!sessionArray[i]->UserID && !sessionArray[i]->State) {
            sessionArray[i]->UserID = userID;
            sessionArray[i]->SessionID = sessionID;
            sessionArray[i]->LastActiveTime = time(NULL);
            sessionArray[i]->State = SESSION_ACTIVE;
            return i; // successful addition
        }
    }
    // expand the array if it's full
    int newSize = sessionArraySize * 2 + 1;
    UserSession** newArray = (UserSession**)realloc(sessionArray, newSize * sizeof(UserSession*));
    for (int i = sessionArraySize; i < newSize; i++) {
        newArray[i] = NULL;
    }
    sessionArray = newArray;
    sessionArraySize = newSize;
    // try to add the session again
    for (int i = 0; i < sessionArraySize; i++) {
        if (!sessionArray[i]->UserID && !sessionArray[i]->State) {
            sessionArray[i]->UserID = userID;
            sessionArray[i]->SessionID = sessionID;
            sessionArray[i]->LastActiveTime = time(NULL);
            sessionArray[i]->State = SESSION_ACTIVE;
            return i; // successful addition
        }
    }
    return -1; // unable to add the session
}

int updateSession(int index, SessionState state) {
    if (index >= 0 && index < sessionArraySize) {
        sessionArray[index]->State = state;
        if (state == SESSION_INACTIVE || state == SESSION_TIMED_OUT) {
            sessionArray[index]->LastActiveTime = time(NULL); // update last active time
        }
        return 1; // successful update
    }
    return -1; // invalid index or session not found
}

int getActiveSessionCount() {
    int count = 0;
    for (int i = 0; i < sessionArraySize; i++) {
        if (sessionArray[i]->State == SESSION_ACTIVE) {
            count++;
        }
    }
    return count;
}

void cleanupInactiveSessions() {
    time_t now = time(NULL);
    for (int i = 0; i < sessionArraySize; i++) {
        if (now - sessionArray[i]->LastActiveTime > timeout) {
            // terminate the inactive session
            updateSession(i, SESSION_TIMED_OUT);
        }
    }
}

void printSessions() {
    for (int i = 0; i < sessionArraySize; i++) {
        printf("User ID: %d, Session ID: %d, State: %s\n", sessionArray[i]->UserID,
               sessionArray[i]->SessionID, stateToString(sessionArray[i]->State));
    }
}

const char* stateToString(SessionState state) {
    switch (state) {
        case SESSION_ACTIVE:
            return "ACTIVE";
        case SESSION_INACTIVE:
            return "INACTIVE";
        case SESSION_TIMED_OUT:
            return "TIMED OUT";
    }
}
