#define MAX_BUFFER_SIZE 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    int ue_identifier;
    float crc_flag_probability;
    size_t buffer_size;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    unsigned int seed;
    double (*generator)(double);
    void (*reset)(void);
} RNG_T;

RNG_T *rng_pool = NULL;
size_t rng_pool_size = 0;

int CreateNfadynamicCRCList(const char* config_file_path) {
    FILE* file = fopen(config_file_path, "r");
    if (!file) {
        printf("Error opening configuration file.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
    size_t crc_list_size = 0;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T new_crc;
        fscanf(file, "%d %f %zu", &new_crc.ue_identifier, &new_crc.crc_flag_probability, &new_crc.buffer_size);
        if (ferror(file)) {
            printf("Error reading configuration file.\n");
            fclose(file);
            return -1;
        }

        // Check for invalid data
        if (new_crc.ue_identifier < 0 || new_crc.crc_flag_probability < 0.0 || new_crc.buffer_size > MAX_BUFFER_SIZE) {
            printf("Invalid data in configuration file.\n");
            fclose(file);
            return -2;
        }

        if (crc_list_size >= MAX_BUFFER_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            printf("Exceeded maximum buffer size.\n");
            fclose(file);
            return -3;
        }

        crc_list = realloc(crc_list, (crc_list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_list) {
            printf("Failed to allocate memory for CRC list.\n");
            fclose(file);
            return -4;
        }

        crc_list[crc_list_size++] = new_crc;

        pthread_mutex_lock(&rng_pool[0].mutex);
        // Perform random number generation and logging
        pthread_mutex_unlock(&rng_pool[0].mutex);
    }

    fclose(file);
    return 0;
}
