// Function to traverse the graph using DFS or BFS
void traverse_graph(int start_vertex, int traversal_type) {
    // Use a visited array to keep track of visited vertices during traversal
    int *visited = (int *)malloc(num_vertices * sizeof(int));

    if (traversal_type == 0) { // DFS
        // Perform DFS starting from the given vertex
        stack<Vertex *> stack;
        stack.push(vertices[start_vertex]);
        while (!stack.empty()) {
            Vertex *curr_vertex = stack.pop();
            if (!visited[curr_vertex->id]) {
                visited[curr_vertex->id] = 1;
                stack.push(curr_vertex);
            }
        }
    } else { // BFS
        // Perform BFS starting from the given vertex
        queue<Vertex *> queue;
        queue.enqueue(vertices[start_vertex]);
        while (!queue.empty()) {
            Vertex *curr_vertex = queue.dequeue();
            if (!visited[curr_vertex->id]) {
                visited[curr_vertex->id] = 1;
                for (int i = 0; i < num_vertices; i++) {
                    if (vertices[i]->id == curr_vertex->id) {
                        queue.enqueue(vertices[i]);
                    }
                }
            }
        }
    }

    // Free allocated memory
    free(visited);
}

