#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* timestamp;
    int event_id;
    char* severity;
    double avg_severity;
} LogEvent;

typedef struct {
    LogEvent* events;
    int size;
} Log;

void process_log(char* filename, Log* log) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        LogEvent* event = (LogEvent*)malloc(sizeof(LogEvent));
        if (sscanf(buffer, "%s %d %s", event->timestamp, &event->event_id, event->severity) != 3) {
            printf("Invalid log line: %s\n", buffer);
            free(event);
            continue;
        }

        // Add event to the end of the array
        if (log->size == 0) {
            log->events = event;
        } else {
            LogEvent* last_event = log->events + log->size - 1;
            int i;
            for (i = log->size; i > 0; i--) {
                log->events[i] = log->events[i - 1];
            }
            log->events[0] = event;
        }

        log->size++;

        // Calculate average severity
        double sum_severity = 0.0;
        int count = min(3, log->size);
        for (int i = 0; i < count; i++) {
            sum_severity += atof(strtok(log->events[i]->severity, ":")) + atof(strtok(NULL, ":"));
        }
        event->avg_severity = sum_severity / count;

        // Handle duplicate events
        int j;
        for (j = 0; j < log->size - 1; j++) {
            if (log->events[j]->event_id == event->event_id) {
                free(log->events[j]);
                break;
            }
        }
        memmove(&log->events[j], &log->events[j + 1], sizeof(LogEvent) * (log->size - j - 1));
        log->size--;

        free(event);
    }

    fclose(file);
}

double min(double a, double b) {
    return a < b ? a : b;
}

int main() {
    Log log;
    log.events = NULL;
    log.size = 0;

    process_log("log.txt", &log);

    // Integration with external data source
    FILE* external_file = fopen("external_data.txt", "r");
    if (!external_file) {
        printf("Error opening external file.\n");
        return -1;
    }

    while (fgets(buffer, 1024, external_file)) {
        // Process the data and update log accordingly
    }

    fclose(external_file);

    // Output log to console or file
    for (int i = 0; i < log.size; i++) {
        printf("%s %d %.2f\n", log.events[i]->timestamp, log.events[i]->event_id, log.events[i]->avg_severity);
    }

    return 0;
}
