#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to derive the encryption key from a user-provided password
void *derive_key(char *password, int iteration_count) {
    // Initialize PBKDF2 with a 32-byte salt and a 32-byte key
    const EVP_MD *md = EVP_md5();
    const EVP_PBE_ALG *pbe_alg = EVP_pbe_algPBKDF2();
    const EVP_GUID *salt = (EVP_GUID *)malloc(32);
    unsigned char key[32];
    int key_len;
    BURN_CTX *ctx;

    // Generate a random salt
    RAND_bytes(salt, 32);

    // Derive the encryption key using PBKDF2 with the provided password and iteration count
    ctx = burn_ctx_new();
    if (burn_key(ctx, password, strlen(password), md, pbe_alg, salt, 32, iteration_count, &key_len) != 1) {
        ERR_error_fp(stderr, NULL);
    }
    free(salt);

    // Initialize the AES-256-CBC cipher for encrypting sensitive data streams
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    unsigned char iv[16];
    int iv_len;

    // Generate a random initialization vector (IV)
    RAND_bytes(iv, 16);
    EVP_CipherInit_ex(cipher, NULL, NULL, key, &key_len, iv);

    // Manage the IV's lifecycle to prevent re-use across different data streams
    void *iv_ptr = malloc(16);
    memcpy(iv_ptr, iv, 16);

    return (void *)iv_ptr;
}

// Function to securely destroy the key material once the cipher is disabled
void destroy_key(void *key) {
    // Free the derived encryption key and its associated resources
    if (key != NULL) {
        free(key);
    }
}
