// Define the UserSession structure
typedef struct {
    int UserID;
    time_t LastActivityTime;
    enum { ACTIVE, INACTIVE } SessionState;
} UserSession;

// Define a linked list node for the dynamic session list
typedef struct Node {
    UserSession session;
    struct Node* next;
} Node;

// Initialize the dynamic session list with a reference count of 0
Node* sessions = NULL;
int refCount = 0;

// Function to add a new user session
void addUserSession(int UserID, time_t LastActivityTime) {
    // Create a new linked list node for the user session
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->session.UserID = UserID;
    newNode->session.LastActivityTime = LastActivityTime;
    newNode->session.SessionState = ACTIVE;

    // Add the new node to the end of the linked list
    if (sessions == NULL) {
        sessions = newNode;
    } else {
        Node* current = sessions;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Increment the reference count for the dynamic session list
    refCount++;
}

// Function to update an existing user session state
void updateUserSession(int UserID, enum { ACTIVE, INACTIVE } SessionState) {
    Node* current = sessions;
    while (current != NULL) {
        if (current->session.UserID == UserID) {
            current->session.SessionState = SessionState;
            return;
        }
        current = current->next;
    }

    // If the user session is not found, print an error message
    printf("User session not found.\n");
}

// Function to query all active user sessions
void listActiveSessions() {
    Node* current = sessions;
    while (current != NULL) {
        if (current->session.SessionState == ACTIVE) {
            printf("UserID: %d, LastActivityTime: %ld\n", 
                   current->session.UserID, current->session.LastActivityTime);
        }
        current = current->next;
    }
}

// Function to periodically check for inactive sessions and release resources
void purgeInactiveSessions() {
    time_t currentTime = time(NULL);

    Node* current = sessions;
    while (current != NULL) {
        if ((currentTime - current->session.LastActivityTime > 3600) && 
            (current->session.SessionState == INACTIVE)) {
            // Remove the inactive session from the linked list
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            current = current->next;
        }
    }

    sessions = NULL;  // Reset the dynamic session list after purging inactive sessions

    refCount = 0;  // Reset the reference count for the dynamic session list
}

// Function to periodically synchronize session data with an external database
void syncSessionData() {
    // TO DO: Implement the synchronization logic with the external database
}

int main() {
    pthread_t thread;

    pthread_create(&thread, NULL, (void*) &purgeInactiveSessions, NULL);
    pthread_detach(thread);

    while (1) {
        int choice;
        printf("Enter 1 to add a new user session, 2 to update an existing user session, 3 to list active sessions, or 4 to exit: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addUserSession(12345, time(NULL));
                break;
            case 2:
                updateUserSession(12345, INACTIVE);
                break;
            case 3:
                listActiveSessions();
                break;
            case 4:
                printf("Exiting...\n");
                return 0;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}
