#define MAX_PDFS 5 // Maximum number of intermediate PDFs retained at any time
#define JPEG_TO_PDF_EXECUTABLE "jpeg2pdf" // Path to third-party tool executable
#define TEMP_FILE_DIR "/tmp/" // Directory for temporary files

int convert_jpegs_to_pdfs(char** jpeg_files, int num_jpegs, 
                          int max_memory_usage, int max_disk_usage) {
    int i;
    char* temp_file_path[MAX_PDFS];
    int pdf_count = 0;

    // Create a list of temporary file paths
    for (i = 0; i < MAX_PDFS; i++) {
        temp_file_path[i] = (char*)malloc(strlen(TEMP_FILE_DIR) + 20);
        sprintf(temp_file_path[i], "%s/temp_pdf_%d.pdf", TEMP_FILE_DIR, i);
    }

    // Process each JPEG file
    for (i = 0; i < num_jpegs; i++) {
        char* jpeg_file = jpeg_files[i];
        char* pdf_file = (char*)malloc(strlen(jpeg_file) + 10);
        sprintf(pdf_file, "%s.pdf", basename(jpeg_file));

        // Apply compression settings and page orientation preferences
        system	sprintf("jpeg2pdf -c -o %s %s", pdf_file, jpeg_file);

        if (access(pdf_file, F_OK) != -1) {
            // Copy the PDF to a temporary file
            system(sprintf("cp %s %s", pdf_file, temp_file_path[pdf_count]));

            // Release any memory allocated for compression settings and page orientation preferences
            free(pdf_file);

            // Increment the PDF count
            pdf_count++;

            if (pdf_count >= MAX_PDFS) {
                // Remove the oldest intermediate PDF to make room for new ones
                system(sprintf("rm %s", temp_file_path[pdf_count - 1]));
                pdf_count--;
            }
        } else {
            // Revert changes and clean up all temporary files on failure
            for (int j = 0; j < i; j++) {
                system(sprintf("rm %s", temp_file_path[j]));
            }

            free(jpeg_files);
            return 1;
        }
    }

    // Remove any intermediate PDFs that were not converted
    for (i = pdf_count - 1; i >= 0; i--) {
        system(sprintf("rm %s", temp_file_path[i]));
    }

    free(temp_file_path);

    // Log execution metrics and return success
    printf("PDF conversions completed successfully.\n");
    return 0;
}
