typedef struct {
    int key;
    float weight;
    time_t last_update;
} record;

record* initArrays(int* offset, int keys[], float weights[], record records[]) {
    CURL *curl;
    CURLcode res;
    char errorbuf[CURL_ERROR_SIZE];
    int i, j, num_services = 4;
    time_t now = time(NULL);

    // Initialize arrays
    for (i = 0; i < 4; ++i) {
        offset[i] = rand();
        keys[i] = rand() % 100;
        weights[i] = (float)rand() / RAND_MAX;
    }

    records = malloc(num_services * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < num_services; ++i) {
        records[i].key = keys[i % 4];
