#define HISTORY_SIZE 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int unique_entries = 0;
int total_entries = 0;

void insert_history(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation error
        printf("Memory allocation failed.\n");
        return;
    }
    newNode->data = data;
    newNode->next = *head;
    *head = newNode;
}

int is_unique(Node* head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = head;
    while (current) {
        if (memcmp(&current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            return 1; // Entry already exists in history
        }
        current = current->next;
    }
    return 0; // Entry not found in history
}

void* process_data(void* arg) {
    // Process data and insert into history
    NFAPI_CRC_INDICATION_PDU_T data;
    while (1) {
        // Acquire lock to ensure thread safety
        pthread_mutex_lock(&lock);

        // Process data and check for uniqueness
        if (!is_unique(&head, data)) {
            // Insert new entry into history
            insert_history(&head, data);
            unique_entries++;
            total_entries++;
        }

        // Release lock
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void print_statistics() {
    printf("Unique entries: %d\n", unique_entries);
    printf("Total entries: %d\n", total_entries);
}

int main() {
    pthread_t threads[HISTORY_SIZE];

    for (int i = 0; i < HISTORY_SIZE; i++) {
        pthread_create(&threads[i], NULL, process_data, NULL);
    }

    while (1) {
        // Sleep and periodically print statistics
        sleep(1);
        print_statistics();
    }

    return 0;
}
