typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    long offset;
    int count;
} SummaryRecord;

typedef struct {
    SummaryRecord* records;
    pthread_mutex_t mutex;
} Summary;

void* allocate_record(int key) {
    return malloc(sizeof(Record));
}

int insert_record(Summary* summary, Record* record) {
    // Insert record into summary
    summary->records = realloc(summary->records, (summary->records ? summary->records->count + 1 : 1) * sizeof(SummaryRecord));
    if (!record) return -1;
    summary->records[summary->records->count].key = record->key;
    summary->records[summary->records->count].offset = (long) record;
    return 0;
}

int lookup_summary(Summary* summary, int key, Record** record) {
    // Search for record in summary
    pthread_mutex_lock(&summary->mutex);
    for (int i = 0; i < summary->records->count; i++) {
        if (summary->records[i].key == key) {
            *record = (Record*) summary->records[i].offset;
            pthread_mutex_unlock(&summary->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&summary->mutex);
    return -1;
}

int update_summary(Summary* summary, Record* record) {
    // Update summary with new record
    pthread_mutex_lock(&summary->mutex);
    for (int i = 0; i < summary->records->count; i++) {
        if (summary->records[i].key == record->key) {
            free((void*) summary->records[i].offset);
            summary->records[i].offset = (long) record;
            break;
        }
    }
    pthread_mutex_unlock(&summary->mutex);
    return 0;
}

int destroy_summary(Summary* summary) {
    // Free memory allocated for summary
    for (int i = 0; i < summary->records->count; i++) {
        free((void*) summary->records[i].offset);
    }
    free(summary->records);
    pthread_mutex_destroy(&summary->mutex);
    return 0;
}

// Initialize and compact the memory as needed
void* initialize_memory() {
