    long* offsets = initialize_memory();
    Summary* summary = malloc(sizeof(Summary));
    pthread_mutex_init(&summary->mutex, NULL);
    summary->records = malloc(sizeof(SummaryRecord));

    // Process data and insert records into the pipeline
    for (int i = 0; i < 1000; i++) {
        Record* record = allocate_record(i);
        // ... process data ...
        insert_record(summary, record);
    }

    // Perform lookups and updates on the summary
