typedef struct {
    int timestamp;
    char interface_id[16];
    int error_code;
    struct tag* tags;
} network_status;

typedef struct {
    int event_id;
    int status;
} tag;

network_status* init_network_status(int num_tags) {
    network_status* status = (network_status*)malloc(sizeof(network_status));
    if (!status) {
        return NULL; // Error: memory allocation failed
    }

    status->timestamp = 0;
    strcpy(status->interface_id, "");
    status->error_code = 0;
    status->tags = (tag*)malloc(num_tags * sizeof(tag));
    if (!status->tags) {
        free(status);
        return NULL; // Error: memory allocation failed
    }

    for (int i = 0; i < num_tags; i++) {
        status->tags[i].event_id = 0;
        status->tags[i].status = 0;
    }

    return status;
}

void serialize_network_status(network_status* status, FILE* file) {
    fwrite(&status->timestamp, sizeof(int), 1, file);
    fwrite(status->interface_id, sizeof(char), strlen(status->interface_id), file);
    fwrite(&status->error_code, sizeof(int), 1, file);

    int num_tags = sizeof(status->tags) / sizeof(status->tags[0]);
    fwrite(&num_tags, sizeof(int), 1, file);

    for (int i = 0; i < num_tags; i++) {
        fwrite(&status->tags[i].event_id, sizeof(int), 1, file);
        fwrite(&status->tags[i].status, sizeof(int), 1, file);
    }
}

network_status* deserialize_network_status(FILE* file) {
    network_status* status = (network_status*)malloc(sizeof(network_status));
    if (!status) return NULL; // Error: memory allocation failed

    fread(&status->timestamp, sizeof(int), 1, file);
    fread(status->interface_id, sizeof(char), 16, file);
    fread(&status->error_code, sizeof(int), 1, file);

    int num_tags;
    fread(&num_tags, sizeof(int), 1, file);

    status->tags = (tag*)malloc(num_tags * sizeof(tag));
    if (!status->tags) {
        free(status);
        return NULL; // Error: memory allocation failed
    }

    for (int i = 0; i < num_tags; i++) {
        fread(&status->tags[i].event_id, sizeof(int), 1, file);
        fread(&status->tags[i].status, sizeof(int), 1, file);
    }

    return status;
}

void free_network_status(network_status* status) {
    if (!status) return; // Error: invalid pointer
    free(status->tags);
    free(status);
}
