#include <string.h>

// Enum to represent connection states
typedef enum {
    CONNECTED,
    DISCONNECTED,
    TIMEOUT
} ConnectionState;

// Structure to represent network connections
typedef struct {
    char* ipAddress;
    int portNumber;
    ConnectionState state;
} NetworkConnectionStatus;

// Dynamic collection of network connections
typedef struct {
    NetworkConnectionStatus** connections;
    int capacity;
    int size;
} ConnectionCollection;

// Function to create a new connection collection
ConnectionCollection* createConnectionCollection(int initialCapacity) {
    ConnectionCollection* collection = (ConnectionCollection*)malloc(sizeof(ConnectionCollection));
    collection->connections = (NetworkConnectionStatus**)malloc(initialCapacity * sizeof(NetworkConnectionStatus*));
    collection->capacity = initialCapacity;
    collection->size = 0;
    return collection;
}

// Function to add a new connection
void addConnection(ConnectionCollection* collection, char* ipAddress, int portNumber) {
    // Check if the collection needs to be resized
    if (collection->size >= collection->capacity) {
        collection->capacity *= 2; // Double the capacity for better performance
        collection->connections = (NetworkConnectionStatus**)realloc(collection->connections, collection->capacity * sizeof(NetworkConnectionStatus*));
    }

    NetworkConnectionStatus* connection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    connection->ipAddress = strdup(ipAddress);
    connection->portNumber = portNumber;
    connection->state = CONNECTED; // Initialize as connected
    collection->connections[collection->size++] = connection;
}

// Function to update a connection's state
void updateConnection(ConnectionCollection* collection, char* ipAddress, ConnectionState state) {
    for (int i = 0; i < collection->size; i++) {
        if (strcmp(collection->connections[i]->ipAddress, ipAddress) == 0) {
            collection->connections[i]->state = state;
            return;
        }
    }
}

// Function to remove an inactive connection
void removeInactiveConnection(ConnectionCollection* collection) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i]->state == DISCONNECTED || collection->connections[i]->state == TIMEOUT) {
            free(collection->connections[i]->ipAddress);
            free(collection->connections[i]);
            memmove(&collection->connections[i], &collection->connections[i + 1], sizeof(NetworkConnectionStatus*) * (collection->size - i - 1));
            collection->size--;
        }
    }
}

// Function to retrieve the total number of active connections
int getActiveConnections(ConnectionCollection* collection) {
    int count = 0;
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i]->state == CONNECTED) {
            count++;
        }
    }
    return count;
}

// Function to periodically cleanup inactive connections
void periodicCleanup(ConnectionCollection* collection) {
    // Simulate a network check that may take some time
    sleep(1); // Replace with actual network check or simulation

    removeInactiveConnection(collection);
}

int main() {
    ConnectionCollection* collection = createConnectionCollection(10);

    addConnection(collection, "192.168.1.100", 8080);
    addConnection(collection, "192.168.1.101", 8081);
    addConnection(collection, "192.168.1.102", 8082);

    updateConnection(collection, "192.168.1.100", DISCONNECTED);
    updateConnection(collection, "192.168.1.101", CONNECTED);

    printf("Active connections: %d\n", getActiveConnections(collection));

    periodicCleanup(collection);

    return 0;
}

