typedef struct {
    char* path;
    size_t buffer_size;
    void (*callback)(const char*);
} Config;

void processFiles(Config config) {
    FILE* file = fopen(config.path, "r");
    if (!file) {
        printf("Error opening file: %s\n", config.path);
        return;
    }

    int line_count = 0;
    size_t buffer_size = config.buffer_size;
    char** lines = (char**)malloc(buffer_size * sizeof(char*));
    char* buffer = (char*)malloc(buffer_size);

    void (*callback)(const char*) = config.callback;

    while (1) {
        ssize_t read = fread(buffer, 1, buffer_size, file);
        if (read == 0) break;
        buffer[read] = '\0'; // Null-terminate the line
        lines[line_count++] = strdup(buffer);

        // Process each line
        for (int i = 0; i < read; i++) {
            callback(&buffer[i]);
        }
    }

    fclose(file);
    free(buffer);
    for (int i = 0; i < line_count; i++) {
        free(lines[i]);
    }
    free(lines);

    // Process the data
    uint32_t key_counts[256] = {0}; // Initialize a hash map with 256 slots
    for (int i = 0; i < line_count; i++) {
        char* line = lines[i];
        // Parse the line and update the key count
        int key = parse_line(line);
        if (key >= 0 && key < 256) {
            key_counts[key]++;
        }
    }

    printf("Unique keys: %d\n", __builtin_popcountll(key_counts));
    for (int i = 0; i < 256; i++) {
        if (key_counts[i] > 0) {
            printf("%02x: %d\n", i, key_counts[i]);
        }
    }
}

// Example callback function
void my_callback(const char* line) {
    printf("Processed line: %s\n", line);
}
