    if (file == NULL) {
        return -1; // File not found or error reading file
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Validate interface entry
        char* token = strtok(buffer, ":");
        if (token != NULL && strlen(token) <= MAX_INTERFACE_NAME) {
            int i;
            for (i = 0; i < total_active; i++) {
                if (!strcmp(interfaces[i].name, token)) {
                    break;
                }
            }
            if (i == total_active) { // New interface
                interfaces[total_active].name[0] = '\0';
                interfaces[total_active++].record_count = 0;
            } else { // Interface already exists
                free(interfaces[i].records);
                interfaces[i].record_count = 0;
            }
        }
    }

    fclose(file);

    // Fetch real-time network status updates from external API
    int active_interfaces = 0;
    for (int i = 0; i < total_active; i++) {
        if (fetch_network_status(interfaces[i].name) > 0) {
            active_interfaces++;
        }
    }

    return active_interfaces;
}

