    for (i = 0; i < *totalRecords; i++) {
        if ((time(NULL) - records[i]->offset) > timeout) {
            free(records[i]);
            (*totalRecords)--;
        }
    }
}

int main() {
    // Example usage
    int capacity = 100;
    int timeout = 60; // seconds
    Record** records = (Record**)malloc(capacity * sizeof(Record));
    int totalRecords = 0;

    for (int i = 0; i < capacity; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        initRecord(records[i], 0, INT_MAX);
        records[i]->offset = time(NULL); // mark record as active
        totalRecords++;
    }

    while (1) {
        // manage records and update timeout if necessary
        manageRecords(records, capacity, timeout, &totalRecords);

        // process records (read or write)
        for (int i = 0; i < totalRecords; i++) {
            updateRecord(records[i], rand() % INT_MAX);
        }
    }

    return 0;
}
