    // Allocate memory for connections
    NetworkConnectionStatus* connections = (NetworkConnectionStatus*)malloc(initialCapacity * sizeof(NetworkConnectionStatus));
    if (!connections) return NULL;

    // Initialize connection indices
    int numConnections = 0;
    int capacity = initialCapacity;

    // Function to add new connections
    void addConnection(IPAddress ip, PortNumber port) {
        // Check for full array and reallocate if necessary
        if (numConnections >= capacity) {
            capacity *= 2; // Double the capacity for next time
            NetworkConnectionStatus* temp = (NetworkConnectionStatus*)realloc(connections, capacity * sizeof(NetworkConnectionStatus));
            if (!temp) return; // Handle allocation failure
            connections = temp;
        }

        // Add new connection to array
        connections[numConnections].ip = ip;
        connections[numConnections].port = port;
        connections[numConnections].state = ConnectionState::PENDING;
        numConnections++;
    }

    // Function to update existing connections
    void updateConnection(IPAddress ip, PortNumber port, ConnectionState state) {
        for (int i = 0; i < numConnections; i++) {
            if (connections[i].ip == ip && connections[i].port == port) {
                connections[i].state = state;
                return;
            }
        }
    }

    // Function to get number of active connections
    int getNumActiveConnections() {
        int count = 0;
        for (int i = 0; i < numConnections; i++) {
            if (connections[i].state == ConnectionState::CONNECTED) count++;
        }
        return count;
