    if (size <= 0 || max_key_range <= 0 || max_offset <= 0) {
        return NULL;
    }

    // Initialize arrays with sequential values starting from 0 up to the specified size
    long *offset_array = (long*)malloc(size * sizeof(long));
    int *key_array = (int*)malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
