    for (int i = 0; i < size; i++) {
        key_array[i] = rand() % max_key_range;
    }

    // Create an array of record structures
    record *records = (record*)malloc(size * sizeof(record));

    for (int i = 0; i < size; i++) {
        records[i].key = &key_array[i];
        records[i].offset = offset_array[i];
    }

    // Return the pointer to the array of record structures
    return records;
}

void free_allocated_memory(record *records) {
