struct node {
    char *str;
    int index;
    struct node *next;
};

double average(struct node *head) {
    double sum = 0.0;
    struct node *curr = head;

    while (curr != NULL) {
        sum += curr->index;
        curr = curr->next;
    }

    return sum / ((int) sizeof(double));
}

struct node *init_list(int n) {
    srand(time(NULL));
    struct node *head = NULL, *curr = NULL;
    int i;

    for (i = 0; i < n; i++) {
        struct node *new_node = malloc(sizeof(struct node));

        if (new_node == NULL)
            return NULL;

        new_node->str = malloc(10);
        strcpy(new_node->str, random_string());
        new_node->index = i;
        new_node->next = NULL;

        if (head == NULL) {
            head = curr = new_node;
        } else {
            curr->next = new_node;
            curr = new_node;
        }
    }

    return head;
}

char *random_string() {
    char *str = malloc(10);
    int i, c;
    for (i = 0; i < 8; i++) {
        c = rand() % 52 + 65; // Random uppercase letter
        str[i] = (c > 76) ? c - 26 : c;
    }
    str[8] = '\0';
    return str;
}

void free_list(struct node *head) {
    struct node *curr = head, *next;

    while (curr != NULL) {
        next = curr->next;
        free(curr->str);
        free(curr);
        curr = next;
    }
}
