#include <chrono>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <unordered_set>
#include <deque>

class Transaction {
public:
    double amount;
    std::string description;
    time_t timestamp;

    Transaction(double minAmount, double maxAmount) : 
        amount((minAmount + maxAmount) / 2.0), 
        description("Transaction " + std::to_string(amount)), 
        timestamp(std::time(nullptr)) {}
};

class TransactionManager {
public:
    std::deque<Transaction> transactions;
    std::unordered_map<double, Transaction*> cache;
    std::mutex mutex;

    void addTransaction(double minAmount, double maxAmount) {
        std::lock_guard<std::mutex> lock(mutex);
        Transaction* newTransaction = new Transaction(minAmount, maxAmount);
        transactions.push_back(*newTransaction);
        if (cache.size() > 1000) {
            // Evict infrequently accessed transactions
            evictInfrequentTransactions();
        }
    }

    void updateTransaction(double amount, double minAmount, double maxAmount) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& transaction : transactions) {
            if (transaction.amount == amount) {
                transaction.amount = ((minAmount + maxAmount) / 2.0);
                return;
            }
        }
    }

    Transaction* getTransaction(double amount) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(amount);
        if (it != cache.end()) {
            return it->second;
        } else {
            for (auto& transaction : transactions) {
                if (transaction.amount == amount) {
                    Transaction* transactionPtr = &transaction;
                    cache[amount] = transactionPtr;
                    return transactionPtr;
                }
            }
            // Handle API unavailability or network failures
            // ...
            return nullptr;
        }
    }

    int getTransactionCount() {
        std::lock_guard<std::mutex> lock(mutex);
        return transactions.size();
    }

private:
    void evictInfrequentTransactions() {
        // Implement eviction strategy based on transaction age, access frequency, etc.
        // For simplicity, remove oldest transactions
        while (transactions.size() > 1000) {
            transactions.pop_front();
        }
    }
};

