typedef struct {
    long offset;
    int key;
    char* identifier;
} Record;

int manage_memory(int max_records, size_t memory_limit) {
    Record** records = NULL;
    size_t record_count = 0;
    size_t total_memory_used = 0;

    while (record_count < max_records) {
        // Calculate the required memory for a new record
        size_t new_record_size = sizeof(Record) + strlen("ID_%d_%ld") + 1; // assuming timestamp format

        if (total_memory_used + new_record_size > memory_limit) {
            // Memory limit exceeded, free partially allocated resources and log the event
            for (int i = 0; i < record_count; i++) {
                free(records[i]->identifier);
            }
            free(records);
            printf("Memory allocation failed due to insufficient resources. Aborting.\n");
            return -1;
        }

        // Allocate memory for a new record and its identifier
        Record* new_record = realloc(NULL, sizeof(Record));
        records = realloc(records, (record_count + 1) * sizeof(Record*));
        if (!new_record || !records) {
            printf("Memory allocation failed. Aborting.\n");
            return -1;
        }

        // Initialize the record and its identifier
        new_record->offset = rand();
        new_record->key = rand() % INT_MAX;
        asprintf(&new_record->identifier, "ID_%d_%ld", record_count, time(NULL));
        new_record->identifier[strlen("ID_") + strlen("_%d_%ld") + 1] = '\0'; // remove the trailing null

        records[record_count] = new_record;
        total_memory_used += sizeof(Record) + strlen("ID_%d_%ld") + 1;

        record_count++;
    }

    for (int i = 0; i < record_count; i++) {
        free(records[i]->identifier);
    }
    free(records);

    return 0;
}
