void print_largest(int **arr, int *n) {
    if (*n == 0) {
        printf("No integers were found.\n");
        return;
    }

    int max = (**arr)[0];
    for (int i = 1; i < *n; i++) {
        if ((**arr)[i] > max) {
            max = (**arr)[i];
        }
    }

    printf("The largest integer is: %d\n", max);
}

void read_integers(int **arr, int *n, FILE *file) {
    fseek(file, 0, SEEK_END);
    size_t len = ftell(file);
    fseek(file, 0, SEEK_SET);

    *n = (int)(len / sizeof(int));

    if (*n > 100000) {
        printf("Array too large. Maximum size is 100000 integers.\n");
        exit(1);
    }

    *arr = (int *)malloc(*n * sizeof(int));
    if (*arr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    fread(*arr, sizeof(int), *n, file);

    if(ferror(file)) {
        fprintf(stderr, "Error reading from the network stream.\n");
        free(*arr);
        *arr = NULL;
        *n = 0;
    }
}

int main() {
    FILE *file = fopen("network_stream", "rb"); // Replace with your network stream
    int *arr = NULL;
    int n = 0;

    read_integers(&arr, &n, file);

    if(arr != NULL) {
        print_largest(&arr, &n);
        free(arr);
    }

    fclose(file);

    return 0;
}

