        networkConnections = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
        connectionsCount = 1;
    } else {
        NetworkConnectionStatus** temp = (NetworkConnectionStatus**)realloc(networkConnections, sizeof(NetworkConnectionStatus*) * (connectionsCount + 1));
        networkConnections = temp;
        networkConnections[connectionsCount++] = connection;
    }
}

void updateNetworkConnection(int index, NetworkConnectionStatus* connection) {
    if (index >= 0 && index < connectionsCount) {
        memcpy(&networkConnections[index], connection, sizeof(NetworkConnectionStatus));
    } else {
