        if (networkConnections[i].connectionState == DISCONNECTED && (getTickCount() - networkConnections[i].lastActivityTime > timeout)) {
            free(networkConnections[i]);
            connectionsCount--;
            memmove(&networkConnections[i], &networkConnections[i + 1], sizeof(NetworkConnectionStatus*) * (connectionsCount - i));
