    for (size_t i = 0; i < num_records; i++) {
        // Initialize PDF file
        if (*pdf_files[i] == NULL) {
            *pdf_files[i] = fopen("output.pdf", "wb");
            if (*pdf_files[i] == NULL) {
                printf("Error opening PDF file.\n");
                return 1;
            }
        }

        // Read JPEG file and write to PDF
        fwrite(records[i].unique_id, sizeof(char), strlen(records[i].unique_id), *pdf_files[i]);
        fflush(*pdf_files[i]);

        if (i % 10 == 0) {
            printf("Converted %zu records.\n", i);
        }
    }

    return 0;
}

int main() {
    const size_t MAX_RECORDS = 100000;
    const size_t MAX_PDF_FILES = 10;

    Record* records = (Record*) malloc(MAX_RECORDS * sizeof(Record));
    FILE** pdf_files = (FILE**) calloc(MAX_PDF_FILES, sizeof(FILE));

    // Initialize and populate records
    srand(time(NULL));
    for (size_t i = 0; i < MAX_RECORDS; i++) {
        Record* record = &records[i];
        record->offset = rand() % 100000;
        record->key = rand() % 10000;
        sprintf(record->unique_id, "record_%zu_%ld", i, time(NULL));
    }

    // Convert JPEGs to PDFs
    convert_jpeg_to_pdf(records, MAX_RECORDS, pdf_files);

    // Clean up
    for (size_t i = 0; i < MAX_PDF_FILES; i++) {
        fclose(pdf_files[i]);
    }
    free(records);
    free(pdf_files);

    return 0;
}
