    size_t capacity;
    size_t count;
} ConnectionArray;

// Initialize and manage the dynamic array
void init_connection_array(ConnectionArray* arr) {
    arr->connections = (NetworkConnectionStatus*)calloc(10, sizeof(NetworkConnectionStatus));
    arr->capacity = 10;
    arr->count = 0;
}

// Add a new connection to the array
int add_connection(ConnectionArray* arr, NetworkConnectionStatus conn) {
    if (arr->count >= arr->capacity) {
        // Double the capacity if full
        arr->connections = (NetworkConnectionStatus*)realloc(arr->connections, 2 * arr->capacity * sizeof(NetworkConnectionStatus));
        arr->capacity *= 2;
    }
    memcpy(&arr->connections[arr->count], &conn, sizeof(NetworkConnectionStatus));
    arr->count++;
    return 0;
}

// Update the state of an existing connection
int update_connection(ConnectionArray* arr, int index, enum { ESTABLISHED, FINISHED } state) {
    if (index >= arr->count || arr->connections[index].connection_state == state)
        return -1; // Not found or already in desired state
    arr->connections[index].connection_state = state;
    return 0;
}

// Get the number of active connections
int get_active_connections(ConnectionArray* arr) {
    int count = 0;
    for (size_t i = 0; i < arr->count; ++i)
        if (arr->connections[i].connection_state == ESTABLISHED)
            count++;
    return count;
}

// Log connection events with a logging framework
void log_connection_event(NetworkConnectionStatus conn) {
    // External logging framework implementation
}

int main() {
    ConnectionArray arr;
    init_connection_array(&arr);

    // Example usage: add and update connections
    NetworkConnectionStatus conn1 = {"192.168.0.1", 80, ESTABLISHED};
    add_connection(&arr, conn1);
    log_connection_event(conn1);

    NetworkConnectionStatus conn2 = {"192.168.0.2", 443, FINISHED};
    update_connection(&arr, arr.count - 1, FINISHED); // Update the last added connection
    log_connection_event(conn2);

    int active_connections = get_active_connections(&arr);
    printf("Active connections: %d\n", active_connections);

    return 0;
}
