#include <time.h>

typedef struct {
    int* values;
    int size;
} record;

record** manageMemory(int numRecords, int minValue, int maxValue, int valueSize) {
    // Initialize the arrays for offset values, keys, and records
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record** records = (record**)malloc(numRecords * sizeof(record*));

    // Generate random values for each record's array
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        // Initialize the record's array of int values
        record* currRecord = (record*)malloc(sizeof(record));
        currRecord->values = (int*)malloc(valueSize * sizeof(int));

        // Generate random values for this record
        for (int j = 0; j < valueSize; j++) {
            currRecord->values[j] = rand() % (maxValue - minValue) + minValue;
        }
        currRecord->size = valueSize;

        // Store the record's data and link it to its segment of memory
        offsets[i] = i * sizeof(record);
        keys[i] = i;
        records[i] = currRecord;
    }

    // Free all dynamically allocated memory upon function return
    for (int i = 0; i < numRecords; i++) {
        free(records[i]->values);
        free(records[i]);
    }
    free(keys);
    free(offsets);

    return records;
}
