#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int* key;
    long offset;
} record;

struct data_block {
    time_t timestamp;
};

record* manage_data_structures(int size, int num_keys, int num_blocks) {
    // Initialize the random number generator
    srand(time(NULL));

    // Allocate arrays for file offsets and unique keys
    long* offsets = aligned_alloc(size);
    int* keys = malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % size;
    }

    // Initialize the record array
    record* records = NULL;
    size_t total_records = 0;

    // Create data blocks and initialize timestamps
    struct data_block** blocks = malloc(num_blocks * sizeof(struct data_block*));
    for (int i = 0; i < num_blocks; i++) {
        blocks[i] = malloc(sizeof(struct data_block));
        blocks[i]->timestamp = time(NULL);
    }

    // Dynamically resize arrays as needed
    int capacity = size;
    long* new_offsets;
    int* new_keys;
    record* new_records;

    while (1) {
        // Resize arrays if necessary
        if (total_records >= capacity) {
            capacity *= 2; // Double the capacity for efficiency
            new_offsets = realloc(offsets, capacity * sizeof(long));
            new_keys = realloc(keys, num_keys * sizeof(int));
            new_records = realloc(records, total_records * sizeof(record));

            // Copy data from old arrays to new arrays
            memcpy(new_offsets, offsets, size * sizeof(long));
            memcpy(new_keys, keys, num_keys * sizeof(int));
            for (int i = 0; i < total_records; i++) {
                new_records[i].key = &new_keys[new_records[i].key - 1];
                new_records[i].offset = new_offsets[new_records[i].offset];
            }

            // Update pointers to point to the new arrays
            free(offsets);
            offsets = new_offsets;
            keys = new_keys;
            records = new_records;

            // Clear any excess capacity from previous resize
            total_records = size;
        }
    }

    // Merge blocks with overlapping timestamps into a single block
    for (int i = 0; i < num_blocks - 1; i++) {
        if (blocks[i]->timestamp > blocks[i + 1]->timestamp) {
            struct data_block* new_block = malloc(sizeof(struct data_block));
            new_block->timestamp = blocks[i]->timestamp;
            // Merge contents of blocks[i] and [i+1] into the new block
            free(blocks[i]);
            free(blocks[i + 1]);
            blocks[i] = new_block;
            num_blocks--;
        }
    }

    // Clean up and return the record array
    for (int i = 0; i < total_records; i++) {
        free(records[i].key);
    }
    free(records);
    for (int i = 0; i < num_blocks; i++) {
        free(blocks[i]);
    }
    free(blocks);

    // Free the random number generator
    rand();

    return records;
}

