typedef struct {
    int value;
} record;

void processRecords() {
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;

    offsets = (long *)malloc(sizeof(long));
    keys = (int *)malloc(sizeof(int));
    records = (record **)malloc(sizeof(record *));

    // allocate space for the arrays based on the number of records
    int numRecords;
    scanf("%d", &numRecords);
    if(numRecords < 1) {
        printf("Invalid number of records. Please enter a positive integer.\n");
        return;
    }

    offsets = (long *)realloc(offsets, sizeof(long) * numRecords);
    keys = (int *)realloc(keys, sizeof(int) * numRecords);
    records = (record **)realloc(records, sizeof(record *) * numRecords);

    for(int i=0; i<numRecords; i++) {
        // read and validate record data
        long offset;
        int key;
        scanf("%ld %d", &offset, &key);
        if(offset < 0 || key < 0) {
            printf("Invalid record data. Please enter positive integers.\n");
            return;
        }

        offsets[i] = offset;
        keys[i] = key;

        // create and initialize the record structure
        record *record = (record *)malloc(sizeof(record));
        record->value = key;
        records[i] = record;
    }

    // helper function to find the largest integer in the array
    int findLargestInt() {
        int max = 0;
        for(int i=0; i<numRecords; i++) {
            if(keys[i] > max) {
                max = keys[i];
            }
        }
        return max;
    }

    // print the largest integer
    printf("The largest integer is: %d\n", findLargestInt());

    // free allocated resources
    for(int i=0; i<numRecords; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    // logging statements to monitor performance and resource utilization
    printf("Memory usage: %lu KB\n", (unsigned long)(sizeof(long) + sizeof(int) + sizeof(record) * numRecords));
}

int main() {
    processRecords();
    return 0;
}
