#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char* id;
} Record;

Record* initRecords(int maxRecords, int memoryLimit) {
    Record* records = NULL;
    int i;

    // Initialize configuration
    srand(time(NULL));
    for (i = 0; i < maxRecords; i++) {
        // Allocate memory for each record
        char* id = malloc(32); // assuming unique ID length <= 32 bytes
        if (!id) return NULL; // handle allocation failure

        // Initialize record structure
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            free(id);
            return NULL;
        }

        record->offset = i;
        record->key = rand() % 1000; // generate random key
        strcpy(record->id, "record_"); // prefix with a unique identifier

        // Add to array of records
        if (!records) {
            records = (Record*)malloc(maxRecords * sizeof(Record));
            if (!records) return NULL;
        }

        records[i] = *record;

        // Monitor and control memory consumption
        if (getTotalMemoryUsage() > memoryLimit) {
            free(id);
            for (int j = 0; j < i; j++) {
                free(records[j].id);
                free(&records[j]);
            }
            return NULL;
        }
    }

    // Set environment variable with total memory usage
    setenv("MEMORY_USAGE", "Initialized");

    return records;
}
