Allocator* init_allocator(size_t initial_capacity) {
    Allocator* alloc = malloc(sizeof(Allocator));
    alloc->capacity = initial_capacity;
    alloc->used = 0;
    alloc->ptr = malloc(initial_capacity * sizeof(int));
    return alloc;
}

// Allocate memory for a new task using the custom allocator
void* allocate_task(Allocator* alloc) {
    void* ptr = alloc->ptr + alloc->used;
    alloc->used++;
    if (alloc->used >= alloc->capacity) {
        // Reallocate when reaching capacity to maintain efficient usage
        alloc->capacity *= 2;
        alloc->ptr = realloc(alloc->ptr, alloc->capacity * sizeof(int));
    }
    return ptr;
}

// Define the 'task' structure with priority level, string description, and deadline
