    int selectAttack(int level, std::string resources) {
        static std::once_flag once;
        std::call_once(once, initialize);

        // Validate input parameters
        if (level <= 0 || !resources.empty()) {
            return -1; // Invalid request
        }

        // Select an attack based on the character's level and available resources
        int selectedAttack = rand() % 2;

        // Cache the result to minimize calls to the service class
        static std::map<int, int> cache;
        auto it = cache.find(level);
        if (it != cache.end()) {
            return it->second; // Return cached result
        }

        // Simulate a database call (network latency)
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Update the cache with the selected attack
        cache[level] = selectedAttack;

        return selectedAttack;
    }

private:
