Record** init_transform(int num_records, int max_string_len, TransformationFunc func) {
    pthread_t threads[10]; // Initialize an array of 10 threads

    // Dynamically allocate memory for the Record array
    Record** record_array = (Record**)malloc(num_records * sizeof(Record*));

    for (int i = 0; i < num_records; i++) {
