    // Create a separate thread to transform each Record array
    for (int i = 0; i < num_records; i++) {
        pthread_create(&threads[i], NULL, transform_record, record_array[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_records; i++)
        pthread_join(threads[i]);

    return record_array;
