typedef struct {
    char *filePath;
    int bufferSize;
    // add more fields as needed
} Config;

Config processFilesAndData(Config config, void (*callback)(const char*)) {
    FILE *file = fopen(config.filePath, "r");
    if (!file) {
        return NULL;  // handle error
    }

    size_t fileSize = 0;
    fseek(file, 0L, SEEK_END);
    fileSize = ftell(file);
    rewind(file);

    char **lines = (char **)malloc((size_t)1 << 10);  // initial buffer size
    int lineCount = 0;

    char *buffer = (char *)malloc(config.bufferSize);
    if (!buffer) {
        fclose(file);
        return NULL;  // handle error
    }

    while (fgets(buffer, config.bufferSize, file)) {
        // trim whitespace from the beginning and end of each line
        size_t start = strspn(buffer, "\n\r\t ");
        size_t end = strlen(buffer) - strspn(&buffer[strlen(buffer) - 1], "\n\r\t ");
        buffer[start] = '\0';
        buffer[end] = '\0';

        // process the trimmed line using callback function
        callback(buffer);

        // increment line count and reallocate if necessary
        lineCount++;
        lines = (char **)realloc(lines, (size_t)(lineCount + 1) << 10);
    }

    fclose(file);

    free(buffer);

    // free the dynamically allocated memory for the array of strings
    for (int i = 0; i < lineCount; i++) {
        free(lines[i]);
    }
    free(lines);

    return config;
}
