#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_MAX 1024 // maximum number of records
#define MAX_CONCURRENT_OPS 10 // max concurrent operations allowed
#define BLOCK_LIST_SIZE 16 // size of fixed-size block list
#define STRING_LENGTH 256 // maximum string length

typedef struct {
    int key;
    char value[STRING_LENGTH];
} Record;

// custom memory allocator
void* my_malloc(size_t size) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static int blocks[BLOCK_LIST_SIZE];
    static int block_count = 0;
    static void** mem_blocks = NULL;

    pthread_mutex_lock(&lock);

    // check if pool is exhausted
    if (block_count == 0) {
        mem_blocks = (void**)malloc(BLOCK_LIST_SIZE * sizeof(void*));
        for (int i = 0; i < BLOCK_LIST_SIZE; i++) {
            mem_blocks[i] = NULL;
        }
        block_count = BLOCK_LIST_SIZE / (size + sizeof(int));
    }

    // reuse previously freed blocks
    int i;
    for (i = 0; i < block_count; i++) {
        if (mem_blocks[i] == NULL) {
            break;
        }
    }

    if (i >= block_count) {
        mem_blocks[block_count++] = malloc(size + sizeof(int));
        *(int*)mem_blocks[block_count - 1] = i;
    }

    void* ptr = mem_blocks[*(int*)mem_blocks[i]];
    mem_blocks[i] = NULL;

    pthread_mutex_unlock(&lock);
    return ptr;
}

void my_free(void* ptr) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static int blocks[BLOCK_LIST_SIZE];
    static int block_count = 0;
    static void** mem_blocks = NULL;

    pthread_mutex_lock(&lock);

    // update the pool
    int i, j;
    for (i = 0; i < block_count; i++) {
        if (mem_blocks[i] == ptr) {
            break;
        }
    }

    // handle edge case where record is freed but has not been initialized
    if (i >= block_count) {
        mem_blocks[block_count++] = ptr;
    } else {
        for (j = i; j < block_count - 1; j++) {
            mem_blocks[j] = mem_blocks[j + 1];
        }
        mem_blocks[--block_count] = NULL;
    }

    pthread_mutex_unlock(&lock);
}

// function to allocate memory and initialize records
Record* createRecords(size_t numRecords) {
    Record* records = my_malloc(numRecords * sizeof(Record));

    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < numRecords; i++) {
        records[i].key = rand() % RECORD_MAX;
        sprintf(records[i].value, "%d", records[i].key);
    }

    return records;
}

// function to handle memory errors
void my_error(const char* message) {
    printf("Error: %s\n", message);
    exit(1);
}

int main() {
    size_t numRecords = 10; // number of records to allocate

    Record* records = createRecords(numRecords);

    if (!records) {
        return 1;
    }

    // use the allocated memory
    for (size_t i = 0; i < numRecords; i++) {
        printf("Record %zu: key=%d, value=%s\n", i, records[i].key, records[i].value);
    }

    my_free(records);

    return 0;
}

