#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <time.h>

#define DNS_BATCH_SIZE 10
#define DNS_RETRY_LIMIT 3
#define MEMORY_THRESHOLD (1024 * 1024) // 1MB

typedef struct {
    time_t timestamp;
    char* ip_address;
    int num_values;
    double avg_value;
} LogEntry;

int dns_resolve(const char* hostname);
void process_log_file(const char* filename);

int main() {
    process_log_file("log.txt");
    return 0;
}

int dns_resolve(const char* hostname) {
    int retry_count = 0;
    struct in_addr result;
    while (retry_count < DNS_RETRY_LIMIT) {
        if (gethostbyname(hostname) != NULL) {
            return 0;
        }
        // Handle rate limiting by queuing additional requests
        if (retry_count > 0) {
            sleep(1); // wait for 1 second before retrying
        }
        retry_count++;
    }
    return -1; // DNS resolution failed
}

void process_log_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    fseek(file, 0L, SEEK_END);
    long file_size = ftell(file);
    if (file_size > MEMORY_THRESHOLD) {
        // Truncate the file to the specified size
        int truncated_size = (int)MEMORY_THRESHOLD;
        fseek(file, 0L, SEEK_SET);
        fwrite("..." , sizeof(char), 3, file); // truncate file with ...
        file_size = MEMERY_THRESHOLD; // update file size
    }

    LogEntry* log_entry = malloc(sizeof(LogEntry));
    while (!feof(file)) {
        if (fscanf(file, "%ld %s %d", &log_entry->timestamp, log_entry->ip_address, &log_entry->num_values) != 3) {
            break;
        }

        // Calculate average of the last five numerical values
        double sum = 0.0;
        for (int i = 0; i < log_entry->num_values && i < 5; i++) {
            sum += atoi(log_entry->ip_address + strlen(log_entry->ip_address) - i);
        }
        log_entry->avg_value = sum / log_entry->num_values;

        // Perform DNS resolution in batches
        int dns_batch_size = MIN(DNS_BATCH_SIZE, log_entry->num_values);
        for (int i = 0; i < log_entry->num_values; i += dns_batch_size) {
            int batch_result = dns_resolve(log_entry->ip_address + strlen(log_entry->ip_address) - i - 1);
            if (batch_result == -1) {
                // Log DNS resolution error and skip this entry
                fprintf(stderr, "DNS resolution failed for %s\n", log_entry->ip_address);
                free(log_entry);
                log_entry = malloc(sizeof(LogEntry));
                continue;
            }
        }

        // Print processed log entry
        printf("%ld %s %.2f\n", log_entry->timestamp, log_entry->ip_address, log_entry->avg_value);

        free(log_entry);
        log_entry = malloc(sizeof(LogEntry));
    }

    fclose(file);
}
