typedef struct {
    int key;
    long offset;
} Record;

Record** dataset = NULL;
int dataset_size = 0;
int* parent = NULL;
int* size = NULL;

void init_dataset(int n) {
    dataset = (Record**)malloc(n * sizeof(Record*));
    for (int i = 0; i < n; i++) {
        dataset[i] = NULL;
    }
}

void add_record(int index, int key, long offset) {
    if (index >= dataset_size) {
        return;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    dataset[index] = record;
}

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void union_sets(int x, int y) {
    int root_x = find(x);
    int root_y = find(y);
    if (root_x == root_y) return;
    if (size[root_x] < size[root_y]) {
        size[root_x] += size[root_y];
        parent[root_y] = root_x;
    } else {
        size[root_x] += size[root_y];
        parent[root_y] = root_x;
    }
}

void process_batch() {
    int total_time = 0;
    for (int i = 0; i < dataset_size; i++) {
        if (!dataset[i]) continue;
        Record* record = dataset[i];
        // Process the record, calculate time taken
        struct timeval start, end;
        gettimeofday(&start, NULL);
        // processing logic here...
        gettimeofday(&end, NULL);
        int time_taken = (int)((end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000);
        total_time += time_taken;
    }
    double average_time = (double)total_time / dataset_size;
    printf("Average time taken: %.2f ms\n", average_time);
}

void clean_up() {
    for (int i = 0; i < dataset_size; i++) {
        if (!dataset[i]) continue;
        Record* record = dataset[i];
        free(record);
    }
    free(dataset);
    free(parent);
    free(size);
}

int main() {
    int n = 100; // initial capacity
    init_dataset(n);

    for (int i = 0; i < 10; i++) { // process batches of records
        add_record(i, i + 1, i * 1024); // example record addition
    }

    // identify disjoint sets using Union-Find algorithm
    int* set_size = (int*)malloc(dataset_size * sizeof(int));
    parent = (int*)malloc(dataset_size * sizeof(int));
    size = (int*)malloc(dataset_size * sizeof(int));
    for (int i = 0; i < dataset_size; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    for (int i = 0; i < dataset_size; i++) {
        for (int j = i + 1; j < dataset_size; j++) {
            if (!dataset[i] || !dataset[j]) continue;
            // check if the records belong to the same set
            int root_x = find(i);
            int root_y = find(j);
            if (root_x == root_y) continue;
            union_sets(root_x, root_y);
        }
    }

    process_batch();

    clean_up();

    return 0;
}
