import yaml
import multiprocessing
import logging
from healthmon import HealthMonitor
import time
import requests
import json

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = yaml.safe_load(f)
    except (FileNotFoundError, yaml.YAMLError) as e:
        logging.error(f"Failed to load configuration from {config_file}: {e}")
        config = {}
    return config

def perform_health_checks(service_name, check_func, concurrencyLevel=10, retry_attempts=3):
    try:
        with open('health_config.yml', 'r') as f:
            health_config = yaml.safe_load(f)
    except FileNotFoundError:
        logging.warning("No configuration file found. Falling back to default settings.")
        health_config = {}

    if not health_config.get('services'):
        health_config['services'] = []

    health_config['services'].append({'name': service_name, 'checks': []})

    checks_queue = multiprocessing.Queue()
    for _ in range(concurrencyLevel):
        checks_queue.put(None)

    def worker(queue):
        while True:
            check_func(service_name)
            queue.get()

    processes = []
    for _ in range(concurrencyLevel):
        p = multiprocessing.Process(target=worker, args=(checks_queue,))
        p.start()
        processes.append(p)

    for p in processes:
        p.join()

    logging.info("Health checks completed.")

def main():
    service_name = "example_service"
    check_func = lambda: print(f"{service_name} is running")

    perform_health_checks(service_name, check_func)
