#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>

class UserSession {
public:
    int UserID;
    long LastActiveTime;
    enum class SessionState { Active, Idle, Terminated };
};

class SessionManager {
private:
    std::list<UserSession> sessions;
    std::unordered_map<int, std::list<UserSession>::iterator> sessionMap;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addSession(int userID, long lastActiveTime, UserSession::SessionState state) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            sessions.emplace_back(UserSession{userID, lastActiveTime, state});
            sessionMap[userID] = --sessions.end();
        }
        cv.notify_all();
    }

    void updateSession(int userID, long lastActiveTime, UserSession::SessionState state) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            for (auto it = sessionMap.find(userID); it != sessionMap.end(); ++it) {
                if (it->second != sessions.end() && it->second->LastActiveTime == lastActiveTime) {
                    it->second->LastActiveTime = lastActiveTime;
                    it->second->SessionState = state;
                    break;
                }
            }
        }
    }

    int getActiveSessionsCount() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            int activeSessions = 0;
            for (const auto& session : sessions) {
                if (session.SessionState == UserSession::SessionState::Active)
                    ++activeSessions;
            }
            return activeSessions;
        }
    }

    void garbageCollect() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            sessions.remove_if([](const auto& session) {
                return session.LastActiveTime + 3600 < time(nullptr); // remove expired sessions
            });
        }
    }
};

int main() {
    SessionManager manager;

    return 0;
}

