record* initializeRecords(int numRecords, int maxMemoryUsage) {
    // Allocate memory for the records array
    record* records = (record*)malloc(numRecords * sizeof(record));

    // Initialize the records with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100;
    }

    return records;
}

unsigned char* computeMD5Hash(const char* inputString) {
    // Compute the MD5 hash of the provided string using a standard library function
    unsigned char* md5Hash = (unsigned char*)malloc(16);
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, inputString, strlen(inputString));
    MD5_Final(md5Hash, &ctx);

    return md5Hash;
}

int countDisjointPairs(int** integerArrays) {
    // Initialize the Union-Find data structure
    int numElements = 0;
    for (int i = 0; i < sizeof(integerArrays) / sizeof(integerArrays[0]); i++) {
        numElements += sizeof(integerArrays[i]) / sizeof(integerArrays[i][0]);
    }

    // Count the number of disjoint pairs using Union-Find
    int* parent = (int*)malloc(numElements * sizeof(int));
    for (int i = 0; i < numElements; i++) {
        parent[i] = i;
    }
    for (int i = 0; i < sizeof(integerArrays) / sizeof(integerArrays[0]); i++) {
        for (int j = 0; j < sizeof(integerArrays[i]) / sizeof(integerArrays[i][0]); j++) {
            int val1 = integerArrays[i][j];
            int val2 = integerArrays[(i + 1) % sizeof(integerArrays)] [(j + 1) % sizeof(integerArrays[i])];
            if (val1 != val2) {
                // Perform union operation
                int root1 = find(parent, val1);
                int root2 = find(parent, val2);
                parent[root1] = root2;
            }
        }
    }

    // Count the number of disjoint pairs
    int disjointPairs = 0;
    for (int i = 0; i < numElements; i++) {
        if (parent[i] == i) {
            disjointPairs++;
        }
    }

    return disjointPairs;
}

int find(int* parent, int val) {
    // Find the root of a node in the Union-Find data structure
    if (parent[val] != val) {
        parent[val] = find(parent, parent[val]);
    }
    return parent[val];
}

