        clock_gettime(CLOCK_REALTIME, &end);
        total_latency += (double)(end.tv_sec - start.tv_sec) + ((double)(end.tv_nsec - start.tv_nsec) / 1000000000.0);
    }
    printf("Total latency: %f seconds\n", total_latency);

    // Task 5: Handle edge cases and invalid input
    if (num_arrays == 0 || arrays[0][1] <= 0) {
        printf("Invalid input data.\n");
        return -1;
    }

    // Generate a summary of the time taken for each part
    double total_time_taken = time_taken + union_find_time_taken + total_latency;
    printf("Total time taken: %f seconds\n", total_time_taken);
