        if (!sorted) {
            // If no sorting was applied, simply calculate and print the average value for this stream
            float avg = average(stream->numbers, stream->size);
            printf("Average: %.2f\n", avg);

            free(stream->numbers);
            free(stream);
        }
    }

    return 0;
}

// Helper function to compare two floating-point numbers
