    pthread_mutex_lock(&list->lock);
    if (pthread_mutex_trylock(&list->lock)) {
        // Concurrency handling: handle concurrent requests by waiting or backing off
        pthread_cond_wait(&list->cond, &list->lock);
    }
    for (int i = 0; i < list->count; ++i) {
        if (strcmp(list->files[i].name, name) == 0) {
            // Version control: increment version number for existing files
            list->files[i].version++;
            return;
        }
