        // Storage management: resize the list when it reaches capacity
        int new_capacity = list->capacity * 2;
        MediaFile* temp_files = (MediaFile*)realloc(list->files, new_capacity * sizeof(MediaFile));
        list->files = temp_files;
        list->capacity = new_capacity;
    }
    list->files[list->count] = *new_file;
    ++list->count;
    pthread_mutex_unlock(&list->lock);
}

