#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <memory>
#include <pugixml.hpp>

struct Record {
    int value;
};

class ConfigReader {
public:
    ConfigReader(const std::string& filename) : filename_(filename) {}

    void loadConfig() {
        pugi::xml_parse_result result = doc_.load_file(filename_.c_str());
        if (!result) {
            std::cerr << "Error parsing XML: " << result.description << "\n";
            return;
        }

        worldWidth_ = doc_.find_child("world").attribute("width").as_int(0);
        worldHeight_ = doc_.find_child("world").attribute("height").as_int(0);

        tileSize_ = doc_.find_child("tile").attribute("size").as_int(0);

        cameraSpeed_ = doc_.find_child("camera").attribute("speed").as_int(0);

        try {
            recordArray_ = std::make_unique<std::vector<Record>>();
            intArray_ = std::make_unique<std::vector<int>>();

            pugi::xml_node recordsNode = doc_.child("records");
            for (pugi::xml_node& recordNode : recordsNode.children("record")) {
                Record rec;
                rec.value = recordNode.attribute("value").as_int(0);
                (*recordArray_).push_back(rec);

                int key = recordNode.attribute("key").as_int(-1);
                if (key >= 0) {
                    (*intArray_).push_back(key);
                }
            }

            offsetArray_ = std::make_unique<std::vector<long>>();
            for (int i = 0; i < worldWidth_; ++i) {
                for (int j = 0; j < worldHeight_; ++j) {
                    long offset = doc_.find_child("world").attribute("offset").as_long(i * tileSize_);
                    (*offsetArray_).push_back(offset);
                }
            }

        } catch (...) {
            std::cerr << "Error loading config: " << std::strerror(errno) << "\n";
        }
    }

    ~ConfigReader() {
        for (auto& offset : *offsetArray_) {
            delete &offset;
        }
        (*intArray_).clear();
        (*recordArray_).clear();
    }

private:
    pugi::xml_document doc_;
    std::string filename_;
    int worldWidth_, worldHeight_, tileSize_, cameraSpeed_;
    std::unique_ptr<std::vector<Record>> recordArray_;
    std::unique_ptr<std::vector<int>> intArray_;
    std::unique_ptr<std::vector<long>> offsetArray_;
};

int main() {
    ConfigReader reader("config.xml");
    reader.loadConfig();

    return 0;
}
