public class MD5Service {
    private static final int CACHE_SIZE = 10000; // 10,000 strings
    private static Map<String, String> cache = new HashMap<>();
    private static long hitCount = 0;
    private boolean cachingEnabled = true;

    public String processStrings(List<String> inputStrings) throws IOException {
        JSONArray outputArray = new JSONArray();

        for (String string : inputStrings) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(string.getBytes());

                // Caching logic
                String cacheKey = getCacheKey(string);
                if (cachingEnabled && cache.containsKey(cacheKey)) {
                    hitCount++;
                    outputArray.put(new JSONObject().put("hash", cache.get(cacheKey)).put("type", "MD5").put("sourceFile", "").put("lineNumber", ""));
                } else {
                    String hash = bytesToHex(hashBytes);
                    outputArray.put(new JSONObject().put("hash", hash).put("type", "MD5").put("sourceFile", "").put("lineNumber", ""));

                    // Cache the result
                    if (cachingEnabled && cache.size() < CACHE_SIZE) {
                        cache.put(cacheKey, hash);
                    }
                }
            } catch (NoSuchAlgorithmException e) {
                throw new IOException("Error hashing string: " + e.getMessage());
            }
        }

        return outputArray.toString();
    }

    private String getCacheKey(String string) {
        // Implement a suitable caching key generation algorithm
        return null;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public void enableCaching(boolean enabled) {
        cachingEnabled = enabled;
    }

    public long getHitCount() {
        return hitCount;
    }
}
