        {
            // Validate the request
            if (!IsValidUpdateRequest(pageSectionId, elementId, htmlContent))
            {
                return "Invalid update request";
            }

            // Sanitize the HTML content
            htmlContent = SanitizeHtml(htmlContent);

            // Send the POST request to the external content management service
            HttpResponseMessage response = await _httpClient.PostAsync("https://content-management-service.com/update", new StringContent(htmlContent, Encoding.UTF8, "text/html"));

            if (response.IsSuccessStatusCode)
            {
                // Log the modification
                _logger.LogInformation($"Page section {pageSectionId} updated successfully");

                return "Page refreshed";
            }
            else
            {
                // Handle exceptions gracefully
                _logger.LogError($"Failed to update page section {pageSectionId}: {response.StatusCode}");
                return "Error updating page content";
            }
        }
        catch (Exception ex)
        {
            // Log the exception
            _logger.LogError("Error handling async HTTP POST request", ex);
            return "Error handling async HTTP POST request";
        }
