// Custom memory allocator with best-fit and first-fit strategies
class MemoryAllocator {
public:
    MemoryAllocator() : bestFitAllocator(), firstFitAllocator() {}

    void* allocate(size_t size) {
        if (bestFitAllocator.allocate(size)) return bestFitAllocator.getAddress();
        else if (firstFitAllocator.allocate(size)) return firstFitAllocator.getAddress();
        return nullptr;
    }

    void deallocate(void* address, size_t size) {
        if (bestFitAllocator.deallocate(address, size))
            firstFitAllocator.free(bestFitAllocator.getAddress());
        else
            bestFitAllocator.free(bestFitAllocator.getAddress());
    }

private:
    class BestFitAllocator {
    public:
        bool allocate(size_t size) {
            if (!allocatedBlocks.empty()) {
                allocatedBlocks.sort([](auto& block1, auto& block2) {
                    return block2.second < block1.second;
                });
                for (auto& block : allocatedBlocks) {
                    if (block.first >= size) {
                        block.second -= size;
                        return true;
                    }
                }
            }
            return false;
        }

        void deallocate(void* address, size_t size) {
            for (auto it = allocatedBlocks.begin(); it != allocatedBlocks.end(); ++it) {
                if (*((size_t*)address) == it->first && size == it->second) {
                    it = allocatedBlocks.erase(it);
                    return;
                }
            }
        }

        void free(void* address) {
            for (auto& block : allocatedBlocks) {
                if (*((size_t*)address) == block.first)
                    block.second += ((size_t*)address)[1];
            }
        }

        size_t getAddress() {
            return *(size_t*)allocatedBlocks.back().first;
        }

    private:
        struct AllocationBlock {
            size_t address;
            size_t size;
        };
        std::vector<AllocationBlock> allocatedBlocks;
    };

    class FirstFitAllocator {
    public:
        bool allocate(size_t size) {
            if (!allocatedBlocks.empty()) {
                for (auto& block : allocatedBlocks) {
                    if (block.size >= size) {
                        block.size -= size;
                        return true;
                    }
                }
            }
            return false;
        }

        void deallocate(void* address, size_t size) {
            for (auto it = allocatedBlocks.begin(); it != allocatedBlocks.end(); ++it) {
                if (*((size_t*)address) == it->first && size == it->second) {
                    it = allocatedBlocks.erase(it);
                    return;
                }
            }
        }

        void free(void* address) {
            for (auto& block : allocatedBlocks) {
                if (*((size_t*)address) == block.first)
                    block.size += ((size_t*)address)[1];
            }
        }

