// Define a structure to represent a network connection status
typedef struct {
    char ip_address[16];
    int port_number;
    enum {
        CONNECTED,
        DISCONNECTED,
        TIMEOUT
    } connection_state;
} NetworkConnectionStatus;

// Define a library structure to manage a collection of connections
typedef struct {
    // Use a doubly-linked list for efficient insertion and deletion
    struct ConnectionNode* head;
    struct ConnectionNode* tail;
    pthread_mutex_t mutex;
} ConnectionLibrary;

// Define a node for the doubly-linked list
typedef struct ConnectionNode {
    NetworkConnectionStatus connection;
    struct ConnectionNode* next;
    struct ConnectionNode* prev;
} ConnectionNode;

// Function to create a new connection library
ConnectionLibrary* connection_library_init() {
    ConnectionLibrary* lib = (ConnectionLibrary*)malloc(sizeof(ConnectionLibrary));
    lib->head = NULL;
    lib->tail = NULL;
    pthread_mutex_init(&lib->mutex, NULL);
    return lib;
}

// Function to add a new network connection to the library
void connection_library_add(ConnectionLibrary* lib, NetworkConnectionStatus* connection) {
    ConnectionNode* node = (ConnectionNode*)malloc(sizeof(ConnectionNode));
    node->connection = *connection;
    node->next = NULL;
    node->prev = lib->tail;

    if (lib->head == NULL) {
        lib->head = node;
    } else {
        lib->tail->next = node;
    }

    lib->tail = node;
    pthread_mutex_unlock(&lib->mutex);
}

// Function to update the state of an existing connection
void connection_library_update(ConnectionLibrary* lib, NetworkConnectionStatus* connection) {
    ConnectionNode* current = lib->head;
    while (current != NULL) {
        if (memcmp(&current->connection, connection, sizeof(NetworkConnectionStatus)) == 0) {
            // Update the state of the matching connection
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lib->mutex);
}

// Function to remove a network connection from the library
void connection_library_remove(ConnectionLibrary* lib, NetworkConnectionStatus* connection) {
    ConnectionNode* current = lib->head;
    while (current != NULL) {
        if (memcmp(&current->connection, connection, sizeof(NetworkConnectionStatus)) == 0) {
            // Remove the matching connection from the list
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                lib->head = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                lib->tail = current->prev;
            }

            free(current);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lib->mutex);
}

// Function to get the total number of active connections
int connection_library_count_active(ConnectionLibrary* lib) {
    int count = 0;
    ConnectionNode* current = lib->head;
    while (current != NULL) {
        if (current->connection.connection_state == CONNECTED) {
            count++;
        }
        current = current->next;
    }
    return count;
}

// Function to periodically scan and close inactive connections
void connection_library_gc(ConnectionLibrary* lib, int interval) {
    // Implement the garbage collection logic here
}

int main() {
    ConnectionLibrary* lib = connection_library_init();
    NetworkConnectionStatus* conn1 = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    *conn1 = (NetworkConnectionStatus){.ip_address = "192.168.0.1", .port_number = 8080, .connection_state = CONNECTED};
    connection_library_add(lib, conn1);

    NetworkConnectionStatus* conn2 = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    *conn2 = (NetworkConnectionStatus){.ip_address = "192.168.0.2", .port_number = 8081, .connection_state = DISCONNECTED};
