// Part 1: JavaScript Application
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

class FileLoader {
  constructor() {
    this.files = [];
    this.cachedFiles = {};
  }

  loadFiles(files) {
    return Promise.all(
      files.map((file) => {
        return new Promise((resolve, reject) => {
          fs.readFile(file, (err, data) => {
            if (err) {
              reject(err);
            } else {
              resolve(data.toString());
            }
          });
        }).then((jsCode) => {
          const script = document.createElement('script');
          script.textContent = jsCode;
          document.head.appendChild(script);
          this.files.push(file);
        });
      })
    );
  }

  executeFiles() {
    return new Promise((resolve, reject) => {
      const promises = this.files.map((file) => {
        return new Promise((resolve, reject) => {
          spawn('node', [file], (err, stdout, stderr) => {
            if (err) {
              reject(err);
            } else {
              resolve(stdout.toString());
            }
          });
        });
      });

      Promise.all(promises).then((results) => {
        resolve(results.join('\n'));
      }).catch((error) => {
        reject(error);
      });
    });
  }

  modifyFileExtension(filename) {
    const baseName = path.basename(filename, path.extname(filename));
    const extension = path.extname(filename);

    let modifiedExtension;
    for (let i = 1; ; i++) {
      modifiedExtension = `${extension}${i}`;
      if (!this.files.find((file) => file.endsWith(modifiedExtension))) {
        return `${baseName}${modifiedExtension}`;
      }
    }
  }

  analyzeFileCharacters(filename) {
    const characters = filename.replace(/[0-9]/g, '').replace(/_/g, '');
    let type;
    switch (true) {
      case /json/.test(characters):
        type = 'json';
        break;
      case /xml/.test(characters):
        type = 'xml';
        break;
      default:
        type = 'txt';
    }
    return type;
  }
}

// Part 2: C Function
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* modify_file_extension(const char* filename) {
    const char* base_name = strstr(filename, ".");
    if (!base_name) {
        return NULL;
    }

    char* modified_filename = (char*)malloc(strlen(filename) + 10);
    strcpy(modified_filename, filename);

    int i = 1;
    while (1) {
        sprintf(modified_filename + strlen(base_name), "_%d", i++);
        if (!strstr(modified_filename, base_name)) {
            break;
        }
    }

    return modified_filename;
}

