typedef struct item {
    char* market_data;
    int timestamp;
} Item;

typedef struct list {
    Item* items;
    int size;
    int capacity;
} List;

List* list_create(int initial_capacity) {
    List* list = (List*) malloc(sizeof(List));
    list->items = (Item*) calloc(initial_capacity, sizeof(Item));
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void list_destroy(List* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->items[i].market_data);
    }
    free(list->items);
    free(list);
}

void list_add_item(List* list, Item item) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->items = (Item*) realloc(list->items, list->capacity * sizeof(Item));
    }
    list->items[list->size] = item;
    list->size++;
}

void list_remove_item(List* list, int timestamp) {
    for (int i = 0; i < list->size; i++) {
        if (list->items[i].timestamp == timestamp) {
            for (int j = i + 1; j < list->size; j++) {
                list->items[j - 1] = list->items[j];
            }
            free(list->items[--list->size].market_data);
            list->items[list->size] = (Item){ NULL, 0 };
        }
    }
}

void list_print_items(List* list) {
    for (int i = 0; i < list->size; i++) {
        printf("Timestamp: %d, Market Data: %s\n", list->items[i].timestamp, list->items[i].market_data);
    }
}
