    int timestamp;
    char interface_id[16];
    int error_code;
    char** event_tags;
} NetworkInterfaceStatus;

int network_interface_status_update(int timestamp, const char* interface_id, int error_code, const char** event_tags) {
    NetworkInterfaceStatus* status = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
    if (!status) return -1; // Handle memory allocation failure

    status->timestamp = timestamp;
    strcpy(status->interface_id, interface_id);
    status->error_code = error_code;

    int tag_count = 0;
    for (const char** event_tag = event_tags; *event_tag; event_tag++) {
        tag_count++;
    }

    status->event_tags = (char**)malloc((tag_count + 1) * sizeof(char*));
    if (!status->event_tags) return -2; // Handle memory allocation failure

    int i;
    for (const char** event_tag = event_tags, i = 0; *event_tag; event_tag++, i++) {
        status->event_tags[i] = (char*)malloc(strlen(*event_tag) + 1);
        strcpy(status->event_tags[i], *event_tag);
    }

    status->event_tags[tag_count] = NULL;

    return 0;
}

int network_interface_status_free(NetworkInterfaceStatus* status) {
    if (!status) return -1; // Handle null pointer

    for (int i = 0; status->event_tags[i]; i++) {
        free(status->event_tags[i]);
    }
    free(status->event_tags);

    free(status);
    return 0;
}

int main() {
    int timestamp = 1643723400;
    const char* interface_id = "eth0";
    int error_code = 0;
    const char* event_tags[] = {"TAG1", "TAG2"};
    network_interface_status_update(timestamp, interface_id, error_code, event_tags);

    NetworkInterfaceStatus* status = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
    // Use the allocated memory...
    network_interface_status_free(status);

    return 0;
}
