        entries = new_entry;

        entries[i].path = malloc(strlen(buffer) + 1);
        strcpy(entries[i].path, buffer);
        entries[i].exists = 0;

        i++;
    }

    for (int j = 0; j < i; j++) {
        struct stat sb;
        if (stat(entries[j].path, &sb) == -1) {
            fprintf(stderr, "Error accessing file: %s\n", entries[j].path);
            free(entries[j].path);
            continue;
        }

        if (!follow_symlinks && S_ISLNK(sb.st_mode)) {
            // Ignore symbolic links
            free(entries[j].path);
            continue;
        }

        entries[j].exists = 1;
    }

