#define MAX_CONNECTIONS 1000
#define SCAN_INTERVAL 60 // seconds
#define DYNAMIC_THRESHOLD 0.8 // fraction of active connections

typedef struct NetworkConnectionStatus {
    char ip_address[16];
    int port_number;
    enum ConnectionState { ESTABLISHED, CLOSED } state;
} NetworkConnectionStatus;

enum ConnectionState {
    ESTABLISHED,
    CLOSED
};

// Forward declarations
void add_connection(NetworkConnectionStatus* conn);
void update_connection(NetworkConnectionStatus* conn);
void remove_connection(int index);
int get_total_active_connections();
void scan_and_close_inactive_connections();

typedef struct ConnectionList {
    NetworkConnectionStatus connections[MAX_CONNECTIONS];
    int size;
    pthread_mutex_t mutex;
} ConnectionList;

// Global connection list
ConnectionList global_connections = {0};

void add_connection(NetworkConnectionStatus* conn) {
    pthread_mutex_lock(&global_connections.mutex);
    // Add new connection to the end of the list
    for (int i = 0; i < MAX_CONNECTIONS - 1; i++) {
        if (global_connections.connections[i].state == ConnectionState::CLOSED) {
            global_connections.connections[i] = *conn;
            break;
        }
    }
    pthread_mutex_unlock(&global_connections.mutex);
}

void update_connection(NetworkConnectionStatus* conn) {
    pthread_mutex_lock(&global_connections.mutex);
    // Find and update the connection
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (strcmp(global_connections.connections[i].ip_address, conn->ip_address) == 0 &&
            global_connections.connections[i].port_number == conn->port_number) {
            global_connections.connections[i] = *conn;
            break;
        }
    }
    pthread_mutex_unlock(&global_connections.mutex);
}

void remove_connection(int index) {
    pthread_mutex_lock(&global_connections.mutex);
    // Remove the connection at the specified index
    for (int i = index; i < MAX_CONNECTIONS - 1; i++) {
        global_connections.connections[i] = global_connections.connections[i + 1];
    }
    global_connections.size--;
    pthread_mutex_unlock(&global_connections.mutex);
}

int get_total_active_connections() {
    int count = 0;
    pthread_mutex_lock(&global_connections.mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (global_connections.connections[i].state == ConnectionState::ESTABLISHED) {
            count++;
        }
    }
    pthread_mutex_unlock(&global_connections.mutex);
    return count;
}

void scan_and_close_inactive_connections() {
    // Check the current network load and server resources
    double threshold = DYNAMIC_THRESHOLD * get_total_active_connections();
    int inactive_count = 0;

    pthread_mutex_lock(&global_connections.mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (global_connections.connections[i].state == ConnectionState::ESTABLISHED) {
            // Check the connection's activity level
            double activity_level = calculate_activity_level();
            if (activity_level < threshold) {
                inactive_count++;
                global_connections.connections[i].state = ConnectionState::CLOSED;
            }
        }
    }
    pthread_mutex_unlock(&global_connections.mutex);

    // Periodically close inactive connections to optimize resource usage
    for (int i = 0; i < inactive_count; i++) {
        remove_connection(0); // Remove the first inactive connection
    }
}

// Function to calculate activity level of a connection
double calculate_activity_level() {
    // Implement your logic here
    return 0.5;
}
