#define MAX_CONCURRENT_RECORDS 5000
#define MAX_RECORD_SIZE 1024
#define BLOCK_SIZE 4096
#define COMPACT_INTERVAL 1000 // adjust this value based on your system's requirements

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C
} event_type;

struct record {
    long offset;
    int key;
    struct record *data;
    char buffer[MAX_RECORD_SIZE];
    event_type type;
};

struct memory_block {
    void *ptr;
    size_t size;
    struct memory_block *next;
};

sem_t semaphore;

void* my_malloc(size_t size) {
    static struct memory_block *free_blocks = NULL, **prev_free_blocks = &free_blocks;
    if (size > BLOCK_SIZE || !free_blocks) {
        return malloc(size);
    }
    void *ptr = free_blocks->ptr;
    *prev_free_blocks = free_blocks->next;
    free_blocks = free_blocks->next;
    return ptr;
}

void my_free(void* ptr, size_t size) {
    struct memory_block *new_block = (struct memory_block*)malloc(sizeof(struct memory_block));
    new_block->ptr = ptr;
    new_block->size = size;
    new_block->next = free_blocks;
    prev_free_blocks = &free_blocks;
    free_blocks = new_block;
}

void compact_memory() {
    struct memory_block *curr = free_blocks, *prev = NULL;
    while (curr) {
        void *ptr = curr->ptr;
        size_t size = curr->size;
        if (!prev) {
            prev = &free_blocks;
            free_blocks = curr->next;
        } else {
            prev->next = curr->next;
        }
        curr = curr->next;
    }
}

void log_memory_usage() {
    // implement your logging mechanism here
}

int main() {
    pthread_t thread;
    sem_init(&semaphore, 0, MAX_CONCURRENT_RECORDS);

    // allocate memory for the record structure
    struct record *record = (struct record*)my_malloc(sizeof(struct record));
    record->offset = 1234; // example value
    record->key = 4567; // example value

    // deallocate the allocated memory
    my_free(record, sizeof(struct record));

    while (1) {
        sem_wait(&semaphore);

        // allocate and use a block of memory
        void *ptr = my_malloc(BLOCK_SIZE);
        // use ptr for your purposes

        // release the semaphore
        sem_post(&semaphore);

        if (COMPACT_INTERVAL < rand() % 1000) {
            compact_memory();
        }
    }

    return 0;
}
