packet_t** allocate_packet_array(size_t num_packets) {
    packet_t** packet_arr = (packet_t**)malloc(num_packets * sizeof(packet_t*));
    if (!packet_arr) {
        return NULL;  // Memory allocation failed
    }

    for (size_t i = 0; i < num_packets; i++) {
        packet_arr[i] = (packet_t*)malloc(sizeof(packet_t));
        if (!packet_arr[i]) {
            // Free previously allocated packets and return error
            for (size_t j = 0; j < i; j++) {
                free(packet_arr[j]);
            }
            free(packet_arr);
            return NULL;
        }
    }

    return packet_arr;
}

void deallocate_packet_array(packet_t** packet_arr, size_t num_packets) {
    for (size_t i = 0; i < num_packets; i++) {
        if (packet_arr[i]->payload) {
            free(packet_arr[i]->payload);
        }
        free(packet_arr[i]);
    }
    free(packet_arr);
}

int initialize_packet_array(packet_t** packet_arr, size_t num_packets) {
    for (size_t i = 0; i < num_packets; i++) {
        // Initialize IP addresses
        if (!inet_pton(AF_INET, "192.168.1.1", &packet_arr[i]->src_ip)) {
            return -1;  // Invalid source IP address
        }
        if (!inet_pton(AF_INET, "192.168.1.2", &packet_arr[i]->dst_ip)) {
            return -1;  // Invalid destination IP address
        }

        // Initialize protocol and payload size
        packet_arr[i]->protocol = (int8_t)(rand() % 256);
        packet_arr[i]->payload_size = rand() % 1000 + 1;

        // Initialize payload with random ASCII characters
        packet_arr[i]->payload = (char*)malloc(packet_arr[i]->payload_size * sizeof(char));
        if (!packet_arr[i]->payload) {
            return -2;  // Memory allocation failed for payload
        }
        memset(packet_arr[i]->payload, ' ', packet_arr[i]->payload_size);
        packet_arr[i]->payload[packet_arr[i]->payload_size - 1] = '\0';

        // Initialize remaining fields to default values (e.g., timestamp)
    }

    return 0;  // Success
}
