<?php

function updateUserProfiles(array $updateRequests) {
    // Initialize distributed lock
    $distributedLock = new Redis('localhost');
    $lockKey = 'user_profiles_lock';
    $locked = false;

    try {
        while (!$locked) {
            if ($distributedLock->setnx($lockKey, microtime())) {
                $locked = true;
            } else {
                usleep(100000);
            }
        }

        // Connect to database
        $dbConnection = new PDO('mysql:host=localhost;dbname=users', 'username', 'password');

        // Process updates in batches of 10
        $batchSize = 10;
        foreach (array_chunk($updateRequests, $batchSize) as $batch) {
            $updateQueries = [];
            foreach ($batch as $request) {
                $token = $request['token'];
                $updates = $request['updates'];

                // Validate token and permissions
                if (!isValidToken($dbConnection, $token)) {
                    continue;
                }

                // Perform updates
                foreach ($updates as $field => $value) {
                    $updateQueries[] = "UPDATE users SET $field = :value WHERE token = :token";
                }

                // Update last login timestamp and device type
                $updateQueries[] = "UPDATE users SET last_login_timestamp = NOW(), device_type = :device_type WHERE token = :token";

                // Apply optional updates
                if (isset($updates['preferred_language'])) {
                    $updateQueries[] = "UPDATE users SET preferred_language = :language WHERE token = :token";
                }
                if (isset($updates['notification_preferences'])) {
                    $updateQueries[] = "UPDATE users SET notification_preferences = :preferences WHERE token = :token";
                }

                // Execute updates
                foreach ($updateQueries as $query) {
                    $stmt = $dbConnection->prepare($query);
                    $stmt->execute([':token' => $token, ':value' => $value, ':device_type' => $updates['device_type'], ':language' => $updates['preferred_language'], ':preferences' => json_encode($updates['notification_preferences'])]);
                }
            }

            // Commit batch updates
            $dbConnection->commit();
        }

        // Release distributed lock
        $distributedLock->del($lockKey);
    } catch (Exception $e) {
        // Log error and release distributed lock
        error_log($e->getMessage());
        $distributedLock->del($lockKey);
    }

    // Return summary response
    return [
        'status' => 'success',
        'logs' => []
    ];
}

function isValidToken(PDO $dbConnection, string $token) {
    // Check token validity and permissions
    // ...
}

