#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <random>

typedef struct {
    int value;
} record;

int* manage_memory(int n, int min, int max) {
    int* offsets = (int*) aligned_alloc(sizeof(int), n);
    int* ids = (int*) aligned_alloc(sizeof(int), n);
    record* records = (record*) aligned_alloc(sizeof(record), n);

    if (!offsets || !ids || !records) {
        free(offsets);
        free(ids);
        free(records);
        return -1;
    }

    // Fill records with random values
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min, max);

    for (int i = 0; i < n; i++) {
        records[i].value = dis(gen);
    }

    return records;
}

size_t aligned_alloc(size_t alignment, size_t size) {
    size_t aligned_size = (alignment > 0) ? ((size + alignment - 1) & ~(alignment - 1)) : size;

    void* ptr = mmap(NULL, aligned_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (ptr == MAP_FAILED) {
        return 0;
    }

    return aligned_size;
}

