record_t* manageMemory(int n, int min, int max, long** offsets, int** keys, int status) {
    // Handle invalid range
    if (min > max) {
        int temp = min;
        min = max;
        max = temp;
        if (max - min > 1000) {
            status = -1; // Set error code
            return NULL;
        }
    }

    // Pre-allocate memory for arrays and records
    long* offsetsArr = (long*)malloc(n * sizeof(long));
    int* keysArr = (int*)malloc(n * sizeof(int));
    record_t* recordsArr = (record_t*)malloc(n * sizeof(record_t));

    if (!offsetsArr || !keysArr || !recordsArr) {
        status = -1; // Set error code
        return NULL;
    }

    // Initialize record structures with random values
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        recordsArr[i].val = min + rand() % ((max - min) + 1);
    }

    *offsets = offsetsArr;
    *keys = keysArr;

    return recordsArr;
}
