<?php

function updatePassword($tenantId, $userId, $oldPassword, $newPassword) {
    // 1. Multi-Tenancy: Get tenant-specific validation rules and database connection
    $tenantConfig = getTenantConfig($tenantId);
    $dbConnection = connectToDatabase($tenantId);

    // 2. Rate Limiting: Check if the user has exceeded the allowed number of attempts within a time window
    $rateLimitConfig = getRateLimitConfig($tenantId);
    if (checkRateLimitExceeded($rateLimitConfig, $userId)) {
        return lockoutUser($rateLimitConfig, $userId);
    }

    // 3. Error Handling: Attempt to connect to the database and perform the update
    try {
        $dbConnection->beginTransaction();
        if (!validateOldPassword($oldPassword, $tenantId, $userId)) {
            throw new Exception('Invalid old password');
        }
        if (!validateNewPassword($newPassword, $tenantId)) {
            throw new Exception('New password does not meet the required strength');
        }
        updatePasswordInDatabase($dbConnection, $userId, $newPassword);
        $dbConnection->commit();
    } catch (Exception $e) {
        // Handle database errors and rethrow with a custom message
        $error = 'Error updating password: ' . $e->getMessage();
        if ($dbConnection->inTransaction()) {
            $dbConnection->rollBack();
        }
        return $error;
    }

    // 4. Idempotency: Ensure the update is idempotent by checking for existing updates
    try {
        $existingUpdate = getExistingPasswordUpdate($tenantId, $userId);
        if ($existingUpdate && $existingUpdate['updated_at'] > time() - 60) { // 1-minute window
            throw new Exception('Another password update is in progress');
        }
    } catch (Exception $e) {
        return $e->getMessage();
    }

    // 5. Logging and Auditing: Log the successful update
    logPasswordUpdate($tenantId, $userId);

    // 6. System Dependencies: Notify external services of the password change (if necessary)
    notifyExternalServices($tenantId, $userId);

    return 'Password updated successfully';
