void* allocate_and_initialize_data_structures(int n, int min, int max) {
    if (min > max) {
        int temp = min;
        min = max;
        max = temp;
    }

    // Determine optimal cache alignment settings
    int align_size = sysconf(_SC_PAGESIZE);
    void* record_aligned = aligned_alloc(align_size, n * sizeof(struct record));
    void* long_aligned = aligned_alloc(align_size, n * sizeof(long));
    void* int_aligned = aligned_alloc(align_size, n * sizeof(int));

    if (record_aligned == NULL || long_aligned == NULL || int_aligned == NULL) {
        return NULL;
    }

    // Initialize and fill record structures with random values
    for (int i = 0; i < n; i++) {
        struct record* rec = record_aligned + i * sizeof(struct record);
        rec->value = rand() % (max - min + 1) + min;
    }

    return record_aligned;
}
