['Here is the Java class that manages a dynamic registry of `ServiceInstance` objects:

```java
import java.util.*;

public class ServiceRegistry {
    private Map<String, ServiceInstance> serviceInstances;
    private Map<String, ServiceInstance> healthyServices;

    public ServiceRegistry() {
        this.serviceInstances = new HashMap<>();
        this.healthyServices = new HashMap<>();
    }

    public void addServiceInstance(String serviceID, String ipAddress, int port) {
        ServiceInstance instance = new ServiceInstance(serviceID, ipAddress, port);
        serviceInstances.put(serviceID, instance);

        if (instance.getHealthStatus().equals(HealthStatus.HEALTHY)) {
            healthyServices.put(serviceID, instance);
        }
    }

    public void updateServiceInstance(String serviceID, HealthStatus healthStatus) {
        ServiceInstance instance = serviceInstances.getOrDefault(serviceID, null);
        if (instance != null) {
            instance.setHealthStatus(healthStatus);

            if (healthStatus.equals(HealthStatus.HEALTHY)) {
                healthyServices.put(serviceID, instance);
            } else {
                healthyServices.remove(serviceID);
            }
        }
    }

    public int getHealthyServiceCount() {
        return healthyServices.size();
    }

    // Periodic garbage collection for instances marked as failed
    public void collectGarbage() {
        List<String> toRemove = new ArrayList<>();
        for (Map.Entry<String, ServiceInstance> entry : serviceInstances.entrySet()) {
            if (entry.getValue().getHealthStatus().equals(HealthStatus.FAILED)) {
                toRemove.add(entry.getKey());
            }
        }

        for (String key : toRemove) {
            serviceInstances.remove(key);
            healthyServices.remove(key);
        }
    }
}

class ServiceInstance {
    private String serviceID;
    private String ipAddress;
    private int port;
    private HealthStatus healthStatus;

    public ServiceInstance(String serviceID, String ipAddress, int port) {
        this.serviceID = serviceID;
        this.ipAddress = ipAddress;
        this.port = port;
        this.healthStatus = HealthStatus.HEALTHY;
    }

    public String getServiceID() {
        return serviceID;
    }

    public String getIpAddress() {
        return ipAddress;
    }

    public int getPort() {
        return port;
    }

    public HealthStatus getHealthStatus() {
        return healthStatus;
    }

    public void setHealthStatus(HealthStatus healthStatus) {
        this.healthStatus = healthStatus;
    }
}

enum HealthStatus {
    HEALTHY,
    DEGRADED,
    FAILED
}
