typedef struct {
    char *file_path;
    int buffer_size;
} Config;

typedef struct {
    int key;
    int value;
} KeyValue;

void processFilesAndData(Config config, size_t num_files, void (*callback)(KeyValue*, size_t), pthread_mutex_t* mutex) {
    // Initialize configuration structure
    Config* conf = malloc(sizeof(Config));
    *conf = config;

    // Allocate memory for buffer to read large files line by line into an array of strings
    char** lines = (char**)malloc(conf->buffer_size * sizeof(char*));

    pthread_t threads[num_files];
    int file_index = 0;
    for(int i = 0; i < num_files; i++) {
        // Initialize thread
        pthread_create(&threads[i], NULL, &readFileLineByLine, (void*)&conf);
        // Wait for thread to finish
        pthread_join(threads[i], NULL);
    }

    // Process each line using callback function
    size_t total_lines = 0;
    for(int i = 0; i < num_files; i++) {
        total_lines += strlen(lines[i]);
    }
    callback(lines, total_lines);

    // Free allocated memory
    free(conf);
    free(lines);
}

void* readFileLineByLine(void* arg) {
    Config* conf = (Config*)arg;
    char** lines = malloc(conf->buffer_size * sizeof(char*));
    // Read file line by line into an array of strings
    FILE* file = fopen(conf->file_path, "r");
    if(file == NULL) {
        return NULL;
    }
    char buffer[conf->buffer_size];
    int line_index = 0;
    while(fgets(buffer, conf->buffer_size, file) != NULL) {
        lines[line_index] = malloc(strlen(buffer));
        strcpy(lines[line_index], buffer);
        line_index++;
    }
    fclose(file);

    // Trim each line of leading and trailing whitespace
    for(int i = 0; i < line_index; i++) {
        int j = 0;
        while(i < line_index && lines[i][j] != '\0') {
            if(lines[i][j] == ' ' || lines[i][j] == '\t' || lines[i][j] == '\n') {
                j++;
            }
            else {
                break;
            }
        }
        int k = strlen(lines[i]) - 1;
        while(k >= 0 && (lines[i][k] == ' ' || lines[i][k] == '\t' || lines[i][k] == '\n')) {
            k--;
        }
        lines[i][j] = '\0';
        lines[i][k+1] = '\0';
    }

    // Process each line using callback function
    size_t total_lines = 0;
    for(int i = 0; i < line_index; i++) {
        total_lines++;
    }
    ((void (*)(KeyValue*, size_t))conf->callback)(lines, total_lines);

    free(lines);
    return NULL;
}

int main() {
    Config config;
    config.file_path = "path_to_file.txt";
    config.buffer_size = 1024;

    // Initialize mutex for concurrency control
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    processFilesAndData(config, 5, &callback_function, mutex);
}

