typedef struct {
    double value;
    struct data* prev;
    struct data* next;
} data;

data* head = NULL;
data* tail = NULL;

int arr_size = 0;
float* values = NULL;
char** identifiers = NULL;

// Custom hash table
int hash_table_size = 128;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int* hash_table = NULL;

void insert_data(float value, char* identifier) {
    data* new_node = (data*)malloc(sizeof(data));
    new_node->value = value;
    new_node->prev = tail;
    new_node->next = NULL;

    if(tail != NULL) {
        tail->next = new_node;
    } else {
        head = new_node;
    }

    tail = new_node;

    values[arr_size] = value;
    identifiers[arr_size] = identifier;
    arr_size++;
}

float get_value(char* identifier) {
    int hash = 0;
    for(int i = 0; i < strlen(identifier); i++) {
        hash += (int)identifier[i];
    }
    hash %= hash_table_size;

    pthread_mutex_lock(&mutex);
    if(hash_table[hash] != -1) {
        free((void*)identifiers[hash_table[hash]]);
    }
    hash_table[hash] = arr_size;
    identifiers[hash_table[hash]] = identifier;
    pthread_mutex_unlock(&mutex);

    for(int i = 0; i < arr_size; i++) {
        if(strcmp(identifiers[i], identifier) == 0) {
            return values[i];
        }
    }

    // Handle missing value
}

void trim_memory() {
    int new_size = arr_size / 2;
    values = (float*)realloc(values, sizeof(float) * new_size);
    identifiers = (char**)realloc(identifiers, sizeof(char*) * new_size);

    for(int i = new_size; i < arr_size; i++) {
        free((void*)identifiers[i]);
    }

    arr_size = new_size;
}

