// Define the maximum size for the 'char' buffer
#define MAX_BUF_SIZE 256

// Define the growth factor for dynamic memory allocation
#define GROWTH_FACTOR 2

typedef struct {
    int value;
    long* arr;
} metadata;

void manage_memory(int num_records) {
    // Dynamic memory allocation for the record array
    record** records = (record**)malloc(num_records * sizeof(record*));

    if (!records) return; // Handle out-of-memory error

    // Initialize random number generator
    srand(time(NULL));

    // Loop through each record and initialize its fields
    for (int i = 0; i < num_records; i++) {
        records[i] = (record*)malloc(sizeof(record));

        if (!records[i]) return; // Handle out-of-memory error

        // Initialize the 'int' field with a random value within a specified range
        records[i]->key = rand() % 100;

        // Allocate memory for the 'char' buffer and initialize it with a random ASCII string
        char* buf = (char*)malloc(MAX_BUF_SIZE);
        if (!buf) return; // Handle out-of-memory error

        int buf_len = rand() % MAX_BUF_SIZE;
        for (int j = 0; j < buf_len; j++) {
            buf[j] = (char)(rand() % 256);
        }

        records[i]->data = buf;

        // Initialize the 'metadata' structure and allocate memory for the 'long' array
        metadata* meta = (metadata*)malloc(sizeof(metadata));
        if (!meta) return; // Handle out-of-memory error

        int arr_len = num_records;
        long* arr = (long*)malloc(arr_len * sizeof(long));
        if (!arr) return; // Handle out-of-memory error

        for (int j = 0; j < arr_len; j++) {
            arr[j] = j;
        }

        meta->value = rand() % 100;
        meta->arr = arr;

        records[i]->meta = meta;
    }

    // Release all dynamically allocated memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]->data);
        free(records[i]->meta->arr);
        free(records[i]->meta);
        free(records[i]);
    }
    free(records);
}
