typedef struct {
    double *values;
    int size;
    char *str;
} DynamicStruct;

DynamicStruct* create_struct(int array_size, const char* format_str) {
    DynamicStruct* dyn_struct = (DynamicStruct*)malloc(sizeof(DynamicStruct));
    if (!dyn_struct) return NULL; // handle memory allocation failure

    dyn_struct->values = (double*)malloc(array_size * sizeof(double));
    if (!dyn_struct->values) {
        free(dyn_struct);
        return NULL;
    }

    dyn_struct->size = array_size;

    dyn_struct->str = malloc(strlen(format_str) + 1);
    strcpy(dyn_struct->str, format_str);

    return dyn_struct;
}

void set_string(DynamicStruct* dyn_struct, int value) {
    char buffer[256];
    sprintf(buffer, "%s %d", dyn_struct->str, value);
    free(dyn_struct->str);
    dyn_struct->str = malloc(strlen(buffer) + 1);
    strcpy(dyn_struct->str, buffer);
}

void fill_array(DynamicStruct* dyn_struct, int array_size, int dist_type) {
    for (int i = 0; i < array_size; i++) {
        if (dist_type == 0) { // uniform distribution
            dyn_struct->values[i] = (double)(rand() % 100) / 99.0;
        } else { // normal distribution
            dyn_struct->values[i] = (double)randg(1);
        }
    }
}

void free_dyn_struct(DynamicStruct* dyn_struct) {
    if (!dyn_struct) return;

    free(dyn_struct->str);
    free(dyn_struct->values);

    free(dyn_struct);
}

int main() {
    DynamicStruct* dyn_struct = create_struct(100, "Hello");
    set_string(dyn_struct, 42);
    fill_array(dyn_struct, 100, 1); // normal distribution
    // more code...

    free_dyn_struct(dyn_struct);

    return 0;
}
