#include <iostream>
#include <memory>

class OctreeNode {
public:
    OctreeNode(size_t size) : data_(new char[size]) {}

    ~OctreeNode() {
        delete[] data_;
    }

    void* get_data() { return data_; }
private:
    void* data_;
};

class Octree {
public:
    Octree(size_t initial_size, size_t initial_capacity) : root_({initial_size}), capacity_(initial_capacity), allocated_(0) {}

    ~Octree() {
        clear();
    }

    void clear() {
        std::unique_ptr<OctreeNode> current = std::move(root_);
        while (current) {
            auto next = current->get_data();
            current.reset();
            if (!next) break;
            std::cout << "Clearing memory..." << std::endl;
            delete[] static_cast<char*>(next);
        }
    }

    void* get_node(size_t level, size_t index) {
        return root_.get()->get_data() + (index * 8 * level);
    }

    void set_node(size_t level, size_t index, void* data) {
        OctreeNode* node = reinterpret_cast<OctreeNode*>(root_.get()->get_data()) + (index * 8 * level);
        node->data_ = data;
    }

private:
    std::unique_ptr<OctreeNode> root_;
    size_t capacity_;
    size_t allocated_;
};

