// Define the structure for nodes in the linked list
typedef struct node {
    char string[64];
    int index;
    double value;
    struct node* next;
} Node;

// Define the structure for network packets
typedef struct packet {
    time_t timestamp;
    int priority;
    int size;
} Packet;

// Define the function to manage the packet processing system
void process_packets(int num_packets, int queue_size) {
    // Initialize the linked list with a specified number of nodes
    Node* head = NULL;
    for (int i = 0; i < num_packets; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed!\n");
            return;
        }
        sprintf(node->string, "%c%c%c", 'A' + rand() % 26, 'a' + rand() % 26, '0' + rand() % 10);
        node->index = i;
        node->value = (double)rand() / RAND_MAX;
        if (!head) {
            head = node;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // Initialize the queue for packet processing
    Packet* queue[queue_size];
    int queue_head = 0, queue_tail = 0;

    // Define the function to enqueue a new task
    void enqueue(Packet packet) {
        if (queue_tail >= queue_size) {
            printf("Queue full!\n");
            return;
        }
        queue[queue_tail] = &packet;
        queue_tail++;
    }

    // Define the function to dequeue tasks older than 10 seconds
    void dequeue() {
        int i = 0;
        while (i < queue_head && time(NULL) - queue[i]->timestamp > 10) {
            free(queue[i]);
            for (; i < queue_head - 1; i++) {
                queue[i] = queue[i + 1];
            }
            queue_head--;
        }
    }

    // Initialize the performance metrics
    int total_packets = 0;
    double average_priority = 0.0;
    int max_packet_size = 0;

    // Process packets in an asynchronous manner
    while (true) {
        Packet packet;
        if (queue_head > queue_tail - 10) {
            dequeue();
        }
        if (queue_head < queue_size && time(NULL) - head->value < 10) {
            Node* current = head;
            for (int i = 0; i < 1000000; i++) { // Simulate recursive traversal
                average_priority += current->index * (double)i / RAND_MAX;
                if (current->size > max_packet_size) {
                    max_packet_size = current->size;
                }
                if (!current->next) {
                    break;
                }
                current = current->next;
            }
            total_packets++;
        } else {
            packet.timestamp = time(NULL);
            packet.priority = rand() % 10; // Assign a random priority
            packet.size = rand() % 1024 + 1; // Generate a random packet size
            enqueue(packet);
        }
    }

    // Free all allocated resources when the linked list or queue is no longer needed
    while (head) {
        Node* current = head;
        head = head->next;
        free(current);
    }
    for (int i = 0; i < queue_size; i++) {
        if (queue[i]) {
            free(queue[i]);
        }
    }
}
