```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
    long* array;
} metadata;

typedef struct {
    int key;
    long offset;
    int data;
    char* buffer;
    metadata* meta;
} record;

record* create_record(int key, long offset) {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->data = rand() % 100; // initialize data field with random value
    new_record->buffer = (char*)malloc((rand() % 256) + 1); // allocate buffer with random length
    new_record->meta = (metadata*)malloc(sizeof(metadata));
    return new_record;
}

void free_record(record* record_to_free) {
    if (record_to_free == NULL) return;
    if (record_to_free->buffer != NULL) free(record_to_free->buffer);
    if (record_to_free->meta != NULL) free(record_to_free->meta);
    free(record_to_free);
}

metadata* create_metadata(int num_elements) {
    metadata* new_metadata = (metadata*)malloc(sizeof(metadata));
    new_metadata->array = (long*)malloc(num_elements * sizeof(long));
    for (int i = 0; i < num_elements; i++) {
        new_metadata->array[i] = i;
    }
    return new_metadata;
}

void free_metadata(metadata* metadata_to_free) {
    if (metadata_to_free == NULL) return;
    free(metadata_to_free->array);
    free(metadata_to_free);
}

record** create_records(int num_records, int key_range, int offset_range) {
    record** records = (record**)malloc(num_records * sizeof(record*));
    for (int i = 0; i < num_records; i++) {
        records[i] = create_record(rand() % key_range, rand() % offset_range);
    }
    return records;
}

void free_records(record** records_to_free, int num_records) {
    if (records_to_free == NULL || num_records == 0) return;
    for (int i = 0; i < num_records; i++) {
        free_record(records_to_free[i]);
    }
    free(records_to_free);
}
