    sem_init(sem, 0, 1);

    for (int i = 0; i < num_updates; i++) {
        NetworkInterfaceStatusUpdate* update = (NetworkInterfaceStatusUpdate*)malloc(sizeof(NetworkInterfaceStatusUpdate));

        // Initialize fields
        time_t timestamp = time(NULL);
        int interface_id = i;
        int error_code = rand() % 100;
        EventTag event_tags[5];
        for (int j = 0; j < 5; j++) {
            event_tags[j].event_id = j;
            strcpy(event_tags[j].status, "OK");
        }

        // Initialize source IP and protocol type
        char* source_ip_str = "192.168.";
        strcat(source_ip_str, (char *)itos((int)interface_id));
        strcpy(update->source_ip, source_ip_str);
        strcpy(update->protocol_type, "TCP");

        update->timestamp = timestamp;
        update->interface_id = interface_id;
        update->error_code = error_code;
        update->event_tags = event_tags;

        updates[i] = update;
    }

    sem_destroy(sem);
}

int serialize_network_interface_status_update(NetworkInterfaceStatusUpdate* update, char* buffer) {
    int offset = 0;

    // Serialize timestamp
    memcpy(buffer + offset, &update->timestamp, sizeof(time_t));
    offset += sizeof(time_t);

    // Serialize interface ID
    memcpy(buffer + offset, &update->interface_id, sizeof(int));
    offset += sizeof(int);

    // Serialize error code
    memcpy(buffer + offset, &update->error_code, sizeof(int));
    offset += sizeof(int);

    // Serialize event tags
    for (int i = 0; i < 5; i++) {
        EventTag* event_tag = &update->event_tags[i];
        memcpy(buffer + offset, &event_tag->event_id, sizeof(int));
        offset += sizeof(int);
        memcpy(buffer + offset, event_tag->status, strlen(event_tag->status) + 1);
        offset += strlen(event_tag->status) + 1;
    }

    // Serialize source IP and protocol type
    char* source_ip = update->source_ip;
    char* protocol_type = update->protocol_type;
    memcpy(buffer + offset, source_ip, strlen(source_ip) + 1);
    offset += strlen(source_ip) + 1;
    memcpy(buffer + offset, protocol_type, strlen(protocol_type) + 1);
    offset += strlen(protocol_type) + 1;

    return offset;
}

