#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define POOL_SIZE 1000
#define RECORD_SIZE sizeof(record_t)
#define KEY_TYPE int
#define OFFSET_TYPE long
#define RECORD_FIELD_TYPE int

typedef struct {
    RECORD_FIELD_TYPE value;
} record_t;

sem_t sem_record_pool, sem_key_pool, sem_offset_pool;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int record_pool_size = 0, key_pool_size = 0, offset_pool_size = 0;
record_t *record_pool = NULL;
KEY_TYPE *key_pool = NULL;
OFFSET_TYPE *offset_pool = NULL;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void* my_free(void* ptr, size_t size) {
    free(ptr);
    return NULL;
}

record_t* get_record() {
    record_t *record = NULL;

    sem_wait(&sem_record_pool);
    pthread_mutex_lock(&mutex);

    if (record_pool_size > 0) {
        record = &record_pool[--record_pool_size];
    } else {
        record = my_malloc(RECORD_SIZE);
        record_pool_size++;
    }

    pthread_mutex_unlock(&mutex);
    sem_post(&sem_record_pool);

    return record;
}

void put_record(record_t* record) {
    pthread_mutex_lock(&mutex);

    if (record_pool_size < POOL_SIZE) {
        record_pool[record_pool_size++] = *record;
    } else {
        my_free(record, RECORD_SIZE);
    }

    pthread_mutex_unlock(&mutex);
}

KEY_TYPE* get_key() {
    KEY_TYPE* key = NULL;

    sem_wait(&sem_key_pool);
    pthread_mutex_lock(&mutex);

    if (key_pool_size > 0) {
        key = &key_pool[--key_pool_size];
    } else {
        key = my_malloc(sizeof(KEY_TYPE));
        key_pool_size++;
    }

    pthread_mutex_unlock(&mutex);
    sem_post(&sem_key_pool);

    return key;
}

void put_key(KEY_TYPE* key) {
    pthread_mutex_lock(&mutex);

    if (key_pool_size < POOL_SIZE) {
        key_pool[key_pool_size++] = *key;
    } else {
        my_free(key, sizeof(KEY_TYPE));
    }

    pthread_mutex_unlock(&mutex);
}

OFFSET_TYPE* get_offset() {
    OFFSET_TYPE* offset = NULL;

    sem_wait(&sem_offset_pool);
    pthread_mutex_lock(&mutex);

    if (offset_pool_size > 0) {
        offset = &offset_pool[--offset_pool_size];
    } else {
        offset = my_malloc(sizeof(OFFSET_TYPE));
        offset_pool_size++;
    }

    pthread_mutex_unlock(&mutex);
    sem_post(&sem_offset_pool);

    return offset;
}

void put_offset(OFFSET_TYPE* offset) {
    pthread_mutex_lock(&mutex);

    if (offset_pool_size < POOL_SIZE) {
        offset_pool[offset_pool_size++] = *offset;
    } else {
        my_free(offset, sizeof(OFFSET_TYPE));
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    record_t* record = get_record();
    KEY_TYPE key = 12345;
    OFFSET_TYPE offset = 54321;

    if (record == NULL || key == NULL || offset == NULL) {
        printf("Memory allocation failed\n");
        return -1;
