#define MAX_LINE_SIZE 1024
#define MAX_CONCURRENCY 16
#define HASH_MAP_SIZE 4096
#define FLUSH_THRESHOLD 1048576

typedef struct {
    char* path;
    int buffer_size;
    int max_lines_per_process;
    int concurrency_limit;
} Config;

typedef struct {
    int count;
    char* key;
} KeyValuePair;

Config config;
pthread_mutex_t hashmap_lock = PTHREAD_MUTEX_INITIALIZER;
int unique_keys = 0;
int key_counts[HASH_MAP_SIZE] = {0};
char* lines[MAX_CONCURRENCY];
int line_count[MAX_CONCURRENCY] = {0};

void processFilesAdvanced(Config config) {
    // Initialize buffer and array to store lines
    char* buffer = malloc(config.buffer_size);
    char** lines_array = malloc(MAX_CONCURRENCY * sizeof(char*));

    // Initialize hashmap
    pthread_mutex_init(&hashmap_lock, NULL);

    FILE* file;
    int line_number = 0;

    for (int i = 0; i < config.concurrency_limit; i++) {
        lines[i] = malloc(config.buffer_size);
        line_count[i] = 0;
    }

    // Process files
    while (file != NULL) {
        // Read file and store lines in buffer
        char* line = fgets(buffer, config.buffer_size, file);
        int current_line_number = 0;

        while (line != NULL) {
            // Trim whitespace and store line
            char trimmed_line[MAX_LINE_SIZE];
            strcpy(trimmed_line, line + strlen(line) - MAX_LINE_SIZE);

            // Process line
            KeyValuePair* pair = malloc(sizeof(KeyValuePair));
            pair->count = 1;
            pair->key = trimmed_line;

            pthread_mutex_lock(&hashmap_lock);
            if (key_counts[atoi(pair->key)] == 0)
                unique_keys++;

            key_counts[atoi(pair->key)]++;
            free(pair);

            // Store line
            lines[line_number % config.concurrency_limit] = line;
            line_count[line_number++ % config.concurrency_limit]++;
            line = fgets(buffer, config.buffer_size, file);
        }
    }

    // Output results
    printf("Unique keys: %d\n", unique_keys);

    for (int i = 0; i < HASH_MAP_SIZE; i++) {
        if (key_counts[i] > 0) {
            printf("%s: %d\n", itoa(i), key_counts[i]);
        }
    }

    // Flush hashmap
    pthread_mutex_unlock(&hashmap_lock);

    free(buffer);
    for (int i = 0; i < config.concurrency_limit; i++) {
        free(lines[i]);
    }
}
