#include <forward_list>
#include <string>
#include <memory>
#include <stdexcept>

void insertAfterFirstOccurrence(
    std::forward_list<std::string>& list,
    const std::string& target,
    const std::string& insertion) {
    auto it = list.cbegin();
    while (it != list.cend()) {
        if (*it == target) {
            list.insert_after(it, insertion);
            return;
        }
        ++it;
    }
    list.append(insertion);
}
