// Function to derive an encryption key and initialization vector from a password
void derive_key_and_iv(char* password, int iteration_count) {
    // Initialize the KDF
    unsigned char salt[] = "salt";
    size_t salt_len = sizeof(salt);
    unsigned char derived_key[32];
    unsigned char iv[16];

    // Derive the key and IV using PBKDF2
    PBKDF2(password, strlen(password), salt, salt_len, derived_key, 32, iteration_count, iv);

    // Initialize the AES-CBC cipher with the derived key and IV
    AES_KEY enc_key;
    AES_set_encrypt_key(derived_key, 32, &enc_key);
    AES_cbc_encrypt(NULL, NULL, 0, &enc_key, iv, AES_ENCRYPT);
}

// Function to manage memory for an array of custom 'entity' structures
