// Define custom memory pool allocator
typedef struct {
    void *pool;
    size_t total_size;
    size_t free_size;
} mem_pool;

mem_pool *create_mem_pool(size_t initial_size) {
    // Initialize the memory pool structure
    mem_pool *mp = (mem_pool *)malloc(sizeof(mem_pool));

    mp->total_size = initial_size;
    mp->free_size = initial_size;
    mp->pool = malloc(initial_size);

    return mp;
}

void *mem_alloc(mem_pool *mp, size_t size) {
    // Allocate memory from the pool
    void *ptr = mp->pool;
    mp->pool += size;
    mp->free_size -= size;

    if (mp->free_size < sizeof(void *)) {
        // No more space left, reallocate the pool
        mem_pool *new_mp = create_mem_pool(mp->total_size + 1024);
        memcpy(new_mp->pool, mp->pool, mp->free_size);
        free(mp->pool);
        mp = new_mp;
    }

    return ptr;
}

void mem_free(mem_pool *mp, void *ptr) {
    // Free the allocated memory
    mp->pool = ptr;
    mp->free_size += sizeof(void *);
}

// Define thread-safe command execution function
int exec_command(char *command) {
    pid_t pid = fork();

    if (pid == 0) {
        // Child process, execute the command
        execl("/usr/bin/jpegtopdf", "jpegtopdf", "-", "output.pdf", NULL);
        return -1;
    } else if (pid > 0) {
        // Parent process, wait for the child to finish
        int status;
        wait(&status);

        return status;
    } else {
        // Error occurred during fork()
        return -1;
    }
}

