#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define a struct for a bucket in the hash table
typedef struct {
    void* key;
    void* value;
} Bucket;

// Define a struct for a hash table
typedef struct {
    int size; // Current size of the hash table
    int capacity; // Desired capacity of the hash table
    double loadFactor; // Desired load factor for the hash table
    Bucket** buckets; // Array of buckets in the hash table
    pthread_mutex_t mutex; // Mutex for thread safety
} HashTable;

// Function to create a new hash table with the given size and load factor
HashTable* createHashTable(int size, double loadFactor) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = 0;
    ht->capacity = size;
    ht->loadFactor = loadFactor;
    ht->buckets = (Bucket**)calloc(size, sizeof(Bucket*));
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Function to resize the hash table
void resizeHashTable(HashTable* ht) {
    int newSize = ht->capacity * 2;
    Bucket** newBuckets = (Bucket**)calloc(newSize, sizeof(Bucket*));
    for(int i = 0; i < ht->capacity; i++) {
        if(ht->buckets[i] != NULL) {
            newBuckets[i % newSize] = ht->buckets[i];
        }
    }
    free(ht->buckets);
    ht->buckets = newBuckets;
    ht->capacity = newSize;
}

// Function to insert a key-value pair into the hash table
void insert(HashTable* ht, void* key, void* value) {
    int index = (int)key % ht->capacity;
    pthread_mutex_lock(&ht->mutex);
    if(ht->buckets[index] == NULL || ht->loadFactor > 0.7) {
        resizeHashTable(ht);
        index = (int)key % ht->capacity;
    }
    ht->buckets[index] = (Bucket*)malloc(sizeof(Bucket));
    ht->buckets[index]->key = key;
    ht->buckets[index]->value = value;
    pthread_mutex_unlock(&ht->mutex);
}

// Function to retrieve a value from the hash table
void* get(HashTable* ht, void* key) {
    int index = (int)key % ht->capacity;
    pthread_mutex_lock(&ht->mutex);
    if(ht->buckets[index] != NULL && ht->buckets[index]->key == key) {
        return ht->buckets[index]->value;
    }
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

// Function to destroy the hash table
void destroyHashTable(HashTable* ht) {
    for(int i = 0; i < ht->capacity; i++) {
        if(ht->buckets[i] != NULL) {
            free(ht->buckets[i]);
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->mutex);
    free(ht);
}

int main() {
    // Create a new hash table with size 10 and load factor 0.5
    HashTable* ht = createHashTable(10, 0.5);

    // Insert some key-value pairs into the hash table
    insert(ht, "hello", "world");
    insert(ht, "foo", "bar");

    // Retrieve a value from the hash table
    void* value = get(ht, "hello");
    printf("Value: %s\n", (char*)value);

    // Destroy the hash table
    destroyHashTable(ht);
}
