// Custom data structure
typedef struct {
    int i;
    float f;
    void* custom_data;
} value_t;

// Hash table node structure
typedef struct {
    char* key;
    value_t value;
    struct hash_node* next;
} hash_node_t;

// Hash table structure
typedef struct {
    size_t bucket_count;
    size_t load_factor;
    size_t max_key_len;
    hash_node_t** buckets;
    pthread_mutex_t mutex;
} hash_table_t;

// Function to create a new hash table
hash_table_t* hash_create(size_t initial_bucket_count, size_t max_load_factor) {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->bucket_count = initial_bucket_count;
    table->load_factor = max_load_factor / 100.0; // Convert to decimal
    table->max_key_len = 32; // Default maximum key length
    table->buckets = (hash_node_t**)calloc(initial_bucket_count, sizeof(hash_node_t*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to insert a key-value pair into the hash table
void hash_insert(hash_table_t* table, const char* key, value_t value) {
    size_t bucket_index = hash(key, table->bucket_count) % table->bucket_count;
    pthread_mutex_lock(&table->mutex);
    if (!table->buckets[bucket_index]) {
        table->buckets[bucket_index] = (hash_node_t*)malloc(sizeof(hash_node_t));
        table->buckets[bucket_index]->key = strdup(key);
        table->buckets[bucket_index]->value = value;
        table->buckets[bucket_index]->next = NULL;
    } else {
        hash_node_t* current = table->buckets[bucket_index];
        while (current->next) current = current->next;
        current->next = (hash_node_t*)malloc(sizeof(hash_node_t));
        current->next->key = strdup(key);
        current->next->value = value;
        current->next->next = NULL;
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to look up a key in the hash table
value_t* hash_lookup(hash_table_t* table, const char* key) {
    size_t bucket_index = hash(key, table->bucket_count) % table->bucket_count;
    pthread_mutex_lock(&table->mutex);
    if (table->buckets[bucket_index]) {
        hash_node_t* current = table->buckets[bucket_index];
        while (current) {
            if (!strcmp(current->key, key)) {
                pthread_mutex_unlock(&table->mutex);
                return &current->value;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL; // Key not found
}

// Function to remove a key-value pair from the hash table
void hash_remove(hash_table_t* table, const char* key) {
    size_t bucket_index = hash(key, table->bucket_count) % table->bucket_count;
    pthread_mutex_lock(&table->mutex);
    if (table->buckets[bucket_index]) {
        hash_node_t* current = table->buckets[bucket_index];
        hash_node_t* prev = NULL;
        while (current) {
            if (!strcmp(current->key, key)) {
                if (prev) {
                    prev->next = current->next;
                } else {
                    table->buckets[bucket_index] = current->next;
                }
                free(current->key);
                free(current);
                break;
            }
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to calculate the hash value for a given key
size_t hash(const char* key, size_t bucket_count) {
    size_t hash_value = 0;
    while (*key) {
        hash_value += *key;
        key++;
    }
    return hash_value % bucket_count;
}
