    char ipAddress[16];
    int portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

// Initialize the dynamic dataset
NetworkConnectionStatus *connections = NULL;
int connectionsCount = 0;

// Function to add a new network connection
void addConnection(char* ipAddress, int portNumber) {
    // Allocate memory for the new connection
    NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));

    // Initialize the connection's state as disconnected
    newConnection->connectionState = DISCONNECTED;

    // Copy the IP address and port number to the new connection
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;

    // Add the new connection to the dataset
    connections[connectionsCount++] = *newConnection;
}

// Function to update an existing network connection
void updateConnection(char* ipAddress, int portNumber, ConnectionState state) {
    // Iterate over the connections array
    for (int i = 0; i < connectionsCount; i++) {
        if (strcmp(connections[i].ipAddress, ipAddress) == 0 && connections[i].portNumber == portNumber) {
            // Update the connection's state
            connections[i].connectionState = state;
            return;
        }
    }
}

// Function to retrieve the number of active connections
int getActiveConnections() {
    int count = 0;

    // Iterate over the connections array
    for (int i = 0; i < connectionsCount; i++) {
        if (connections[i].connectionState == CONNECTED) {
            count++;
        }
    }

    return count;
}

// Union-Find algorithm to identify disjoint sets based on integer keys
void unionFind(int x, int y) {
    // Find the root of set x
    while (x != connections[x].portNumber) {
        x = connections[x].portNumber;
    }

    // Find the root of set y
    while (y != connections[y].portNumber) {
        y = connections[y].portNumber;
    }

    // Make the root of set x the parent of set y
    if (x < y) {
        connections[x] = *connections;
    } else {
        connections[y] = *connections;
    }
}

// Function to process a batch of network connections
void processBatch() {
    int batchSize = 1000; // Process up to 1 million concurrent connections efficiently

    for (int i = 0; i < batchSize; i++) {
        // Calculate the average time taken to process each batch in milliseconds
        float avgTime = (float)(getActiveConnections()) / 1000.0f;

        printf("Average processing time per batch: %f ms\n", avgTime);
    }
}

// Function to log warnings or errors encountered during processing
void logError(char* message) {
    // Log the error message for further analysis and debugging
    printf("%s\n", message);
}

int main() {
    // Initialize the dynamic dataset with up to 1 million concurrent connections efficiently
    connections = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus) * 1000000);

