void addConnection(char* ipAddress, int portNumber) {
    // Check if memory is available for a new connection
    if (numConnections >= 10000) {
        printf("No more connections can be added.\n");
        return;
    }

    NetworkConnectionStatus* newConnection = malloc(sizeof(NetworkConnectionStatus));
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;
    newConnection->connectionState = CONNECTED;

    if (connections == NULL) {
        connections = newConnection;
    } else {
        NetworkConnectionStatus* temp = connections;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newConnection;
    }

    numConnections++;
}

void updateConnection(int index, char* ipAddress, int portNumber) {
    if (index < 0 || index >= numConnections) {
        printf("Invalid connection index.\n");
        return;
    }

    NetworkConnectionStatus* current = connections;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    strcpy(current->ipAddress, ipAddress);
    current->portNumber = portNumber;

    if (current->connectionState == DISCONNECTED) {
        current->connectionState = CONNECTED;
    }
}

void deleteConnection(int index) {
    if (index < 0 || index >= numConnections) {
        printf("Invalid connection index.\n");
        return;
    }

    NetworkConnectionStatus* current = connections;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    NetworkConnectionStatus* next = current->next;
    free(current);

    if (numConnections > 1) {
        connections = next;
    } else {
        connections = NULL;
    }

    numConnections--;
}

int listActiveConnections() {
    int count = 0;

    for (NetworkConnectionStatus* connection = connections; connection != NULL; connection = connection->next) {
        if (connection->connectionState == CONNECTED) {
            printf("IP Address: %s, Port Number: %d\n", connection->ipAddress, connection->portNumber);
            count++;
        }
    }

    return count;
}

int main() {
    // Example usage:
    addConnection("192.168.1.100", 1234);
    addConnection("10.0.0.1", 5678);

    printf("Number of active connections: %d\n", listActiveConnections());

    deleteConnection(1);

    printf("Number of active connections after deletion: %d\n", listActiveConnections());

    return 0;
}
