void processFilesAndData(Config config[], ProcessConfig process_config, pthread_mutex_t *mutex) {
    pthread_t threads[process_config.num_threads];
    for (int i = 0; i < process_config.num_threads; i++) {
        pthread_create(&threads[i], NULL, process_thread, &config);
    }
    for (int i = 0; i < process_config.num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    int num_unique_keys = 0;
    // Store key-value pairs in a hash map
    // ...

    printf("Number of unique keys: %d\n", num_unique_keys);
