void *process_thread(void *config) {
    Config *conf = (Config *) config;
    FILE *file = fopen(conf->file_path, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    size_t buffer_size = conf->buffer_size;
    char *buffer = (char *) malloc(buffer_size);
    pthread_mutex_lock(mutex);
    // Read and process lines from the file
    for (int i = 0; i < MAX_LINE_LENGTH; i++) {
        fgets(buffer, buffer_size, file);
        if (feof(file)) break;
        pthread_mutex_unlock(mutex);
        // Call callback function to process line
        process_config.callback(buffer);
        pthread_mutex_lock(mutex);
    }
    fclose(file);
    free(buffer);

    return NULL;
}

