typedef struct {
    int value;
} record_t;

typedef struct {
    int sum;
    int count;
} summary_t;

void* malloc_checked(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int init_pipeline(int num_records, int max_offset_value, int min_record_value, int max_record_value) {
    long* offsets = (long*)malloc_checked(num_records * sizeof(long));
    int* keys = (int*)malloc_checked(num_records * sizeof(int));
    record_t* records = (record_t*)malloc_checked(num_records * sizeof(record_t));
    summary_t* summaries = (summary_t*)malloc_checked(num_records * sizeof(summary_t));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % max_offset_value;
        keys[i] = rand() % 100;
        records[i].value = (rand() % (max_record_value - min_record_value)) + min_record_value;
        summaries[i].sum = 0;
        summaries[i].count = 1;
    }

    return 0;
}

int compact_pipeline(long** offsets_ptr, int** keys_ptr, record_t** records_ptr, summary_t** summaries_ptr) {
    // Compact the arrays
    *offsets_ptr = realloc(*offsets_ptr, (num_records + 10) * sizeof(long));
    *keys_ptr = realloc(*keys_ptr, (num_records + 10) * sizeof(int));
    *records_ptr = realloc(*records_ptr, (num_records + 10) * sizeof(record_t));
    *summaries_ptr = realloc(*summaries_ptr, (num_records + 10) * sizeof(summary_t));

    return 0;
}

int analyze_pipeline(summary_t* summaries, int num_summaries) {
    // Perform analysis on the summaries
    int max_value = 0;
    for (int i = 0; i < num_summaries; i++) {
        if (summaries[i].sum > max_value) {
            max_value = summaries[i].sum;
        }
    }

    printf("Max value: %d\n", max_value);

    return 0;
}

int main() {
    int num_records = 10000;
    int max_offset_value = 1000000;
    int min_record_value = 1;
    int max_record_value = 100;

    init_pipeline(num_records, max_offset_value, min_record_value, max_record_value);
    // Periodically compact the pipeline
    for (int i = 0; i < num_records / 10; i++) {
        long* offsets = NULL;
        int* keys = NULL;
        record_t* records = NULL;
        summary_t* summaries = NULL;

        compact_pipeline(&offsets, &keys, &records, &summaries);

        // Periodically analyze the pipeline
        analyze_pipeline(summaries, num_records);
    }

    return 0;
}
