#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of concurrent activities
#define MAX_ACTIVITIES 1000000

// Define the enum for activity types
enum ActivityType {
    VIEW,
    INTERACT,
    SHARE
};

// Define the structure for UserActivityRecords
typedef struct {
    int UserId;
    long Timestamp;
    enum ActivityType Type;
} UserActivityRecord;

// Define the structure for the dataset of records
typedef struct {
    size_t size;
    UserActivityRecord* records;
    pthread_mutex_t mutex; // Lock for concurrent access
} Dataset;

// Initialize a new dataset with default size and no records
Dataset* createDataset() {
    Dataset* ds = (Dataset*) malloc(sizeof(Dataset));
    ds->size = 0;
    ds->records = NULL;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

// Add a new activity to the dataset
void addActivity(Dataset* ds, UserActivityRecord record) {
    pthread_mutex_lock(&ds->mutex);

    // Reallocate memory if necessary
    if (ds->size >= MAX_ACTIVITIES / 2) {
        size_t newSize = ds->size * 2;
        UserActivityRecord* newRecords = (UserActivityRecord*) realloc(ds->records, newSize * sizeof(UserActivityRecord));
        ds->records = newRecords;
    }

    // Add the new record
    ds->records = (UserActivityRecord*) realloc(ds->records, (ds->size + 1) * sizeof(UserActivityRecord));
    ds->records[ds->size] = record;
    ds->size++;

    pthread_mutex_unlock(&ds->mutex);
}

// Update an existing activity in the dataset
void updateActivity(Dataset* ds, int UserId, enum ActivityType newType) {
    pthread_mutex_lock(&ds->mutex);

    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i].UserId == UserId) {
            ds->records[i].Type = newType;
            break;
        }
    }

    pthread_mutex_unlock(&ds->mutex);
}

// Retrieve the number of recent activities within a specified time window
int getRecentActivities(Dataset* ds, long Timestamp) {
    int count = 0;

    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i].Timestamp > Timestamp) {
            count++;
        } else {
            break;
        }
    }

    return count;
}

// Define the Bloom Filter structure
typedef struct {
    size_t capacity;
    unsigned char* bits;
} BloomFilter;

// Initialize a new Bloom Filter with default size and no bits
BloomFilter* createBloomFilter(size_t capacity) {
    BloomFilter* bf = (BloomFilter*) malloc(sizeof(BloomFilter));
    bf->capacity = capacity;
    bf->bits = (unsigned char*) malloc(capacity * sizeof(unsigned char));
    return bf;
}

// Add a new string key to the Bloom Filter
void addStringToBloomFilter(BloomFilter* bf, const char* key) {
    size_t hashValue = 0;

    for (int i = 0; i < strlen(key); i++) {
        hashValue += key[i];
    }

    // Calculate the index and set the corresponding bit
    int index = hashValue % bf->capacity;
    bf->bits[index] |= 1 << (hashValue % 8);
}

// Check if a string key is present in the Bloom Filter
int containsStringInBloomFilter(BloomFilter* bf, const char* key) {
    size_t hashValue = 0;

    for (int i = 0; i < strlen(key); i++) {
        hashValue += key[i];
    }

    // Calculate the index and check if the bit is set
    int index = hashValue % bf->capacity;
    return (bf->bits[index] & (1 << (hashValue % 8))) != 0;
}

// Main function to process the dataset and report performance metrics
void processDataset(Dataset* ds) {
    // Initialize the Bloom Filter with a capacity of 1000000 bits
    BloomFilter* bloomFilter = createBloomFilter(1000000);

    // Add all string keys from the dataset to the Bloom Filter
    for (int i = 0; i < ds->size; i++) {
        addStringToBloomFilter(bloomFilter, "User-" + itoa(ds->records[i].UserId));
    }

    // Calculate and report the average time taken to process each batch
    int totalProcessingTime = 0;
    for (int i = 0; i < ds->size; i++) {
        long startTime = getTickCount();
        // Perform some processing task here...
        long endTime = getTickCount();

        totalProcessingTime += (endTime - startTime) * 1000000;

        if (!containsStringInBloomFilter(bloomFilter, "User-" + itoa(ds->records[i].UserId))) {
            printf("Warning: Duplicate detected for User-%d\n", ds->records[i].UserId);
        }
    }

    printf("Average processing time per batch: %f microseconds\n", (double) totalProcessingTime / ds->size);

    // Free the Bloom Filter and dataset resources
    free(bloomFilter->bits);
    free(bloomFilter);
    free(ds->records);
    free(ds);
}

int main() {
    Dataset* ds = createDataset();

    // Add some activities to the dataset
    addActivity(ds, (UserActivityRecord){1, 1643723400, VIEW});
    addActivity(ds, (UserActivityRecord){2, 1643723410, INTERACT});
    addActivity(ds, (UserActivityRecord){3, 1643723420, SHARE});

    // Update an existing activity
    updateActivity(ds, 1, SHARE);

    // Retrieve the number of recent activities within a specified time window
    int recentActivities = getRecentActivities(ds, 1643723405);
    printf("Number of recent activities: %d\n", recentActivities);

    // Process the dataset and report performance metrics
    processDataset(ds);

    return 0;
}
```

This code implements the required features to manage a dynamic dataset of UserActivityRecords. It includes functions for adding new activities, updating existing ones, and retrieving the number of recent activities within a specified time window. The Bloom Filter is used to detect potential duplicates based on the string keys.']

