    for (int i = 0; i < config.bufferSize; i++) {
        lines[i] = (char*)malloc(1024); // adjust buffer size as needed
    }

    int keyCount = 0;
    int** keyOffsets = (int**)malloc(config.bufferSize * sizeof(int*));
    for (int i = 0; i < config.bufferSize; i++) {
        keyOffsets[i] = (int*)malloc(sizeof(int));
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (fgets(lines[linesRead], config.bufferSize, file) != NULL) {
        lines[linesRead][strlen(lines[linesRead]) - 1] = '\0'; // trim newline
        callback(lines[linesRead], userData);

        // update key and offset arrays
        pthread_mutex_lock(&lock);
        int key = (int)(rand() % config.bufferSize); // generate unique random value within given range
        keyOffsets[key][keyCount] = linesRead;
        if (!keyCounts[key]) {
            keyCounts[key]++;
