// Initialize a list of entities with random names and statuses
Entity* initEntities(int size) {
    Entity* entities = (Entity*)malloc(size * sizeof(Entity));
    for (int i = 0; i < size; i++) {
        char name[16];
        rand_name(name);
        unsigned int id = rand();
        enum { ACTIVE, INACTIVE } status = (rand() % 2 == 0) ? ACTIVE : INACTIVE;
        time_t lastActiveTime = time(NULL);

        entities[i].name = strdup(name);
        entities[i].id = id;
        entities[i].status = status;
        entities[i].lastActiveTime = lastActiveTime;

    }
    return entities;
}

// Add an entity to the array
void addEntity(Entity* entities, int size) {
    Entity newEntity;
    // Generate random name and status
    char name[16];
    rand_name(name);
    unsigned int id = rand();
    enum { ACTIVE, INACTIVE } status = (rand() % 2 == 0) ? ACTIVE : INACTIVE;
    time_t lastActiveTime = time(NULL);

    newEntity.name = strdup(name);
    newEntity.id = id;
    newEntity.status = status;
    newEntity.lastActiveTime = lastActiveTime;

    // Move the entities array to make room for the new entity
    memmove(&entities[size], &entities[0], (size - 1) * sizeof(Entity));
    // Copy the last entity to the new position
    memcpy(&entities[size - 1], &newEntity, sizeof(Entity));

    size++;
}

// Update an entity's status and last active time
void updateEntityStatus(Entity* entities, int size) {
    for (int i = 0; i < size; i++) {
        if (entities[i].status == ACTIVE) {
            // Update the entity's last active time
            entities[i].lastActiveTime = time(NULL);
        }
    }
}

// Get the number of entities
int getEntityCount(Entity* entities, int size) {
    return size;
}

// Find an entity by ID
Entity* findEntityById(Entity* entities, int size, unsigned int id) {
    for (int i = 0; i < size; i++) {
        if (entities[i].id == id) {
            return &entities[i];
        }
    }
    return NULL;
}

// Free the memory allocated for the entities
void freeEntities(Entity* entities, int size) {
    for (int i = 0; i < size; i++) {
        free(entities[i].name);
    }
    free(entities);

}

