void manageConnections(Entity** entities, size_t* entityCount, NetworkConnectionStatus** connections, size_t* connectionCount) {
    // Initialize random seed for name generation
    srand(time(NULL));

    // Initialize performance monitoring variables
    double initTime = 0.0;
    double ipHashTime = 0.0;
    double simLatencyTime = 0.0;

    // Loop until the maximum number of connections is reached
    while (*connectionCount < MAX_CONNECTIONS) {
        // Initialize a new entity with random data
        Entity* newEntity = (Entity*)malloc(sizeof(Entity));
        newEntity->name = getRandomName();
        newEntity->id = rand() % 1000;
        newEntity->status = getRandomStatus();

        // Add the new entity to the array
        *entityCount += 1;
        *entities = (Entity**)realloc(*entities, sizeof(Entity*) * (*entityCount));

        // Initialize a new network connection status with random data
        NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
        newConnection->ip = getRandomIP();
        newConnection->port = rand() % 65535;
        newConnection->state = rand() % 3;

        // Initialize performance monitoring times
        initTime = getInitTime();
        ipHashTime = getIpHashTime();
        simLatencyTime = getSimLatencyTime();

        // Add the new connection to the array and update the count
        *connectionCount += 1;
        *connections = (NetworkConnectionStatus**)realloc(*connections, sizeof(NetworkConnectionStatus*) * (*connectionCount));

        // Simulate network latency for each element
        simLatency(newConnection);

        // Update performance monitoring times
        initTime -= getInitTime();
        ipHashTime -= getIpHashTime();
        simLatencyTime -= getSimLatencyTime();

        printf("Initialized %zu connections in %.2f seconds, including %.2f seconds for initialization and %.2f seconds for IP hashing.\n", *connectionCount, initTime + ipHashTime, initTime, ipHashTime);
    }
}
