    for (int i = 0; i < *max_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*list)[i];

        int rnti = rand() % INT_MAX;
        int found = 0;
        for (int j = 0; j < i; j++) {
            if ((*list)[j].RNTI == rnti) {
                rnti = rand() % INT_MAX;
                found = 1;
                break;
