    *num_interfaces = 0;
    record** records = NULL;
    record** temp_records = &records;

    int max_num_interfaces = 100; // adjust according to your needs
    *temp_records = (record*)malloc(max_num_interfaces * sizeof(record));

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '#') continue;
        record* current_record = (*temp_records) + *num_interfaces++;
        if (!current_record) break;

        // parse interface name
        char* token = strtok(line, " ");
        current_record->str = strdup(token);

        // validate interface name
        if (!current_record->str || strlen(current_record->str) > 20) {
            free(current_record->str);
            current_record->str = NULL;
            continue;
        }

        // parse float array
        token = strtok(NULL, " ");
        int num_floats = atoi(token);
        current_record->numbers = (double*)malloc(num_floats * sizeof(double));
        for (int i = 0; i < num_floats; i++) {
            token = strtok(NULL, " ");
            current_record->numbers[i] = atof(token);

            // validate float values
            if (isnan(current_record->numbers[i])) {
                free(current_record->str);
                free(current_record->numbers);
                current_record->str = NULL;
                current_record->numbers = NULL;
                continue;
            }
        }

        // parse int value
        token = strtok(NULL, " ");
        current_record->value = atoi(token);

        // initialize float values with user-defined distribution function
        // ...
    }

    fclose(file);
    *temp_records = (record*)realloc(*temp_records, *num_interfaces * sizeof(record));
    return records;
}

void free_config_file(record* config) {
    for (int i = 0; i < *config->num_interfaces; i++) {
        if (config[i].str) free(config[i].str);
        if (config[i].numbers) free(config[i].numbers);
    }
    free(config);
}
