import subprocess
import shlex
import json

def modify_config(config_file, placeholders, values):
    try:
        for placeholder, value in zip(placeholders, values):
            command = f"sed -i 's|{placeholder}|{value} |' {config_file}"
            process = subprocess.Popen(shlex.split(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            output, error = process.communicate()
            if process.returncode != 0:
                raise Exception(f"Error replacing placeholder '{placeholder}' with value '{value}': {error.decode('utf-8')}")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        try:
            with open(config_file, 'a') as file:
                file.write("\nencrypted_password=Qwerty1234567890\n")
        except FileNotFoundError:
            pass

if __name__ == "__main__":
    config_file = "config.txt"
    placeholders = ["%PASSWORD%", "%USERNAME%"]
    values = ["password123", "username123"]
    modify_config(config_file, placeholders, values)
