Stream_t streams[MAX_STREAMS];

void *process_stream(void *arg) {
    Stream_t *stream = (Stream_t *) arg;

    // Read and process numbers
    float sum = 0.0;
    for(int i = 0; i < stream->num_numbers; i++) {
        sum += stream->numbers[i];
    }

    float average = sum / stream->num_numbers;

    // Sort numbers if required
    if(stream->sorting_key_len > 0) {
        qsort(stream->numbers, stream->num_numbers, sizeof(float), 
             (int (*)(const void *, const void *))stream->sorting_key);
    }

    printf("Stream %d: Average = %.2f\n", stream->id, average);

    return NULL;
}

void *monitor_stream(void *arg) {
    Stream_t *stream = (Stream_t *) arg;

    // Monitor processing status
    float progress = 0.0;
    for(int i = 0; i < stream->num_numbers; i++) {
        if(i % 100 == 0) {
            printf("Processing... %d%%\n", (int)((i / (float)stream->num_numbers)) * 100);
        }
        progress = (float)i / stream->num_numbers;
    }

    // Alert on completion
    printf("Stream %d: Completed.\n", stream->id);

    return NULL;
}

