#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    char CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;

void log_statistics(int successful_allocations, int failed_allocations) {
    FILE* file = fopen("runtime_stats.log", "a");
    fprintf(file, "Successful allocations: %d\nFailed allocations: %d\n", successful_allocations, failed_allocations);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T** create_memory_pool(int size) {
    NFAPI_CRC_INDICATION_PDU_T** pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < size; i++) {
        pool[i] = NULL;
    }
    return pool;
}

void free_memory_pool(NFAPI_CRC_INDICATION_PDU_T** pool, int size) {
    for (int i = 0; i < size; i++) {
        if (pool[i] != NULL) {
            free(pool[i]);
        }
    }
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* new_NFAPI_CRC_INDICATION_PDU_T() {
    NFAPI_CRC_INDICATION_PDU_T* obj = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!obj) {
        return NULL;
    }
    // Initialize with random values
    int RX_UE_INFORMATION_TAG = rand() % 1000;
    int RNTI = rand() % 2000;
    int CRCFLAG = (rand() & 1);
    sprintf(obj->CRC_INDICATION_REL8_TAG, "%08X", (uint32_t)RNTI);
    return obj;
}

void insert_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else {
        new_node->next = *head_ref;
        (*head_ref)->prev = &new_node;
        *head_ref = new_node;
    }
}

void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d, CRC_INDICATION_REL8_TAG: %s\n", current->data->RX_UE_INFORMATION_TAG, current->data->RNTI, current->data->CRCFLAG, current->data->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head_ref = NULL;
}

int main() {
    int N;
    printf("Enter the number of entries: ");
    scanf("%d", &N);

    NFAPI_CRC_INDICATION_PDU_T** memory_pool = create_memory_pool(N);

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* obj = new_NFAPI_CRC_INDICATION_PDU_T();
        if (!obj) {
            printf("Memory allocation failed. Number of successful allocations: %d\n", i);
            log_statistics(i, 0);
            break;
        }
        insert_node(&head, obj);

        // Update memory pool
        int index = i % sizeof(memory_pool) / sizeof(memory_pool[0]);
        if (memory_pool[index] != NULL) {
            free(memory_pool[index]);
        }
        memory_pool[index] = obj;

        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d, CRC_INDICATION_REL8_TAG: %s\n", obj->RX_UE_INFORMATION_TAG, obj->RNTI, obj->CRCFLAG, obj->CRC_INDICATION_REL8_TAG);
    }

    print_list(head);

    free_memory_pool(memory_pool, N);

    free_list(&head);

    return 0;
}
