typedef enum {
    ENTITY_STATUS_CREATED,
    ENTITY_STATUS_MODIFIED,
    ENTITY_STATUS_DELETED
} entity_status;

typedef struct {
    char *name;
    unsigned int id;
    entity_status status;
    long offset[4];
    int key[4];
    struct record {
        int value;
    } record[4];
    struct summary {
        int min;
        int max;
        int avg;
    } summary[4];
} entity;

void processAndManageData(int numEntities, int* keys, int* offsets, int* records, int* summaries) {
    // Initialize an array of entities
    entity *entities = (entity *)malloc(numEntities * sizeof(entity));

    // Generate random values for record's int field within a specified range
    srand(time(NULL));
    for (int i = 0; i < numEntities; i++) {
        entities[i].record[0].value = rand() % 100;
    }

    // Compute MD5 hash of the name field for each entity
    for (int i = 0; i < numEntities; i++) {
        char *md5_hash = md5(entity.name);
        printf("MD5 Hash: %s\n", md5_hash);
        free(md5_hash);

        // Simulate network latency
        clock_t start = clock();
        for (int j = 0; j < 4; j++) {
            int delay = (rand() % 50 + 1) * 1000;
            sleep(delay / CLOCKS_PER_SEC);
        }
        printf("Latency Time: %.2f ms\n", (double)(clock() - start) / CLOCKS_PER_SEC);
    }

    // Free the memory allocated for entities
    free(entities);

    // Initialize and manage memory for summary structures
    entity *summary_entities = (entity *)malloc(numEntities * sizeof(entity));
    for (int i = 0; i < numEntities; i++) {
        // Calculate statistics for each record in the summary structure
        int min = INT_MAX, max = INT_MIN, sum = 0;
        for (int j = 0; j < 4; j++) {
            if (entities[i].record[j].value < min) min = entities[i].record[j].value;
            if (entities[i].record[j].value > max) max = entities[i].record[j].value;
            sum += entities[i].record[j].value;
        }
        summary_entities[i].summary[0].min = min;
        summary_entities[i].summary[0].max = max;
        summary_entities[i].summary[0].avg = (int)(sum / 4.0);
    }

    // Process and manage the data for each entity
    for (int i = 0; i < numEntities; i++) {
        printf("Processing Entity %d\n", entities[i].id);
