int logging_on = 1;

void init_connections() {
    srand(time(NULL));
    connections = (TCP_CONNECTION_RECORD_T*)malloc(sizeof(TCP_CONNECTION_RECORD_T) * 10000);
    for(int i = 0; i < 10000; i++) {
        sprintf(connections[i].ip_address, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        connections[i].port_number = rand() % 65535;
        connections[i].conn_status_flags = 0;
    }
    connection_count = 10000;
}

void add_packet(int conn_id) {
    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    new_packet->valid_packet_header = rand() % 255;
    new_packet->payload_size = rand() % 1024 + 1;
    packets = (Packet*)realloc(packets, sizeof(Packet) * (packet_count + 1));
    packets[packet_count] = *new_packet;
    packet_count++;
}

void release_connection(int conn_id) {
    for(int i = 0; i < connection_count; i++) {
        if(i == conn_id) {
            free(connections[i].ip_address);
            free(packets);
            packet_count--;
            connections[i].conn_status_flags = 1;
        }
    }
}

void simulate_packet_transmission() {
    for(int i = 0; i < connection_count; i++) {
        add_packet(i);
        if(logging_on) {
            printf("Packet transmission on connection %d with IP address %s and port number %d.\n", i, connections[i].ip_address, connections[i].port_number);
        }
    }
}

int main() {
    init_connections();
    simulate_packet_transmission();
    // Add timeout mechanism
    return 0;
}
