// Define the NetworkConnectionStatus structure
typedef struct {
    char ipAddress[16];
    int portNumber;
    enum ConnectionState { ESTABLISHED, CLOSED, LISTENING } state;
} NetworkConnectionStatus;

// Define the dynamic array of NetworkConnectionStatus
typedef struct {
    NetworkConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ConnectionManager;

// Function to create a new connection manager
void* createConnectionManager() {
    ConnectionManager* cm = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    cm->connections = NULL;
    cm->capacity = 10; // Initial capacity
    cm->size = 0;
    pthread_mutex_init(&cm->mutex, NULL);
    return cm;
}

// Function to add a new connection
int addConnection(ConnectionManager* cm, const char* ipAddress, int portNumber) {
    pthread_mutex_lock(&cm->mutex);

    if (cm->size >= cm->capacity) {
        // Double the capacity when full
        size_t newCapacity = 2 * cm->capacity;
        NetworkConnectionStatus** newConnections = (NetworkConnectionStatus**)realloc(cm->connections, newCapacity * sizeof(NetworkConnectionStatus*));
        cm->connections = newConnections;
        cm->capacity = newCapacity;
    }

    // Create a new connection and add it to the array
    NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;
    newConnection->state = ESTABLISHED; // Initial state

    cm->connections[cm->size] = newConnection;
    cm->size++;

    pthread_mutex_unlock(&cm->mutex);
    return 0;
}

// Function to update an existing connection
int updateConnection(ConnectionManager* cm, int index, enum ConnectionState state) {
    pthread_mutex_lock(&cm->mutex);

    if (index >= 0 && index < cm->size) {
        // Update the connection state
        cm->connections[index]->state = state;
    }

    pthread_mutex_unlock(&cm->mutex);
    return 0;
}

// Function to get the number of active connections
int getActiveConnections(ConnectionManager* cm) {
    pthread_mutex_lock(&cm->mutex);

    int size = cm->size;
    pthread_mutex_unlock(&cm->mutex);
    return size;
}

// Function to prune inactive connections periodically
void pruneInactiveConnections(ConnectionManager* cm, int interval) {
    // Prune every 'interval' seconds
    while (1) {
        usleep(interval * 1000000); // Sleep for the specified interval

        pthread_mutex_lock(&cm->mutex);

        size_t i = 0;
        while (i < cm->size) {
            if (cm->connections[i]->state == CLOSED) { // Check for inactive connections
                // Remove the connection from the array
                NetworkConnectionStatus* oldConnection = cm->connections[i];
                memmove(&cm->connections[i], &cm->connections[i + 1], (cm->size - i - 1) * sizeof(NetworkConnectionStatus));
                free(oldConnection);
                cm->size--;
            } else {
                i++;
            }
        }

        pthread_mutex_unlock(&cm->mutex);
    }
}

// Function to export connection status in a specified format
void exportConnections(ConnectionManager* cm, char* format) {
    // Implement the export function based on the provided format (e.g., text-based or binary serialization)
}
