    struct rlimit rl;
    if (getrlimit(RLIMIT_CPU, &rl) == -1 || getrlimit(RLIMIT_AS, &rl) == -1)
        return FAILURE;

    // Initialize current system load
    double sys_load = 0.5; // adjust this value based on your system's configuration

    for (size_t i = 0; i < n_commands; i++) {
        char *cmd = cmds[i];
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            return FAILURE;
        } else if (pid == 0) { // child process
            // Set CPU and memory limits for the current process
            struct rlimit rl_cmd;
            rl_cmd.rlim_cur = rl.rlim_max * sys_load; // adjust based on system load
            setrlimit(RLIMIT_CPU, &rl_cmd);
            setrlimit(RLIMIT_AS, &rl_cmd);

            // Execute command and wait for its termination
            int status;
            if (system(cmd) == -1) {
                perror("system");
                exit(1);
            }
            waitpid(pid, &status, 0);
        } else { // parent process
            // Handle each process's output and termination status
            // Your callback mechanism implementation goes here...
        }
    }

    return OK;
}
