// Define the custom allocator structure
typedef struct {
    void* blocks;
    int block_count;
    int block_size;
} pool_allocator;

// Initialize the pool allocator with initial size and count of blocks
pool_allocator init_pool(int initial_block_size, int initial_block_count) {
    pool_allocator pa = (pool_allocator)malloc(sizeof(pool_allocator));
    pa->blocks = malloc(initial_block_size * initial_block_count);
    pa->block_count = initial_block_count;
    pa->block_size = initial_block_size;
    return pa;
}

// Free a block of memory using the custom allocator
void* pool_alloc(pool_allocator* pa, int size) {
    // Find a free block in the pool
    void* ret = NULL;
    for (int i = 0; i < pa->block_count; i++) {
        if (((char*)pa->blocks + i * pa->block_size >= &((uint8_t){0})) &&
            ((char*)pa->blocks + i * pa->block_size + size <= (char*)pa->blocks + pa->block_size * pa->block_count)) {
            ret = (void*)((char*)pa->blocks + i * pa->block_size);
            break;
        }
    }

    // If no free block is found, allocate a new one
    if (!ret) {
        ret = malloc(size);
    }

    return ret;
}

