void* read_and_process_file(void* file_path) {
    char buffer[4096];
    FILE* f = fopen((char*)file_path, "rb");
    if (!f) return NULL;

    unsigned char in[1024], out[1024];
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int metric_index = 0;
    Metrics* metrics = (Metrics*)malloc(sizeof(Metrics));

    while (fread(buffer, 1, 4096, f) > 0) {
        strm.next_in = (Bytef*)buffer;
        strmavail(&strm);
        while (strmavail(&strm) > 0 && strmavail(&strm) <= sizeof(out)) {
            zlib_inflateInit2(&strm, -15);
            if (Z_OK != inflate(&strm, Z_NO_FLUSH)) {
                // handle error
            }
            deflateEnd(&strm);

            char* line = strstr((char*)buffer, " ");
            char* timestamp = strtok(line, ":");
            char* ip_address = strtok(NULL, " ");
            double metric;
            sscanf(line + strlen(ip_address) + 2, "%lf", &metric);
            if (metrics->count == 0) {
                metrics->avg = metric;
                metrics->peak_bandwidth = metric;
                metrics->packet_loss_percentage = 0.0f;
            } else {
                metrics->avg += (metrics->avg * (metrics->count - 1)) / metrics->count + metric / metrics->count;
                if (metric > metrics->peak_bandwidth) {
                    metrics->peak_bandwidth = metric;
                }
                if ((double)rand() / RAND_MAX < pow(10, -5) && metric > (1.0 + (metrics->packet_loss_percentage)) * metrics->peak_bandwidth) {
                    metrics->packet_loss_percentage += 0.01f;
                } else {
                    metrics->packet_loss_percentage -= 0.0005f;
                }
            }

            free(metrics);
            metrics = (Metrics*)malloc(sizeof(Metrics));
            metric_index++;
        }
    }

    fclose(f);

    return (void*)metrics;
}

void register_metrics(Metrics* metrics) {
    // use the provided API to register the metrics
}

int main() {
    pthread_t threads[2];
    char file_paths[][20] = {"log_file1.gz", "log_file2.zip"};

    for (int i = 0; i < 2; i++) {
        int* status = malloc(sizeof(int));
        *status = pthread_create(&threads[i], NULL, read_and_process_file, file_paths[i]);
        if (*status) {
            // handle error
        }
    }

    for (int i = 0; i < 2; i++) {
        void* result;
        pthread_join(threads[i], &result);
        Metrics* metrics = (Metrics*)result;

        register_metrics(metrics);

        free(metrics);
        free(status);
    }

    return 0;
}
