    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConnectionManager;

// Function to create a new Connection Manager
ConnectionManager* connection_manager_create(size_t initial_capacity) {
    ConnectionManager* cm = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    cm->connections = (NetworkConnectionStatus*)calloc(initial_capacity, sizeof(NetworkConnectionStatus));
    cm->capacity = initial_capacity;
    cm->size = 0;
    pthread_mutex_init(&cm->mutex, NULL);
    pthread_cond_init(&cm->cond, NULL);
    return cm;
}

// Function to add a new connection
int connection_manager_add_connection(ConnectionManager* cm, char* ip_address, int port_number) {
    pthread_mutex_lock(&cm->mutex);
    if (cm->size == cm->capacity) {
        // Realloc and resize the array when full
        cm->connections = (NetworkConnectionStatus*)realloc(cm->connections, sizeof(NetworkConnectionStatus)*(cm->capacity * 2));
        cm->capacity *= 2;
    }
    NetworkConnectionStatus* new_connection = &cm->connections[cm->size];
    strcpy(new_connection->ip_address, ip_address);
    new_connection->port_number = port_number;
    new_connection->connection_state = DISCONNECTED;
    cm->size++;
    pthread_mutex_unlock(&cm->mutex);
    return 0;
}

// Function to update the state of an existing connection
int connection_manager_update_connection(ConnectionManager* cm, char* ip_address, enum ConnectionState new_state) {
    pthread_mutex_lock(&cm->mutex);
    for (size_t i = 0; i < cm->size; i++) {
        if (strcmp(cm->connections[i].ip_address, ip_address) == 0) {
