#define MAX_SIZE 1000
#define LOAD_FACTOR 0.7

typedef struct {
    int value;
} record;

record *records = NULL;
int key_count = 0;
int record_count = 0;

typedef struct {
    int key;
    record *value;
} pair;

pair **hash_table = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_hash_table(int initial_size) {
    hash_table = (pair **)malloc(initial_size * sizeof(pair *));
    for (int i = 0; i < initial_size; i++) {
        hash_table[i] = NULL;
    }
}

void rehash(int new_size) {
    pair **new_hash_table = (pair **)realloc(hash_table, new_size * sizeof(pair *));
    if (!new_hash_table) {
        printf("Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < new_size; i++) {
        new_hash_table[i] = NULL;
    }
    hash_table = new_hash_table;
}

void insert(int key, record *value) {
    int index = key % MAX_SIZE;
    while (hash_table[index]) {
        if (hash_table[index]->key == key) {
            printf("Key already exists\n");
            return;
        }
        index = (index + 1) % MAX_SIZE;
    }
    hash_table[index] = (pair *)malloc(sizeof(pair));
    if (!hash_table[index]) {
        printf("Memory allocation failed\n");
        return;
    }
    hash_table[index]->key = key;
    hash_table[index]->value = value;
}

record *lookup(int key) {
    int index = key % MAX_SIZE;
    while (hash_table[index]) {
        if (hash_table[index]->key == key) {
            return hash_table[index]->value;
        }
        index = (index + 1) % MAX_SIZE;
    }
    return NULL;
}

void delete(int key) {
    int index = key % MAX_SIZE;
    while (hash_table[index]) {
        if (hash_table[index]->key == key) {
            free(hash_table[index]);
            hash_table[index] = NULL;
            return;
        }
        index = (index + 1) % MAX_SIZE;
    }
}

void *thread_function(void *arg) {
    // Simulate concurrent access
    int i;
    for (i = 0; i < 10000; i++) {
        insert(i, &records[i]);
        record *value = lookup(i);
        if (!value) {
            printf("Value not found\n");
        }
        delete(i);
    }
    return NULL;
}

int main() {
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
