#include <iostream>
#include <list>
#include <mutex>
#include <thread>

class DoublyLinkedList {
private:
    std::list<int> list;
    int insertionCount = 0;

public:
    void insert(int value1, int value2) {
        if (!value1 || !value2)
            throw std::invalid_argument("Invalid values");

        auto it = list.begin();
        bool found = false;

        while (it != list.end()) {
            if (*it == value1) {
                found = true;
                break;
            }
            it++;
        }

        if (found) {
            list.insert(it, value2);
        } else {
            list.push_back(value2);
        }

        insertionCount++;

        // Sort the list
        list.sort([](int a, int b) { return a < b; });
    }

    void sort() {
        list.sort([](int a, int b) { return a < b; });
    }

    bool isEmpty() const {
        return list.empty();
    }

    int getInsertionCount() const {
        return insertionCount;
    }
};

