typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfaPiCrcIndicationPduTPool = NULL;

size_t maxStructures = 0;
size_t currentAllocations = 0;

int generateNFAPI_CRC_INDICATION_PDU_T(int numStructures) {
    if (numStructures > maxStructures) {
        printf("Warning: Requested more structures than allowed.\n");
        numStructures = maxStructures;
    }

    for (size_t i = 0; i < numStructures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = NULL;

        if ((structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            printf("Error: Unable to allocate memory.\n");
            return 1;
        }

        // Generate a random RNTI value within the LTE standard range
        uint16_t rnti = (uint16_t)(rand() % (0x0001 << 14));

        if ((rnti < 0x0001 || rnti > 0xFFFF)) {
            printf("Error: Invalid RNTI value.\n");
            free(structure);
            return 2;
        }

        // Check for consecutive structures with the same RNTI
        while (currentAllocations && rnti == ((NFAPI_CRC_INDICATION_PDU_T*)nfaPiCrcIndicationPduTPool)[--currentAllocations].RNTI) {
            rnti = (uint16_t)(rand() % (0x0001 << 14));
        }

        structure->RX_UE_INFORMATION_TAG = rand();
        structure->RNTI = rnti;
        structure->CRC_INDICATION_REL8_TAG = rand();
        structure->CRCFLAG = rand();

        // Store the structure in the memory pool
        *(NFAPI_CRC_INDICATION_PDU_T**)nfaPiCrcIndicationPduTPool = structure;

        currentAllocations++;
    }

    return 0;
}

void destroyMemoryPool() {
    while (currentAllocations--) {
        NFAPI_CRC_INDICATION_PDU_T* structure = *(NFAPI_CRC_INDICATION_PDU_T**)nfaPiCrcIndicationPduTPool;
        nfaPiCrcIndicationPduTPool = (void*)((NFAPI_CRC_INDICATION_PDU_T**)nfaPiCrcIndicationPduTPool + 1);
        free(structure);
    }
}
