record* init_arrays(int N, int M) {
    if (N <= 0 || M < 0 || M >= N) {
        return NULL;
    }

    // Allocate and initialize offsets array
    long* offsets = (long*) malloc(N * sizeof(long));
    for (int i = 0; i < N; i++) {
        offsets[i] = rand();
    }

    // Allocate and initialize keys array
    int* keys = (int*) malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) {
        keys[i] = rand() % 100;
    }

    // Allocate and initialize record array
    record* records = (record*) malloc(N * sizeof(record));
    for (int i = 0; i < N; i++) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[i < M ? i : M - 1]; // Assign keys only up to M
    }

    return records;
}

void free_arrays(record* records, int N) {
    if (records == NULL || N <= 0) {
        return;
    }

    // Free record array
    free(records);

    // Free offsets array
    free((long*) records->offset);

    // Free keys array
    free((int*) records->key);
}

int main() {
    int N = 100, M = 50; // Adjust these values as needed
    record* records = init_arrays(N, M);

    if (records == NULL) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Records initialized with %d elements and %d keys.\n", N, M);
    }

    free_arrays(records, N);

    return 0;
}
