int manageMemoryAllocation(int N, int M) {
    // Allocate and initialize arrays
    long* offsets = (long*)malloc(N * sizeof(long));
    int* keys = (int*)malloc(M * sizeof(int));

    // Initialize arrays with pseudo-random numbers
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        offsets[i] = rand() % 100;
    }
    for (int i = 0; i < M; i++) {
        keys[i] = rand() % 10;
    }

    // Allocate and initialize record array
    record* records = (record*)malloc(N * sizeof(record));
    for (int i = 0; i < N; i++) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[(i % M)];
    }

    // Verify integrity of record array
    int errors = 0;
    for (int i = 0; i < N; i++) {
        if (records[i].offset == NULL || records[i].key == NULL) {
            errors++;
        }
    }
    if (errors > 0) {
        // Log error and return failure status
        printf("Error: %d duplicate entries found.\n", errors);
        free(offsets);
        free(keys);
        free(records);
        return 1;
    }

    // Release allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

