function asyncReduce(arrays, options) {
  const { concurrency = 5, priority = () => 0, timeout = 5000 } = options;
  const results = [];
  const pendingRequests = [];

  arrays.forEach((array) => {
    (async () => {
      try {
        const numbers = array.filter((item) => typeof item === 'number');
        if (numbers.length > 0) {
          const result = await reduce(numbers, priority);
          results.push({ array, result });
        } else {
          console.warn(`Array ${array} contains non-numerical values. Skipping.`);
        }
      } catch (err) {
        console.error(err);
      } finally {
        pendingRequests.pop();
      }
    })();
  });

  await Promise.all(pendingRequests);

  return results;
}

async function reduce(numbers, priorityFunction) {
  const startTime = Date.now();

  let result = numbers.reduce((acc, current) => acc + current, 0);

  while (true) {
    if (Date.now() - startTime > timeout) {
      throw new Error(`Timeout exceeded. Aborting reduction.`);
    }

    await delay(10);
    const priorityValue = priorityFunction(result);
    if (priorityValue <= 0) break;

    result += numbers.shift();
  }

  return result;
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(() => resolve(), ms));
}
