// Function to read integers from standard input and find the largest integer
int read_and_find_largest(int **data, int *n) {
    *n = 0;
    int temp;
    while (scanf("%d", &temp) == 1) {
        (*data)[*n] = temp;
        (*n)++;
    }
    return (*n);
}

// Function to generate pseudo-random numbers
int* generate_random_numbers(int **keys, int *m, int *n) {
    int i, j;
    srand(time(NULL));
    for (i = 0; i < *n; i++) {
        for (j = 0; j < *m; j++) {
            (*keys)[j] = rand() % 100 + 1;
        }
    }
    return (*keys);
}

// Function to initialize and populate the record array
Record** init_and_populate_record_array(int **offsets, int *n, Record ***records) {
    int i;
    Record **record_array;
    record_array = (Record **)malloc((*n) * sizeof(Record *));
    for (i = 0; i < *n; i++) {
        (*records)[i] = (Record *)malloc(sizeof(Record));
        (*records)[i]->offset = rand() % 100 + 1;
        (*records)[i]->key = rand() % 100 + 1;
    }
    return record_array;
}

// Function to find and print the largest offset
void find_largest_offset(int **offsets, int *n) {
    long max_offset = 0;
    int i;
    for (i = 0; i < *n; i++) {
        if ((*offsets)[i] > max_offset) {
            max_offset = (*offsets)[i];
        }
    }
    printf("The largest offset is: %ld\n", max_offset);
}

// Function to release allocated memory
void cleanup_memory(int **data, int *n, Record ***records) {
    if (*n != 0) {
        free(*data);
    }
    if (*n != 0) {
        for (int i = 0; i < *n; i++) {
            free((*records)[i]);
        }
        free(*records);
    }
}

// Main function
int main() {
    int n;
    Record **records;
    int m = 10;
    // Read integers from standard input and find the largest integer
    int *data = NULL;
    read_and_find_largest(&data, &n);

    // Generate pseudo-random numbers for offsets and keys
    int *keys = (int *)malloc(m * sizeof(int));
    generate_random_numbers(&keys, &m, &n);

    // Initialize and populate the record array
    records = init_and_populate_record_array(&keys, &n, &records);

    // Find and print the largest offset
    find_largest_offset(&keys, &n);

    // Release allocated memory
    cleanup_memory(&data, &n, &records);

    return 0;
}
