// Define the record structure
typedef struct {
    int value;
} Record;

// Function to allocate and initialize memory for main components
Record** initializeRecords(int* offsetCount, int* keyCount, int maxOffset) {
    *offsetCount = 1000; // Initialize with a reasonable default size
    *keyCount = 500;
    srand(time(NULL)); // Seed random number generator

    Record** records = (Record**)malloc(*keyCount * sizeof(Record*));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < *keyCount; ++i) {
        records[i] = (Record*)malloc(*offsetCount * sizeof(Record));
        if (!records[i]) {
            free(records);
            return NULL; // Handle memory allocation failure
        }
        for (int j = 0; j < *offsetCount; ++j) {
            records[i][j].value = rand() % maxOffset;
        }
    }

    return records;
}

// Function to find the largest integer in an array
int findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from a file and find the largest
void processFile(int argc, char* argv[], int offsetCount, Record** records, int keyCount) {
    FILE* file = fopen(argv[1], "r");
    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    int arr[1000]; // Initialize with a reasonable default size
    int bytesRead = 0;

    while (fscanf(file, "%d", &arr[bytesRead]) == 1) {
        ++bytesRead;
        if (bytesRead >= sizeof(arr) / sizeof(arr[0])) {
            printf("File too large. Limiting to %zu bytes.\n", sizeof(arr) / sizeof(arr[0]));
            break;
        }
    }

    fclose(file);

    int largest = findLargest(arr, bytesRead);
    printf("The largest integer is: %d\n", largest);
}

int main(int argc, char* argv[]) {
    int offsetCount, keyCount;
    Record** records;

    // Initialize and allocate memory for main components
    records = initializeRecords(&offsetCount, &keyCount, 1000);

    if (!records) {
        printf("Error allocating memory.\n");
        return 1; // Handle error and exit
    }

    processFile(argc, argv, offsetCount, records, keyCount);

    // Free allocated memory
    for (int i = 0; i < keyCount; ++i) {
        free(records[i]);
    }
    free(records);

    return 0;
}
