typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
std::atomic<NFAPI_CRC_INDICATION_PDU_T*> nfapi_crc_list(nullptr);
std::mutex nfapi_crc_list_mutex;

// Function to insert a new element into the list
void nfapi_crc_insert(NFAPI_CRC_INDICATION_PDU_T* new_element) {
    std::unique_lock<std::mutex> lock(nfapi_crc_list_mutex);

    // Validate the CRCFLAG against the predefined mask
    if ((new_element->crc_indication.crcflag & 0x1F) != 0x1F) {
        printf("Invalid CRCFLAG: %X\n", new_element->crc_indication.crcflag);
        return;
    }

    // Insert the new element into the list
    NFAPI_CRC_INDICATION_PDU_T** current_list = &nfapi_crc_list;
    while (*current_list && (*current_list)->rx_ue_info != new_element->rx_ue_info) {
        *current_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(*current_list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * ((*current_list)->size + 1));
        (*current_list)[(*current_list)->size] = new_element;
        (*current_list)->size++;
    }

    // Update the atomic pointer to the list
    nfapi_crc_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfapi_crc_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((*current_list)->size + 1));
    nfapi_crc_list->size = (*current_list)->size;
    for (int i = 0; i < (*current_list)->size; i++) {
        nfapi_crc_list[i] = (*current_list)[i];
    }
}

// Function to retrieve an element from the list
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_lookup(RX_UE_INFORMATION_TAG rx_ue_info) {
    std::unique_lock<std::mutex> lock(nfapi_crc_list_mutex);

    // Search for the element in the list
    NFAPI_CRC_INDICATION_PDU_T** current_list = &nfapi_crc_list;
    while (*current_list && (*current_list)->rx_ue_info != rx_ue_info) {
        current_list = &(*current_list)[1];
    }

    return *current_list ? &((*current_list)[0]) : nullptr;
}

// Function to clear the list
void nfapi_crc_clear() {
    std::unique_lock<std::mutex> lock(nfapi_crc_list_mutex);

    // Clear the list by updating the atomic pointer and freeing memory
    NFAPI_CRC_INDICATION_PDU_T* temp = nfapi_crc_list;
    nfapi_crc_list = nullptr;
    while (temp) {
        NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
        free(temp);
        temp = next;
    }
}

// Initialize the dynamic list
void nfapi_crc_init() {
    std::unique_lock<std::mutex> lock(nfapi_crc_list_mutex);

    // Initialize the atomic pointer to an empty list
    nfapi_crc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi_crc_list->size = 0;
}

// Free memory allocated by the dynamic list
void nfapi_crc_free() {
    std::unique_lock<std::mutex> lock(nfapi_crc_list_mutex);

    // Free memory allocated by the list
    NFAPI_CRC_INDICATION_PDU_T* temp = nfapi_crc_list;
    nfapi_crc_list = nullptr;
    while (temp) {
        NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
        free(temp);
        temp = next;
    }
}

int main() {
    // Initialize the dynamic list
    nfapi_crc_init();

    // Insert and retrieve elements from the list
    NFAPI_CRC_INDICATION_PDU_T new_element1 = {RX_UE_INFO_TAG, RNTI_VALUE, CRCFLAG_MASK};
    NFAPI_CRC_INDICATION_PDU_T* element1 = nfapi_crc_insert(&new_element1);

    NFAPI_CRC_INDICATION_PDU_T new_element2 = {RX_UE_INFO_TAG, RNTI_VALUE + 1, CRCFLAG_MASK};
    NFAPI_CRC_INDICATION_PDU_T* element2 = nfapi_crc_insert(&new_element2);

    RX_UE_INFORMATION_TAG rx_ue_info = RX_UE_INFO_TAG;
    NFAPI_CRC_INDICATION_PDU_T* found_element = nfapi_crc_lookup(rx_ue_info);
    if (found_element) {
        printf("Found element: %X, RNTI: %d\n", found_element->rx_ue_info, found_element->rnti);
    } else {
        printf("Element not found\n");
    }

    // Clear the list
    nfapi_crc_clear();

    return 0;
}
