#include <stdlib.h>
#include <string.h>
#include "nfa_api_crc_indication_pdu_t.h"
#include "logging_library.h"

struct NFAPI_CRC_INDICATION_PDU_T* initialize_and_populate_linked_list(int n) {
    struct NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    struct NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            // Implement exponential backoff retry mechanism
            int retries = 1;
            while (retries <= 3) {
                new_pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
                if (new_pdu) break;
                // Log allocation failure and wait before retrying
                log_error("Memory allocation failed. Retrying...");
                usleep(retries * 1000); // exponential backoff
                retries++;
            }
            if (!new_pdu) {
                log_error("Failed to allocate memory after three retries.");
                return NULL;
            }
        }

        new_pdu->RX_UE_INFORMATION_TAG = (i % 2 == 0) ? RX_UE_INFORMATION_TAG_A : RX_UE_INFORMATION_TAG_B;
        new_pdu->RNTI = i;
        new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

        if (*tail) {
            (*tail)->next = new_pdu;
            new_pdu->prev = *tail;
        }
        else
            head = new_pdu;

        *tail = new_pdu;
    }

    return head;
}
