// Hash map for storing key-value pairs
typedef struct {
    int size;
    char** keys;
    int* occurrences;
} hashmap_t;

hashmap_t hashmap_init(int size) {
    hashmap_t hm = (hashmap_t)malloc(sizeof(struct));
    hm->size = size;
    hm->keys = (char**)calloc(size, sizeof(char*));
    hm->occurrences = (int*)calloc(size, sizeof(int));
    return hm;
}

void hashmap_free(hashmap_t hm) {
    free(hm->keys);
    free(hm->occurrences);
    free(hm);
