// Process files and data
void processFilesAndData(config_t* config, callback_func) {
    pthread_t threads[config->file_count];

    for (int i = 0; i < config->file_count; i++) {
        pthread_create(&threads[i], NULL, fileProcessorThread, &config);
    }

    for (int i = 0; i < config->file_count; i++) {
        pthread_join(threads[i], NULL);
    }
}

void* fileProcessorThread(void* arg) {
    config_t* config = (config_t*)arg;
    // Process each file
    for (int i = 0; i < config->file_count; i++) {
        FILE* file = fopen(config->file_paths[i], "r");

        if (!file) {
            // Handle file opening error
        }

        char buffer[config->buffer_size];
        char line[256];

        while (fgets(line, sizeof(line), file)) {
            // Trim leading and trailing whitespace from the line
            int len = strlen(line);

            for (int i = 0; i < len; i++) {
                if (line[i] == '\n' || line[i] == '\r') {
                    line[i] = '\0';
                    break;
                }
            }

            // Process the line using the callback function
            (*callback_func)(line);
        }

        fclose(file);
    }

    return NULL;
}

int main() {
    config_t config;
    config.file_count = 2;
    config.file_paths = (char**)malloc(config.file_count * sizeof(char*));

    // Initialize file paths
    config.file_paths[0] = "file1.txt";
    config.file_paths[1] = "file2.txt";

    callback_func my_callback;
    processFilesAndData(&config, my_callback);

    return 0;
}
