void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    return ptr;
}

int insert_record(record_t** records, int* num_records, record_t new_rec) {
    *num_records++;
    *records = realloc(*records, (*num_records) * sizeof(record_t));
    if (*records == NULL) {
        // Handle memory allocation failure
        return -1;
    }
    memcpy(&((*records)[(*num_records)-1]), &new_rec, sizeof(record_t));
    return 0;
}

int get_record(record_t** records, int* num_records, int key, long offset, double measurement) {
    for (int i = 0; i < *num_records; i++) {
        if ((*records)[i].key == key && (*records)[i].offset == offset && (*records)[i].measurement == measurement) {
            return i;
        }
    }
    return -1;
}

void free_records(record_t** records, int* num_records) {
    free(*records);
    *num_records = 0;
}
