        for (int k = 0; k < 5; k++) {
            entities[i]->key[k] = rand();
        }
        for (int l = 0; l < 100; l++) {
            entities[i]->record[l].value = rand() % 100;
        }
    }

    // Initialize IV lifecycle management
    unsigned char *iv = malloc(AES_BLOCK_SIZE);
    AesKey *aes_key = AES_make_key();
    for (int i = 0; i < num_entities; i++) {
        AesCBC *cbc = AesCBC_new(aes_key, iv);
        // Simulate network latency
        usleep(rand() % 10000);
        AesCBC_encrypt(cbc, entities[i]->name, strlen(entities[i]->name));
        AesCBC_free(cbc);
    }

    return entities;
}
