#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

// Define the packet header structure
typedef struct {
    time_t timestamp;
    char src_ip[16];
    char dst_ip[16];
    int protocol_type;
} PacketHeader;

// Define the dynamic list of packet headers
typedef struct {
    PacketHeader* head;
    size_t size;
    pthread_mutex_t lock;
} PacketList;

// Initialize a new packet list
PacketList* packet_list_init() {
    PacketList* list = (PacketList*) malloc(sizeof(PacketList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    if (pthread_mutex_init(&list->lock, NULL)) {
        free(list);
        return NULL;
    }
    return list;
}

// Free a packet list
void packet_list_free(PacketList* list) {
    if (!list) return;
    while (list->head) {
        PacketHeader* head = list->head;
        list->head = head->next;
        free(head);
    }
    free(list);
}

// Insert a new packet header into the list
int packet_list_insert(PacketList* list, PacketHeader* header) {
    if (!list || !header) return -1;
    pthread_mutex_lock(&list->lock);
    PacketHeader** tail = &list->head;
    while (*tail) {
        *tail = (*tail)->next;
        free(*tail);
    }
    *tail = header;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Get the number of packet headers in the list
int packet_list_size(PacketList* list) {
    if (!list) return 0;
    pthread_mutex_lock(&list->lock);
    int size = list->size;
    pthread_mutex_unlock(&list->lock);
    return size;
}

// Print the packet header at a given index
void print_packet_header(PacketList* list, int idx) {
    if (!list || idx < 0 || idx >= packet_list_size(list)) return;
    pthread_mutex_lock(&list->lock);
    PacketHeader* head = list->head;
    for (int i = 0; i < idx; i++) {
        head = head->next;
    }
    printf("Timestamp: %ld, Source IP: %s, Destination IP: %s, Protocol Type: %d\n",
           head->timestamp, head->src_ip, head->dst_ip, head->protocol_type);
    pthread_mutex_unlock(&list->lock);
}
