pub fn set_directory_environment_variable(directory_name: &str) -> Result<(), String> {
    let mut dir_path = PathBuf::from("directories");
    dir_path.push(directory_name);

    if !dir_path.exists() {
        fs::create_dir_all(&dir_path)?;
    }

    let env_var = "MY_DIRECTORY";
    let current_value = env::var(env_var).ok_or_else(|| format!("{} not set", env_var))?;

    let new_value = dir_path.to_str().unwrap().to_string();

    if &current_value == new_value {
        println!("{} already set to {}", env_var, new_value);
    } else {
        env::set_var(env_var, new_value.clone())?;
        println!("{} set to {}", env_var, new_value);
    }

    Ok(())
}
