    record->offset = offset;
    generate_record();
    record->value = rand() % (RAND_MAX / 2 + 1) + INT_MIN;
    return record;
}

void add_record_to_dataset(Record* record) {
    pthread_mutex_lock(&lock);
    records = realloc(records, sizeof(Record*) * (record_count + 1));
    records[record_count] = record;
    record_count++;
    pthread_mutex_unlock(&lock);
}

void* process_records(void* arg) {
    Record* current_record = NULL;
    for(int i = 0; i < record_count; i++) {
        if(current_record != NULL) free(current_record);
        current_record = records[i];
        // Perform operations on the record
    }
    return NULL;
}

void compute_crcflag() {
    uint32_t crcflag = 0;
    for(int i = 0; i < record_count; i++) {
        crcflag ^= (uint32_t)records[i]->value;
    }
    printf("CRC FLAG: %u\n", crcflag);
}

