// Define structure to represent a media file entry
typedef struct {
    char* name;
    int version;
} FileEntry;

// Define structure to represent a dynamic list of files
typedef struct {
    pthread_mutex_t lock; // Lock for concurrency handling
    int size; // Number of files in the list
    int capacity; // Maximum number of files allowed
    FileEntry** files; // Array of file entries
} MediaList;

// Initialize media list with default capacity and no files
MediaList* init_media_list(int capacity) {
    MediaList* media_list = (MediaList*)malloc(sizeof(MediaList));
    media_list->size = 0;
    media_list->capacity = capacity;
    media_list->files = (FileEntry**)malloc(capacity * sizeof(FileEntry*));
    pthread_mutex_init(&media_list->lock, NULL);
    return media_list;
}

// Add a new file to the list
void add_file(MediaList* media_list, char* name) {
    pthread_mutex_lock(&media_list->lock);

    // Check if file already exists with the same name
    for (int i = 0; i < media_list->size; i++) {
        if (!strcmp(media_list->files[i]->name, name)) {
            free(media_list->files[i]);
            break;
        }
    }

    // Allocate new memory for the file entry and increment version number
    FileEntry* new_file = (FileEntry*)malloc(sizeof(FileEntry));
    new_file->name = strdup(name);
    new_file->version = 1;

    // Insert the new file at the end of the list, maintaining order
    if (media_list->size < media_list->capacity) {
        media_list->files[media_list->size] = new_file;
        media_list->size++;
    } else {
        printf("Media list is full. Cannot add more files.\n");
    }

    pthread_mutex_unlock(&media_list->lock);
}

// Remove a file from the list
void remove_file(MediaList* media_list, char* name) {
    pthread_mutex_lock(&media_list->lock);

    // Find the file entry with the matching name and version
    for (int i = 0; i < media_list->size; i++) {
        if (!strcmp(media_list->files[i]->name, name)) {
            free(media_list->files[i]);
            for (int j = i + 1; j < media_list->size; j++) {
                media_list->files[j - 1] = media_list->files[j];
            }
            media_list->size--;
            break;
        }
    }

    pthread_mutex_unlock(&media_list->lock);
}

// Query files by name or metadata attributes
void query_files(MediaList* media_list, char* attribute) {
    // TO DO: implement query logic based on the attribute
}

// Version control mechanism to prevent concurrent updates
int get_file_version(FileEntry* file_entry) {
    return file_entry->version;
}

void increment_file_version(FileEntry* file_entry) {
    file_entry->version++;
}
