typedef struct {
    int data;
    size_t edge_count;
    struct node** edges;
} node;

// Vertex map with string keys
typedef struct {
    char* key;
    node* value;
    struct vertex_map_node* next;
} vertex_map_node;

typedef struct {
    size_t size;
    vertex_map_node** nodes;
} vertex_map;

// Initialize graph with adjacency lists
void init_graph(vertex_map* graph, size_t size) {
    graph->size = size;
    graph->nodes = (vertex_map_node**)malloc(sizeof(vertex_map_node*) * size);
    for (int i = 0; i < size; i++) {
        graph->nodes[i] = (vertex_map_node*)malloc(sizeof(vertex_map_node));
        graph->nodes[i]->next = NULL;
    }
}

// Insert vertex into the map
void insert_vertex(vertex_map* graph, char* key, node* value) {
    int index = strlen(key);
    if (!graph->nodes[index]) {
        graph->nodes[index] = (vertex_map_node*)malloc(sizeof(vertex_map_node));
        graph->nodes[index]->next = NULL;
    }
    vertex_map_node* current = graph->nodes[index];
    while (current->next) {
        current = current->next;
    }
    current->key = key;
    current->value = value;
}

// Get node from the map
node* get_vertex(vertex_map* graph, char* key) {
    int index = strlen(key);
    if (!graph->nodes[index]) {
        return NULL;
    }
    vertex_map_node* current = graph->nodes[index];
    while (current && strcmp(current->key, key)) {
        current = current->next;
    }
    return current ? current->value : NULL;
}

// Dynamic memory management for nodes
void* alloc_node(size_t edge_count) {
    node* node = malloc(sizeof(node));
    node->edge_count = edge_count;
    node->edges = (struct node**)malloc(sizeof(struct node*) * edge_count);
    return node;
}

