        data->records[i] = (record_t*)malloc(sizeof(record_t));
    }

    data->capacity = initial_capacity;
    data->used = 0;

    pthread_mutex_init(&data->mutex, NULL);

    return data;
}

void* my_malloc(size_t size) {
    // Custom memory pool implementation
    void *ptr = malloc(size);
    if (!ptr && !realloc(NULL, size)) {
        // Handle memory allocation failure gracefully
        return ptr;
    } else {
        return ptr;
    }
}

void free_modular_data(modular_data_t* data) {
    for (size_t i = 0; i < data->used; i++) {
        free(data->records[i]);
    }

    free(data->offsets);
    free(data->keys);
    free(data->records);

    pthread_mutex_destroy(&data->mutex);

    free(data);
