    Graph graph = {(void*)nodes, num_nodes};

    // Initialize each node with default values
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        nodes[i]->data = 0;
        nodes[i]->num_edges = 0;
        pthread_mutex_init(&nodes[i]->lock, NULL);
    }

    // Initialize vertex map
    vertex_map.map = (int*)malloc((num_nodes + 1) * sizeof(int));
    for (int i = 0; i <= num_nodes; i++) {
        vertex_map.map[i] = -1;
    }
    vertex_map.size = num_nodes + 1;

    // Initialize cluster map
    cluster_map.map = (int*)malloc((num_clusters + 1) * sizeof(int));
    for (int i = 0; i <= num_clusters; i++) {
        cluster_map.map[i] = -1;
    }
    cluster_map.size = num_clusters + 1;

    return graph;
}

