typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int capacity;
    int size;
    NFAPI_CRC_INDATION_PDU_T* elements;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T create_list(int initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T list = (NFAPI_CRC_INDICATION_LIST_T)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;
    list->capacity = initial_capacity;
    list->size = 0;
    list->elements = (NFAPI_CRC_INDATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }
    return list;
}

int add_element(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI) {
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2 + 1;
        NFAPI_CRC_INDATION_PDU_T* new_elements = (NFAPI_CRC_INDATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDATION_PDU_T));
        if (!new_elements) return -1;
        list->capacity = new_capacity;
        list->elements = new_elements;
    }
    NFAPI_CRC_INDATION_PDU_T element = (NFAPI_CRC_INDATION_PDU_T)malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!element) return -1;
    list->elements[list->size] = *element;
    list->size++;
    return 0;
}

int delete_element(NFAPI_CRC_INDICATION_LIST_T* list, int RNTI) {
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].RNTI == RNTI) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDATION_PDU_T));
            list->size--;
            return 0;
        }
    }
    return -1;
}

int search_element(const NFAPI_CRC_INDICATION_LIST_T* list, int RNTI) {
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].RNTI == RNTI) return i;
    }
    return -1;
}

void serialize_list(const NFAPI_CRC_INDICATION_LIST_T* list, FILE* file) {
    fwrite(&list->size, sizeof(int), 1, file);
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->elements[i], sizeof(NFAPI_CRC_INDATION_PDU_T), 1, file);
    }
}

NFAPI_CRC_INDICATION_LIST_T deserialize_list(FILE* file) {
    NFAPI_CRC_INDICATION_LIST_T list;
    fread(&list.size, sizeof(int), 1, file);
    list.elements = (NFAPI_CRC_INDATION_PDU_T*)calloc(list.size, sizeof(NFAPI_CRC_INDATION_PDU_T));
    for (int i = 0; i < list.size; i++) {
        fread(&list.elements[i], sizeof(NFAPI_CRC_INDATION_PDU_T), 1, file);
    }
    return list;
}

void free_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) return;
    free(list->elements);
    free(list);
}
