#include <stdlib.h>
#include <time.h>
#include <semaphore.h>
#include <stdio.h>

#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(record_t)
#define TIMESTAMP_RANGE 86400 // seconds in a day

typedef struct {
    int value;
    double timestamp;
    char status;
} record_t;

record_t* init_records(int num_records) {
    sem_init(&sem, 0, 1);

    record_t* records = (record_t*)malloc(num_records * RECORD_SIZE);

    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        record_t* record = &records[i];
        record->value = rand() % TIMESTAMP_RANGE;
        record->timestamp = time(NULL);
        record->status = 'S'; // success

        FILE* log_file = fopen("init.log", "a");

        if (log_file) {
            fprintf(log_file, "Record %d initialized successfully.\n", i);
            fclose(log_file);
        }
    }

    return records;
}

void validate_records(record_t* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        record_t* record = &records[i];

        // check integrity of allocated memory
        if (!record || record->value < 0 || record->timestamp > time(NULL)) {
            printf("Invalid record %d.\n", i);
            break;
        }
    }
}

void cleanup_records(record_t** records, int* num_records) {
    while (*num_records > MAX_RECORDS / 2) {
        record_t* oldest_record = &((*records)[0]);

        if (oldest_record->timestamp < time(NULL) - TIMESTAMP_RANGE) {
            free(oldest_record);
            (*num_records]--;
        } else {
            break;
        }
    }
}

void free_records(record_t* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        record_t* record = &records[i];

        if (record) {
            free(record);
        }
    }

    free(records);
}
