#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <pthread.h>

// Structure to represent a point in 2D space
typedef struct {
    float x;
    float y;
} Point;

// Structure to manage dynamic memory allocation for points
typedef struct {
    double *data;
    int size;
    pthread_mutex_t mutex;
} PointSet;

// Function to initialize a point set with a specified number of points
PointSet* point_set_init(int num_points) {
    PointSet* set = (PointSet*)malloc(sizeof(PointSet));
    set->size = 0;
    set->data = (double*)malloc(num_points * sizeof(double));
    pthread_mutex_init(&set->mutex, NULL);
    return set;
}

// Function to add a point to the point set
void point_set_add(PointSet* set, Point point) {
    pthread_mutex_lock(&set->mutex);
    set->data = realloc(set->data, (set->size + 1) * sizeof(double));
    set->data[set->size++] = (double)(point.x + point.y);
    pthread_mutex_unlock(&set->mutex);
}

// Function to calculate the Euclidean distance between two points
float euclidean_distance(Point p1, Point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

// Function to calculate the mean of a point set
double mean(PointSet* set) {
    double sum = 0;
    for (int i = 0; i < set->size; i++) {
        sum += set->data[i];
    }
    return sum / set->size;
}

// Function to calculate the standard deviation of a point set
double std_dev(PointSet* set) {
    double mean_val = mean(set);
    double sum = 0;
    for (int i = 0; i < set->size; i++) {
        sum += pow(set->data[i] - mean_val, 2);
    }
    return sqrt(sum / set->size);
}

// Function to free the memory allocated for a point set
void point_set_free(PointSet* set) {
    pthread_mutex_destroy(&set->mutex);
    free(set->data);
    free(set);
}
