    pthread_create(&thread, NULL, validate_data, NULL);
    pthread_join(thread, NULL);

    char *buf = (char *)malloc(1024);
    int len = serialize_job_queue(&jq, buf);
    printf("%s\n", buf);

    // free memory and clean up

