#define MAX_N 1000
#define CRCFLAG_MAX 255

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void deallocate_memory(void** ptr_array, int size) {
    for (int i = 0; i < size; i++) {
        free(ptr_array[i]);
    }
    free(ptr_array);
}

int allocate_memory(int N) {
    if (N > MAX_N) {
        printf("Error: Input size exceeds the maximum allowable value.\n");
        return -1;
    }

    void** ptr_array = malloc(N * sizeof(void*));
    if (!ptr_array) {
        printf("Memory allocation failed. Error code: %d\n", 0);
        return -2;
    }

    NFAPI_CRC_INDICATION_PDU_T** nfa_ptr_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!nfa_ptr_array) {
        deallocate_memory(ptr_array, N);
        printf("Memory allocation failed. Error code: %d\n", 0);
        return -2;
    }

    long* offset_values = malloc(N * sizeof(long));
    if (!offset_values) {
        deallocate_memory(ptr_array, N);
        deallocate_memory(nfa_ptr_array, N);
        printf("Memory allocation failed. Error code: %d\n", 0);
        return -2;
    }

    int* keys = malloc(N * sizeof(int));
    if (!keys) {
        deallocate_memory(ptr_array, N);
        deallocate_memory(nfa_ptr_array, N);
        free(offset_values);
        printf("Memory allocation failed. Error code: %d\n", 0);
        return -2;
    }

    // Initialize structures
    for (int i = 0; i < N; i++) {
        nfa_ptr_array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfa_ptr_array[i]) {
            deallocate_memory(ptr_array, i);
            deallocate_memory(nfa_ptr_array, i);
            free(offset_values);
            free(keys);
            printf("Memory allocation failed. Error code: %d\n", 0);
            return -2;
        }

        // Randomly set CRCFLAG
        nfa_ptr_array[i]->CRCFLAG = (rand() % CRCFLAG_MAX);

        // Generate unique RX_UE_INFORMATION_TAG
        while ((nfa_ptr_array[i]->RX_UE_INFORMATION_TAG = rand()) <= 0) {
            ; // Do nothing, just wait for a new random number
        }

        nfa_ptr_array[i]->RNTI = i; // Set RNTI to the current index

        ptr_array[i] = (void*)nfa_ptr_array[i];
    }

    // Initialize offset_values and keys arrays
    for (int i = 0; i < N; i++) {
        offset_values[i] = i;
        keys[i] = i;
    }

    return N;
}
