    record->offset = 0;
    return record;
}

void* allocate_event_tag(void* arg) {
    event_tag_t* tag = (event_tag_t*)malloc(sizeof(event_tag_t));
    if(tag == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    tag->id = 0;
    tag->status = EVENT_STATUS_OK;
    return tag;
}

void cleanup_memory(record_t** records, int size) {
    for(int i=0; i<size; i++) {
        if(records[i] != NULL) {
            free(records[i]);
            records[i] = NULL;
        }
    }
    free(event_tags);
