use std::fs::File;
use std::io::{Read, Write};
use std::path::Path;

fn generate_cpp_code(input_file_path: &str) -> String {
    let mut file = File::open(Path::new(input_file_path))?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    // Parse the binary file and generate C++ code
    let cpp_code = parse_binary_file(buffer);

    Ok(cpp_code.to_string())
}

fn parse_binary_file(mut buffer: Vec<u8>) -> String {
    // Initialize logging levels
    let mut log_levels = vec!["debug", "info", "warning", "error"];

    // Parse the binary file and generate C++ code
    let version = buffer[0..4].try_into().unwrap();
    match version {
        1 => {
            // Version 1: Simple structure with variable-length fields
            let mut cpp_code = String::new();
            for i in 0..buffer.len() {
                if buffer[i] == 0x01 {
                    // Variable-length field detected
                    let field_len = buffer[(i + 1)..(i + 5)].try_into().unwrap();
                    let field_data = &buffer[(i + 5)..((i + 5) + (field_len as usize))];
                    cpp_code.push_str(&format!("data.{:x} = {{\n", i));
                    for j in 0..field_data.len() {
                        if field_data[j] == 0x00 {
                            // Field termination detected
                            break;
                        }
                        cpp_code.push_str(&format!("    data.{:x} += ({}, 0);\n", j, field_data[j]));
