// Load and execute JavaScript files in order
function loadJsFiles(files) {
    const jsFiles = [];
    for (const file of files) {
        try {
            const code = fs.readFileSync(file, 'utf8');
            const fn = new Function(code);
            jsFiles.push(fn);
        } catch (err) {
            console.error(`Error loading ${file}: ${err}`);
        }
    }
    return jsFiles;
}

// Modify filename extension
function modifyExtension(filename, prefix, suffix) {
    const ext = path.extname(filename);
    const newFilename = `${filename.substr(0, filename.length - ext.length)}${prefix}${suffix}`;
    return newFilename;
}
