void process_files(int* file_descriptors, int num_files, long* offset_values, int* keys, int* total_records, int min_value, int max_value) {
    int i;
    int records_per_file = 0;
    record_t *records = NULL;
    for (i = 0; i < num_files; i++) {
        int file_descriptor = file_descriptors[i];
        int offset_value = lseek(file_descriptor, 0, SEEK_END);
        long current_offset_values[1];
        int current_keys[1];
        if (pread(file_descriptor, &current_offset_values[0], sizeof(long), offset_value) == -1) {
            perror("Error reading file");
            continue;
        }
        if (pread(file_descriptor, &current_keys[0], sizeof(int), offset_value + sizeof(long)) == -1) {
            perror("Error reading file");
            continue;
        }
        records_per_file += 1;
        // Handle concurrent file operations and memory management here
    }

    int total_records_allocated = records_per_file * sizeof(record_t);
    records = (record_t *)malloc(total_records_allocated);

    for (i = 0; i < num_files; i++) {
        int file_descriptor = file_descriptors[i];
        int offset_value = lseek(file_descriptor, 0, SEEK_END);
        long current_offset_values[1];
        int current_keys[1];
        if (pread(file_descriptor, &current_offset_values[0], sizeof(long), offset_value) == -1) {
            perror("Error reading file");
            continue;
        }
        if (pread(file_descriptor, &current_keys[0], sizeof(int), offset_value + sizeof(long)) == -1) {
            perror("Error reading file");
            continue;
        }
        int record_count = current_offset_values[0] / sizeof(long);
        for (int j = 0; j < record_count; j++) {
            records[i * record_count + j].value = rand() % (max_value - min_value) + min_value;
        }
    }

    // Implement thread safety and logging here
    int total_records_read = 0;
    for (i = 0; i < num_files; i++) {
        if (*total_records[i] > records_per_file) {
            *total_records[i] = records_per_file;
        } else {
            *total_records[i]++;
        }
        total_records_read += *total_records[i];
    }

    free(records);
}
