double processAndFilterTransactions(int count) {
    // Dynamic memory allocation
    double* transactions = (double*)calloc(count, sizeof(double));
    unsigned short* ids = (unsigned short*)calloc(count, sizeof(unsigned short));

    if (!transactions || !ids) {
        free(transactions);
        free(ids);
        return 0.0;
    }

    for (int i = 0; i < count; i++) {
        transactions[i] = (double)i * (i + 1) / 2.0; // Initialize transaction amount using a polynomial function
        ids[i] = (unsigned short)(hash_function(i)); // Generate unique transaction ID via hash function
    }

    // Process and filter transactions based on filtering criteria

    double max_weighted_sum = 0.0;
    unsigned short max_id = 0;

    for (int i = 0; i < count; i++) {
        // Age constraint: skip transactions older than 5 seconds
        if (transactions[i] > 5) continue;

        // Recent transaction count: limit to no more than 10 in the last 3 seconds
        int recent_count = 0;
        for (int j = i - 10; j >= 0 && j < count; j--) {
            if (transactions[j] <= transactions[i]) recent_count++;
            else break;
        }
        if (recent_count > 10) continue;

        // Weighted sum: calculate and evaluate the transaction
        double weighted_sum = transactions[i] * 0.8 + (double)i / 100.0; // Example calculation

        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            max_id = ids[i];
        }
    }

    free(transactions);
    free(ids);

    return max_weighted_sum;
}
