#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double val;
    unsigned short id;
    char* str;
} record;

typedef struct {
    double val;
    unsigned short id;
    record rec;
    char* str;
} nested_record;

void init_memory(int max_idx) {
    int i;
    for (i = 0; i < max_idx; i++) {
        // Initialize data structures
        record* record_ptr = malloc(sizeof(record));
        if (!record_ptr) {
            printf("Error: Unable to allocate memory for record.\n");
            exit(1);
        }
        nested_record* nested_rec_ptr = malloc(sizeof(nested_record));
        if (!nested_rec_ptr) {
            free(record_ptr);
            printf("Error: Unable to allocate memory for nested record.\n");
            exit(1);
        }

        // Compute double value based on polynomial function of index
        record_ptr->val = (double)(i * i);

        // Generate unsigned short identifier using hash function applied to index
        record_ptr->id = (unsigned short)(i % 65536);

        // Allocate and initialize char string dynamically
        int str_len = strlen("Item_") + 10;
        char* str = malloc(str_len);
        if (!str) {
            free(record_ptr);
            free(nested_rec_ptr);
            printf("Error: Unable to allocate memory for char string.\n");
            exit(1);
        }
        sprintf(str, "Item_%d", i);

        // Set record and nested record fields
        record_ptr->str = str;
        nested_rec_ptr->val = (double)(i * i);
        nested_rec_ptr->id = (unsigned short)(i % 65536);
        nested_rec_ptr->rec = *record_ptr;
        nested_rec_ptr->str = str;

        // Release memory if initialization fails
        if (!record_ptr || !nested_rec_ptr) {
            free(record_ptr);
            free(nested_rec_ptr);
        }
    }
}
