        }
        client_pool = temp_pool;
        pool_size++;
    }

    Transaction** transaction_array = (Transaction**)calloc(num_transactions, sizeof(Transaction*));
    for (int i = 0; i < num_transactions; i++) {
        // Reuse existing client objects whenever possible
        if (i >= pool_capacity) {
            transaction_array[i] = NULL;
        } else {
            void* client = client_pool[i % pool_capacity];
            Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
            transaction->transaction_id = i + 1; // Assign unique ID
            transaction->client = client; // Store client object
            if (!disable_transaction_logging) {
                // Log transaction details with timestamp
                time_t current_time = time(NULL);
                printf("Logged transaction %lu (Client: %p, Timestamp: %lu)\n", transaction->transaction_id, client, current_time);
            }
            transaction_array[i] = transaction;
        }
    }

    return transaction_array;
}

// Example usage
int main() {
    int num_transactions = 1000; // Adjust as needed
    Transaction** transactions = dynamic_allocation(num_transactions);

    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i]) {
            printf("Transaction %lu: Client Object at address %p\n", transactions[i]->transaction_id, transactions[i]->client);
        } else {
            printf("No client object available.\n");
        }
    }

    return 0;
}
