    pthread_mutex_lock(&lock);
    sessions = realloc(sessions, (session_count + 1) * sizeof(UserSession));
    sessions[session_count].UserID = user_id;
    sessions[session_count].LastActivityTime = time(NULL);
    sessions[session_count].SessionState = ACTIVE;
    session_count++;
    pthread_mutex_unlock(&lock);
}

void update_session(int user_id, enum { INACTIVE, ACTIVE } state) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].UserID == user_id) {
            sessions[i].SessionState = state;
            sessions[i].LastActivityTime = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

int get_active_sessions() {
    pthread_mutex_lock(&lock);
    int active_count = 0;
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].SessionState == ACTIVE) {
            active_count++;
        }
    }
    pthread_mutex_unlock(&lock);
    return active_count;
}

void remove_session(int user_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].UserID == user_id) {
            free(sessions + i);
            memmove(sessions + i, sessions + i + 1, (session_count - i - 1) * sizeof(UserSession));
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

