int hash(int key, int size) {
    return key % size;
}

void insert_hash_table(int key, record* record, int** hash_table, int size) {
    int index = hash(key, size);
    (*hash_table)[index] = (record*)malloc(sizeof(record));
    if ((*hash_table)[index]) {
        (*(*hash_table)[index]) = *record;
    } else {
        printf("Memory allocation failed\n");
    }
}

void print_hash_table(int** hash_table, int size) {
    for (int i = 0; i < size; i++) {
        record* currentRecord = (*hash_table)[i];
        if (currentRecord != NULL) {
            printf("Key: %d Value: %d\n", i, currentRecord->value);
        }
    }
}

void free_hash_table(int** hash_table, int size) {
    for (int i = 0; i < size; i++) {
        record* currentRecord = (*hash_table)[i];
        if (currentRecord != NULL) {
            free(currentRecord);
        }
    }
    for (int i = 0; i < size; i++) {
        free((void*)((*hash_table)+i));
    }
}

void manage_memory() {
    int offset_size = 10000;
    long* offsets = (long*)malloc(sizeof(long)*offset_size);
    if (!offsets) {
        printf("Memory allocation failed\n");
        return;
    }

    int key_size = 5000;
    int* keys = (int*)malloc(sizeof(int)*key_size);
    if (!keys) {
        printf("Memory allocation failed\n");
        free(offsets);
        return;
    }

    record* records = NULL;
    for (int i = 0; i < offset_size; i++) {
        long offset = i;
        record* newRecord = create_record(i);
        // Insert into hash table
        int size = 10000;
        int** hash_table = (int**)malloc(sizeof(int*)*size);
        for (int j = 0; j < size; j++) {
            hash_table[j] = NULL;
        }
        insert_hash_table(offset, newRecord, &hash_table, size);
    }

    // Print hash table
    print_hash_table(&hash_table, size);

    // Free memory
    free_records(records);
    free_keys(keys);
    free_offsets(offsets);
}

int main() {
    manage_memory();
    return 0;
