work_item* create_work_item(unsigned long task_id) {
    work_item* item = malloc(sizeof(work_item));
    item->task_id = task_id;

    // Allocate resource
    if (available_resources > 0) {
        pthread_mutex_lock(&lock);
        void* resource = NULL;
        if (used_resources < RESOURCE_POOL_SIZE) {
            for (int i = 0; i < available_resources && !resource; i++) {
                resource_pool[i] = NULL;
                if (!resource_pool[i]) {
                    resource = resource_pool[i];
                    break;
                }
            }
            used_resources--;
        } else {
            // Use secondary resource pool with reduced quality
            // or defer task until resources become available
        }

        pthread_mutex_unlock(&lock);
        item->resource = resource;
    } else {
        // Defer task until resources become available
    }

    return item;
}

void destroy_work_item(work_item* item) {
    if (item) {
        // Release resource
        pthread_mutex_lock(&lock);
        used_resources++;
        void* resource = item->resource;
        for (int i = 0; i < available_resources && resource != resource_pool[i]; i++) {
            resource_pool[i] = resource;
        }
        free(resource);
        pthread_mutex_unlock(&lock);

        // Free work_item structure
        free(item);
    }
}

