#include <time.h>

typedef struct {
    int value;
} record;

void process_records(int fd_in, int fd_out, int lower, int upper,
                     int* num_records, size_t* serialized_size) {
    // Initialize variables and seeds for random number generation
    srand(time(NULL));
    int records_per_batch = 100; // adjust based on system load and resources
    int current_batch = 0;
    int total_records = 0;

    while (1) {
        // Read the number of records from the input file
        int num_records_in_file;
        if (fscanf(fd_in, "%d", &num_records_in_file) != 1) {
            break; // reached end-of-file or error
        }

        // Check for integer overflow and ensure records_per_batch does not exceed system limit
        if (num_records_in_file > INT_MAX / records_per_batch || num_records_in_file < 0) {
            fprintf(stderr, "Error: Invalid number of records.\n");
            return;
        }

        total_records += num_records_in_file;

        // Dynamically allocate memory for the arrays and records
        long* offsets = (long*)malloc(num_records_in_file * sizeof(long));
        int* keys = (int*)malloc(num_records_in_file * sizeof(int));
        record* records = (record*)malloc(num_records_in_file * sizeof(record));

        // Populate the records with random values within the specified range
        for (int i = 0; i < num_records_in_file; i++) {
            records[i].value = rand() % (upper - lower + 1) + lower;
        }

        // Serialize the data and write it to the output file
        size_t serialized_size_for_batch = num_records_in_file * sizeof(long) + num_records_in_file * sizeof(int) + num_records_in_file * sizeof(record);
        void* buffer = malloc(serialized_size_for_batch);

        if (buffer == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }

        // Write the serialized data to the output file
        fwrite(buffer, 1, serialized_size_for_batch, fd_out);

        free(buffer);
        free(offsets);
        free(keys);
        free(records);

        current_batch++;
    }

    *num_records = total_records;
    *serialized_size = num_records_in_file * (sizeof(long) + sizeof(int) + sizeof(record));
}
