#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

class NetworkConnectionStatus {
public:
    std::string ipAddress;
    int portNumber;
    enum ConnectionState { ESTABLISHED, BROKEN, PENDING } connectionState;
    long lastActivityTimestamp;

    // constructor
    NetworkConnectionStatus(std::string ip, int port, ConnectionState state, long timestamp)
        : ipAddress(ip), portNumber(port), connectionState(state), lastActivityTimestamp(timestamp) {}
};

class ConnectionManager {
private:
    std::vector<NetworkConnectionStatus> connections;
    std::map<long, NetworkConnectionStatus*> priorityQueue;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addConnection(NetworkConnectionStatus& connection) {
        connections.push_back(connection);
        // update priority queue
        if (priorityQueue.find(connection.lastActivityTimestamp) == priorityQueue.end()) {
            priorityQueue[connection.lastActivityTimestamp] = &connections.back();
        }
    }

    void updateConnectionState(NetworkConnectionStatus& connection) {
        // update connection state and last activity timestamp
        connection.connectionState = ESTABLISHED;
        connection.lastActivityTimestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();

        // rebalance priority queue
        if (priorityQueue.find(connection.lastActivityTimestamp) != priorityQueue.end()) {
            // update priority queue with new timestamp and connection state
            auto it = priorityQueue.begin();
            while (it != priorityQueue.end() && it->first < connection.lastActivityTimestamp) {
                ++it;
            }
            if (it != priorityQueue.end()) {
                priorityQueue.erase(it);
            }
        }

        // notify interested threads
        cv.notify_all();
    }

    void getConnectionList(std::vector<NetworkConnectionStatus>& list) {
        std::lock_guard<std::mutex> lock(mtx);
        list = connections;
    }

    bool getConnectionPriority(NetworkConnectionStatus& connection) {
        if (priorityQueue.find(connection.lastActivityTimestamp) != priorityQueue.end()) {
            // return true if connection has highest priority
            return true;
        }
        return false;
    }

    void logConnectionStateUpdate(NetworkConnectionStatus& connection) {
        // integrate with external logging framework and monitoring tools
        std::cout << "Connection state updated for " << connection.ipAddress << ":" << connection.portNumber << std::endl;
    }
};

int main() {
    ConnectionManager manager;

    // simulate concurrent connections
    std::thread threads[50];
    for (int i = 0; i < 49; ++i) {
        NetworkConnectionStatus connection("192.168." + std::to_string(i), 12345, ESTABLISHED, std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count());
        threads[i] = std::thread([&manager, &connection]() {
            manager.addConnection(connection);
            while (true) {
                // simulate network activity and updates
                std::this_thread::sleep_for(std::chrono::seconds(1));
                connection.connectionState = BROKEN;
                connection.lastActivityTimestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
                manager.updateConnectionState(connection);
            }
        });
    }

    // main thread
    while (true) {
        // simulate monitoring and logging
        NetworkConnectionStatus connection;
        manager.getConnectionList(connections);
        for (const auto& conn : connections) {
            if (manager.getConnectionPriority(conn)) {
                std::cout << "Highest priority connection: " << conn.ipAddress << ":" << conn.portNumber << std::endl;
                break;
            }
        }
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }

    return 0;
}
