#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 1000
#define MIN_RECORD_VALUE 0
#define MAX_RECORD_VALUE 255

typedef struct {
    int key;
    int value;
} record_t;

record_t *records = NULL;
int num_records = 0;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void *thread_func(void *fd) {
    int file_fd = *(int *)fd;
    pthread_mutex_lock(&records_mutex);
    if (records == NULL || num_records >= MAX_RECORDS) {
        // Handle error, file descriptor not processed
        return NULL;
    }
    for (int i = 0; i < 100; i++) { // Read and process 100 records from each file
        char buffer[1024];
        int bytes_read = read(file_fd, buffer, 1024);
        if (bytes_read <= 0) {
            // Handle error, file descriptor not processed
            return NULL;
        }
        for (int j = 0; j < bytes_read; j++) {
            record_t *record = &records[num_records];
            record->key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
            record->value = rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE + 1) + MIN_RECORD_VALUE;
            num_records++;
        }
    }
    pthread_mutex_unlock(&records_mutex);
}

int main(int argc, char *argv[]) {
    int file_descriptors[argc];
    for (int i = 0; i < argc; i++) {
        file_descriptors[i] = atoi(argv[i]);
    }

    // Initialize thread pool
    int threads = 4;
    pthread_t thread_pool[threads];
    for (int i = 0; i < threads; i++) {
        pthread_create(&thread_pool[i], NULL, thread_func, &file_descriptors[i * (argc / threads)]);
    }
    for (int i = 0; i < threads; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    // Log statistics
    printf("Total records processed: %d\n", num_records);

    return 0;
}
