void manageMemory(int size, int max_size) {
    // Calculate the total memory required
    size_t total_memory = sizeof(long) + sizeof(int) * size + sizeof(record) * size;

    // Check if the allocation exceeds the maximum allowed size
    if (total_memory > max_size) {
        printf("Error: Allocation exceeds maximum allowed size.\n");
        return;
    }

    // Allocate memory for all data structures in a single call
    void* memory = malloc(total_memory);

    if (!memory) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    // Initialize records with random values
    record* records = (record*)memory;
    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        int value = rand() % 100; // Random value between 0 and 99
        records[i].key = (int*)malloc(sizeof(int));
        *records[i].key = value;
        records[i].offset = i;
        records[i].value = 0;
    }

    // Deallocate memory at the end of function execution to prevent leaks
    free(memory);
}
