async fn process_args(args: Vec<String>) {
    let func_name = args.get(1).map_or_else(|| "default_function".to_string(), |s| s.clone());

    match &func_name as &str {
        "api_func" => {
            // Call API function
            println!("API Function Called");
        }
        _ => {
            // Default function
            println!("Default Function Called");
        }
    }
}

async fn api_function() -> Result<(), Box<dyn std::error::Error>> {
    let url = "https://example.com/api/data";
    let response = reqwest::get(url).await?;

    if !response.status().is_success() {
        return Err("API request failed".to_string().into());
    }

    let data = response.text().await?;
    println!("Received Data: {}", data);

    Ok(())
}

#[tokio::main]
async fn main() {
    env_logger::init();
    let args: Vec<String> = env::args().collect();

    if args.is_empty() || args.get(1).is_none() {
        eprintln!("Usage: {} <function_name>", &args[0]);
        process::exit(1);
    }

    runtime::Builder::new_multi_thread()
        .enable_time()
        .build()
        .unwrap()
        .block_on(process_args(args));
}

