typedef struct {
    char ip_address[16];
    int port_number;
    enum ConnectionState { CONNECTED, DISCONNECTED } connection_state;
} NetworkConnectionStatus;

void* custom_malloc(size_t size) {
    // Implement your custom malloc function here
    return malloc(size);
}

void custom_free(void* ptr) {
    // Implement your custom free function here
    free(ptr);
}

typedef struct {
    NetworkConnectionStatus** connections;
    int connection_count;
    pthread_mutex_t mutex;
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager* manager = (ConnectionManager*)custom_malloc(sizeof(ConnectionManager));
    manager->connections = NULL;
    manager->connection_count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_connection_manager(ConnectionManager* manager) {
    for (int i = 0; i < manager->connection_count; i++) {
        custom_free(manager->connections[i]);
    }
    custom_free(manager->connections);
    pthread_mutex_destroy(&manager->mutex);
    custom_free(manager);
}

int add_connection(ConnectionManager* manager, const char* ip_address, int port_number) {
    NetworkConnectionStatus* new_connection = (NetworkConnectionStatus*)custom_malloc(sizeof(NetworkConnectionStatus));
    strcpy(new_connection->ip_address, ip_address);
    new_connection->port_number = port_number;
    new_connection->connection_state = CONNECTED;

    pthread_mutex_lock(&manager->mutex);
    manager->connections = realloc(manager->connections, (manager->connection_count + 1) * sizeof(NetworkConnectionStatus*));
    manager->connections[manager->connection_count] = new_connection;
    manager->connection_count++;
    pthread_mutex_unlock(&manager->mutex);

    return 0; // Assume success
}

int update_connection(ConnectionManager* manager, const char* ip_address, int port_number, enum ConnectionState state) {
    for (int i = 0; i < manager->connection_count; i++) {
        if (strcmp(manager->connections[i]->ip_address, ip_address) == 0 && manager->connections[i]->port_number == port_number) {
            manager->connections[i]->connection_state = state;
            return 0; // Assume success
        }
    }

    return -1; // Connection not found
}

int get_active_connection_count(ConnectionManager* manager) {
    int active_connections = 0;

    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->connection_count; i++) {
        if (manager->connections[i]->connection_state == CONNECTED) {
            active_connections++;
        }
    }
    pthread_mutex_unlock(&manager->mutex);

    return active_connections;
}

void remove_inactive_connections(ConnectionManager* manager, int timeout_in_seconds) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->connection_count; i++) {
        if ((timeout_in_seconds > 0 && manager->connections[i]->connection_state == DISCONNECTED) || timeout_in_seconds <= 0) {
            custom_free(manager->connections[i]);
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->connection_count - i - 1) * sizeof(NetworkConnectionStatus*));
            manager->connection_count--;
            i--; // Decrement the loop counter
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}
