Project* create_project(const char* title, double estimated_time, int budget) {
    Project* project = (Project*)malloc(sizeof(Project));
    project->title = strdup(title);
    project->estimated_time = estimated_time;
    project->budget = budget;
    project->active = true;
    return project;
}

void insert_project(Project** head, const char* title, double estimated_time, int budget) {
    Project* new_project = create_project(title, estimated_time, budget);
    if (*head == NULL) {
        *head = new_project;
    } else {
        Project* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_project;
    }
}

void print_projects(Project* head) {
    Project* current = head;
    while (current != NULL) {
        printf("Title: %s, Estimated Time: %.2f hours, Budget: $%d, Active: %s\n", 
               current->title, current->estimated_time, current->budget, current->active ? "Yes" : "No");
        current = current->next;
    }
}

void free_projects(Project* head) {
    Project* current = head;
    while (current != NULL) {
        Project* next = current->next;
        free(current->title);
        free(current);
        current = next;
    }
}
