timestamp_t* process_file_data(const char* filename, int n) {
    FILE* file = fopen(filename, "r");
    if (file == NULL || fgetc(file) != '\n') {
        fclose(file);
        return NULL;
    }

    DataPoint* data_points = (DataPoint*)malloc(n * sizeof(DataPoint));
    timestamp_t* timestamps = (timestamp_t*)malloc(n * sizeof(timestamp_t));

    int i = 0;
    while (fscanf(file, "%f,%s,%lld\n", &data_points[i].value, data_points[i].string, &timestamps[i]) == 3 && i < n) {
        if (data_points[i].value < 0 || data_points[i].value > 100) {
            free(data_points);
            free(timestamps);
            fclose(file);
            return NULL;
        }
        if (strlen(data_points[i].string) > 50) {
            free(data_points);
            free(timestamps);
            fclose(file);
            return NULL;
        }
        i++;
    }

    data_points = (DataPoint*)realloc(data_points, sizeof(DataPoint) * i);
    timestamps = (timestamp_t*)realloc(timestamps, sizeof(timestamp_t) * i);

    for (int j = i; j < n; j++) {
        data_points[j].value = 0;
        data_points[j].string = NULL;
        timestamps[j] = 0;
    }

    fclose(file);
    return &data_points[0];
}
