Node* head = NULL;

void insert_at_head(Task task) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->task = task;
    new_node->next = head;
    head = new_node;
}

void insert_at_tail(Task task) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->task = task;
    if (!head) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void free_list() {
    Node* temp = head;
    Node* next;
    while (temp) {
        next = temp->next;
        free(temp);
        temp = next;
    }
    head = NULL;
}

