#define MAX_PROJECTS 1000
#define MEMORY_THRESHOLD (40 / 100.0) // 40% of available RAM

typedef struct {
    char* title;
    double estimated_time;
    int budget;
    bool active;
} Project;

Project* project_list = NULL;
int project_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert_project(Project* new_project) {
    if (project_count >= MAX_PROJECTS) {
        printf("Error: Project list is full.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    Project* current = project_list;
    if (!current || !new_project->title) {
        new_project->next = NULL;
        project_list = new_project;
    } else {
        while (current->next && current->next->title) {
            current = current->next;
        }
        current->next = new_project;
    }
    pthread_mutex_unlock(&lock);

    // Monitor memory usage and trigger alerts if exceeded
    size_t total_memory_used = 0;
    Project* temp = project_list;
    while (temp) {
        total_memory_used += strlen(temp->title) + sizeof(Project);
        temp = temp->next;
    }
    double memory_usage = (double)total_memory_used / (1024 * 1024); // in MB
    if (memory_usage > MEMORY_THRESHOLD) {
        printf("Memory usage exceeded %f%% of available RAM.\n", memory_usage * 100);
    }

    project_count++;
}

void print_projects() {
    Project* temp = project_list;
    while (temp) {
        printf("Title: %s, Estimated Time: %.2f hours, Budget: $%d, Active: %s\n",
               temp->title, temp->estimated_time, temp->budget, temp->active ? "true" : "false");
        temp = temp->next;
    }
}

void cleanup() {
    Project* current = project_list;
    while (current) {
        Project* next = current->next;
        free(current->title);
        free(current);
        current = next;
    }
}
