#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    CONNECTED,
    DISCONNECTED,
    PENDING
} ConnectionState;

typedef struct {
    uint32_t ipAddress;
    uint16_t portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

void network_connection_init(void** connections, size_t* capacity) {
    *connections = malloc(sizeof(NetworkConnectionStatus));
    *capacity = 1;
}

int network_connection_add(void** connections, size_t* capacity, uint32_t ipAddress, uint16_t portNumber) {
    if (*capacity <= (size_t)(-1) / sizeof(NetworkConnectionStatus)) {
        // Reallocate memory
        void* newConnections = realloc(*connections, sizeof(NetworkConnectionStatus) * 2);
        if (!newConnections) return -1;
        *connections = newConnections;
        *capacity *= 2;
    }
    NetworkConnectionStatus* connection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    connection->ipAddress = ipAddress;
    connection->portNumber = portNumber;
    connection->connectionState = PENDING;
    *(void**)connections = connection;
    return 0;
}

int network_connection_update(void** connections, size_t capacity, uint32_t ipAddress, ConnectionState newState) {
    for (size_t i = 0; i < capacity; i++) {
        if (((NetworkConnectionStatus*)connections)[i].ipAddress == ipAddress) {
            ((NetworkConnectionStatus*)connections)[i].connectionState = newState;
            return 0;
        }
    }
    return -1;
}

int network_connection_get_active(void** connections, size_t capacity) {
    int count = 0;
    for (size_t i = 0; i < capacity; i++) {
        if (((NetworkConnectionStatus*)connections)[i].connectionState == CONNECTED) {
            count++;
        }
    }
    return count;
}

void network_connection_gc(void** connections, size_t capacity) {
    // Periodic garbage collection
    for (size_t i = 0; i < capacity; i++) {
        if (((NetworkConnectionStatus*)connections)[i].connectionState == DISCONNECTED) {
            free(connections);
            *connections = realloc(connections, sizeof(NetworkConnectionStatus) * (capacity - 1));
            memmove(connections, connections + 1, sizeof(NetworkConnectionStatus) * (capacity - i - 1));
            capacity--;
        }
    }
}

