    def create_vertex(self, id):
        if id not in self.vertices:
            self.vertices.add(id)
            return True
        else:
            return False

    def create_edge(self, vertex1_id, vertex2_id):
        if vertex1_id in self.vertices and vertex2_id in self.vertices:
            self.edges.add((vertex1_id, vertex2_id))
            return True
        else:
            return False

