        recordArray[i] = malloc(sizeof(Record));
        keys[i] = (short)(i % 32767);
        values[i] = pow(2, -i);
        offsets[i] = (long)i;
    }

    // Compact and optimize memory usage
    for (int i = 0; i < numRecords; i++) {
        if (offsets[i] > numRecords) {
            offsets[i] = numRecords;
            break;
        }
    }

    // Free allocated memory
    for (int i = 0; i < numRecords; i++) {
        free(recordArray[i]);
    }
    free(recordArray);
}

// Function to read integers from standard input and validate range
void readIntegers(int* max, int* min) {
    int value;
    while (scanf("%d", &value) == 1) {
        if (value > *max || value < *min) {
            printf("Invalid integer. Please enter an integer within the specified range.\n");
            return;
        }
        (*max) = value;
        (*min) = value;
    }
}

// Function to identify and print the largest integer
void findLargestInt(int max, int min) {
    if (max == min) {
        printf("The largest integer is: %d\n", max);
    } else {
        printf("The range of integers is [%d, %d].\n", min, max);
    }
}

int main() {
    // Initialize variables
    int numRecords = 0;
    int* records = NULL;
    short* keys = NULL;
    double* values = NULL;
    long* offsets = NULL;

    // Read integers from standard input and validate range
    readIntegers(&numRecords, &records);

    // Initialize arrays
    records = (int*)malloc(numRecords * sizeof(int));
    keys = (short*)malloc(numRecords * sizeof(short));
    values = (double*)malloc(numRecords * sizeof(double));
    offsets = (long*)malloc(numRecords * sizeof(long));

    // Process records
    for (int i = 0; i < numRecords; i++) {
        scanf("%d", &records[i]);
    }

    // Find and print the largest integer
    findLargestInt(*max, *min);

    // Free allocated memory
    free(records);
    free(keys);
    free(values);
    free(offsets);

    return 0;
}

