TCP_HEADER* create_tcp_headers(int num_headers) {
    TCP_HEADER* headers = (TCP_HEADER*)malloc(num_headers * sizeof(TCP_HEADER));

    for (int i = 0; i < num_headers; i++) {
        headers[i].source_ip = rand();
        headers[i].destination_ip = rand();

        int flag = 0;
        if (rand() % 2) {
            flag |= 1 << 0; // URG
        }
        if (rand() % 2) {
            flag |= 1 << 1; // ACK
        }
        if (rand() % 2) {
            flag |= 1 << 2; // PSH
        }
        if (rand() % 2) {
            flag |= 1 << 3; // RST
        }
        if (rand() % 2) {
            flag |= 1 << 4; // SYN
        }
        if (rand() % 2) {
            flag |= 1 << 5; // FIN
        }

        headers[i].flag = flag;
    }

    return headers;
}

float read_and_calculate_average(float* numbers, int num_numbers) {
    float sum = 0.0;

    for (int i = 0; i < num_numbers; i++) {
        scanf("%f", &numbers[i]);
        sum += numbers[i];
    }

    return sum / num_numbers;
}

void read_and_create_tcp_headers(int* num_headers) {
    float numbers[100]; // Assuming maximum 100 headers

    int num_numbers = 0;

    while (1) {
        if (scanf("%f", &numbers[num_numbers]) != 1) {
            break;
        }

        if (num_numbers >= sizeof(numbers) / sizeof(numbers[0])) {
            printf("Error: Too many numbers.\n");
            exit(1);
        }

        num_numbers++;
    }

    *num_headers = num_numbers;
}
