// Custom allocator data structure
typedef struct {
    void **blocks;
    int num_blocks;
    pthread_mutex_t lock;
} Allocator;

// Initialize the custom allocator with a fixed-size block list
Allocator* init_allocator(int num_blocks) {
    Allocator* allocator = malloc(sizeof(Allocator));
    allocator->num_blocks = num_blocks;
    allocator->blocks = malloc(num_blocks * sizeof(void *));
    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

// Custom allocator function to allocate memory
void* custom_alloc(Allocator* allocator, size_t size) {
    void* block;
    int i;

    // Try to find an unused block from the pool
    for (i = 0; i < allocator->num_blocks; i++) {
        pthread_mutex_lock(&allocator->lock);
        if (!allocator->blocks[i]) {
            block = allocator->blocks[i];
            break;
        }
        pthread_mutex_unlock(&allocator->lock);
    }

    // If no unused block is found, allocate a new one
    if (block == NULL) {
        block = malloc(size);
    }

    return block;
}

// Custom allocator function to free memory
void custom_free(Allocator* allocator, void* ptr) {
    int i;

    // Mark the block as used
    pthread_mutex_lock(&allocator->lock);
    for (i = 0; i < allocator->num_blocks; i++) {
        if (!allocator->blocks[i]) {
            allocator->blocks[i] = ptr;
            break;
        }
    }
    pthread_mutex_unlock(&allocator->lock);
}

