    // Periodically free unused memory blocks
    for(size_t i = 0; i < audio->size; i++) {
        if(audio->samples[i] == 0.0f) {  // Check for zero values
            free(audio->samples);
            audio->samples = (float*)malloc(audio->capacity * sizeof(float));  // Reallocate with variable-size allocation
            break;
        }
    }
}

