    pthread_mutex_init(&block_list->mutex, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        block_list[i].size = sizeof(Metadata);
        block_list[i].data = malloc(block_list[i].size);
    }

    return &block_list;
}

// Custom allocator function to manage memory blocks
void custom_deallocator(void* ptr) {
    Block* block_list = (Block*)ptr;

    for (int i = 0; i < MAX_RECORDS; i++) {
        free(block_list[i].data);
    }

    free(ptr);
    pthread_mutex_destroy(&block_list->mutex);
}

// Function to manage dynamic collection of user-defined data structures
void manage_collection(int num_records, Metadata** records) {
    // Initialize the semaphore with the maximum number of concurrent accesses allowed
    sem_t* semaphore = sem_open("/my_semaphore", O_CREAT | O_RDWR, 0644, MAX_RECORDS);

    if (semaphore == SEM_FAILED) {
        printf("Error creating semaphore\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        records[i] = (Metadata*)malloc(sizeof(Metadata));
        // Initialize metadata fields
        records[i]->user_id = i;
        records[i]->timestamp = time(NULL);
        records[i]->status = 1;

        sem_wait(semaphore); // Wait for semaphore permission

        // Log changes in the collection size and status updates
        printf("Record %d added\n", i);

        sem_post(semaphore); // Release semaphore permission
    }

    sem_close(semaphore);

    return;
}

int main() {
    int num_records = 100; // Number of records to manage

    Metadata** records = (Metadata**)malloc(num_records * sizeof(Metadata*));

    // Initialize the custom allocator and manager for dynamic collection
    void* ptr = custom_allocator(num_records);
    manage_collection(num_records, records);

    // Deallocate memory blocks using custom deallocator function
    custom_deallocator(ptr);

    return 0;
}
