class UserSession {
public:
    int UserID;
    std::string SessionToken;
    long LastActivityTime;
    enum class SessionState { ACTIVE, INACTIVE, EXPIRED };
};

class SessionManager {
private:
    struct SessionData {
        int userID;
        std::string token;
        long lastActive;
        SessionManager::SessionState state;
    };

    std::vector<SessionData> sessions;
    std::unordered_map<std::string, int> sessionMap;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addSession(int userID, const std::string& token, long lastActive, SessionManager::SessionState state) {
        std::unique_lock<std::mutex> lock(mtx);
        sessions.emplace_back(userID, token, lastActive, state);
        sessionMap[token] = sessions.size() - 1;
    }

    void updateSession(const std::string& token, SessionManager::SessionState state) {
        std::unique_lock<std::mutex> lock(mtx);
        for (int i = 0; i < sessions.size(); ++i) {
            if (sessions[i].token == token) {
                sessions[i].state = state;
                return;
            }
        }
    }

    int getActiveSessionCount() {
        std::unique_lock<std::mutex> lock(mtx);
        int count = 0;
        for (const auto& session : sessions) {
            if (session.state == SessionManager::SessionState::ACTIVE)
                ++count;
        }
        return count;
    }

    void garbageCollect() {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = sessions.begin();
        while (it != sessions.end()) {
            if ((it->lastActive + 3600) < time(nullptr)) { // assume 1 hour inactivity threshold
                sessions.erase(it);
                sessionMap.erase(it->token);
            } else {
                ++it;
            }
        }
    }

    void logUnusualSessionPatterns() {
        // implement logging mechanism here
    }
};
