// Dynamic array of UserSessions
UserSession** sessions = NULL;
int sessionCount = 0;
int maxSessions = 10; // Initial capacity

void addSession(int userID, char* token) {
    // Grow the array if necessary
    if (sessionCount >= maxSessions) {
        maxSessions *= 2; // Double capacity
        sessions = realloc(sessions, sizeof(UserSession*) * maxSessions);
    }

    UserSession* newSession = malloc(sizeof(UserSession));
    newSession->UserID = userID;
    strcpy(newSession->SessionToken, token);
    time(&newSession->LastActivityTime); // Initialize with current time
    newSession->SessionState = 1; // Initially logged in

    sessions[sessionCount++] = newSession;
}

void updateSession(int userID) {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i]->UserID == userID) {
            time(&sessions[i]->LastActivityTime); // Update last activity time
            return;
        }
    }
}

int getActiveSessions() {
    int activeSessions = 0;
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i]->SessionState == 1) {
            activeSessions++;
        }
    }
    return activeSessions;
}

void cleanupExpiredSessions(int timeoutMinutes) {
    time_t now = time(NULL);
    for (int i = 0; i < sessionCount; i++) {
        if ((now - sessions[i]->LastActivityTime) / 60 > timeoutMinutes) {
            // Session expired, mark as LOGGED_OUT
            sessions[i]->SessionState = 0;
        }
    }
}

void cleanupSessions() {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i]->SessionState == 0) {
            free(sessions[i]);
            // Shift remaining sessions down to fill the gap
            for (int j = i + 1; j < sessionCount; j++) {
                sessions[j - 1] = sessions[j];
            }
            sessionCount--;
        }
    }
}

void saveSessionsToDatabase() {
    // Implement database write operations here
}

void loadSessionsFromDatabase() {
    // Implement database read operations here
}

