    addSession(1, "sessionToken");
    updateSession(1);
    int active = getActiveSessions();
    printf("Active sessions: %d\n", active);

    cleanupExpiredSessions(30); // Mark sessions as LOGGED_OUT after 30 minutes

    saveSessionsToDatabase();

    return 0;
}
