// Initialize and manage a dynamic array of NetworkConnectionStatus structures
NetworkConnectionStatus** initializeConnections(int initialCapacity) {
    return (NetworkConnectionStatus**)malloc(initialCapacity * sizeof(NetworkConnectionStatus*));
}

int addConnection(NetworkConnectionStatus** connections, int currentCapacity, char* ipAddress, int portNumber, enum { CONNECTED, DISCONNECTED, PENDING } connectionState) {
    // Allocate memory for the new connection
    NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;
    newConnection->connectionState = connectionState;

    // Check if we've reached the capacity and need to resize
    int newSize = currentCapacity * 2;
    if (newSize > 1000000) {
        newSize = 1000000; // Limit to 1 million connections
    }
    NetworkConnectionStatus** newConnections = (NetworkConnectionStatus**)realloc(connections, newSize * sizeof(NetworkConnectionStatus*));
    if (!newConnections) return -1; // Handle memory allocation failure

    // Update the capacity and insert the new connection
    int i;
    for (i = 0; i < currentCapacity; i++) {
        newConnections[i] = connections[i];
    }
    newConnections[currentCapacity] = newConnection;
    currentCapacity++;
    return currentCapacity;
}

int updateConnection(NetworkConnectionStatus** connections, int currentCapacity, int index, enum { CONNECTED, DISCONNECTED, PENDING } connectionState) {
    if (index >= 0 && index < currentCapacity) {
        connections[index]->connectionState = connectionState;
        return 1; // Update successful
    }
    return -1; // Invalid or out-of-range index
}

int getActiveConnections(NetworkConnectionStatus** connections, int currentCapacity) {
    int activeCount = 0;
    for (int i = 0; i < currentCapacity; i++) {
        if (connections[i]->connectionState == CONNECTED)
            activeCount++;
    }
    return activeCount;
}

// Manage memory for transactions and their items
Transaction* addTransaction(Transaction** transactions, int currentCapacity, int transactionId, long timestamp, int itemQuantity) {
    // Allocate memory for the new transaction
    Transaction* newTransaction = (Transaction*)malloc(sizeof(Transaction));
    newTransaction->transactionId = transactionId;
    newTransaction->timestamp = timestamp;
    newTransaction->itemQuantity = itemQuantity;

    // Dynamically allocate memory for the item names and description
    int itemNameSize = sizeof(char) * (itemQuantity + 1);
    char* itemNamesTemp = (char*)malloc(itemNameSize);
    strcpy(itemNamesTemp, "");
    for (int i = 0; i < itemQuantity; i++) {
        // Add each item name to the temporary string
        sprintf(itemNamesTemp + strlen(itemNamesTemp), "%s-%d,", itemNameTemp, i);
    }
    newTransaction->itemNames = itemNamesTemp;
    char* transactionDescriptionTemp = (char*)malloc(50); // Limit description size
    strcpy(transactionDescriptionTemp, "New Transaction");
    newTransaction->transactionDescription = transactionDescriptionTemp;

    // Update the capacity and insert the new transaction
    int i;
    for (i = 0; i < currentCapacity; i++) {
        transactions[i] = transactions[i];
    }
    transactions[currentCapacity] = newTransaction;
    currentCapacity++;
    return currentCapacity;
}

int updateTransaction(Transaction** transactions, int currentCapacity, int index, char* transactionDescription) {
    if (index >= 0 && index < currentCapacity) {
        strcpy(transactions[index]->transactionDescription, transactionDescription);
        return 1; // Update successful
    }
    return -1; // Invalid or out-of-range index
}

int getTransactionCount(Transaction** transactions, int currentCapacity) {
    int count = 0;
    for (int i = 0; i < currentCapacity; i++) {
        count++;
    }
    return count;
}
