NFAPI_CRC_INDICATION_PDU_T* structures[MAX_ACTIVE_STRUCTURES];
pthread_mutex_t structure_queue_lock = PTHREAD_MUTEX_INITIALIZER;
int active_structure_count = 0;
FILE* log_file;

void handle_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int calculate_crcflag(int largest_integer) {
    int crcflag = (largest_integer >> 16) & 0xFFFF;
    return crcflag;
}

void register_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&structure_queue_lock);
    if (active_structure_count < MAX_ACTIVE_STRUCTURES) {
        structures[active_structure_count] = structure;
        active_structure_count++;
    } else {
        handle_error("Maximum number of active structures reached");
    }
    pthread_mutex_unlock(&structure_queue_lock);
}

void log_crcflag_calculation(int largest_integer) {
    int crcflag = calculate_crcflag(largest_integer);
    fprintf(log_file, "%d: CRCFLAG calculated as 0x%x\n", time(NULL), crcflag);
    if (fseek(log_file, 0, SEEK_END)) {
        handle_error("Error writing to log file");
    }
}

void* process_input_list(void* input) {
    int largest_integer = 0;
    int integers[MAX_INPUT_SIZE];
    int count = 0;

