    // ...

    if (count > 0) {
        int largest_integer = integers[0];
        for (int i = 1; i < count; i++) {
            if (integers[i] > largest_integer) {
                largest_integer = integers[i];
            }
        }

        NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        structure->RX_UE_INFORMATION_TAG = 0;
        structure->RNTI = 1;
        structure->CRC_INDICATION_REL8_TAG = largest_integer;
        crcflag = calculate_crcflag(largest_integer);
        structure->CRCFLAG = crcflag;

        register_structure(structure);

        log_crcflag_calculation(largest_integer);
    }

    return NULL;
}

int main() {
    pthread_t thread;
    int* input_list = (int*)malloc(sizeof(int) * MAX_INPUT_SIZE);
    FILE* log_file = fopen("log.txt", "a");

    if (!log_file) {
        handle_error("Error opening log file");
    }

    // Create and start the processing thread
    pthread_create(&thread, NULL, process_input_list, input_list);

    return 0;
