    int UserID;
    char* SessionID;
    time_t LastActivityTime;
    enum { ACTIVE, INACTIVE } SessionState;
} UserSession;

// Define the session management function
int manage_user_sessions(int timeout) {
    // Initialize a dynamic array of UserSessions
    UserSession** sessions = NULL;
    int num_sessions = 0;

    // Function to add a new user session
    void add_session(int UserID, char* SessionID) {
        // Allocate memory for the new session
        UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));

        // Initialize the new session with the given ID and state
        new_session->UserID = UserID;
        new_session->SessionState = ACTIVE;
        new_session->LastActivityTime = time(NULL);

        // Add the new session to the array
        sessions = realloc(sessions, (num_sessions + 1) * sizeof(UserSession*));
        sessions[num_sessions++] = new_session;
    }

    // Function to update an existing user session
    void update_session(int UserID, enum { ACTIVE, INACTIVE } NewState) {
        for (int i = 0; i < num_sessions; i++) {
            if (sessions[i]->UserID == UserID) {
                sessions[i]->SessionState = NewState;
                sessions[i]->LastActivityTime = time(NULL);
                return;
            }
        }
    }

    // Function to remove an inactive user session
    void expire_inactive_sessions(int timeout) {
        for (int i = 0; i < num_sessions; i++) {
            if ((time(NULL) - sessions[i]->LastActivityTime) > timeout) {
                free(sessions[i]);
                sessions[i] = NULL;
                // Compact the array by shifting non-null elements
                int j = i + 1;
                while (j < num_sessions && sessions[j]) {
                    sessions[i++] = sessions[j++];
                }
                // Resize the array to remove unnecessary memory allocation
                sessions = realloc(sessions, i * sizeof(UserSession*));
                num_sessions--;
            }
        }
    }

    // Function to retrieve the number of active user sessions
    int get_num_active_sessions() {
        int count = 0;
        for (int i = 0; i < num_sessions; i++) {
            if (sessions[i]->SessionState == ACTIVE) {
                count++;
            }
        }
        return count;
    }

    // Add a new user session
    add_session(1, "session1");

    // Update an existing user session
    update_session(1, INACTIVE);

    // Remove inactive user sessions based on the timeout period
    expire_inactive_sessions(timeout);

    // Retrieve the number of active user sessions
    int num_active = get_num_active_sessions();

    return num_active;
}
