#define MAX_ENTITIES 1000
#define MAX_NAME_LENGTH 20
#define MAX_STATUS 5
#define TIMEOUT 300 // in seconds

typedef enum {
    EntityStatusActive,
    EntityStatusInactive,
} EntityState;

typedef struct {
    char name[MAX_NAME_LENGTH];
    unsigned int id;
    EntityState status;
    time_t lastActive;
} Entity;

Entity* entities = NULL;
int entityCount = 0;

void initEntities(int size) {
    if (size > MAX_ENTITIES)
        size = MAX_ENTITIES;

    entities = (Entity*)malloc(size * sizeof(Entity));
    for (int i = 0; i < size; i++) {
        strcpy(entities[i].name, validNames[rand() % strlen(validNames)]);
        entities[i].id = rand();
        entities[i].status = (rand() % MAX_STATUS == 0) ? EntityStatusActive : EntityStatusInactive;
        entities[i].lastActive = time(NULL);
    }
    entityCount = size;
}

void addEntity(Entity newEntity) {
    // Check for memory allocation errors
    if (!entities)
        initEntities(1);

    // Find the first inactive or empty slot and replace it with the new entity
    for (int i = 0; i < entityCount; i++) {
        if (entities[i].status == EntityStatusInactive) {
            memcpy(&entities[i], &newEntity, sizeof(Entity));
            return;
        }
    }

    // If all slots are active or filled, allocate a new block of entities
    int newSize = entityCount + 1;
    entities = (Entity*)realloc(entities, newSize * sizeof(Entity));
    for (int i = entityCount; i < newSize; i++) {
        strcpy(entities[i].name, validNames[rand() % strlen(validNames)]);
        entities[i].id = rand();
        entities[i].status = (rand() % MAX_STATUS == 0) ? EntityStatusActive : EntityStatusInactive;
        entities[i].lastActive = time(NULL);
    }
    entityCount = newSize;
}

void updateEntity(int index, Entity newEntity) {
    // Check for index out of bounds and ensure the entity exists
    if (index >= entityCount || !entities)
        return;

    // Update the entity's status and last active time
    entities[index].status = newEntity.status;
    entities[index].lastActive = time(NULL);
}

int getEntityCount() {
    return entityCount;
}

void purgeInactiveEntities(int timeout) {
    // Check for memory allocation errors
    if (!entities)
        return;

    for (int i = 0; i < entityCount; i++) {
        if (difftime(time(NULL), entities[i].lastActive) > timeout) {
            // Mark the entity as inactive and update its last active time
            entities[i].status = EntityStatusInactive;
            entities[i].lastActive = time(NULL);
        }
    }
}

void logEntityActivity() {
    // Implement logging mechanism here
    printf("Entity activity logged.\n");
}
