} UserSession;

int user_session_count = 0;
UserSession *user_sessions = NULL;

void add_user_session(int userID, long lastActivityTime, int sessionState) {
    // Allocate memory for new record
    UserSession* new_record = (UserSession*)malloc(sizeof(UserSession));
    if (!new_record) {
        // Handle allocation failure
        printf("Error: Memory allocation failed.\n");
        return;
    }

    new_record->UserID = userID;
    new_record->LastActivityTime = lastActivityTime;
    new_record->SessionState = sessionState;

    // Add record to user_sessions array and increment count
    user_session_count++;
    if (user_sessions == NULL || user_session_count > 1) {
        user_sessions = (UserSession*)realloc(user_sessions, sizeof(UserSession) * user_session_count);
        if (!user_sessions) {
            // Handle allocation failure
            printf("Error: Memory reallocation failed.\n");
            free(new_record);
            return;
        }
    }

    user_sessions[user_session_count - 1] = *new_record;
}

int get_active_session_count() {
    int activeSessions = 0;
    for (int i = 0; i < user_session_count; i++) {
        if (user_sessions[i].SessionState == 1) {
            activeSessions++;
        }
    }
    return activeSessions;
}

void update_user_session(int userID, int sessionState) {
    // Find and update existing record
    for (int i = 0; i < user_session_count; i++) {
        if (user_sessions[i].UserID == userID) {
            user_sessions[i].SessionState = sessionState;
            return;
        }
    }

    printf("Error: User session not found.\n");
}

void delete_user_session(int userID) {
    int i, j;

    for (i = 0; i < user_session_count; i++) {
        if (user_sessions[i].UserID == userID) {
            break;
        }
    }

    if (i >= user_session_count) {
        printf("Error: User session not found.\n");
        return;
    }

    // Shift remaining records down
    for (j = i + 1; j < user_session_count; j++) {
        user_sessions[j - 1] = user_sessions[j];
    }

    // Decrement count and free memory
    user_session_count--;
    if (user_session_count > 0) {
        user_sessions = (UserSession*)realloc(user_sessions, sizeof(UserSession) * user_session_count);
    } else {
        free(user_sessions);
        user_sessions = NULL;
    }
}

void init_user_sessions() {
    pthread_mutex_init(&lock, NULL);

    // Initialize with dummy values
    for (int i = 0; i < 10000; i++) {
        UserSession record;
        record.UserID = rand();
        record.LastActivityTime = time(NULL);
        record.SessionState = 1;

        user_sessions = (UserSession*)realloc(user_sessions, sizeof(UserSession) * (i + 1));
        user_sessions[i] = record;
    }

    user_session_count = 10000;
}

void cleanup_user_sessions() {
    pthread_mutex_destroy(&lock);

    if (user_sessions) {
        free(user_sessions);
    }
}

int main() {
    // Initialize the system
    init_user_sessions();

    // Add, update, and retrieve user sessions
    add_user_session(1, time(NULL), 1);
    add_user_session(2, time(NULL), 0);

    int activeSessions = get_active_session_count();
    printf("Active Sessions: %d\n", activeSessions);

    update_user_session(1, 1);

    int userID = 2;
    delete_user_session(userID);

    // Clean up the system
    cleanup_user_sessions();

    return 0;
}
