#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    ConnectionState_DISCONNECTED,
    ConnectionState_CONNECTED,
    ConnectionState_PENDING
} ConnectionState;

typedef struct {
    char* ipAddress;
    int portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

typedef struct {
    NetworkConnectionStatus* connections;
    int capacity;
    int size;
    pthread_mutex_t lock;
} ConnectionArray;

void initConnectionArray(ConnectionArray* array, int initialCapacity) {
    array->connections = (NetworkConnectionStatus*)malloc(initialCapacity * sizeof(NetworkConnectionStatus));
    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

int addConnection(ConnectionArray* array, char* ipAddress, int portNumber, ConnectionState connectionState) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        // Reallocation mechanism
        array->connections = (NetworkConnectionStatus*)realloc(array->connections, 2 * array->capacity * sizeof(NetworkConnectionStatus));
        array->capacity *= 2;
    }

    NetworkConnectionStatus* newConnection = &array->connections[array->size++];
    newConnection->ipAddress = ipAddress;
    newConnection->portNumber = portNumber;
    newConnection->connectionState = connectionState;

    pthread_mutex_unlock(&array->lock);
    return array->size - 1;
}

int getActiveConnections(ConnectionArray* array) {
    int activeCount = 0;
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->size; i++) {
        if (array->connections[i].connectionState == ConnectionState_CONNECTED) {
            activeCount++;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return activeCount;
}

void printConnectionSummary(ConnectionArray* array) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->size; i++) {
        printf("IP Address: %s, Port Number: %d, Connection State: %s\n", 
               array->connections[i].ipAddress, array->connections[i].portNumber,
               connectionStateToString(array->connections[i].connectionState));
    }

    pthread_mutex_unlock(&array->lock);
}

char* connectionStateToString(ConnectionState state) {
    switch (state) {
        case ConnectionState_DISCONNECTED:
            return "DISCONNECTED";
        case ConnectionState_CONNECTED:
            return "CONNECTED";
        case ConnectionState_PENDING:
            return "PENDING";
    }
}

void freeConnectionArray(ConnectionArray* array) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->size; i++) {
        free(array->connections[i].ipAddress);
    }

    free(array->connections);
    pthread_mutex_unlock(&array->lock);
}
