void addConnection(NetworkConnectionStatus* newConnection) {
    pthread_mutex_lock(&mutex);
    if (networkConnectionsCount >= capacity) {
        int newSize = capacity * 2;
        NetworkConnectionStatus* tempArray = realloc(networkConnections, newSize * sizeof(NetworkConnectionStatus));
        if (!tempArray) {
            printf("Memory allocation failed.\n");
            return;
        }
        networkConnections = tempArray;
        capacity = newSize;
    }
    networkConnections[networkConnectionsCount++] = *newConnection;
    pthread_mutex_unlock(&mutex);
}

NetworkConnectionStatus* getConnection(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < networkConnectionsCount) {
        return &networkConnections[index];
    } else {
        printf("Index out of bounds.\n");
        return NULL;
    }
    pthread_mutex_unlock(&mutex);
}

int getActiveConnections() {
    pthread_mutex_lock(&mutex);
    int active = 0;
    for (int i = 0; i < networkConnectionsCount; i++) {
        if (networkConnections[i].connectionState == ConnectionState_Connected) {
            active++;
        }
    }
    pthread_mutex_unlock(&mutex);
    return active;
}

