    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_nfastructures(int num_structures) {
    NFAPI_CRC_INDICATION_PDU_T *nfastructures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_structures; i++) {
        nfastructures[i].RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti = rand() % (0xFFFF - 0x0001 + 1) + 0x0001;
        while (i > 0 && nfastructures[i-1].RNTI == rnti) {
            rnti = rand() % (0xFFFF - 0x0001 + 1) + 0x0001;
        }
        nfastructures[i].RNTI = rnti;
        nfastructures[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        nfastructures[i].CRCFLAG = rand() % 2;

        if (nfastructures[i].RNTI < 0x0001 || nfastructures[i].RNTI > 0xFFFF) {
            // Log invalid RNTI values
            printf("Invalid RNTI value: %d\n", nfastructures[i].RNTI);
        }
    }

    free(nfastructures);

    return system("rustc --hook=custom-logging-hook");
}

int main(int argc, char *argv[]) {
    int num_structures = 100000;
    clock_t start_time = clock();
    rlim_t core_limit = getrlimit(RLIMIT_CORE);
    rlim_t data_limit = getrlimit(RLIMIT_DATA);

    // Install an ice hook using the SyncLazy module
    void (*early_error)(const char *message) = NULL;

    int exit_code = generate_nfastructures(num_structures);

    clock_t end_time = clock();
    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    rlim_t core_limit_after = getrlimit(RLIMIT_CORE);
    rlim_t data_limit_after = getrlimit(RLIMIT_DATA);

    printf("Time taken: %f seconds\n", time_taken);
    printf("Core limit before: %lu, after: %lu\n", core_limit, core_limit_after);
    printf("Data limit before: %lu, after: %lu\n", data_limit, data_limit_after);

    return exit_code;
}
