#define MAX_STRUCTURES 10000
#define MAX_FLOATS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[2];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_RX_FRAME_T {
    uint8_t signal_strength;
    int64_t timestamp;
} NFAPI_RX_FRAME_T;

void* initialize_and_allocate_structures(void** structures, pthread_mutex_t* lock) {
    *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        (*structures)[i].RX_UE_INFORMATION_TAG = rand() % 256;
        (*structures)[i].RNTI = rand() % 65536;
        (*structures)[i].CRC_INDICATION_REL8_TAG[0] = (uint8_t)(rand() % 256);
        (*structures)[i].CRC_INDATION_REL8_TAG[1] = (uint8_t)(rand() % 256);
        (*structures)[i].CRCFLAG = rand() % 2;
    }
    return NULL;
}

void* process_floats_and_allocate_array(void** floats, pthread_mutex_t* lock) {
    *floats = (double*)malloc(MAX_FLOATS * sizeof(double));
    int count = 0;
    while (scanf("%lf", &(*floats)[count]) == 1) {
        count++;
        if (count >= MAX_FLOATS) break;
    }
    (*floats)[count] = NaN; // sentinel value
    return NULL;
}

double find_smallest_number(double* array, int size) {
    double smallest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] < smallest) smallest = array[i];
    }
    return smallest;
}

void calculate_signal_strength(NFAPI_CRC_INDICATION_PDU_T* structures, NFAPI_RX_FRAME_T** rx_frames, pthread_mutex_t* lock) {
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        double magnitude = 1.0; // use the floating-point number as magnitude
        int count = 0;
        for (double* floats = (*rx_frames)[i].signal_strength_data; *floats != NaN; floats++) {
            magnitude += *floats;
            count++;
        }
        (*rx_frames)[i].signal_strength = (uint8_t)(magnitude / count);
    }
}

void* main_function(void** structures, void** floats, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);
    initialize_and_allocate_structures(structures, lock);
    process_floats_and_allocate_array(floats, lock);
    pthread_mutex_unlock(lock);

    NFAPI_RX_FRAME_T* rx_frames = (NFAPI_RX_FRAME_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_RX_FRAME_T));
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        rx_frames[i].timestamp = time(NULL);
    }

    calculate_signal_strength(*structures, &rx_frames, lock);

    double* smallest = find_smallest_number(*floats, *floats - (*floats) + 1);
    printf("Smallest number: %f\n", smallest);

    free(rx_frames);
    return NULL;
}

int main() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* structures;
    void* floats;

    pthread_create(&main_function, &lock);
}
