    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void* nfaPI_CRC_indication_pdu_list_manager(void* data) {
    // Define the mask for CRCFLAG validation
    int crc_mask = 0x0001; // Example: 0x0001

    // Initialize the list and its size
    NFAPI_CRC_INDICATION_PDU_T** record;
    int num_records = 0;

    // Create a lock for thread-safe operations
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    // Function to add new entry to the list (thread-safe)
    void add_entry(NFAPI_CRC_INDICATION_PDU_T* new_record) {
        pthread_mutex_lock(&list_lock);

        // Validate CRCFLAG against the predefined mask
        if ((new_record->CRCFLAG & crc_mask) != 0x0001) {
            printf("Error: Invalid CRCFLAG\n");
            return;
        }

        // Allocate memory for a new record and add it to the list
        record = realloc(record, (num_records + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        record[num_records] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *record[num_records] = *new_record;
        num_records++;

        pthread_mutex_unlock(&list_lock);
    }

    // Function to retrieve an entry from the list (thread-safe)
    NFAPI_CRC_INDICATION_PDU_T* get_entry(int index) {
        pthread_mutex_lock(&list_lock);

        if (index >= num_records || record[index] == NULL) {
            printf("Error: Invalid index\n");
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T* result = record[index];
        pthread_mutex_unlock(&list_lock);
        return result;
    }

    // Function to clear the list (thread-safe)
    void clear_list() {
        pthread_mutex_lock(&list_lock);

        for (int i = 0; i < num_records; i++) {
            free(record[i]);
        }
        free(record);
        record = NULL;
        num_records = 0;

        pthread_mutex_unlock(&list_lock);
    }

    // Initialize the list and its size
    add_entry((NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = 3, .CRCFLAG = 0x0001});

    // Manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
    while (1) {
        pthread_mutex_lock(&list_lock);

        // Perform periodic integrity checks on the record array
        for (int i = 0; i < num_records; i++) {
            if (record[i]->CRCFLAG & crc_mask) {
                printf("Warning: Duplicate CRCFLAG detected\n");
            }
        }

        pthread_mutex_unlock(&list_lock);
    }
}

