// Define the structure for NetworkConnectionStatus
typedef struct {
    char ipAddress[17]; // 15 bytes for IPv4 and 45 bytes for IPv6 plus null terminator
    int portNumber;
    enum {
        CONNECTED,
        DISCONNECTED,
        PENDING
    } connectionState;
} NetworkConnectionStatus;

// Define the dynamic array structure to manage NetworkConnectionStatus objects
typedef struct {
    NetworkConnectionStatus* connections;
    size_t capacity;
    size_t size;
} ConnectionArray;

// Function to initialize a new ConnectionArray with initial capacity and size
ConnectionArray* initConnectionArray(size_t initialCapacity) {
    ConnectionArray* arr = (ConnectionArray*)malloc(sizeof(ConnectionArray));
    arr->connections = (NetworkConnectionStatus*)calloc(initialCapacity, sizeof(NetworkConnectionStatus));
    arr->capacity = initialCapacity;
    arr->size = 0;
    return arr;
}

// Function to add a new connection to the array
void addConnection(ConnectionArray* arr, NetworkConnectionStatus conn) {
    if (arr->size >= arr->capacity) {
        // Resize the array when it's full
        size_t newCapacity = arr->capacity * 2;
        NetworkConnectionStatus* newConnArr = (NetworkConnectionStatus*)realloc(arr->connections, newCapacity * sizeof(NetworkConnectionStatus));
        arr->connections = newConnArr;
        arr->capacity = newCapacity;
    }
    arr->connections[arr->size] = conn;
    arr->size++;
}

// Function to update an existing connection in the array
void updateConnection(ConnectionArray* arr, int idx, NetworkConnectionStatus updatedConn) {
    if (idx >= 0 && idx < arr->size) {
        arr->connections[idx] = updatedConn;
    } else {
        printf("Error: Connection index out of bounds\n");
    }
}

// Function to delete a connection from the array
void deleteConnection(ConnectionArray* arr, int idx) {
    if (idx >= 0 && idx < arr->size) {
        for (int i = idx; i < arr->size - 1; i++) {
            arr->connections[i] = arr->connections[i + 1];
        }
        arr->size--;
    } else {
        printf("Error: Connection index out of bounds\n");
    }
}

// Function to get the number of active connections
size_t getActiveConnections(ConnectionArray* arr) {
    size_t count = 0;
    for (int i = 0; i < arr->size; i++) {
        if (arr->connections[i].connectionState == CONNECTED || arr->connections[i].connectionState == PENDING) {
            count++;
        }
    }
    return count;
}

// Function to serialize the ConnectionArray to a file
void serializeConnectionArray(ConnectionArray* arr, FILE* file) {
    fwrite(&arr->size, sizeof(size_t), 1, file);
    for (int i = 0; i < arr->size; i++) {
        fwrite(&arr->connections[i], sizeof(NetworkConnectionStatus), 1, file);
    }
}

// Function to deserialize the ConnectionArray from a file
ConnectionArray* deserializeConnectionArray(FILE* file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    ConnectionArray* arr = initConnectionArray(size);
    for (int i = 0; i < size; i++) {
        NetworkConnectionStatus conn;
        fread(&conn, sizeof(NetworkConnectionStatus), 1, file);
        addConnection(arr, conn);
    }
    return arr;
}
