#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int* integer;
    long offset;
    int key;
} record;

record* allocateRecords(int size) {
    if (size <= 0) {
        printf("Invalid input size. Size must be positive.\n");
        return NULL;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].integer = malloc(sizeof(int));
        if (!records[i].integer) {
            free(records);
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }
        *records[i].integer = rand() % 1001;
        records[i].offset = (long)i; // initialize with sequential values
        records[i].key = findNextPrime(i + 1) % 1000; // generate unique prime key
    }

    return records;
}

void populateRecords(record* records, int size) {
    for (int i = 0; i < size; i++) {
        *records[i].integer = rand() % 1001;
    }
}

long findNextPrime(long num) {
    if (num <= 1)
        return 2;

    while (true) {
        long test = (num << 1) + 1;
        for (long i = 3; i * i <= test; i += 2) {
            if ((test % i) == 0)
                return findNextPrime(num);
        }
        return num;
    }
}

void deallocateRecords(record* records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i].integer);
    }
    free(records);
}
