// Define the array to manage the devices
NetworkDevice* devices[MAX_DEVICES];

// Initialize the device management function
void initialize_device_management() {
    // Initialize the devices array with NULLs
    for (int i = 0; i < MAX_DEVICES; i++) {
        devices[i] = NULL;
    }
}

// Add a new device to the management system
void add_device(NetworkDevice* device) {
    // Find an available slot in the devices array
    int i;
    for (i = 0; i < MAX_DEVICES; i++) {
        if (!devices[i]) {
            break;
        }
    }

    // If no slots are available, handle error
    if (i == MAX_DEVICES) {
        log_error("Maximum number of devices reached!");
        return;
    }

    // Store the device information in the array
    devices[i] = device;

    // Update the metadata for the new device
    update_device_metadata(device);
}

// Update an existing device's state
void update_device_state(int index, ConnectionState newState) {
    // Find the device with the matching index
    if (index >= 0 && index < MAX_DEVICES) {
        NetworkDevice* device = devices[index];
        if (device) {
            device->state = newState;
            log_info("Updated device state to %s", get_state_string(newState));
        } else {
            log_error("Device not found!");
        }
    } else {
        log_error("Invalid device index!");
    }
}

// Retrieve the number of active devices
int get_active_device_count() {
    int count = 0;
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (devices[i] && devices[i]->state == ConnectionState_CONNECTED) {
            count++;
        }
    }
    return count;
}

// Periodically perform garbage collection to free up resources
void perform_garbage_collection() {
    // Iterate through the devices array and remove any inactive devices
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (devices[i] && devices[i]->state == ConnectionState_DISCONNECTED) {
            // Remove the device from the array
            free(devices[i]);
            devices[i] = NULL;
        }
    }
}

// Main function to manage devices
int main() {
    initialize_device_management();

    // Add some sample devices
    add_device((NetworkDevice*)malloc(sizeof(NetworkDevice)));
    add_device((NetworkDevice*)malloc(sizeof(NetworkDevice)));

    // Update device states and retrieve the active count
    update_device_state(0, ConnectionState_CONNECTED);
    log_info("Active device count: %d", get_active_device_count());

    // Periodically perform garbage collection
    while (1) {
        perform_garbage_collection();
        sleep(1); // Simulate periodic updates
    }

    return 0;
}
