// Define a function to find and print the maximum value
double find_max(float* array, int size) {
    double max = -INFINITY;
    for (int i = 0; i < size; i++) {
        if (array[i] > max)
            max = array[i];
    }
    printf("Maximum value: %f\n", max);
    return max;
}

