    // Apply polynomial scaling factor based on the maximum value
    double scaling_factor = 0.1 * (max - 20.0) + 0.5;
    return temperature * scaling_factor;
}

// Define a function to manage memory and swap elements in the array
void manage_memory(float** array, int* size, float threshold) {
    if (*size > 10000 && *(array[*size-1]) < threshold) {
        for (int i = *size - 1; i > 0; i--) {
            array[i] = array[i-1];
        }
        *size -= 1;
    }
}

// Define a function to process temperature readings
void process_temperature_readings(float** array, int* size) {
    // Initialize variables for processing and scaling
    double max_value = find_max(*array, *size);
    for (int i = 0; i < *size; i++) {
        TemperatureReading reading;
        reading.timestamp = time(NULL); // Get current timestamp
        strcpy(reading.sensor_id, "SENSOR_ID"); // Initialize sensor ID
        reading.temperature = scale_temperature(max_value, (*array)[i]);
        // Validate historical data and register temperature readings with interface
    }
}

// Define a function to monitor memory usage and swap elements if necessary
