        char buffer[256];
        fgets(buffer, sizeof(buffer), stdin);
        if (!strcmp(buffer, "q\n"))
            break;
        size++;
        float* temp_array = (float*)realloc(array, (size+1) * sizeof(float));
        array = temp_array;
        sscanf(buffer, "%f", &array[size-1]);
    }

    process_temperature_readings(&array, &size);
    free(array);

    return 0;
}
