        if (!records[i].integer) {
            for (int j = i; j >= 0; --j) {
                free(records[j].integer);
                free(&keys[j]);
                free(&offsets[j]);
            }
            free(keys);
            free(offsets);
            free(records);
            return NULL; // Error allocating memory for integers
        }
        *records[i].integer = rand() % 1001;
    }

    struct {
        record* records;
        int status;
    } result;

    result.records = records;
    result.status = 0; // Successful allocation

    return &result;
}

int rand_prime() {
    int num;
    do {
        num = rand() % 999 + 1;
        for (int i = 2, sqrt_i = (int)sqrt((double)num); i <= sqrt_i; ++i) {
            if (num % i == 0) {
                break;
            }
        }
    } while (num < 2);
    return num;
}
