    int activeCount = 0;
    for (int i = 0; i < connectionsCount; i++) {
        if (connections[i].connectionState == NetworkConnectionStatus::ACTIVE) {
            activeCount++;
        }
    }
    return activeCount;
}

void printConnectionSummary() {
    for (int i = 0; i < connectionsCount; i++) {
        printf("IP Address: %s, Port Number: %d, ConnectionState: %s\n",
               connections[i].ipAddress,
               connections[i].portNumber,
               (connections[i].connectionState == NetworkConnectionStatus::DISCONNECTED) ? "Disconnected" :
              (connections[i].connectionState == NetworkConnectionStatus::CONNECTING) ? "Connecting" :
              (connections[i].connectionState == NetworkConnectionStatus::ACTIVE) ? "Active" : "Finished");
    }
}

int findLargest(int* array, int size) {
    if (size <= 0)
        return -1;
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max)
            max = array[i];
    }
    return max;
}

int main() {
    int inputArray[100]; // adjust size as needed
    int inputCount = 0;

    printf("Enter integers (separated by spaces, enter 'q' to quit):\n");
    while (scanf("%d", &inputArray[inputCount++]) == 1) {
        if (getchar() == 'q')
            break;
    }

    for (int i = 0; i < inputCount - 1; i++) {
        printf(" %d", inputArray[i]);
    }
    printf("\n");
    int largest = findLargest(inputArray, inputCount);
    if (largest != -1)
        printf("The largest integer is: %d\n", largest);

    return 0;
}
