#include "network_device.h"

typedef struct {
    NetworkDevice *devices;
    int capacity;
    int size;
} DynamicArray;

DynamicArray* createDynamicArray(int initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->devices = malloc(initialCapacity * sizeof(NetworkDevice));
    array->capacity = initialCapacity;
    array->size = 0;
    return array;
}

void freeDynamicArray(DynamicArray* array) {
    if (array == NULL) return;
    for (int i = 0; i < array->size; i++) {
        free(array->devices[i].ipAddress);
        free(array->devices[i].deviceType);
    }
    free(array->devices);
    free(array);
}

void addDevice(DynamicArray* array, NetworkDevice device) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->devices = realloc(array->devices, array->capacity * sizeof(NetworkDevice));
    }
    array->devices[array->size] = device;
    array->size++;
}

void updateDevice(DynamicArray* array, int index, NetworkDevice device) {
    if (index >= array->size || index < 0) return;
    array->devices[index] = device;
}

int getActiveDevices(DynamicArray* array) {
    int count = 0;
    for (int i = 0; i < array->size; i++) {
        if (array->devices[i].connectionState == ConnectionState_ACTIVE)
            count++;
    }
    return count;
}
