    int tx_power_level;
    int srs_config;
    double srs_periodicity;
} LOGICAL_CHANNEL_GROUP;

LOGICAL_CHANNEL_GROUP* allocate_logical_channel_group(int N) {
    LOGICAL_CHANNEL_GROUP* logical_channels = NULL;

    for (int i = 0; i < 3 && !logical_channels; i++) {
        logical_channels = (LOGICAL_CHANNEL_GROUP*)malloc(N * sizeof(LOGICAL_CHANNEL_GROUP));

        if (!logical_channels) {
            printf("Memory allocation failed. Retrying...\n");
        } else {
            break;
        }
    }

    return logical_channels;
}

void deallocate_logical_channel_group(LOGICAL_CHANNEL_GROUP* logical_channels, int N) {
    for (int i = 0; i < N; i++) {
        free(logical_channels + i);
    }
    free(logical_channels);
}

LOGICAL_CHANNEL_GROUP* process_logical_channel_groups(int N) {
    LOGICAL_CHANNEL_GROUP* logical_channels = allocate_logical_channel_group(N);

    if (!logical_channels) {
        printf("Failed to allocate memory for %d logical channel groups.\n", N);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        LOGICAL_CHANNEL_GROUP* logical_channel = logical_channels + i;

        if ((logical_channel->channel_id >= 0 && logical_channel->channel_id <= 255) 
            || printf("Invalid CHANNEL_ID: %d\n", logical_channel->channel_id)) {
            continue;
        }

        logical_channel->tx_power_level = rand() % 100;
        logical_channel->srs_config = rand() % 256;
        logical_channel->srs_periodicity = (double)rand() / RAND_MAX;
    }

    // Log statistical information
    int min_srs_periodicity = INT_MAX, max_srs_periodicity = 0;
    for (int i = 0; i < N; i++) {
        LOGICAL_CHANNEL_GROUP* logical_channel = logical_channels + i;

        if (logical_channel->srs_periodicity < min_srs_periodicity)
            min_srs_periodicity = logical_channel->srs_periodicity;

        if (logical_channel->srs_periodicity > max_srs_periodicity)
            max_srs_periodicity = logical_channel->srs_periodicity;
    }

    printf("Min SRS Periodicity: %f, Max SRS Periodicity: %f\n", min_srs_periodicity, max_srs_periodicity);

    return logical_channels;
}

int main() {
    int N;
    scanf("%d", &N);

    LOGICAL_CHANNEL_GROUP* logical_channels = process_logical_channel_groups(N);

    if (!logical_channels) {
        printf("Memory allocation failed. Exiting...\n");
        return 1;
    }

    deallocate_logical_channel_group(logical_channels, N);

    return 0;
}
