const fs = require('fs');
const jsonSchema = require('jsonschema');
const { performance } = require('perf_hooks');

function validateFiles(directory, schema) {
  const cache = {};
  const log = console.log.bind(console, 'Cache:');

  async function readAndValidate(file) {
    try {
      const content = await fs.promises.readFile(`${directory}/${file}`);
      if (cache[file]) return cache[file];
      const result = jsonSchema.validate(JSON.parse(content.toString()), schema);
      if (!result.errors.length) {
        cache[file] = JSON.parse(content.toString());
        return cache[file];
      }
      throw new Error(`Invalid file: ${file}`);
    } catch (err) {
      console.error(err.message, err.stack);
    }
  }

  async function validateDirectory() {
    const files = await fs.promises.readdir(directory);
    const results = [];

    for (const file of files) {
      try {
        results.push(await readAndValidate(file));
      } catch {}
    }

    return results;
  }

  async function cacheOptimizedValidation(dir, schema) {
    let lastCacheUpdate = performance.now();
    const validatedFiles = [];

    (async () => {
      for await (const file of validateDirectory()) {
        try {
          validatedFiles.push(await readAndValidate(file));
        } catch {}

        if (performance.now() - lastCacheUpdate > 1000) { // cache update every 1s
          console.log('Caching files...');
          Object.keys(cache).forEach((file) => {
            log(`File: ${file} - Hit: ${cache[file].length}`);
          });
          lastCacheUpdate = performance.now();
        }
      }
    })();

    return validatedFiles;
  }

  return cacheOptimizedValidation(directory, schema);
}
