MAC_CONTEXT* allocate_MAC_contexts(int N) {
    MAC_CONTEXT *contexts = NULL;
    if (!(contexts = (MAC_CONTEXT *)malloc(N * sizeof(MAC_CONTEXT)))) {
        // Handle memory allocation failure
        return NULL;
    }

