#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define BUFFER_SIZE 1024
#define MAX_EVENTS 1000
#define LOG_FILE "event_log.txt"

typedef struct {
    int timestamp;
    int id;
} Event;

Event *buffer = NULL;
int buffer_len = 0;
int overflow_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void processEvents(int sockfd) {
    int i, event_size;
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    Event *event;

    while (1) {
        event = (Event *)malloc(sizeof(Event));
        if (!event) {
            printf("Memory allocation failed!\n");
            break;
        }

        if (read(sockfd, event, sizeof(Event)) == 0) {
            close(sockfd);
            free(event);
            return;
        }

        pthread_mutex_lock(&lock);
        if (buffer_len >= BUFFER_SIZE) {
            overflow_count++;
            printf("Buffer overflow detected! (%d events)\n", buffer_len);
        } else {
            buffer[buffer_len++] = *event;
        }
        pthread_mutex_unlock(&lock);
    }
}

void handleOverflow() {
    // Handle the overflow here
    printf("Overflow handled.\n");
}

void logSessionActivity() {
    // Log session activity here
    printf("Logged session activity.\n");
}

int main(int argc, char *argv[]) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return -1;
    }

    // Bind and listen
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(8080);
    bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    listen(sockfd, 3);

    while (1) {
        int client_sockfd = accept(sockfd, NULL, NULL);
        if (client_sockfd < 0) {
            perror("Accept failed");
            continue;
        }

        processEvents(client_sockfd);
        close(client_sockfd);
    }

    return 0;
}
