#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Index;

Index* index_create(size_t capacity) {
    Index* idx = (Index*)malloc(sizeof(Index));
    idx->records = (Record*)calloc(capacity, sizeof(Record));
    idx->capacity = capacity;
    idx->count = 0;
    pthread_mutex_init(&idx->mutex, NULL);
    return idx;
}

void index_destroy(Index* idx) {
    if (!idx) return;
    free(idx->records);
    pthread_mutex_destroy(&idx->mutex);
    free(idx);
}

int index_insert(Index* idx, int key, long offset) {
    Record record = (Record){key, offset};
    if (idx->count >= idx->capacity) {
        size_t new_capacity = idx->capacity * 2;
        Record* new_records = (Record*)realloc(idx->records, new_capacity * sizeof(Record));
        idx->records = new_records;
        idx->capacity = new_capacity;
    }
    pthread_mutex_lock(&idx->mutex);
    for (size_t i = 0; i < idx->count; ++i) {
        if (idx->records[i].key == key) {
            pthread_mutex_unlock(&idx->mutex);
            return -1; // Duplicate key
        }
    }
    idx->records[idx->count++] = record;
    pthread_mutex_unlock(&idx->mutex);
    return 0;
}

int index_delete(Index* idx, int key) {
    pthread_mutex_lock(&idx->mutex);
    for (size_t i = 0; i < idx->count; ++i) {
        if (idx->records[i].key == key) {
            memmove(&idx->records[i], &idx->records[i + 1], (idx->count - i - 1) * sizeof(Record));
            --idx->count;
            break;
        }
    }
    pthread_mutex_unlock(&idx->mutex);
    return 0;
}

int index_lookup(Index* idx, int key, long* offset) {
    pthread_mutex_lock(&idx->mutex);
    for (size_t i = 0; i < idx->count; ++i) {
        if (idx->records[i].key == key) {
            *offset = idx->records[i].offset;
            pthread_mutex_unlock(&idx->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&idx->mutex);
    return -1; // Key not found
}

int main() {
    Index* idx = index_create(16);
    int key = 42;
    long offset = 123456789;
    index_insert(idx, key, offset);
    printf("Inserted record with key %d and offset %ld.\n", key, offset);

    // ... (insert more records or perform other operations)

    index_destroy(idx);
    return 0;
}
