void processEntitiesAndEncryptData(Entity** entities, int entityCount) {
    // Initialize random data for entities
    srand(time(NULL));
    char* names[] = {"John", "Jane", "Bob", "Alice"};
    for (int i = 0; i < entityCount; i++) {
        entities[i]->name = (char*)malloc(strlen(names[rand() % sizeof(names) / sizeof(names[0])]) + 1);
        strcpy(entities[i]->name, names[rand() % sizeof(names) / sizeof(names[0])]);
        entities[i]->id = rand();
        entities[i]->status = rand() % STATUS_STATES;
    }

