        long fileSize = ftell(file);
        rewind(file);
        bytesRead = fread(hash, 1, fileSize, file);
        fclose(file);
        uint32_t hashVal = *((uint32_t*)hash);
        free(hash);

        // Simulate network latency
        usleep(50000); // 50 milliseconds

        printf("MD5 computation time: %f seconds\n", difftime(time(NULL), startTime));
    }

    // Derive AES key from user-provided password using PBKDF2
    const char* password = "my_secret_password";
    uint8_t salt[16];
    RAND_bytes(salt, 16);
    uint32_t iterations = 100000;
    unsigned char derivedKey[AES_KEY_SIZE];
    int ret;
    PBKDF2_CTX ctx;
    PBKDF2_key(ctx, (const unsigned char*)password, strlen(password), salt, 16, iterations, AES_KEY_SIZE / 8, derivedKey);

    // Generate and validate random IV
    uint8_t iv[IV_SIZE];
    RAND_bytes(iv, IV_SIZE);
    for (int i = 0; i < IV_SIZE; i++) {
        if (iv[i] == 0) {
            RAND_bytes(iv + i, 1);
            break;
        }
    }

    // Integrate AES-256-CBC encryption
    AES_KEY key;
    ret = AES_set_encrypt_key(derivedKey, AES_KEY_SIZE, &key);
    if (ret < 0) {
        perror("Error setting AES key");
        exit(EXIT_FAILURE);
    }
    uint8_t plaintext[] = "Hello, World!";
    int plaintextLen = strlen((char*)plaintext);
    uint8_t ciphertext[AES_BLOCK_SIZE];
    ret = AES_cbc_encrypt(plaintext, ciphertext, plaintextLen, &key, iv, AES_ENCRYPT);
    if (ret < 0) {
        perror("Error encrypting data");
        exit(EXIT_FAILURE);
    }

    // Securely destroy key material
    memset(&derivedKey, 0, AES_KEY_SIZE);
    RAND_cleanup();
}
