int manage_nfa_api_crc_indications(int n, const char **hostnames) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int active_requests = 0;
    int failed_requests = 0;
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        indications[i].crcflag = rand() % 2;
    }
    // Initialize DNS connection pool
    int dns_sockets[MAX_CONCURRENT_REQUESTS];
    pthread_t dns_threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        dns_sockets[i] = socket(AF_INET, SOCK_STREAM, 0);
        setsockopt(dns_sockets[i], SOL_SOCKET, SO_REUSEADDR, &i, sizeof(i));
    }
    // Perform DNS resolution
