#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_POOL_SIZE 1024
#define MIN_POOL_SIZE 128
#define INITIAL_POOL_SIZE 256
#define RECLAIM_THRESHOLD 0.5
#define LOCK_STRIPING_THREADS 8

typedef struct {
    char *key;
    void *value;
} entry_t;

entry_t *entries = NULL;
size_t pool_size = INITIAL_POOL_SIZE;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int reclaim_threshold = RECLAIM_THRESHOLD;
int reclaim_count = 0;
int lock_striping_threads = LOCK_STRIPING_THREADS;
entry_t **lock_striping_handles;

void *memory_pool_alloc(size_t size) {
    if (size > pool_size) {
        size_t new_size = size + (size / 2);
        void *ptr = malloc(new_size);
        if (!ptr) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        // Reclaim excess memory if threshold is reached
        if ((reclaim_count += 1) >= reclaim_threshold * pool_size) {
            size_t reclaimed = new_size - size;
            memmove(ptr, ptr + reclaimed, size);
            free(ptr + size);
        }
    } else {
        ptr = malloc(size);
    }
    return ptr;
}

void memory_pool_free(void *ptr, size_t size) {
    if (size > pool_size) {
        size_t new_size = size - (size / 2);
        memmove(entries, entries + new_size, size);
        free((char *)entries + size);
        pool_size = new_size;
    } else {
        free(ptr);
    }
}

void *config_database_alloc(size_t size) {
