NFAPI_UL_CCCH_MESSAGE* addMessage(NFAPI_UL_CCCH_MESSAGE* message, int sequenceNumber) {
    pthread_mutex_lock(&mutex);

    if (sequenceNumber < 1) {
        printf("Invalid sequence number.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    NFAPI_UL_CCCH_MESSAGE** newArray = (NFAPI_UL_CCCH_MESSAGE**)realloc(dynamicArray, (size + 1) * sizeof(NFAPI_UL_CCCH_MESSAGE*));

    if (!newArray) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    dynamicArray = newArray;

    NFAPI_UL_CCCH_MESSAGE* newNode = (NFAPI_UL_CCCH_MESSAGE*)malloc(sizeof(NFAPI_UL_CCCH_MESSAGE));

    if (!newNode) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    *newNode = *message;
    dynamicArray[size] = newNode;

    int existingIndex = -1;

    for (int i = 0; i < size; i++) {
        if (dynamicArray[i]->sequenceNumber == sequenceNumber) {
            existingIndex = i;
            break;
        }
    }

    if (existingIndex != -1) {
        printf("Duplicate sequence number detected.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    dynamicArray[size].message = message->message;
    dynamicArray[size].sequenceNumber = sequenceNumber;
    size++;

    pthread_mutex_unlock(&mutex);

    return &dynamicArray[size - 1];
}

NFAPI_UL_CCCH_MESSAGE* getMessage(int sequenceNumber) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < size; i++) {
        if (dynamicArray[i]->sequenceNumber == sequenceNumber) {
            NFAPI_UL_CCCH_MESSAGE* message = dynamicArray[i];
            pthread_mutex_unlock(&mutex);
            return message;
        }
    }

    pthread_mutex_unlock(&mutex);

    printf("Message not found.\n");

    return NULL;
}

