// Custom record structure with integer field
typedef struct {
    int key;
    int value;
} Record;

// Custom memory pool for efficient management of record structures
typedef struct {
    void** pointers; // Array of memory pointers
    size_t capacity;  // Initial and current capacity
    size_t used;      // Number of allocated records
    pthread_mutex_t lock; // Mutex for thread-safe access
} MemoryPool;

// Function to initialize and manage the custom memory pool
void* record_memory_pool_init(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->pointers = (void**) calloc(initial_capacity, sizeof(void*));

    if (!pool->pointers) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Function to allocate a record from the memory pool
Record* record_memory_pool_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->capacity) {
        // Dynamically reallocate and resize the memory pool if necessary
        size_t new_capacity = pool->capacity * 2;
        void** new_pointers = realloc(pool->pointers, new_capacity * sizeof(void*));
        if (!new_pointers) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure
        }
        pool->pointers = new_pointers;
        pool->capacity = new_capacity;
    }

    void* ptr = pool->pointers[pool->used];
    pool->pointers[pool->used] = NULL;
    Record* record = (Record*) ptr;

    pool->used++;

    pthread_mutex_unlock(&pool->lock);
    return record;
}

// Function to free a record from the memory pool
void record_memory_pool_free(MemoryPool* pool, Record* record) {
    pthread_mutex_lock(&pool->lock);

    if (!record) {
        // Handle null pointer
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    size_t idx = (size_t) (long long) record - (size_t) pool->pointers[0];
    pool->pointers[idx] = NULL;

    pthread_mutex_unlock(&pool->lock);
}

// Function to generate random records with integer values
void* generate_random_records(size_t count, MemoryPool* pool) {
    if (!pool) return NULL;

    for (size_t i = 0; i < count; i++) {
        Record* record = record_memory_pool_alloc(pool);

        if (!record) {
            // Handle allocation failure
            break;
        }

        srand((unsigned) time(NULL));
        int value = rand() % 100; // Random integer within range [0, 99]
        record->key = i; // Set key as record index
        record->value = value;

        printf("Record %zu: Key=%d, Value=%d\n", i, record->key, record->value);
    }

    return NULL;
}

int main() {
    size_t initial_capacity = 16;
    MemoryPool* pool = record_memory_pool_init(initial_capacity);

    if (!pool) {
        // Handle initialization failure
        printf("Initialization failed.\n");
        return -1;
    }

    size_t count = 10; // Number of records to generate
    generate_random_records(count, pool);

    for (size_t i = 0; i < count; i++) {
        Record* record = record_memory_pool_free(pool, NULL);
    }

    free(pool->pointers);
    free(pool);

    return 0;
}
