#include <iostream>
#include <vector>
#include <unordered_map>

void hashTableExample(int numElements, int tableSize) {
    std::unordered_map<int, int> hashTable(tableSize);

    for (int i = 0; i < numElements; i++) {
        // Generate a unique key using a hashing algorithm
        int key = i * 31 + 17;

        // Insert element into the hash table
        if (hashTable.find(key) == hashTable.end()) {
            hashTable.insert(std::make_pair(key, i));
        } else {
            // Handle collision by resolving duplicates
            key += 1;
            while (hashTable.find(key) != hashTable.end()) {
                key++;
            }
            hashTable.insert(std::make_pair(key, i));
        }
    }

    for (auto& pair : hashTable) {
        std::cout << "Key: " << pair.first << ", Value: " << pair.second << std::endl;
    }
}
