#include <iostream>
#include <vector>

void unionFindExample(int numArrays, int arraySize) {
    std::vector<int> parent(numArrays);
    for (int i = 0; i < numArrays; i++) {
        parent[i] = i;
    }

    for (int i = 0; i < arraySize; i++) {
        // Perform union operation on disjoint sets
        int set1 = i % numArrays;
        int set2 = (i + 1) % numArrays;
        if (set1 != set2) {
            int t = parent[set1];
            parent[set1] = set2;
            for (int j = 0; j < numArrays; j++) {
                if (parent[j] == t) {
                    parent[j] = set2;
                }
            }
        }
    }

    // Determine the number of disjoint sets
    int disjointSets = 0;
    for (int i = 0; i < numArrays; i++) {
        if (parent[i] == i) {
            disjointSets++;
        }
    }

    std::cout << "Number of disjoint sets: " << disjointSets << std::endl;
}
