void errorHandlingAndRecoveryExample(int numElements) {
    try {
        // Perform operations that may throw exceptions
        for (int i = 0; i < numElements; i++) {
            if (i % 2 == 0) {
                throw new Exception("Error occurred at element " + std::to_string(i));
            }
        }
    } catch (Exception& e) {
        // Handle and recover from the exception
        std::cout << "Caught exception: " << e.what() << std::endl;

        // Attempt to recover by retrying the operation
        for (int i = 0; i < numElements; i++) {
            if (i % 2 == 0) {
                try {
                    // Perform operation again
                    throw new Exception("Error occurred at element " + std::to_string(i));
                } catch (Exception& e) {
                    // Log the error and continue with the next iteration
                    std::cout << "Caught exception during recovery: " << e.what() << std::endl;
                }
            }
        }
    }
}
