#define MAX_HOSTNAME_LENGTH 256
#define MAX_DNS_QUERY_STATISTICS 1024
#define DNS_QUERY_THRESHOLD 10 // queries per second

typedef struct {
    unsigned int rnti;
    char hostname[MAX_HOSTNAME_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

void process_dnf_pdu_and_dns(NFAPI_CRC_INDINATION_PDU_T* pdu_list, int pdu_count) {
    // Initialize DNS query statistics and error details
    static int dns_query_count = 0;
    static char dns_error_details[MAX_DNS_QUERY_STATISTICS];

    for (int i = 0; i < pdu_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = pdu_list[i];

        // Perform DNS resolution for the hostname
        char* hostname = pdu.hostname;
        char buffer[MAX_HOSTNAME_LENGTH];
        struct in_addr ipaddr;
        memset(&ipaddr, 0, sizeof(struct in_addr));
        if (gethostbyname(hostname, buffer, &ipaddr) == NULL) {
            // Log DNS query statistics and error details
            int bytes_written = sprintf(dns_error_details + strlen(dns_error_details), "Failed to resolve hostname %s: %s\n", hostname, strerror(errno));
            if (bytes_written > MAX_DNS_QUERY_STATISTICS - 1) {
                // Handle buffer overflow
                printf("DNS query statistics buffer overflow!\n");
                return;
            }
        } else {
            // Log DNS query statistics and error details
            int bytes_written = sprintf(dns_error_details + strlen(dns_error_details), "Resolved hostname %s to IP address %s\n", hostname, inet_ntoa(ipaddr));
            if (bytes_written > MAX_DNS_QUERY_STATISTICS - 1) {
                // Handle buffer overflow
                printf("DNS query statistics buffer overflow!\n");
                return;
            }
        }

        // Perform rate limiting for DNS queries
        static time_t last_dns_query = 0;
        time_t current_time = time(NULL);
        if (current_time - last_dns_query > 1 / (double)DNS_QUERY_THRESHOLD) {
            last_dns_query = current_time;
        } else {
            printf("Rate limiting: delaying next DNS query\n");
            return; // delay the query
        }
    }

    // Log final DNS query statistics and error details
    int bytes_written = sprintf(dns_error_details + strlen(dns_error_details), "Total DNS queries: %d\n", dns_query_count);
    if (bytes_written > MAX_DNS_QUERY_STATISTICS - 1) {
        // Handle buffer overflow
        printf("DNS query statistics buffer overflow!\n");
    }
}
