#define MAX_JOBS 1000
#define JOB_SIZE sizeof(job_t)

typedef struct job {
    int status;
    int priority;
    time_t deadline;
} job_t;

job_t *jobs = NULL;
int num_jobs = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
time_t last_reorg_time = 0;

void add_job(job_t *job) {
    pthread_mutex_lock(&lock);
    jobs = realloc(jobs, (num_jobs + 1) * JOB_SIZE);
    memcpy(jobs + num_jobs * JOB_SIZE, job, JOB_SIZE);
    num_jobs++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

void remove_job(int index) {
    pthread_mutex_lock(&lock);
    if (index >= num_jobs) {
        pthread_mutex_unlock(&lock);
        return;
    }
    memmove(jobs + index * JOB_SIZE, jobs + (index + 1) * JOB_SIZE, (num_jobs - index - 1) * JOB_SIZE);
    num_jobs--;
    free(jobs);
    jobs = realloc(jobs, num_jobs * JOB_SIZE);
    pthread_mutex_unlock(&lock);
}

void update_job(int index, job_t *job) {
    pthread_mutex_lock(&lock);
    memcpy(jobs + index * JOB_SIZE, job, JOB_SIZE);
    pthread_mutex_unlock(&lock);
}

job_t *get_job_by_status(int status) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_jobs; i++) {
        if (jobs[i].status == status) {
            pthread_mutex_unlock(&lock);
            return jobs + i;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

job_t *get_job_by_deadline(time_t deadline, time_t threshold) {
    pthread_mutex_lock(&lock);
    job_t *result = NULL;
    for (int i = 0; i < num_jobs; i++) {
        if ((jobs[i].deadline - deadline) <= threshold) {
            result = jobs + i;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return result;
}

void reorganize_jobs() {
    time_t current_time = time(NULL);
    if (current_time - last_reorg_time < 60 * 5) { // Reorganize every 5 minutes
        return;
    }
    last_reorg_time = current_time;

    pthread_mutex_lock(&lock);

    job_t *new_jobs = malloc(num_jobs * JOB_SIZE);
    int i = 0, j = 0;
    for (int k = 0; k < num_jobs; k++) {
        if (jobs[k].status == 1) { // Prioritize jobs with status 1
            memcpy(new_jobs + i++, &jobs[k], JOB_SIZE);
        } else {
            j++;
        }
    }

    free(jobs);
    jobs = new_jobs;
    num_jobs = i;

    pthread_mutex_unlock(&lock);
}

void *monitor_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        time_t current_time = time(NULL);
        if (current_time - last_reorg_time > 60 * 5) { // Reorganize every 5 minutes
            reorganize_jobs();
        }
        pthread_cond_wait(&cond, &lock);
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    pthread_t monitor;
    pthread_create(&monitor, NULL, monitor_thread, NULL);

    // Add jobs and test update/remove/get operations

    return 0;
}
