    long offset;
    int key;
} UE_INFO;

// Function to dynamically allocate memory for an array of structures
int* ueInfoArray(int size, int seed) {
    // Seed for random number generation
    srand(seed);

    // Initialize a pthread mutex for thread safety
    pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the array of UE_INFO structures
    UE_INFO* arr = (UE_INFO*)malloc(size * sizeof(UE_INFO));

    if (!arr) {
        return NULL;
    }

    // Initialize each structure in the array
    for (int i = 0; i < size; i++) {
        UE_INFO ue_info;

        // Randomly generate CRC_INDICATION_REL8_TAG and key values
        int crc_indication_rel8_tag_val = rand();
        int key_val = rand();

        while (key_val <= 0) {
            key_val = rand();
        }

        // Initialize the structure fields
        ue_info.RX_UE_INFORMATION_TAG = malloc(strlen("RX_UE_INFORMATION_TAG") + 1);
        strcpy(ue_info.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        ue_info.RNTI = i;
        ue_info.crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG)crc_indication_rel8_tag_val;
        ue_info.offset = i * sizeof(long);
        ue_info.key = key_val;

        // Store the structure in the array
        arr[i] = ue_info;
    }

    return arr;
}

// Function to free allocated memory for an array of structures
void freeUeInfoArray(int* arr, int size) {
    if (!arr) {
        return;
    }

    for (int i = 0; i < size; i++) {
        // Free each structure in the array
        UE_INFO ue_info = arr[i];
        free(ue_info.RX_UE_INFORMATION_TAG);

        // Release the mutex to avoid deadlocks
        pthread_mutex_unlock(&mtx);
    }

    // Deallocate the array itself
    free(arr);
}
