    int messageType;
    char payload[];
} NFAPI_L2_PDU_T;

NFAPI_L2_PDU_T* initializeRRCMessages(int N, const rrcMessageConfig* config) {
    if (N < 0 || config == NULL) {
        printf("Invalid input: N must be a non-negative integer and config cannot be null.\n");
        return NULL;
    }

    NFAPI_L2_PDU_T* messages = (NFAPI_L2_PDU_T*)malloc(N * sizeof(NFAPI_L2_PDU_T));

    if (messages == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        int messageType = config->type + i; // assign a unique message type to each message

        if (messageType >= config->maxPayloadSize || messageType < 0) {
            printf("Invalid message type %d. Skipping.\n", messageType);
            continue;
        }

        messages[i].messageType = messageType;

        size_t payloadSize = (size_t)(rand() % (config->maxPayloadSize - 1)) + 1; // generate a random payload size
        if (payloadSize > config->maxPayloadSize) {
            printf("Payload size %zu exceeds maximum allowed size.\n", payloadSize);
            continue;
        }

        messages[i].payload = (char*)malloc(payloadSize);

        if (messages[i].payload == NULL) {
            printf("Memory allocation for payload failed.\n");
            return NULL;
        }

        // populate the payload with random data
        for (size_t j = 0; j < payloadSize; j++) {
            messages[i].payload[j] = 'a' + rand() % 26;
        }
    }

    return messages;
}
