#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMS 100000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *elems;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

NFAPI_CRC_INDICATION_PDU_LIST_T nfa_list = {0};

void init_list() {
    pthread_mutex_init(&nfa_list.lock, NULL);
    nfa_list.elems = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfa_list.count = 0;
}

void add_elem(RNTI rnti, RX_UE_INFORMATION_TAG rx_ue_info) {
    pthread_mutex_lock(&nfa_list.lock);
    NFAPI_CRC_INDICATION_PDU_T elem;
    elem.rx_ue_info = rx_ue_info;
    elem.rnti = rnti;
    int idx = nfa_list.count++;
    while (idx < MAX_ELEMS && nfa_list.elems[idx].rnti != 0) {
        idx++;
    }
    if (idx >= MAX_ELEMS) {
        pthread_mutex_unlock(&nfa_list.lock);
        return;
    }
    memcpy(&nfa_list.elems[idx], &elem, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&nfa_list.lock);
}

void update_elem(RNTI rnti, RX_UE_INFORMATION_TAG rx_ue_info) {
    pthread_mutex_lock(&nfa_list.lock);
    for (int i = 0; i < nfa_list.count; i++) {
        if (nfa_list.elems[i].rnti == rnti) {
            memcpy(&nfa_list.elems[i], &rx_ue_info, sizeof(RX_UE_INFORMATION_TAG));
            pthread_mutex_unlock(&nfa_list.lock);
            return;
        }
    }
    pthread_mutex_unlock(&nfa_list.lock);
}

void remove_elem(RNTI rnti) {
    pthread_mutex_lock(&nfa_list.lock);
    for (int i = 0; i < nfa_list.count; i++) {
        if (nfa_list.elems[i].rnti == rnti) {
            memmove(&nfa_list.elems[i], &nfa_list.elems[i + 1], (nfa_list.count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfa_list.count--;
            pthread_mutex_unlock(&nfa_list.lock);
            return;
        }
    }
    pthread_mutex_unlock(&nfa_list.lock);
}

int get_count() {
    pthread_mutex_lock(&nfa_list.lock);
    int count = nfa_list.count;
    pthread_mutex_unlock(&nfa_list.lock);
    return count;
}
