typedef struct {
    char* key;
    void* value;
} Preference;

typedef struct {
    int size;
    Preference* preferences;
} Preferences;

Preferences* read_preferences(const char* filename);
void write_preferences(Preferences* preferences, const char* filename);
void* fetch_data_from_api(void* context);

// Initialize the cache with a default timeout
int cache_timeout = 300; // 5 minutes

// Mutex for thread-safe access to the cache and preferences file
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache to store fetched data
void** cache;

Preferences* read_preferences(const char* filename) {
    // Read existing preferences from file
    Preferences* preferences = malloc(sizeof(Preferences));
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        return NULL;
    }
    size_t fileSize = lseek(fd, 0, SEEK_END);
    void* buffer = mmap(NULL, fileSize, PROT_READ, MAP_SHARED, fd, 0);
    if (!buffer) {
        close(fd);
        free(preferences);
        return NULL;
    }
    // Deserialize and initialize preferences
    preferences->size = *(int*)buffer;
    preferences->preferences = malloc(preferences->size * sizeof(Preference));
    for (int i = 0; i < preferences->size; i++) {
        preference = (Preference*)malloc(sizeof(Preference));
        memcpy(&preference, buffer + sizeof(int), sizeof(Preference));
        // Add to the list
        preferences->preferences[i] = preference;
    }
    munmap(buffer, fileSize);
    close(fd);
    return preferences;
}

void write_preferences(Preferences* preferences, const char* filename) {
    int fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return;
    }
    // Serialize and write the preferences
    *(int*)mmap(NULL, sizeof(int), PROT_WRITE, MAP_SHARED, fd, 0) = preferences->size;
    for (int i = 0; i < preferences->size; i++) {
        preference = &preferences->preferences[i];
        memcpy(mmap(NULL, sizeof(Preference), PROT_WRITE, MAP_SHARED, fd, sizeof(int) + i * sizeof(Preference)), preference, sizeof(Preference));
    }
    munmap(mmap(NULL, sizeof(int), PROT_WRITE, MAP_SHARED, fd, 0), sizeof(int));
    munmap(mmap(NULL, sizeof(Preference), PROT_WRITE, MAP_SHARED, fd, sizeof(int)), sizeof(Preference));
    close(fd);
}

