    void* payload;
    int payload_length;
    int is_payload_valid;
} NFAPI_L2_PDU_T;

int initializeNfapiL2PduList(int N, void* buffer, void* config) {
    // Dynamic memory allocation for the PDU list
    NFAPI_L2_PDU_T* pdu_list = (NFAPI_L2_PDU_T*)malloc(N * sizeof(NFAPI_L2_PDU_T));

    if (!pdu_list) {
        return -1;  // Allocation error
    }

    for (int i = 0; i < N; i++) {
        NFAPI_L2_PDU_T* pdu = &pdu_list[i];

        // Extract message type and maximum payload size from the configuration structure
        int max_payload_size = ((struct config*)config)->max_payload_sizes[(pdu->message_type)];

        // Deserialize RRC messages from the buffer
        void* payload_data = (void*)buffer + ((struct config*)config)->payload_offsets[i];
        pdu->payload_length = ((struct config*)config)->payload_lengths[i];

        // Validate and set the payload validity flag
        if (pdu->payload_length > max_payload_size) {
            pdu->is_payload_valid = 0;  // Set invalid flag
            printf("Warning: PDU %d has an oversized payload (%d bytes), maximum allowed size is %d bytes.\n", i, pdu->payload_length, max_payload_size);
        } else {
            pdu->is_payload_valid = 1;  // Set valid flag
        }

        // Record initialization details
        printf("Initialized PDU %d: Type - %s, Payload length - %d bytes, Validity - %s.\n", i, get_message_type_name(pdu->message_type), pdu->payload_length, pdu->is_payload_valid ? "Valid" : "Invalid");
    }

    // Free the dynamically allocated memory
    free(pdu_list);

    return 0;  // Success
}
