// Process files and data
void processFilesAndData(Config* config, Callback callback, void* userData) {
    int i;
    pthread_t threads[config->numFiles];

    // Create a thread pool to process multiple files concurrently
    for (i = 0; i < config->numFiles; i++) {
        pthread_create(&threads[i], NULL, (void*)fileProcessorThread, &config->filePaths[i]);
    }

    // Wait for all threads to finish
    for (i = 0; i < config->numFiles; i++) {
        pthread_join(threads[i], NULL);
    }
}

// File processor thread
void* fileProcessorThread(void* filePath) {
    char buffer[config->bufferSize];
    FILE* file = fopen(filePath, "r");
    if (!file) {
        // Handle error opening the file
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Trim leading and trailing whitespace from the line
        callback(line, userData);
    }

    fclose(file);

    return NULL;
}

// Initialize configuration structure
Config* initConfig(int numFiles) {
    Config* config = malloc(sizeof(Config));
    config->numFiles = numFiles;
    config->bufferSize = 1024;

    // Allocate memory for file paths and buffer sizes
