    size_t num_blocks = (n + block_size - 1) / block_size;
    vector_t* vectors = (vector_t*)malloc(num_blocks * sizeof(vector_t));

    if (!vectors) {
        printf("Failed to allocate memory for vectors.\n");
        return NULL;
    }

    for (size_t i = 0; i < num_blocks; i++) {
        size_t block_start = i * block_size;
        size_t block_end = MIN(block_start + block_size, n);

        for (size_t j = block_start; j < block_end; j++) {
            vectors[j].f = sin((float)j / 10.0);
            vectors[j].i = (int)(j % 2 == 0 ? 1 : -1);
            vectors[j].d = log10(j + 1.0);
        }
    }

    return vectors;
}

size_t MIN(size_t a, size_t b) {
    return a < b ? a : b;
}
