void my_free(void* ptr) {
    free(ptr);
}

record_t* initialize_records(int initial_size, int max_value) {
    record_t* records = (record_t*)my_calloc(initial_size * sizeof(record_t));
    if (!records) return NULL;

    srand(time(NULL)); // Initialize random seed
    for (int i = 0; i < initial_size; ++i) {
        records[i].value = rand() % max_value;
    }

    int* keys = (int*)my_calloc(initial_size * sizeof(int));
    long* offsets = (long*)my_calloc(initial_size * sizeof(long));

    if (!keys || !offsets) {
        my_free(records);
        return NULL; // Fail and return error
    }

    // Initialize offset and key arrays with random values
    for (int i = 0; i < initial_size; ++i) {
        offsets[i] = rand() % 10000000;
        keys[i] = rand() % 1000;
    }

    return records;
}

void finalize_records(record_t* records, int size, my_free free_func) {
    for (int i = 0; i < size; ++i) {
        free_func(&records[i]);
    }
    free_func(records);
}
