void processFilesAdvanced(Configuration config) {
    // Allocate memory for the buffer and line array
    uint8_t* buffer = malloc(config.bufferSize);
    char** lines = (char**)malloc(config.maxLinesToProcess * sizeof(char*));

    FILE* file = fopen(config.filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", config.filePath);
        return;
    }

    // Trim and store each line in the buffer
    int i = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int lineSize = strlen(line) - 1; // Remove trailing newline
        if (lineSize > config.bufferSize) {
            printf("Line exceeds maximum buffer size: %s\n", line);
            continue;
        }
        memcpy(buffer + i * config.bufferSize, line, lineSize);
        i++;
    }

    fclose(file);

    // Process each line by invoking the callback function
    for (int j = 0; j < i; j++) {
        int keyCount = processLineCallback(buffer + j * config.bufferSize);
        if (keyCount < 0) {
            fprintf(stderr, "Error processing line: %s\n", buffer + j * config.bufferSize);
        } else {
            // Update the hash map and store the processed data
            uint8_t key;
            for (int k = 0; k < keyCount; k++) {
                if (getProcessedData(key) < 0) {
                    fprintf(stderr, "Error updating hash map: %s\n", buffer + j * config.bufferSize);
                }
            }
        }
    }

    // Output the number of unique keys encountered and their counts
    printf("Unique keys: %d\n", getUniqueKeyCount());
    printf("Total occurrences: %d\n", getTotalOccurrences());

    // Generate a summary report for the top N most frequent keys
    printf("Top N most frequent keys:\n");
    for (int j = 0; j < config.topNKeys; j++) {
        printf("%s: %d\n", getMostFrequentKey(j), getMostFrequentCount(j));
    }

    // Flush the buffer to disk periodically
    if (bufferSize > flushThreshold) {
        flushBuffer();
    }

    // Monitor system resources and adjust dynamically
    int memoryUsage = getMemoryUsage();
    if (memoryUsage > 80) {
        printf("Adjusting buffer size due to high memory usage: %d\n", memoryUsage);
        config.bufferSize /= 2;
    } else if (memoryUsage < 20) {
        printf("Increasing buffer size for efficient processing: %d\n", memoryUsage);
        config.bufferSize *= 2;
    }

    // Coordinate file processing across threads
    pthread_mutex_lock(&fileProcessingMutex);
    pthread_cond_signal(&fileProcessingCondition);
    pthread_mutex_unlock(&fileProcessingMutex);
}

int processLineCallback(uint8_t* line) {
    // Parse the line into key-value pairs and store them in a hash map
    int keyCount = 0;
    char key[16];
    while (sscanf(line, "%s", key) == 1) {
        int value = getKeyValue(key);
        if (value < 0) {
            return -1; // Error processing line
        }
        processKey(key, value);
        keyCount++;
    }
    return keyCount;
}

int main() {
    Configuration config;
    config.filePath = "example.txt";
    config.bufferSize = 1024;
    config.maxLinesToProcess = 1000;
    config.flushThreshold = 0.8;
    config.topNKeys = 10;

    processFilesAdvanced(config);
    return 0;
}
