    scriptTag.id = `script-${script.uniqueId}`;
    scriptTag.type = script.type;
    scriptTag.dangerouslySetInnerHTML = script.code;
    try {
      if (script.type === 'module') {
        // Handle module scripts
      } else if (script.type === 'text/javascript') {
        // Handle JavaScript scripts
      }
    } catch (error) {
      console.error(`Error processing script ${script.uniqueId}:`, error);
    }
    footer.appendChild(scriptTag);
  });
  document.body.appendChild(footer);

  const dnsResolutionPool = [];
  let maxConcurrency = 5; // adjust according to your needs
  let retryDelay = 1000;
  let timeout = 5000;

  async function resolveDns(hostname) {
    try {
      const { ip } = await dnsQuery(hostname);
      return ip;
    } catch (error) {
      if (error.name === 'TimeoutError') {
        await new Promise(resolve => setTimeout(resolve, retryDelay));
        return resolveDns(hostname);
      }
      throw error;
    }
  }

  async function dnsQuery(hostname) {
    const request = { hostname };
    const response = await dnsPool.getAvailableConnection().then(connection => {
      try {
        connection.resolve(hostname, (error, address) => {
          if (error) {
            dnsPool.returnConnection(connection);
            throw error;
          }
          dnsPool.returnConnection(connection);
          return address;
        });
      } catch (error) {
        throw error;
      }
    });
    return response;
  }

  async function resolveHostnames() {
    const resolved = [];
    for await (const hostname of hostnames) {
      try {
        const ip = await resolveDns(hostname);
        resolved.push({ hostname, ip });
      } catch (error) {
        console.error(`Error resolving DNS for ${hostname}:`, error);
      }
    }
    return resolved;
  }

  async function main() {
    const resolvedHostnames = await resolveHostnames();
    // Process the resolved hostnames here
    return 'OK';
  }

  main().then(status => {
    if (status === 'OK') {
      console.log('DNS resolution successful');
    } else {
      console.error(`DNS resolution failed: ${status}`);
    }
  });
}

class DnsPool {
  connections = [];
  availableConnections = [];

  async getAvailableConnection() {
    const connection = this.availableConnections.shift();
    if (connection) {
      return connection;
    }
    await new Promise(resolve => setTimeout(resolve, 100));
    return this.getAvailableConnection();
  }

  returnConnection(connection) {
    this.connections.push(connection);
    this.availableConnections.unshift(connection);
  }
}

// Initialize the DNS pool
const dnsPool = new DnsPool();

// Example usage:
const scripts = [
  { uniqueId: 'script-1', type: 'module', code: 'console.log("Hello World!");' },
  { uniqueId: 'script-2', type: 'text/javascript', code: 'alert("Goodbye!");' }
];

const hostnames = ['example.com', 'www.example.io'];

renderFooterWithDnsIntegration(scripts, hostnames);
