void* allocate_vectors(size_t num_vectors) {
    // Pre-allocate memory in chunks to minimize fragmentation
    size_t chunk_size = 32; // adjust this value based on your system's cache size and memory requirements
    void* vectors = NULL;
    for (size_t i = 0; i < num_vectors; i += chunk_size) {
        size_t current_chunk_size = (i + chunk_size > num_vectors) ? (num_vectors - i) : chunk_size;
        void* current_chunk = malloc(current_chunk_size * sizeof(vector));
        if (!vectors) vectors = current_chunk;
        else {
            void* previous_chunk = vectors;
            vectors = ((vector*)previous_chunk) + (i / chunk_size);
            memcpy(vectors, current_chunk, current_chunk_size * sizeof(vector));
            free(current_chunk);
        }
    }

    // Initialize the vector elements
    for (size_t i = 0; i < num_vectors; i++) {
        vector* vec = &((vector*)vectors)[i];
        float f = sin((float)i) + cos((float)(i * 3.14));
        int y = (int)f;
        double z = log2(i);
        vec->x = f;
        vec->y = y;
        vec->z = z;
    }

    return vectors;
}

int main() {
    size_t num_vectors = 1000; // adjust this value based on your use case
    void* vectors = allocate_vectors(num_vectors);

    // Use the allocated memory...

    free(vectors);
    return 0;
}
