void serializeEntities(const Entity** entities, FILE* file) {
    int numEntities = 0;
    for (int i = 0; i < GROWTH_FACTOR && entities[i] != NULL; i++) {
        numEntities++;
    }

    fwrite(&numEntities, sizeof(int), 1, file);
    fwrite(&GROWTH_FACTOR, sizeof(double), 1, file);

    for (int i = 0; i < numEntities; i++) {
        fwrite(entities[i]->name, strlen(entities[i]->name) + 1, 1, file);
        fwrite(&entities[i]->id, sizeof(unsigned int), 1, file);
        fwrite(&entities[i]->status, sizeof(EntityStatus), 1, file);
    }
}

Entity* deserializeEntities(FILE* file) {
    Entity* entities = NULL;
    int numEntities = 0;
    double growthFactor;

    fread(&numEntities, sizeof(int), 1, file);
    fread(&growthFactor, sizeof(double), 1, file);

    for (int i = 0; i < numEntities; i++) {
        Entity* entity = malloc(sizeof(Entity));
        entities = realloc(entities, (i + 1) * sizeof(Entity));
        entities[i] = entity;

        fread(entity->name, strlen(predefinedNames[0]) + 1, 1, file);
        fread(&entity->id, sizeof(unsigned int), 1, file);
