    if (!records) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].value = rand() % RANDOM_MAX;
        int str_length = rand() % CHAR_STRING_LENGTH + 1;
        char *str = (char *)malloc((str_length + 1) * sizeof(char));
        if (!str) {
            free(records);
            return NULL;
        }
        for (int j = 0; j < str_length; j++) {
            str[j] = (char)(rand() % 2 ? 'a' : 'A') + (rand() % 26);
        }
        str[str_length] = '\0';
        records[i].str = str;
    }

    return records;
}

void log_records(Record *records, int count) {
    FILE *log_file = fopen("record_log.txt", "a");
    if (!log_file) {
        // Handle logging error
        return;
    }

    for (int i = 0; i < count; i++) {
        fprintf(log_file, "%d: %s\n", records[i].value, records[i].str);
        fflush(log_file);

        // Check the logging threshold
        if (++log_file->tellp > MAX_LOGGING_RECORDS * sizeof(int) + LOGGING_THRESHOLD) {
            fclose(log_file);
            return;
        }
    }

    fclose(log_file);
}

void free_records(Record *records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].str);
    }
    free(records);
