typedef struct {
    long timestamp;
    int transaction_id;
    double transaction_amount;
} Transaction;

typedef struct {
    Transaction *transactions;
    int size;
    int capacity;
    int *frequency_count;
    int frequency_count_size;
} TransactionCollection;

TransactionCollection* create_transaction_collection() {
    TransactionCollection *collection = (TransactionCollection*)malloc(sizeof(TransactionCollection));
    if (!collection) {
        return NULL; // Memory allocation failed
    }

    collection->transactions = NULL;
    collection->size = 0;
    collection->capacity = 2;

    collection->frequency_count = (int*)calloc(collection->capacity, sizeof(int));
    if (!collection->frequency_count) {
        free(collection);
        return NULL; // Memory allocation failed
    }

    collection->frequency_count_size = collection->capacity;

    return collection;
}

void add_transaction(TransactionCollection *collection, Transaction transaction) {
    if (collection->size >= collection->capacity) {
        collection->capacity *= 2;
        int *new_frequency_count = (int*)realloc(collection->frequency_count, collection->capacity * sizeof(int));
        if (!new_frequency_count) {
            printf("Error: Memory allocation failed\n");
            return; // Memory allocation failed
        }
        collection->frequency_count = new_frequency_count;
    }

    Transaction *new_transactions = (Transaction*)realloc(collection->transactions, (collection->size + 1) * sizeof(Transaction));
    if (!new_transactions) {
        printf("Error: Memory allocation failed\n");
        return; // Memory allocation failed
    }
    collection->transactions = new_transactions;

    collection->transactions[collection->size] = transaction;
    if (!transaction.transaction_id) {
        transaction.transaction_id = collection->size + 1;
    }

    int idx = transaction.transaction_id % (collection->capacity / 2);
    Transaction *bucket = &collection->transactions[idx];
    while(bucket->timestamp){
        bucket++;
    }
    *(bucket - 1) = transaction;

    if (transaction.transaction_id >= collection->frequency_count_size) {
        int *new_frequency_count = (int*)realloc(collection->frequency_count, (transaction.transaction_id + 1) * sizeof(int));
        if (!new_frequency_count) {
            printf("Error: Memory allocation failed\n");
            return; // Memory allocation failed
        }
        collection->frequency_count = new_frequency_count;
        collection->frequency_count_size = transaction.transaction_id + 1;
    }

    if (transaction.transaction_id >= collection->size) {
        int *new_frequency_count = (int*)realloc(collection->frequency_count, (collection->size + 1) * sizeof(int));
        if (!new_frequency_count) {
            printf("Error: Memory allocation failed\n");
            return; // Memory allocation failed
        }
        collection->frequency_count = new_frequency_count;
    }

    collection->transactions[collection->size].transaction_id++;
    transaction.transaction_id++;
    (collection->transactions[collection->size].transaction_amount)++;
    if (!transaction.transaction_id) {
        transaction.transaction_id = collection->size + 1;
    }
    if (transaction.transaction_id >= collection->frequency_count_size) {
        int *new_frequency_count = (int*)realloc(collection->frequency_count, (transaction.transaction_id + 1) * sizeof(int));
        if (!new_frequency_count) {
            printf("Error: Memory allocation failed\n");
            return; // Memory allocation failed
        }
        collection->frequency_count = new_frequency_count;
        collection->frequency_count_size = transaction.transaction_id + 1;
    }

    (collection->size)++;
}

void remove_transaction(TransactionCollection *collection, Transaction transaction) {
    if (transaction.transaction_id >= collection->size) return; // Transaction ID not found

    int idx = transaction.transaction_id % (collection->capacity / 2);
    Transaction *bucket = &collection->transactions[idx];
    while(bucket->timestamp){
        bucket++;
    }
    *(bucket - 1) = transaction;


    if (transaction.transaction_id < collection->size) {
        memmove(&collection->transactions[transaction.transaction_id], &collection->transactions[transaction.transaction_id + 1], (collection->size - transaction.transaction_id - 1) * sizeof(Transaction));
    }

    for(int i = 0; i <= transaction.transaction_id; i++){
        collection->frequency_count[i]--;
        if(collection->frequency_count[i] == 0){
            int *new_frequency_count = (int*)realloc(collection->frequency_count, (collection->size - 1) * sizeof(int));
            if (!new_frequency_count) {
                printf("Error: Memory allocation failed\n");
                return; // Memory allocation failed
            }
            collection->frequency_count = new_frequency_count;
        }
    }

    for(int i = transaction.transaction_id; i < collection->size; i++){
        (collection->transactions[i].transaction_id]--;
        (collection->transactions[i].transaction_amount)--;

        if(!collection->transactions[i].transaction_id){
            memmove(&collection->transactions[i], &collection->transactions[i + 1], (collection->size - i - 1) * sizeof(Transaction));
        }
    }

    for(int i = transaction.transaction_id; i < collection->size; i++){
        if(!collection->transactions[i].transaction_id){
            memmove(&collection->transactions[i], &collection->transactions[i + 1], (collection->size - i - 1) * sizeof(Transaction));
            break;
        }
    }

    (collection->size)--;

    free(collection->frequency_count);
    collection->frequency_count = NULL;
    int *new_frequency_count = (int*)calloc(10, sizeof(int));
    if (!new_frequency_count) {
        printf("Error: Memory allocation failed\n");
        return; // Memory allocation failed
    }
    collection->frequency_count = new_frequency_count;
    collection->frequency_count_size = 10;

}

void update_transaction(TransactionCollection *collection, Transaction transaction) {
    int idx = transaction.transaction_id % (collection->capacity / 2);
    Transaction *bucket = &collection->transactions[idx];
    while(bucket->timestamp){
        bucket++;
    }
    *(bucket - 1) = transaction;

    if(transaction.transaction_amount > collection->transactions[transaction.transaction_id].transaction_amount){
        for(int i = transaction.transaction_id; i < collection->size; i++){
            (collection->transactions[i].transaction_id)++;
            (collection->transactions[i].transaction_amount)++;
        }

        for(int i = 0; i <= transaction.transaction_id; i++){
            collection->frequency_count[i]++;
        }
    }else if(transaction.transaction_amount < collection->transactions[transaction.transaction_id].transaction_amount){
        for(int i = transaction.transaction_id; i < collection->size; i++){
            (collection->transactions[i].transaction_id)++;
            (collection->transactions[i].transaction_amount)--;
        }

        for(int i = 0; i <= transaction.transaction_id; i++){
            if(collection->frequency_count[i] > 1){
                collection->frequency_count[i]--;
            }else{
                for(int j = i; j < collection->size; j++){
                    (collection->transactions[j].transaction_id)++;
                    (collection->transactions[j].transaction_amount)--;
                }
            }
        }
    }
}

void free_transaction_collection(TransactionCollection *collection) {
    if (!collection) return;

    if (collection->frequency_count) free(collection->frequency_count);
    free(collection->transactions);
    free(collection);
}
