void gc(void) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i] == NULL || connections[i]->connectionState != ConnectionState_Disconnected) continue;
        free(connections[i]);
        connections[i] = NULL;
    }
    maxActiveConnectionsCount = activeConnectionsCount;
    pthread_mutex_unlock(&mutex);
}

void updateConnection(int index, NetworkConnectionStatus* connection) {
    if (index < 0 || index >= MAX_CONNECTIONS) return;
    connections[index] = connection;
    if (connection->connectionState == ConnectionState_Connected)
