typedef enum {
    CONNECTED,
    DISCONNECTED,
} ConnectionState;

typedef struct {
    char *ipAddress;
    int portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

NetworkConnectionStatus* connections = NULL;
int connectionCount = 0;
int timeout = 30; // seconds
int maxInactiveTime = 300; // seconds

// Function to initialize the dynamic array of connections
void initConnections() {
    connections = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
}

// Function to add a new connection to the array
void addConnection(char* ipAddress, int portNumber) {
    // Allocate memory for the new connection structure
    NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));

    // Initialize the new connection with the given details
    newConnection->ipAddress = (char*)malloc(strlen(ipAddress) + 1);
    strcpy(newConnection->ipAddress, ipAddress);
    newConnection->portNumber = portNumber;
    newConnection->connectionState = CONNECTED;

    // Add the new connection to the array and increment the count
    connections = realloc(connections, (connectionCount + 1) * sizeof(NetworkConnectionStatus));
    connections[connectionCount].ipAddress = newConnection->ipAddress;
    connections[connectionCount].portNumber = newConnection->portNumber;
    connections[connectionCount++].connectionState = newConnection->connectionState;

    free(newConnection);
}

// Function to update an existing connection
void updateConnection(int id, char* ipAddress, int portNumber) {
    // Find the connection with the given ID and update its details
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i].portNumber == portNumber && strcmp(connections[i].ipAddress, ipAddress) == 0) {
            connections[i].ipAddress = (char*)malloc(strlen(ipAddress) + 1);
            strcpy(connections[i].ipAddress, ipAddress);
            connections[i].portNumber = portNumber;
            break;
        }
    }
}

// Function to delete a connection
void deleteConnection(int id) {
    // Find the connection with the given ID and remove it from the array
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i].portNumber == id) {
            connections[i] = connections[connectionCount - 1];
            connectionCount--;
            break;
        }
    }
}

// Function to list active connections
void listActiveConnections() {
    // Iterate through the array and print the details of all currently active connections
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i].connectionState == CONNECTED) {
            printf("IP Address: %s, Port Number: %d\n", connections[i].ipAddress, connections[i].portNumber);
        }
    }
}

// Function to serialize the array of connections to a file
void serializeConnections() {
    // Write the connection details to a file in JSON format
    FILE* file = fopen("connections.json", "w");
    if (file) {
        for (int i = 0; i < connectionCount; i++) {
            fprintf(file, "{\"ipAddress\":\"%s\",\"portNumber\":%d,\"connectionState\":\"%s\"}\n",
                connections[i].ipAddress, connections[i].portNumber,
                connections[i].connectionState == CONNECTED ? "CONNECTED" : "DISCONNECTED");
        }
        fclose(file);
    }
}

// Function to deserialize the array of connections from a file
void deserializeConnections() {
    // Read the connection details from a file in JSON format
    FILE* file = fopen("connections.json", "r");
    if (file) {
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), file)) {
            NetworkConnectionStatus* newConnection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));

            // Parse the connection details from the JSON string
            int portNumber;
            char *ipAddress;
            ConnectionState connectionState;

            // Code to parse the JSON string goes here

            // Add the new connection to the array and increment the count
            connections = realloc(connections, (connectionCount + 1) * sizeof(NetworkConnectionStatus));
            connections[connectionCount].ipAddress = ipAddress;
            connections[connectionCount].portNumber = portNumber;
            connections[connectionCount++].connectionState = connectionState;

            free(newConnection);
        }
        fclose(file);
    }
}

// Function to periodically clean up inactive connections
void cleanupConnections() {
    // Iterate through the array and remove any inactive connections
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i].connectionState == DISCONNECTED && time() - connections[i].lastCommunicationTimestamp > maxInactiveTime) {
            connections[i] = connections[connectionCount - 1];
            connectionCount--;
            break;
        }
