#include <iostream>
#include <map>
#include <thread>
#include <mutex>
#include <chrono>

class Session {
public:
    int userId;
    std::time_t lastActivityTime;
    std::time_t expirationTime;
    std::map<std::string, std::string> requestParams;

    Session(int userId) : userId(userId), lastActivityTime(std::time(nullptr)), expirationTime(std::time(nullptr)) {}
};

class SessionManager {
private:
    std::mutex mtx;
    std::map<int, Session*> sessions;
    std::map<int, std::chrono::steady_clock::time_point> sessionExpirationTimes;

public:
    void createSession(int userId) {
        std::lock_guard<std::mutex> lock(mtx);
        Session* newSession = new Session(userId);
        sessions[userId] = newSession;
        sessionExpirationTimes[userId] = std::chrono::steady_clock::now() + std::chrono::seconds(3600); // 1 hour expiration
    }

    void updateSession(int userId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (sessions.find(userId) != sessions.end()) {
            Session* session = sessions[userId];
            session->lastActivityTime = std::time(nullptr);
            sessionExpirationTimes[userId] = std::chrono::steady_clock::now() + std::chrono::seconds(3600); // 1 hour expiration
        }
    }

    void deleteSession(int userId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (sessions.find(userId) != sessions.end()) {
            Session* session = sessions[userId];
            delete session;
            sessions.erase(userId);
            sessionExpirationTimes.erase(userId);
        }
    }

    void cleanupExpiredSessions() {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        for (auto it = sessions.begin(); it != sessions.end();) {
            if (it->second->expirationTime < now) {
                delete it->second;
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    void cleanupDormantSessions() {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        for (auto& pair : sessions) {
            if ((pair.second->expirationTime - now).count() > 30000) { // 30 minutes dormancy
                delete pair.second;
                sessions.erase(pair.first);
                break;
            }
        }
    }

    void logCleanupProcess() {
        std::cout << "Cleaned up expired and dormant sessions. Memory usage: " << (getMemoryUsage() / 1024) << " KB." << std::endl;
    }

    double getMemoryUsage() {
        return static_cast<double>(std::distance(&sessions.begin()->first, &sessions.end())) * sizeof(int);
    }
};

int main() {
    SessionManager manager;

    // Create sessions
    manager.createSession(1);
    manager.createSession(2);

    // Update and delete sessions
    manager.updateSession(1);
    manager.deleteSession(2);

    // Cleanup expired and dormant sessions
    while (true) {
        manager.cleanupExpiredSessions();
        manager.cleanupDormantSessions();
        std::this_thread::sleep_for(std::chrono::seconds(10));
    }

    return 0;
}
