typedef struct {
    int offset;
    char key[256];
    int value;
} Record;

Record* processRecords(int numRecords, int minOffset, int maxOffset, int minValue, int maxValue) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) return NULL;

    int largestInt = 0;
    for (int i = 0; i < numRecords; i++) {
        scanf("%d %s %d", &records[i].offset, records[i].key, &records[i].value);
        largestInt = records[i].offset > largestInt ? records[i].offset : largestInt;

        if (records[i].offset < minOffset || records[i].offset > maxOffset) {
            free(records);
            return NULL;
        }

        if (records[i].value < minValue || records[i].value > maxValue) {
            free(records);
            return NULL;
        }
    }

    Record* sortedRecords = (Record*)malloc(numRecords * sizeof(Record));
    if (!sortedRecords) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        sortedRecords[i] = records[i];
    }

    for (int i = 1; i < numRecords; i++) {
        Record temp = sortedRecords[i];
        int j = i - 1;
        while (j >= 0 && temp.offset > sortedRecords[j].offset) {
            sortedRecords[j + 1] = sortedRecords[j];
            j--;
        }
        sortedRecords[j + 1] = temp;
    }

    free(records);
    return sortedRecords;
}
