// Function to manage dynamic array of user sessions
void manageUserSessions(int numSessions, int timeout) {
    // Dynamically allocate memory for user sessions array
    UserSession** sessions = (UserSession**)malloc(numSessions * sizeof(UserSession*));

    // Initialize the last active time for each session
    time_t lastActiveTime[numSessions];

    // Initialize the number of active sessions
    int numActiveSessions = 0;

    // Main loop to manage user sessions
    for (int i = 0; i < numSessions; i++) {
        UserSession* session = &sessions[i];

        // Initialize the session state and last active time
        session->SessionState = NEW;
        lastActiveTime[i] = time(NULL);

        // Main loop to manage records in each session
        for (int j = 0; j < numSessions; j++) {
            Record* record = &record[j];

            // Dynamically allocate memory for strings and initialize records
            record->String = malloc(MAX_STRING_LENGTH * sizeof(char));
            record->Value = (double)i;
            record->Index = j;
        }

        // Main loop to handle session updates
        while (1) {
            int userID, sessionID;

            // Handle user input for new sessions
            if (scanf("%d %s", &userID, sessionID) == 2) {
                UserSession* newSession = &sessions[userID];

                // Check if the session is active and update last active time
                if (newSession->SessionState != INACTIVE) {
                    newSession->lastActiveTime = time(NULL);
                }
            } else {
                break;
            }
        }
    }

    // Main loop to handle timeout mechanism
    while (1) {
        int i;

        // Check for inactive sessions and terminate them if necessary
        for (i = 0; i < numSessions; i++) {
            if (time(NULL) - lastActiveTime[i] > timeout) {
                free(sessions[i]->SessionID);
                sessions[i]->SessionState = INACTIVE;
            }
        }

        // Check for active sessions and update last active time
        for (i = 0; i < numSessions; i++) {
            if (sessions[i]->SessionState == ACTIVE) {
                sessions[i]->lastActiveTime = time(NULL);
            }
        }
    }
}

// Function to fill strings with random alphanumeric characters
void fillStrings(char* str, int maxLength) {
    // Initialize the string with spaces
    for (int i = 0; i < maxLength; i++) {
        str[i] = ' ';
    }

    // Fill the string with random alphanumeric characters
    for (int i = 0; i < maxLength; i++) {
        char c;

        do {
            c = rand() % 52 + 65; // ASCII value of uppercase letters
        } while (!isalnum((unsigned char)c));

        str[i] = c;
    }
}

