    // Dynamically allocate memory for records array
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));

    // Initialize the records with default values
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];

        // Fill strings with random alphanumeric characters
        fillStrings(record->String, maxLength);

        // Initialize records with default values
        record->Value = (double)i;
        record->Index = i;
