// Define the task structure
typedef struct {
    int id;
    enum { PENDING, IN_PROGRESS, COMPLETED } status;
    struct {
        union {
            int result_int;
            double result_float;
        } result;
    } data;
} Task;

// Function to dynamically allocate memory for an array of 'task' structures
Task* allocateTasks(int num_tasks) {
    // Initialize the random seed
    srand(time(NULL));

    // Allocate memory for the task array
    Task* tasks = (Task*)malloc(num_tasks * sizeof(Task));

    if (!tasks) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each task's status and data
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].id = i + 1;
        tasks[i].status = PENDING;

        // Generate random values for the 'data' structure
        if (rand() % 2) { // 50% chance of integer value
            tasks[i].data.result.result_int = rand();
        } else {
            tasks[i].data.result.result_float = (double)rand() / RAND_MAX;
        }
    }

    return tasks;
}

// Function to deallocate the task array memory
void freeTasks(Task* tasks, int num_tasks) {
    if (!tasks)
        return;

    free(tasks);
}

int main() {
    // Initialize the random seed
    srand(time(NULL));

    // Allocate a maximum of 10 tasks
    Task* tasks = allocateTasks(10);

    if (tasks) {
        // Process the allocated tasks...
        for (int i = 0; i < 10; i++) {
            printf("Task %d: status - %s, data - %.2f\n", 
                   tasks[i].id, get_status_string(tasks[i].status), 
