// Function to initialize and manage a dynamic array of ServiceInstances
ServiceInstanceManager* serviceInstanceManager_init(size_t initialCapacity) {
    ServiceInstanceManager* manager = (ServiceInstanceManager*)malloc(sizeof(ServiceInstanceManager));
    manager->instances = (ServiceInstance*)calloc(initialCapacity, sizeof(ServiceInstance));
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);
    return manager;
}

// Function to add a new ServiceInstance
void serviceInstanceManager_add(ServiceInstanceManager* manager, char* ipAddress, int portNumber) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        // Reallocate memory when the array reaches capacity threshold
        size_t newCapacity = manager->capacity * 2;
        ServiceInstance* newInstances = (ServiceInstance*)realloc(manager->instances, newCapacity * sizeof(ServiceInstance));
        manager->instances = newInstances;
        manager->capacity = newCapacity;
    }
    ServiceInstance instance = { ipAddress, portNumber, UNKNOWN };
    // Validate the IP address and Port number using an external service health monitoring API
    // ...
    // Add the validated instance to the array
    manager->instances[manager->count] = instance;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

// Function to update the health status of a ServiceInstance
void serviceInstanceManager_updateHealthStatus(ServiceInstanceManager* manager, char* ipAddress, int portNumber, enum { HEALTHY, UNHEALTHY, UNKNOWN } healthStatus) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (!strcmp(manager->instances[i].ipAddress, ipAddress) && manager->instances[i].portNumber == portNumber) {
            manager->instances[i].healthStatus = healthStatus;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve the number of healthy instances
size_t serviceInstanceManager_getHealthyCount(ServiceInstanceManager* manager) {
    size_t count = 0;
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->instances[i].healthStatus == HEALTHY) {
            count++;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return count;
}

// Function to provide a summary report of all instances sorted by their health status
void serviceInstanceManager_getSummaryReport(ServiceInstanceManager* manager) {
    // Sort the array based on instance health status
    qsort(manager->instances, manager->count, sizeof(ServiceInstance), (int (*)(const void*, const void*))serviceInstanceManager_healthStatusComparator);
    // Print the report
    printf("Summary Report:\n");
    for (size_t i = 0; i < manager->count; i++) {
        printf("Instance %s:%d - Health Status: %s\n", manager->instances[i].ipAddress, manager->instances[i].portNumber,
               healthStatusToString(manager->instances[i].healthStatus));
    }
}

// Custom comparator function for sorting instances by their health status
int serviceInstanceManager_healthStatusComparator(const void* a, const void* b) {
    ServiceInstance* instanceA = (ServiceInstance*)a;
    ServiceInstance* instanceB = (ServiceInstance*)b;
    if (instanceA->healthStatus == HEALTHY && instanceB->healthStatus == UNHEALTHY)
        return -1;
    else if (instanceA->healthStatus == UNHEALTHY && instanceB->healthStatus == HEALTHY)
        return 1;
    else
        return 0;
}

// Function to convert the health status enum to a human-readable string
char* serviceInstanceManager_healthStatusToString(enum { HEALTHY, UNHEALTHY, UNKNOWN } healthStatus) {
    switch (healthStatus) {
        case HEALTHY:
            return "Healthy";
        case UNHEALTHY:
            return "Unhealthy";
        default:
            return "Unknown";
    }
}

// Helper function to free memory allocated for the ServiceInstanceManager
void serviceInstanceManager_free(ServiceInstanceManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        pthread_cond_destroy(&manager->cond);
        free(manager->instances);
        free(manager);
    }
}
