// Custom memory pool allocator struct
typedef struct {
    void** blocks;
    int capacity;
    sem_t* semaphore;
} MemoryPool;

// Linked list node structure
typedef struct Node {
    double value;
    char buffer[64];
    struct Node* next;
} Node;

// Initialize the linked list with a custom memory pool allocator
Node* initializeLinkedList(int sizeLimit) {
    // Create a fixed-size block list for tracking available memory blocks
    MemoryPool* memoryPool = (MemoryPool*)malloc(sizeof(MemoryPool));
    memoryPool->blocks = (void**)calloc(sizeLimit, sizeof(void*));
    memoryPool->capacity = sizeLimit;
    sem_init(&memoryPool->semaphore, 0, sizeLimit);

    // Initialize the linked list
    Node* head = NULL;
    int activeNodes = 0;

    return head;
}

// Custom hash function for floating-point numbers
unsigned long hashFunction(double value) {
    unsigned long result = (unsigned long)(value * 1000003);
    return result;
}

// Allocate a new node using the custom memory pool allocator
Node* allocateNode(MemoryPool* memoryPool, double value) {
    // Acquire the semaphore to ensure thread-safe access
    sem_wait(&memoryPool->semaphore);

    // Find an available block in the memory pool
    int i;
    for (i = 0; i < memoryPool->capacity; i++) {
        if (!memoryPool->blocks[i]) {
            break;
        }
    }

    // If no available blocks are found, allocate a new one
    if (i == memoryPool->capacity) {
        void* block = malloc(1024);
        memoryPool->blocks[i] = block;
    }

    // Initialize the node using the allocated block
    Node* node = (Node*)memoryPool->blocks[i];
    node->value = value;

    // Release the semaphore to allow other threads to access the linked list
    sem_post(&memoryPool->semaphore);

    return node;
}

// Free a node and release its memory back to the custom allocator
void freeNode(Node* node, MemoryPool* memoryPool) {
    // Acquire the semaphore to ensure thread-safe access
    sem_wait(&memoryPool->semaphore);

    // Mark the block as available in the memory pool
    memoryPool->blocks[node - head] = NULL;

    // Release the semaphore to allow other threads to access the linked list
    sem_post(&memoryPool->semaphore);
}

// Function to check if the linked list has exceeded its size limit
int isLinkedListSizeExceeded(Node* head, int sizeLimit) {
    int activeNodes = 0;
    Node* current = head;
    while (current != NULL) {
        activeNodes++;
        current = current->next;
    }
    return activeNodes >= sizeLimit;
}

// Function to monitor the number of active nodes in the linked list
void monitorActiveNodes(Node* head, MemoryPool* memoryPool) {
    int activeNodes = 0;
    Node* current = head;
    while (current != NULL) {
        activeNodes++;
        current = current->next;
    }
}

// Main function to demonstrate the usage of the custom linked list
int main() {
    // Initialize the linked list with a size limit of 100 nodes
    Node* head = initializeLinkedList(100);

    // Allocate and insert nodes into the linked list
    for (int i = 0; i < 50; i++) {
        double value = i * 3.14;
        Node* node = allocateNode(&memoryPool, value);
        // Insert the node at the beginning of the linked list
        node->next = head;
        head = node;
    }

    // Monitor the number of active nodes in the linked list
    monitorActiveNodes(head, &memoryPool);

    return 0;
}

