```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_POOL_SIZE 10000
#define MIN_SERVER_ID 1
#define MAX_SERVER_ID 0xFFFE
#define LATENCY_THRESHOLD 150
#define ERROR_RATE_THRESHOLD 2
#define LOG_BUFFER_SIZE 1024

typedef struct {
    uint16_t client_id;
    uint16_t server_id;
    int connection_status_flags;
} TCP_CONNECTION;

TCP_CONNECTION *tcp_connections = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t new_connection_available = PTHREAD_COND_INITIALIZER;
int current_pool_size = 0;
uint16_t last_server_id = MIN_SERVER_ID - 1;
int latency_metric = 0;
float error_rate_metric = 0.0;

void *allocate_new_structure() {
    TCP_CONNECTION *new_conn = (TCP_CONNECTION *)malloc(sizeof(TCP_CONNECTION));
    if (!new_conn) {
        return NULL;
    }
    new_conn->client_id = 0;
    new_conn->server_id = last_server_id + 1;
    new_conn->connection_status_flags = 0;
    last_server_id++;
    current_pool_size++;
    pthread_mutex_unlock(&pool_lock);
    pthread_cond_signal(&new_connection_available);
    return (void *)new_conn;
}

int deallocate_structure(TCP_CONNECTION *conn) {
    if (!conn || current_pool_size <= 0) {
        return -1;
    }
    free(conn);
    current_pool_size--;
    return 0;
}

