#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    int size;
    point **data;
} hash_table;

hash_table* create_hash_table(int initial_size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->size = initial_size;
    table->data = (point**)malloc(table->size * sizeof(point*));
    for (int i = 0; i < table->size; i++) {
        table->data[i] = NULL;
    }
    return table;
}

void insert_point(hash_table* table, int x, point p) {
    int index = x % table->size;
    while (table->data[index]) {
        if (table->data[index]->x == x) {
            // Update existing point
            free(table->data[index]);
            table->data[index] = &p;
            return;
        }
        index = (index + 1) % table->size;
    }
    table->data[index] = &p;
}

point* get_point(hash_table* table, int x) {
    int index = x % table->size;
    while (table->data[index]) {
        if (table->data[index]->x == x) {
            return table->data[index];
        }
        index = (index + 1) % table->size;
    }
    return NULL; // Not found
}

void resize_hash_table(hash_table* table, int new_size) {
    hash_table* new_table = create_hash_table(new_size);
    for (int i = 0; i < table->size; i++) {
        point* p = table->data[i];
        while (p) {
            int index = p->x % new_table->size;
            if (!new_table->data[index]) {
                new_table->data[index] = p;
            } else {
                int j = index + 1;
                while (j != index && !new_table->data[j]) {
                    j = (j + 1) % new_table->size;
                }
                if (j == index) {
                    // Collision resolved, insert at next available slot
                    j = (j + 1) % new_table->size;
                }
                new_table->data[index] = p;
            }
            p = p->next;
        }
    }
    free(table);
    table = new_table;
}

int main() {
    // Example usage:
    hash_table* table = create_hash_table(16);
    point p1 = {0, 10};
    point p2 = {5, 20};
    point p3 = {7, 30};
    insert_point(table, 0, p1);
    insert_point(table, 5, p2);
    insert_point(table, 7, p3);

    printf("Get point (x=0): %d, %d\n", get_point(table, 0)->x, get_point(table, 0)->y);
    printf("Get point (x=5): %d, %d\n", get_point(table, 5)->x, get_point(table, 5)->y);
    printf("Get point (x=7): %d, %d\n", get_point(table, 7)->x, get_point(table, 7)->y);

    // Resize the hash table
    resize_hash_table(table, 32);

    return 0;
}
