void manage_resources(int n, int limit) {
    srand(time(NULL));

    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;
    NFAPI_CRC_INDICATION_PDU_T** crc_indications = NULL;

    try {
        if (offsets == NULL) {
            offsets = malloc(n * sizeof(long));
            if (offsets == NULL || offsets == MAP_FAILED) {
                perror("malloc");
                return;
            }
        }

        if (keys == NULL) {
            keys = malloc(n * sizeof(int));
            if (keys == NULL || keys == MAP_FAILED) {
                free(offsets);
                offsets = NULL;
                return;
            }
        }

        if (records == NULL) {
            records = malloc(sizeof(record*) * n);
            if (records == NULL || records == MAP_FAILED) {
                free(keys);
                keys = NULL;
                free(offsets);
                offsets = NULL;
                return;
            }

            for (int i = 0; i < n; i++) {
                records[i] = malloc(sizeof(record));
