                if (crc_indications[i] == NULL || crc_indications[i] == MAP_FAILED) {
                    for (int j = 0; j <= i; j++) {
                        free(crc_indications[j]);
                    }
                    for (int k = 0; k < i; k++) {
                        free(records[k]);
                    }
                    free(keys);
                    keys = NULL;
                    free(offsets);
                    offsets = NULL;
                    return;
                }

                NFAPI_CRC_INDICATION_PDU_T* c = crc_indications[i];
                c->RX_UE_INFORMATION_TAG = rand() % limit;
                c->RNTI = rand() % limit;
                c->CRC_INDICATION_REL8_TAG = rand() % limit;
                c->CRCFLAG = rand() % limit;
            }
        }

    } catch (int e) {
        if (offsets != NULL) {
            free(offsets);
        }

        if (keys != NULL) {
            free(keys);
        }

        if (records != NULL) {
            for (int i = 0; i < n; i++) {
                free(records[i]);
            }

            free(records);
        }

        if (crc_indications != NULL) {
            for (int i = 0; i < n; i++) {
                free(crc_indications[i]);
            }

            free(crc_indications);
        }
    }

