        r->l = rand() % 1000000;
        r->i = rand() % 10;
        const char* id_chars[] = {"ABC", "DEF", "GHI", "JKL"};
        const size_t id_len = sizeof(id_chars) / sizeof(id_chars[0]);
        size_t id_idx = rand() % id_len;
        strncpy(r->str, id_chars[id_idx], 50);
    }

    return records;
}

