typedef struct {
    char* filePath;
    int fileSize;
    int accessFrequency;
} FileSystemMetadata;

void* dynamicArrayInit(int size) {
    return calloc(size, sizeof(FileSystemMetadata));
}

void dynamicArrayAdd(void* arr, FileSystemMetadata file) {
    ((FileSystemMetadata*)arr)[((FileSystemMetadata*)arr + 1) - (FileSystemMetadata*)arr].filePath = file.filePath;
    ((FileSystemMetadata*)arr)[((FileSystemMetadata*)arr + 1) - (FileSystemMetadata*)arr].fileSize = file.fileSize;
    ((FileSystemMetadata*)arr)[((FileSystemMetadata*)arr + 1) - (FileSystemMetadata*)arr].accessFrequency = file.accessFrequency;
}

int dynamicArrayUpdate(void* arr, FileSystemMetadata file) {
    int i = 0;
    while (((FileSystemMetadata*)arr)[i].filePath != NULL) {
        if (!strcmp(((FileSystemMetadata*)arr)[i].filePath, file.filePath)) {
            ((FileSystemMetadata*)arr)[i].fileSize = file.fileSize;
            ((FileSystemMetadata*)arr)[i].accessFrequency = file.accessFrequency;
            return 0;
        }
        i++;
    }
    return -1; // File not found
}

int dynamicArrayGetMostAccessed(void* arr) {
    int maxAccess = 0, idx = 0;
    for (int i = 0; i < ((FileSystemMetadata*)arr)[0].fileSize; i++) {
        if (((FileSystemMetadata*)arr)[i].accessFrequency > maxAccess) {
            maxAccess = ((FileSystemMetadata*)arr)[i].accessFrequency;
            idx = i;
        }
    }
    return idx;
}

int executeCommands(void* arr, char** commands) {
    for (int i = 0; commands[i] != NULL; i++) {
        if (!strcmp(commands[i], "add")) {
            FileSystemMetadata file;
            // parse command arguments
            // ...
            dynamicArrayAdd(arr, file);
        } else if (!strcmp(commands[i], "update")) {
            FileSystemMetadata file;
            // parse command arguments
            // ...
            int ret = dynamicArrayUpdate(arr, file);
            if (ret == -1) {
                printf("File not found\n");
                return -1;
            }
        } else if (!strcmp(commands[i], "getMostAccessed")) {
            int idx = dynamicArrayGetMostAccessed(arr);
            // parse output
            // ...
        } else {
            printf("Invalid command\n");
            return -1;
        }
    }
    return 0; // success
}

int main(int argc, char** argv) {
    void* arr = dynamicArrayInit(10); // initialize with some capacity

    // execute commands
    char* commands[] = {"add path/file", "update path/file", "getMostAccessed"};
    int ret = executeCommands(arr, commands);

    // free memory and resources
    free(arr);
    return ret;
}
