// Define a structure for point coordinates
typedef struct {
    int x;
    int y;
} point;

// Define the hash table node structure
typedef struct {
    point value;
    struct { // Linked list of nodes with same hash value
        struct {
            point value;
            struct {
                struct node *next;
            } as[1];
        } as[1];
    } as[1];
} Node;

// Define the hash table structure
typedef struct {
    Node **table; // Table to store nodes
    int size; // Size of the table
    int count; // Number of elements in the table
} HashTable;

// Function to initialize a new hash table with given size
HashTable* create_hash_table(int size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->table = (Node**)calloc(size, sizeof(Node*));
    ht->size = size;
    ht->count = 0;
    return ht;
}

// Function to insert a point into the hash table
void insert_point(HashTable *ht, int x, int y) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->value.x = x;
    node->value.y = y;
    int index = x % ht->size;
    if (!ht->table[index]) {
        ht->table[index] = (Node*)malloc(sizeof(Node));
    }
    node->as[0].next = ht->table[index]->as[0].next;
    ht->table[index]->as[0].next = node;
}

// Function to retrieve a point from the hash table
point* get_point(HashTable *ht, int x) {
    Node *node = ht->table[x % ht->size];
    while (node && node->value.x != x) {
        node = node->as[0].next;
    }
    return node ? &node->value : NULL;
}

