    for (int i = 0; i < 10; i++) {
        insert_point(ht, i, i * i);
    }
    point* p = get_point(ht, 5);
    if (p) {
        printf("Point found: x=%d y=%d\n", p->x, p->y);
    } else {
        printf("Point not found\n");
    }
