#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define RECORD_SIZE 100
#define CHAR_MAX_SIZE 50

// Define the record structure with optional compression feature
typedef struct {
    long offset;
    int key;
    char data[CHAR_MAX_SIZE];
} record_t;

record_t* allocate_memory(int num_records, bool compress);
void deallocate_memory(record_t** records);
void log_memory_event(const char* event_type);
void print_memory_report();

int main() {
    // Example usage
    record_t* records = allocate_memory(1000, true);
    if (records != NULL) {
        // Use the allocated memory...
        free(records);
    }
    return 0;
}

record_t* allocate_memory(int num_records, bool compress) {
    if (num_records <= 0) {
        return NULL;
    }

    // Allocate arrays for offset values, keys, and records
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    record_t* records = malloc(num_records * RECORD_SIZE);

    if (offsets == NULL || keys == NULL || records == NULL) {
        log_memory_event("Allocation Failure");
        deallocate_memory((record_t**)&offsets);
        deallocate_memory((int**)&keys);
        deallocate_memory(&records);
        return NULL;
    }

    // Initialize record structures with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % LONG_MAX;
        keys[i] = rand() % INT_MAX;
        strcpy(records[i].data, "Random Data");
    }

    return records;
}

void deallocate_memory(record_t** records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

void log_memory_event(const char* event_type) {
    // External logging system implementation
    printf("[%s] Memory %s event occurred.\n", time(NULL), event_type);
}

void print_memory_report() {
    // Report memory usage statistics
    static int total_allocated = 0, current_usage = 0;
    static int peak_usage = 0;

    // Calculate current and peak memory usage
    current_usage += RECORD_SIZE * num_records;
    if (current_usage > peak_usage) {
        peak_usage = current_usage;
    }

    printf("Total Allocated Memory: %d bytes\n", total_allocated);
    printf("Current Used Memory: %d bytes\n", current_usage);
    printf("Peak Memory Usage: %d bytes\n", peak_usage);
