Record* generateRandomRecords(int numRecords) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    for(int i=0; i<numRecords; i++) {
        Record record;
        record.value = rand() % 10000;
        char* str = generateRandomString();
        record.str = str;
        records[i] = record;
    }
    return records;
}

// Function to manage memory and process data
void processFile(FILE* file, int offsetValues[], int keys[], Record* records) {
    int auxArray[10000];
    int maxIndex = 0;
    int maxValue = INT_MIN;

    // Read integers from the file into an auxiliary array
    while(fscanf(file, "%d", &auxArray[i]) == 1) {
        i++;
    }

    for(int j=0; j<i; j++) {
        int key = auxArray[j];
        Record record = records[key];

        if(record.value > maxValue) {
            maxValue = record.value;
            maxIndex = j;
        }
    }

    // Print the largest integer and associated information
    printf("Largest integer: %d\n", maxValue);
    printf("Index in auxiliary array: %d\n", maxIndex);
    printf("Offset value: %ld\n", offsetValues[maxIndex]);
    printf("Key: %d\n", keys[maxIndex]);

    // Free allocated memory
    for(int k=0; k<i; k++) {
        free(records[k].str);
    }
    free(records);
}

int main() {
    FILE* file = fopen("input.txt", "r");
    int offsetValues[10000];
    int keys[10000];
    Record* records = generateRandomRecords(10000);

    processFile(file, offsetValues, keys, records);

