// Dynamic array to store orders
Order **orders = NULL;
int orderCount = 0;
int maxOrders = 100; // Initial capacity

void initOrderManagement() {
    orders = (Order **)calloc(maxOrders, sizeof(Order *));
}

void addOrder(int id, int customerID, const char *orderDate, double totalAmount) {
    Order *newOrder = (Order *)malloc(sizeof(Order));
    newOrder->id = id;
    newOrder->customerID = customerID;
    strcpy(newOrder->orderDate, orderDate);
    newOrder->totalAmount = totalAmount;
    newOrder->status = ORDER_PLACED;

    if (orderCount >= maxOrders) {
        // Realloc and resize the orders array
        maxOrders *= 2;
        orders = (Order **)realloc(orders, maxOrders * sizeof(Order *));
    }

    orders[orderCount] = newOrder;
    orderCount++;
}

void updateOrderStatus(int id, OrderStatus status) {
    for (int i = 0; i < orderCount; i++) {
        if (orders[i]->id == id) {
            orders[i]->status = status;
            break;
        }
    }
}

double getTotalProcessedOrders() {
    double total = 0.0;
    for (int i = 0; i < orderCount; i++) {
        if (orders[i]->status != ORDER_PLACED) {
            total += orders[i]->totalAmount;
        }
    }
    return total;
}

void voidOrder(int id) {
    for (int i = 0; i < orderCount; i++) {
        if (orders[i]->id == id && orders[i]->status == ORDER_IN_PROGRESS) {
            // Mark the order as cancelled
            orders[i]->status = ORDER_CANCELLED;
            break;
        }
    }
}

void closeOrderManagement() {
    for (int i = 0; i < orderCount; i++) {
        free(orders[i]);
    }
    free(orders);
}
