#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CONNS 1000
#define TIMEOUT 300 // seconds

typedef enum {
    CONNECTED,
    DISCONNECTED
} ConnectionState;

typedef struct {
    char ipAddress[16];
    int portNumber;
    ConnectionState state;
} NetworkConnectionStatus;

// Custom hash table structure for efficient lookups and memory management
typedef struct {
    size_t bucketCount;
    NetworkConnectionStatus** buckets;
    pthread_mutex_t mutex;
} HashTable;

HashTable* hashTableCreate(size_t initialSize) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->bucketCount = initialSize;
    table->buckets = (NetworkConnectionStatus**)malloc(initialSize * sizeof(NetworkConnectionStatus*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void hashTableFree(HashTable* table) {
    for (size_t i = 0; i < table->bucketCount; i++) {
        free(table->buckets[i]);
    }
    free(table->buckets);
    free(table);
}

// Function to add a new connection
int addConnection(HashTable* table, char* ipAddress, int portNumber) {
    size_t index = hashFunction(ipAddress) % table->bucketCount;
    NetworkConnectionStatus* conn = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    strcpy(conn->ipAddress, ipAddress);
    conn->portNumber = portNumber;
    conn->state = CONNECTED;

    // Insert the new connection into the hash table
    for (size_t i = 0; i < table->bucketCount; i++) {
        if (!table->buckets[i]) {
            table->buckets[index] = conn;
            return 0;
        }
    }

    // Handle full bucket, handle this in your actual implementation
    printf("Hash table is full!\n");
    return -1;
}

// Function to update an existing connection
int updateConnection(HashTable* table, char* ipAddress) {
    size_t index = hashFunction(ipAddress) % table->bucketCount;

    // Find the connection and update its state
    for (size_t i = 0; i < table->bucketCount; i++) {
        if (table->buckets[i] && !strcmp(table->buckets[i]->ipAddress, ipAddress)) {
            table->buckets[i]->state = DISCONNECTED;
            return 0;
        }
    }

    // Connection not found
    printf("Connection not found!\n");
    return -1;
}

// Function to retrieve the number of active connections
int getActiveConnections(HashTable* table) {
    int count = 0;

    for (size_t i = 0; i < table->bucketCount; i++) {
        if (table->buckets[i] && table->buckets[i]->state == CONNECTED)
            count++;
    }

    return count;
}

// Function to periodically clean up inactive connections
void cleanupConnections(HashTable* table) {
    for (size_t i = 0; i < table->bucketCount; i++) {
        if (table->buckets[i] && table->buckets[i]->state == DISCONNECTED) {
            // Handle cleaning up disconnected connections, handle this in your actual implementation
            free(table->buckets[i]);
        }
    }
}

// Custom hash function for efficient lookups
size_t hashFunction(char* key) {
    size_t result = 0;

    for (int i = 0; i < strlen(key); i++) {
        result += (size_t)key[i];
    }

    return result % MAX_CONNS;
}

// Function to serialize the entire collection of `NetworkConnectionStatus` structures
void serializeConnections(HashTable* table, FILE* file) {
    fwrite(&table->bucketCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < table->bucketCount; i++) {
        if (table->buckets[i]) {
            fwrite(&table->buckets[i]->portNumber, sizeof(int), 1, file);
            fwrite(table->buckets[i]->ipAddress, 1, strlen(table->buckets[i]->ipAddress), file);
            fputc((int)table->buckets[i]->state, file);
        }
    }
}

// Function to deserialize the entire collection of `NetworkConnectionStatus` structures
HashTable* deserializeConnections(FILE* file) {
    HashTable* table = hashTableCreate(MAX_CONNS);

    fread(&table->bucketCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < table->bucketCount; i++) {
        NetworkConnectionStatus* conn = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
        fread(&conn->portNumber, sizeof(int), 1, file);
        char buffer[17];
        fread(buffer, 1, 16, file);
        buffer[16] = '\0';
        strcpy(conn->ipAddress, buffer);
        fgetc(file); // Read the ConnectionState enum
        table->buckets[i] = conn;
    }

    return table;
}
