#define MAX_SIZE 50000
#define MAX_THREADS 100
#define LOG_VERBOSITY 1

typedef struct {
    int rnti;
    char crcflag;
    int qos;
    int priority;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

int nfpdu_list_size = 0;
NFAPI_CRC_INDICATION_PDU_T *nfpdu_list = NULL;

void init_nfpdu_list() {
    if ((nfpdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
        printf("Error allocating memory for NFAPI_CRC_INDICATION_PDU_T list.\n");
        exit(EXIT_FAILURE);
    }
}

void insert_nfpdu(int rnti, char crcflag, int qos, int priority) {
    pthread_mutex_lock(&nfpdu_list[nfpdu_list_size].lock);

    if (nfpdu_list_size >= MAX_SIZE) {
        printf("NFAPI_CRC_INDICATION_PDU_T list is full.\n");
        return;
    }

    nfpdu_list[nfpdu_list_size].rnti = rnti;
    nfpdu_list[nfpdu_list_size].crcflag = crcflag;
    nfpdu_list[nfpdu_list_size].qos = qos;
    nfpdu_list[nfpdu_list_size].priority = priority;

    if (nfpdu_list_size == 0) {
        pthread_mutex_init(&nfpdu_list[0].lock, NULL);
    }

    if (LOG_VERBOSITY > 0) {
        printf("NFAPI_CRC_INDICATION_PDU_T inserted with RNTI: %d\n", rnti);
    }

    nfpdu_list_size++;
    pthread_mutex_unlock(&nfpdu_list[nfpdu_list_size-1].lock);
}

void delete_nfpdu(int rnti) {
    int i;
    for (i = 0; i < nfpdu_list_size; i++) {
        if (nfpdu_list[i].rnti == rnti) {
            pthread_mutex_lock(&nfpdu_list[i].lock);

            if (LOG_VERBOSITY > 0) {
                printf("NFAPI_CRC_INDICATION_PDU_T deleted with RNTI: %d\n", rnti);
            }

            for (; i < nfpdu_list_size - 1; i++) {
                nfpdu_list[i] = nfpdu_list[i+1];
            }

            pthread_mutex_unlock(&nfpdu_list[i].lock);

            nfpdu_list_size--;
            return;
        }
    }
}

int main() {
    init_nfpdu_list();

    // Insert NFAPI_CRC_INDICATION_PDU_T structures
    insert_nfpdu(1, 'a', 0, 2);
    insert_nfpdu(2, 'b', 1, 3);

    // Delete an NFAPI_CRC_INDICATION_PDU_T structure
    delete_nfpdu(1);

    return 0;
}
