typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int crc_validation;
    time_t timestamp;
} NICPDU;

typedef struct {
    NICPDU *data;
    int size;
    int capacity;
} NICPDUList;

NICPDUList* nicpdu_list_new(int initial_capacity) {
    NICPDUList* list = (NICPDUList*)malloc(sizeof(NICPDUList));
    list->size = 0;
    list->capacity = initial_capacity;
    list->data = (NICPDU*)malloc(initial_capacity * sizeof(NICPDU));
    return list;
}

void nicpdu_list_free(NICPDUList* list) {
    if(list != NULL) {
        free(list->data);
        free(list);
    }
}

void nicpdu_list_add(NICPDUList* list, NICPDU* nicpdu) {
    if(list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NICPDU* new_data = (NICPDU*)malloc(new_capacity * sizeof(NICPDU));
        memcpy(new_data, list->data, list->size * sizeof(NICPDU));
        free(list->data);
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size] = *nicpdu;
    list->size++;
}

int nicpdu_list_serialize(const NICPDUList* list, void** serialized_data) {
    int total_size = 0;
    for(int i = 0; i < list->size; i++) {
        total_size += sizeof(NICPDU);
    }
    *serialized_data = malloc(total_size);
    NICPDU* data = (NICPDU*)malloc(list->size * sizeof(NICPDU));
    memcpy(data, list->data, list->size * sizeof(NICPDU));
    FILE* file = fopen("/dev/shm/nicpdu_list", "wb");
    fwrite(&total_size, sizeof(int), 1, file);
    fwrite(&list->size, sizeof(int), 1, file);
    fwrite(data, sizeof(NICPDU), list->size, file);
    fclose(file);
    free(data);
}

int main() {
    NICPDUList* list = nicpdu_list_new(10);
    // Add some NICPDUs to the list
    for(int i = 0; i < 5; i++) {
        NICPDU nicpdu;
        nicpdu.RX_UE_INFORMATION_TAG = i;
        nicpdu.RNTI = i * 2;
        nicpdu.CRC_INDICATION_REL8_TAG = i * 3;
        nicpdu.crc_validation = (i % 2 == 0);
        nicpdu.timestamp = time(NULL);
        nicpdu_list_add(list, &nicpdu);
    }
    void* serialized_data;
    int ret = nicpdu_list_serialize(list, &serialized_data);
    // ...
    return 0;
}
