    // Add connection to indices array
    ConnectionIndex newConnection;
    newConnection.offset = offset;
    newConnection.key = key;
    indices[offset] = newConnection;
}

int getOffset(int key) {
    // Retrieve offset value from key
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (indices[i].key == key) {
            return indices[i].offset;
        }
    }
    return -1;
}

void updateConnectionState(int offset, char* newState) {
    // Update connection state in connections array
    strcpy(connections[offset].connectionState, newState);
}

