// Function to allocate memory for structures and arrays
int allocateMemory(int numRecords, int* keys) {
    // Check user input against maximum size constraint
    if (numRecords > 500) {
        return -1; // Error: Excessive memory usage
    }

    // Allocate array of long offsets
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        return -2; // Error: Memory allocation failed for offsets
    }

    // Initialize array of int keys
    int* keyArray = (int*)malloc(1000 * sizeof(int));
    for (int i = 0; i < 1000; i++) {
        keyArray[i] = i;
    }

    // Allocate and initialize record structures
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = &keyArray[rand() % 1000];
        records[i].value = rand() % 1000 + 1;
        records[i].offset = offsets[rand() % numRecords];
    }

    // Free allocated memory
    free(keyArray);
    for (int i = 0; i < numRecords; i++) {
        free((void*)records[i].key);
    }
    free(offsets);

    return 0; // Success
}

