            records[i] = (record *)malloc(sizeof(record));
            records[i]->key = &keys[rand() % 1000];
            records[i]->value = rand() % 101;
            records[i]->offset = &offsets[rand() % num_records];
        }
    } else {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        if (offsets) free(offsets);
        if (keys) free(keys);
        for (int i = 0; i < num_records; i++) {
            if (records[i]) free(records[i]);
        }
        return -1;
    }

