        measurement->timestamp = time(NULL);
        measurement->sensor_reading = (float)rand() / RAND_MAX * SENSOR_READING_RANGE;
        sprintf(measurement->id, "%f", measurement->sensor_reading);
        pthread_mutex_lock(&lock);
        if (measurement_log == NULL) {
            measurement_log = measurement;
        } else {
            measurement->next = measurement_log;
            measurement_log = measurement;
        }
        pthread_mutex_unlock(&lock);
    }
}

