            measurement->sensor_reading += (float)rand() / RAND_MAX * SENSOR_READING_RANGE;
            sprintf(measurement->id, "%f", measurement->sensor_reading);
            pthread_mutex_lock(&lock);
            measurement_log = measurement->next;
            free(measurement);
            pthread_mutex_unlock(&lock);
        }
    }
}

void delete_measurements(int retention_policy) {
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_MEASUREMENTS; i++) {
        measurementLog *measurement = measurement_log;
        while (measurement != NULL) {
            if ((current_time - measurement->timestamp) > retention_policy) {
                pthread_mutex_lock(&lock);
                measurement_log = measurement->next;
                free(measurement);
                pthread_mutex_unlock(&lock);
            } else {
                measurement = measurement->next;
            }
        }
    }
}

int main() {
    // initialize sensors
    initialize_sensors();

    // update sensors periodically
    while (1) {
        update_sensors();
        sleep(1); // adjust according to your needs
    }

    return 0;
