typedef struct {
    int qos; // Quality of Service parameter
    char *header; // MAC PDU header
    char *payload; // MAC PDU payload
} lte_mac_pdu;

// Function to manage dynamically resizable list of LTE MAC PDUs
void* handle_lte_mac_pdu_list(void** head, void** tail) {
    // Allocate memory for new PDU if none exist
    if (*head == NULL) {
        *head = malloc(sizeof(lte_mac_pdu));
        *tail = *head;
    } else {
        lte_mac_pdu* p = (lte_mac_pdu*)malloc(sizeof(lte_mac_pdu));
        // Ensure no two consecutive PDUs have identical QoS classes
        while (p->qos <= 0xFF && p->qos >= 0x01) {
            p++;
            if ((p)->qos > 0xFF || (p)->qos < 0x01) break;
        }
        *tail = p;
    }

    return NULL;
}

int main() {
    void* head, *tail;

    // Example usage: Add some PDUs to the list
    for (int i = 0; i < 1000; ++i) {
        lte_mac_pdu* p = (lte_mac_pdu*)malloc(sizeof(lte_mac_pdu));
        // Initialize PDU parameters and QoS class
        p->qos = rand() % 256;
        p->header = "MAC Header";
        p->payload = "Payload";

        // Add the new PDU to the list
        handle_lte_mac_pdu_list(&head, &tail);

        free(p);
    }

    return 0;
}
