    NetworkConnectionStatus** network_connection_statuses;
    MeasurementLog** measurement_logs;
} ConnectionTable;

void init_connection_table(ConnectionTable* connection_table, int size) {
    connection_table->size = size;
    connection_table->network_connection_statuses = (NetworkConnectionStatus**)malloc(size * sizeof(NetworkConnectionStatus*));
    connection_table->measurement_logs = (MeasurementLog*)malloc(size * sizeof(MeasurementLog));
    for (int i = 0; i < size; i++) {
