                strcpy(productName, "Product_");
                int productQuantity = rand() % 100 + 1;

                // Add the new order and product details to the list
                orders = (CustomerOrder*)realloc(orders, (totalOrders + 2) * sizeof(CustomerOrder));
                products[totalOrders] = productName;
                totalOrders++;
                break;
            }
            case 2: {
                // Update an existing customer order
                int updateOrderID;
                printf("Enter the order ID to update: ");
                scanf("%d", &updateOrderID);

                // Find the order with the specified ID and update its details
                for (int i = 0; i < totalOrders; i++) {
                    if (orders[i].OrderID == updateOrderID) {
                        orders[i].TotalAmount += rand() % 100 - 50; // Randomly update the order total
                        orders[i].OrderDate = time(NULL); // Update the last update time
                        break;
                    }
                }

                break;
            }
            case 3: {
                // Calculate and display the average order value
                double sum = 0.0;
                for (int i = 0; i < totalOrders; i++) {
                    sum += orders[i].TotalAmount;
                }
                printf("Average order value: %.2f\n", sum / totalOrders);
                break;
            }
            case 4: {
                // Exit the program
                free(orders);
                for (int i = 0; i < totalOrders; i++) {
                    free(products[i]);
                }
                free(products);
                return 0; // Success
            }
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

