    int totalSize = offsetSize * sizeof(long) + keySize * sizeof(int) + recordSize * sizeof(record);

    // Check if allocation would exceed system limits
    if (totalSize > 1024 * 1024 * 10) { // 10MB limit
        printf("Memory usage exceeds limit, cannot allocate.\n");
        return NULL;
    }

    // Allocate memory for arrays
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(keySize * sizeof(int));
    record* records = (record*)malloc(recordSize * sizeof(record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed, cannot continue.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize cache for previously generated random numbers
