    int* cachedNumbers = (int*)malloc(cacheSize * sizeof(int));
    int cacheIndex = 0;

    // Populate arrays and cache with random values
    for (int i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % 1000000;
    }
    for (int i = 0; i < keySize; i++) {
        keys[i] = rand() % 10000;
    }
    for (int i = 0; i < recordSize; i++) {
        records[i].value = rand() % 1000;
    }

