Node* init_nodes(int num_nodes) {
    Node* nodes = (Node*)malloc(num_nodes * sizeof(Node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes\n");
        return NULL;
    }

    for (int i = 0; i < num_nodes; i++) {
        Node* node = &nodes[i];
        uuid_t uuid;
        uuid_generate(uuid);
        char* uuid_str = malloc(UUID_SIZE + 1);
        uuid_unparse(uuid, uuid_str);
        strcpy(node->uuid, uuid_str);
        free(uuid_str);

        node->key = rand() % KEY_MAX;

        if (i < num_nodes - 1) {
            node->next = NULL;
        } else {
            node->next = NULL;
        }
    }

    return nodes;
}

