    Node* nodes = init_nodes(num_nodes);

    // Verify integrity of data structures
    for (int i = 0; i < num_nodes; i++) {
        printf("Node %d: uuid=%s, key=%d\n", i, nodes[i].uuid, nodes[i].key);
    }

    // Free dynamically allocated memory
    free(nodes);

    return 0;
