    int numPDU;
    int* pduSessions;
    int timer;
} UeSessionState;

// Cache of previously processed session states
int cacheSize = 1000;
UeSessionState* cache = (UeSessionState*)malloc(cacheSize * sizeof(UeSessionState));

// Lock for concurrent access to the session state array and cache
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initAndPopulateSessionStates(int numSessions) {
    UeSessionState* sessionStates = (UeSessionState*)malloc(numSessions * sizeof(UeSessionState));

    for (int i = 0; i < numSessions; i++) {
        sprintf(sessionStates[i].ueId, "UE_%d", i);
        sessionStates[i].numPDU = i;
        sessionStates[i].pduSessions = (int*)malloc(i * sizeof(int));

        // Initialize PDU sessions
        for (int j = 0; j < i; j++) {
            sessionStates[i].pduSessions[j] = j;
        }

        sessionStates[i].timer = 60; // default timer value

        // Add to cache if not full
        if (cacheSize == numSessions) {
            for (int k = 0; k < numSessions; k++) {
                cache[k] = sessionStates[k];
            }
            free(sessionStates);
            sessionStates = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
}

void* getSessionState(int ueIdIndex) {
    pthread_mutex_lock(&lock);

    // Check if the UE session state is in the cache
    for (int i = 0; i < cacheSize; i++) {
        if (strcmp(cache[i].ueId, "UE_" + itoa(ueIdIndex)) == 0) {
            pthread_mutex_unlock(&lock);
            return &cache[i];
        }
    }

    // Not found in cache, retrieve from the session state array
    UeSessionState* sessionState = &sessionStates[ueIdIndex];
    pthread_mutex_unlock(&lock);
    return sessionState;
}

void releaseSessionState(UeSessionState* sessionState) {
    free(sessionState->pduSessions);
    free(sessionState);
}
