#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

// Structure for a log record
typedef struct {
    int key;
    time_t timestamp;
    char* message;
} LogRecord;

// Structure to manage the dynamic dataset of records
typedef struct {
    size_t capacity;
    size_t size;
    LogRecord** records;
    pthread_mutex_t mutex; // Mutex for thread safety
} LogDataset;

// Function to initialize memory for a log dataset
LogDataset* log_dataset_init(size_t initial_capacity) {
    LogDataset* dataset = (LogDataset*)malloc(sizeof(LogDataset));
    dataset->capacity = initial_capacity;
    dataset->size = 0;
    dataset->records = (LogRecord**)calloc(initial_capacity, sizeof(LogRecord*));
    pthread_mutex_init(&dataset->mutex, NULL);
    return dataset;
}

// Function to add a new log record to the dataset
void log_dataset_add(LogDataset* dataset, int key, const char* message) {
    LogRecord* record = (LogRecord*)malloc(sizeof(LogRecord));
    record->key = key;
    record->timestamp = time(NULL);
    record->message = strdup(message);

    pthread_mutex_lock(&dataset->mutex);
    if (dataset->size >= dataset->capacity) {
        size_t new_capacity = dataset->capacity * 2;
        LogRecord** new_records = (LogRecord**)realloc(dataset->records, sizeof(LogRecord*) * new_capacity);
        for (size_t i = 0; i < dataset->size; i++) {
            new_records[i] = dataset->records[i];
        }
        free(dataset->records);
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }
    dataset->records[dataset->size++] = record;
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to update an existing log record in the dataset
void log_dataset_update(LogDataset* dataset, int key, const char* message) {
    for (int i = 0; i < dataset->size; i++) {
        if (dataset->records[i]->key == key) {
            free(dataset->records[i]->message);
            dataset->records[i]->message = strdup(message);
            return;
        }
    }
}

// Function to delete a log record from the dataset
void log_dataset_delete(LogDataset* dataset, int key) {
    for (int i = 0; i < dataset->size; i++) {
        if (dataset->records[i]->key == key) {
            free(dataset->records[i]->message);
            memmove(&dataset->records[i], &dataset->records[i + 1], sizeof(LogRecord*) * (dataset->size - i - 1));
            dataset->size--;
            i--; // Reset the loop variable
        }
    }
}

// Function to clear all allocated memory and release resources when the dataset is no longer needed
void log_dataset_free(LogDataset* dataset) {
    for (int i = 0; i < dataset->size; i++) {
        free(dataset->records[i]->message);
        free(dataset->records[i]);
    }
    free(dataset->records);
    pthread_mutex_destroy(&dataset->mutex);
    free(dataset);
}

// Example usage:
int main() {
    LogDataset* dataset = log_dataset_init(10);

    // Add some records
    log_dataset_add(dataset, 1, "This is a test message");
    log_dataset_add(dataset, 2, "Another test message");

    // Update an existing record
    log_dataset_update(dataset, 1, "Updated message");

    // Delete a record
    log_dataset_delete(dataset, 2);

    // Print the records in the dataset
    for (int i = 0; i < dataset->size; i++) {
        printf("Key: %d, Timestamp: %ld, Message: %s\n", dataset->records[i]->key, dataset->records[i]->timestamp, dataset->records[i]->message);
    }

    // Clear all allocated memory and release resources
    log_dataset_free(dataset);

    return 0;
}
