#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a thread-safe linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Thread-safe linked list implementation
Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&mutex);
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = new_data;
    new_node->next = *head_ref;
    *head_ref = new_node;
    pthread_mutex_unlock(&mutex);
}

void remove_node(Node** head_ref, RNTI rnti) {
    pthread_mutex_lock(&mutex);
    Node* current = *head_ref;
    Node* previous = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    if (previous == NULL) {
        *head_ref = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&mutex);
}

// Serialize the linked list to a file
void serialize_to_file(Node* head, FILE* output_file) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, output_file);
