// Define the structure for NetworkElementStatus
typedef struct {
    char ip_address[16];
    int operational_status;
    float health_metric;
} NetworkElementStatus;

// Define a thread-safe hash table implementation using open addressing
typedef struct {
    NetworkElementStatus *data;
    pthread_mutex_t mutex;
    unsigned long size;
    unsigned long capacity;
} HashTable;

HashTable* create_hash_table(unsigned long capacity) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = 0;
    hash_table->capacity = capacity;
    hash_table->data = (NetworkElementStatus*)malloc(capacity * sizeof(NetworkElementStatus));
    pthread_mutex_init(&hash_table->mutex, NULL);
    return hash_table;
}

void insert_hash_table(HashTable* hash_table, NetworkElementStatus* network_element_status) {
    unsigned long index = network_element_status->health_metric % hash_table->capacity;
    while (hash_table->data[index].ip_address[0] != '\0') {
        // Handle collision using open addressing
        index = (index + 1) % hash_table->capacity;
    }
    pthread_mutex_lock(&hash_table->mutex);
    strcpy(hash_table->data[index].ip_address, network_element_status->ip_address);
    hash_table->data[index].operational_status = network_element_status->operational_status;
    hash_table->data[index].health_metric = network_element_status->health_metric;
    hash_table->size++;
    pthread_mutex_unlock(&hash_table->mutex);
}

NetworkElementStatus* lookup_hash_table(HashTable* hash_table, char* ip_address) {
    unsigned long index = 0;
    while (index < hash_table->capacity) {
        if (strcmp(hash_table->data[index].ip_address, ip_address) == 0) {
            return &hash_table->data[index];
        }
        index++;
    }
    return NULL;
}

void update_hash_table(HashTable* hash_table, NetworkElementStatus* network_element_status) {
