typedef enum {
    IDENTIFIERS,
    MEASUREMENTS,
    STATUS_FLAGS,
    METADATA_RECORDS
} DataStructures;

void* manageMemory(int size, DataStructures type) {
    void* ptr;

    switch (type) {
        case IDENTIFIERS:
            ptr = malloc(size * sizeof(int));
            break;
        case MEASUREMENTS:
            ptr = malloc(size * sizeof(double));
            break;
        case STATUS_FLAGS:
            ptr = malloc(size * sizeof(char));
            break;
        case METADATA_RECORDS:
            ptr = malloc(size * sizeof(struct metadata));
            break;
    }

    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize data structures
    if (type == IDENTIFIERS) {
        for (int i = 0; i < size; i++) {
            ((int*) ptr)[i] = i;
        }
    } else if (type == MEASUREMENTS) {
        for (int i = 0; i < size; i++) {
            ((double*) ptr)[i] = (double) i;
        }
    } else if (type == STATUS_FLAGS) {
        for (int i = 0; i < size; i++) {
            ((char*) ptr)[i] = 'A';
        }
    } else if (type == METADATA_RECORDS) {
        struct metadata* record = (struct metadata*) ptr;
        for (int i = 0; i < size; i++) {
            record[i].id = i;
            record[i].data = (void*) &i;
        }
    }

    return ptr;
}

int main() {
    int size = 10;
    DataStructures type = IDENTIFIERS;

    void* memory = manageMemory(size, type);

    // Process data structures
    if (type == IDENTIFIERS) {
        printf("Identifiers: ");
        for (int i = 0; i < size; i++) {
            printf("%d ", ((int*) memory)[i]);
        }
        printf("\n");
    } else if (type == MEASUREMENTS) {
        printf("Measurements: ");
        for (int i = 0; i < size; i++) {
            printf("%f ", ((double*) memory)[i]);
        }
        printf("\n");
    } else if (type == STATUS_FLAGS) {
        printf("Status Flags: ");
        for (int i = 0; i < size; i++) {
            printf("%c", ((char*) memory)[i]);
        }
        printf("\n");
    } else if (type == METADATA_RECORDS) {
        struct metadata* record = (struct metadata*) memory;
        printf("Metadata Records: ");
        for (int i = 0; i < size; i++) {
            printf("{ id:%d, data:%p } ", record[i].id, record[i].data);
        }
        printf("\n");
    }

    free(memory);

    return 0;
}

struct metadata {
    int id;
    void* data;
};
