typedef struct {
    int portNumber;
    enum {DISCONNECTED, CONNECTED} connectionState;
} NetworkConnectionStatus;

typedef struct {
    int size;
    int capacity;
    NetworkConnectionStatus** connections;
} ConnectionArray;

void initializeConnections(ConnectionArray* array) {
    array->size = 0;
    array->capacity = 10; // Initial capacity
    array->connections = (NetworkConnectionStatus**)malloc(array->capacity * sizeof(NetworkConnectionStatus*));
}

int addConnection(ConnectionArray* array, int portNumber, enum {DISCONNECTED, CONNECTED} connectionState) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->connections = (NetworkConnectionStatus**)realloc(array->connections, array->capacity * sizeof(NetworkConnectionStatus*));
    }
    array->connections[array->size] = malloc(sizeof(NetworkConnectionStatus));
    array->connections[array->size]->portNumber = portNumber;
    array->connections[array->size]->connectionState = connectionState;
    array->size++;
    return 0;
}

int updateConnection(ConnectionArray* array, int portNumber, enum {DISCONNECTED, CONNECTED} connectionState) {
    for (int i = 0; i < array->size; i++) {
        if (array->connections[i]->portNumber == portNumber) {
            array->connections[i]->connectionState = connectionState;
            return 0;
        }
    }
    return -1; // Connection not found
}

int getActiveConnections(ConnectionArray* array) {
    int count = 0;
    for (int i = 0; i < array->size; i++) {
        if (array->connections[i]->connectionState == CONNECTED) {
            count++;
        }
    }
    return count;
}
