        }

        yaml_parser_t Y;
        yaml_event_t event;
        int event_size;

        yaml_parser_initialize(&Y);
        yaml_parser_set_input_file(&Y, file);

        while (yaml_parser_parse(&Y, &event, &event_size)) {
            if (event.type == YAML_STREAM_START_EVENT) {
                // Process YAML stream
                yaml_stream_start_event_t* start_event = (yaml_stream_start_event_t*) &event;
                printf("Stream started with version %d\n", start_event->version);
            } else if (event.type == YAML_DOCUMENT_START_EVENT) {
                // Process YAML document
                yaml_document_start_event_t* doc_event = (yaml_document_start_event_t*) &event;
                printf("Document started with node %s\n", doc_event->node.name);

                // Dynamically adjust logging level based on configured settings
