                strcpy(uri, "/");
                char* http_version = (char*)malloc(8);
                strcpy(http_version, "HTTP/1.1");

                // Initialize HTTP_REQUEST_PDU_T structure
                HTTP_REQUEST_PDU_T* http_request = (HTTP_REQUEST_PDU_T*)malloc(sizeof(HTTP_REQUEST_PDU_T));
                http_request->REQUEST_METHOD = request_method;
                http_request->URI = uri;
                http_request->HTTP_VERSION = http_version;

                // Process YAML node and update log entries and HTTP requests
                yaml_node_t* node = doc_event->node.root_node;
                if (node) {
                    if (yaml.NodeKind(node) == YAML_SCALAR_NODE) {
                        char* scalar_value = (char*)malloc(strlen(node->value.str) + 1);
                        strcpy(scalar_value, node->value.str);
                        // Update log entries
                        // ...
                        // Update HTTP requests
                        num_http_requests++;
                        http_request = (HTTP_REQUEST_PDU_T*)realloc(http_request, sizeof(HTTP_REQUEST_PDU_T) * (num_http_requests + 1));
                        http_request[num_http_requests - 1] = http_request;
                    } else if (yaml.NodeKind(node) == YAML_SEQUENCE_NODE) {
                        yaml_sequence_node_t* sequence_node = (yaml_sequence_node_t*)node;
                        for (int j = 0; j < sequence_node->length; j++) {
                            yaml_node_t* child_node = sequence_node->children + j;
                            if (child_node && yaml.NodeKind(child_node) == YAML_SCALAR_NODE) {
                                // Process scalar node
                                char* scalar_value = (char*)malloc(strlen(child_node->value.str) + 1);
                                strcpy(scalar_value, child_node->value.str);
                                // Update log entries
                                // ...
                            }
                        }
                    }
                }

                free(request_method);
                free(uri);
                free(http_version);
            } else {
                yaml_event_delete(&event);
            }
        }

        fclose(file);
        yaml_parser_delete(&Y);
    }

    return 0;
}
