#include <stdio.h>
#include <stdlib.h>
#include <complex.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 10000
#define MAX_COMPLEX_PARTS 10.0f
#define MAX_REAL_PARTS 5.0f
#define THRESHOLD 0.5

typedef struct complex_t {
    double real;
    double imag;
} Complex;

typedef struct node_t {
    float value;
    Complex complex;
    char* id;
    struct node_t* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
bool gc_enabled = false;
int gc_threshold = THRESHOLD;

void init_complex(Complex* c) {
    c->real = (double)rand() / RAND_MAX * MAX_REAL_PARTS;
    c->imag = (double)rand() / RAND_MAX * MAX_COMPLEX_PARTS;
}

char* select_id(int i) {
    static char* ids[] = {"A", "B", "C", "D"};
    return ids[i % 4];
}

void add_node(float value, int i) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = value;
    init_complex(&node->complex);
    node->id = select_id(i);
    node->next = head;
    pthread_mutex_lock(&mutex);
    if (!head) {
        head = node;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&mutex);
}

void gc_node(Node** head_ref, float threshold) {
    Node* current = *head_ref;
    Node* prev = NULL;
    while (current) {
        if (current->value > threshold) {
            Node* temp = current;
            current = current->next;
            free(temp);
            if (!prev) {
                *head_ref = current;
            } else {
                prev->next = current;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void analyze_distribution() {
    double mean_real = 0.0, mean_imag = 0.0;
    int count = 0;
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current) {
        mean_real += current->complex.real;
        mean_imag += current->complex.imag;
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);

    double variance_real = 0.0, variance_imag = 0.0;
    current = head;
    while (current) {
        variance_real += pow(current->complex.real - mean_real / count, 2);
        variance_imag += pow(current->complex.imag - mean_imag / count, 2);
        current = current->next;
    }

    double stddev_real = sqrt(variance_real / count);
    double stddev_imag = sqrt(variance_imag / count);

    printf("Mean real: %lf\n", mean_real / count);
    printf("Variance real: %lf\n", variance_real / count);
    printf("Standard deviation real: %lf\n", stddev_real);
    printf("Mean imag: %lf\n", mean_imag / count);
    printf("Variance imag: %lf\n", variance_imag / count);
    printf("Standard deviation imag: %lf\n", stddev_imag);
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < MAX_NODES; i++) {
        add_node((float)i, i);
    }
    gc_enabled = true;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (gc_enabled && head->value > THRESHOLD) {
            gc_node(&head, THRESHOLD);
        }
        pthread_mutex_unlock(&mutex);
        analyze_distribution();
    }
    return 0;
}
