typedef enum {
    TASK_NEW,
    TASK_PENDING,
    TASK_RUNNING,
    TASK_TIMEOUT
} TaskStatus;

typedef struct {
    int task_id;
    int priority_level;
    time_t start_time;
    TaskStatus status;
} TaskExecution;

void* malloc_aligned(size_t size) {
    void* ptr = malloc(size);
    return (size % 16 == 0 ? NULL : _aligned_free(ptr));
}

int init_task_list(void** task_list, size_t capacity) {
    *task_list = calloc(capacity, sizeof(TaskExecution));
    if (*task_list == NULL) {
        return -1;
    }
    return 0;
}

int add_task(void* task_list, int task_id, int priority_level) {
    // Find the first empty slot
    for (size_t i = 0; i < capacity; i++) {
        TaskExecution* task = &((TaskExecution*)task_list)[i];
        if (task->status == TASK_NEW) {
            task->task_id = task_id;
            task->priority_level = priority_level;
            task->start_time = time(NULL);
            task->status = TASK_PENDING;
            return 0;
        }
    }
    return -1;
}

int update_task(void* task_list, int task_id, TaskStatus status) {
    for (size_t i = 0; i < capacity; i++) {
        TaskExecution* task = &((TaskExecution*)task_list)[i];
        if (task->task_id == task_id) {
            task->status = status;
            return 0;
        }
    }
    return -1;
}

int get_pending_tasks(void* task_list, size_t* count) {
    *count = 0;
    for (size_t i = 0; i < capacity; i++) {
        TaskExecution* task = &((TaskExecution*)task_list)[i];
        if (task->status == TASK_PENDING) {
            (*count)++;
        }
    }
    return 0;
}

int get_running_tasks(void* task_list, size_t* count) {
    *count = 0;
    for (size_t i = 0; i < capacity; i++) {
        TaskExecution* task = &((TaskExecution*)task_list)[i];
        if (task->status == TASK_RUNNING) {
            (*count)++;
        }
    }
    return 0;
}

int periodic_task_timeout(void* task_list, time_t timeout) {
    for (size_t i = 0; i < capacity; i++) {
        TaskExecution* task = &((TaskExecution*)task_list)[i];
        if (task->start_time + timeout <= time(NULL)) {
            // Time out logic here
        }
    }
    return 0;
}

