        // Update the hash map with processed data
        // ...
        free(hash);
    }

    // Persist processed data periodically
    // ...

    // Track most frequent key and its frequency in real-time
    // ...

    for (int i = 0; i < lineNo; i++) free(lines[i]);
    free(lines);
    free(buffer);
}

void strstrip(char *str) {
    size_t len = strlen(str);
    if (len == 0) return;

    while (len > 0 && isspace(str[len - 1])) len--;
    str[len] = '\0';
