// Function to manage dynamic memory allocation for three distinct data structures and a collection of NetworkConnectionStatus structures
void networkConnectionManagement(int* connectionsSize, NetworkConnectionStatus** connectionsArray) {

    // Add new connection
    void addConnection(NetworkConnectionStatus*** connectionsArray) {
        *connectionsArray = realloc(*connectionsArray, (*connectionsSize + 1) * sizeof(NetworkConnectionStatus));
        strcpy((*connectionsArray)[*connectionsSize]->IPAddress, "new IP");
        (*connectionsArray)[*connectionsSize]->PortNumber = 8080;
        (*connectionsArray)[*connectionsSize]->ConnectionState = CONNECTED;
        (*connectionsSize)++;
    }

    // Update existing connection
    void updateConnection(NetworkConnectionStatus*** connectionsArray, int index) {
        if (index >= *connectionsSize || index < 0)
            printf("Invalid index\n");
        else {
            strcpy((*connectionsArray)[index]->IPAddress, "new IP");
            (*connectionsArray)[index]->PortNumber = 8081;
            (*connectionsArray)[index]->ConnectionState = DISCONNECTED;
        }
    }

    // Retrieve the number of active connections
    int getActiveConnections(NetworkConnectionStatus** connectionsArray) {
        int count = 0;
        for (int i = 0; i < *connectionsSize; i++) {
            if ((*connectionsArray)[i]->ConnectionState == CONNECTED)
                count++;
        }
        return count;
    }

    // Periodically clean up inactive connections to prevent memory growth
    void cleanupConnections(NetworkConnectionStatus*** connectionsArray) {
        for (int i = 0; i < *connectionsSize; i++) {
            if ((*connectionsArray)[i]->ConnectionState == DISCONNECTED)
                free((*connectionsArray)[i]);
