class UserSession {
public:
    int userID;
    SessionState state;
    time_t lastActivityTime;
};

class SessionManager {
private:
    std::unordered_map<int, UserSession> sessions;
    std::deque<UserSession*> expiredSessions;
    std::mutex sessionMutex;
    std::condition_variable cv;
    thread_local std::mutex localCacheMutex;
    int maxThreads;

public:
    SessionManager(int maxThreads) : maxThreads(maxThreads) {
        for (int i = 0; i < maxThreads; ++i)
            sessions.insert({i, {}});
    }

    void addSession(int userID, SessionState state) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        sessions[userID] = {userID, state, time(0)};
        cv.notify_all();
    }

    void updateSession(int userID, SessionState state) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        if (sessions.find(userID) != sessions.end()) {
            sessions[userID].state = state;
            sessions[userID].lastActivityTime = time(0);
        }
    }

    void removeExpiredSessions() {
        std::unique_lock<std::mutex> lock(sessionMutex);
        auto it = sessions.begin();
        while (it != sessions.end()) {
            if (difftime(time(0), it->second.lastActivityTime) > 3600) {
                expiredSessions.push_back(&(*it));
                sessions.erase(it++);
            } else
                ++it;
        }
    }

    void syncWithDatabase() {
        // database API code to persist session metadata
    }

    void run() {
        for (int i = 0; i < maxThreads; ++i)
            std::thread([this, i]() { 
                while (true) {
                    cv.wait_for(std::chrono::seconds(1), [this, &cv]() {
                        cv.notify_all();
                    });
                    removeExpiredSessions();
                    syncWithDatabase();
                }
            }).detach();
    }

    void monitorActivity() {
        // monitoring and alerting code for unusual activity patterns
    }

    int getActiveSessionCount() {
        std::lock_guard<std::mutex> lock(sessionMutex);
        return sessions.size();
    }
};
