record* initialize_records(int offset_count, int key_count, int max_value) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for offset values
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    if (!offsets) return NULL;

    // Allocate memory for keys
    int* keys = (int*)malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for records
    record* records = (record*)malloc(offset_count * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record values
    for (int i = 0; i < offset_count; i++) {
        records[i].key = rand() % max_value;
    }

    // Return allocated memory
    return records;
}

void free_all(record* records, long* offsets, int* keys) {
    free(records);
    free(offsets);
    free(keys);
}
