#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

void* record_collection = NULL;

int record_set(int key, int offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        return -1; // Memory allocation failed
    }
    record->offset = offset;
    record->key = key;
    pthread_mutex_lock(&record_collection);
    if (record_collection == NULL) {
        record_collection = record;
    } else {
        Record* current = record_collection;
        while (current != NULL) {
            Record* next = current->offset > offset ? current : current->next;
            if (next == current) {
                current->next = record;
                break;
            }
            current = next;
        }
    }
    pthread_mutex_unlock(&record_collection);
    return 0; // Successful operation
}

int main() {
    return 0;
}
```

