#include <iostream>
#include <map>
#include <set>
#include <queue>
#include <functional>
#include <thread>

class UserSession {
public:
    int UserID;
    long LastActiveTime;
    std::string SessionState;
    std::string IPCountryCode;

    UserSession(int userID, long lastActiveTime, const std::string& sessionState, const std::string& ipCountryCode)
        : UserID(userID), LastActiveTime(lastActiveTime), SessionState(sessionState), IPCountryCode(ipCountryCode) {}
};

class SessionManager {
public:
    using SessionMap = std::map<int, UserSession>;
    using ActiveSessionsSet = std::set<UserSession*>;
    using ExpirationQueue = std::priority_queue<std::pair<long, int>, std::vector<std::pair<long, int>>, std::greater<std::pair<long, int>>>;

    SessionManager(size_t cacheSize) : activeSessions_(new ActiveSessionsSet()), expirationQueue_(), cacheSize_(cacheSize), localCache_(new SessionMap()) {}

    ~SessionManager() {
        delete activeSessions_;
        delete localCache_;
    }

    void addSession(int userID, long lastActiveTime, const std::string& sessionState, const std::string& ipCountryCode) {
        auto session = new UserSession(userID, lastActiveTime, sessionState, ipCountryCode);
        (*localCache_)[userID] = session;
        activeSessions_->insert(session);

        if (lastActiveTime > 0) {
            expirationQueue_.push({lastActiveTime, userID});
        }
    }

    void updateSession(int userID, long lastActiveTime, const std::string& sessionState) {
        auto it = localCache_->find(userID);
        if (it != localCache_->end()) {
            it->second.LastActiveTime = lastActiveTime;
            it->second.SessionState = sessionState;
        }
    }

    size_t getActiveSessionCount() const {
        return activeSessions_->size();
    }

    void expireSessions(long timestamp) {
        while (!expirationQueue_.empty()) {
            auto& pair = expirationQueue_.top();
            if (pair.first <= timestamp) {
                expireSession(pair.second);
                expirationQueue_.pop();
            } else {
                break;
            }
        }
    }

    void logExpirationEvent(int userID, long timestamp) {
        // Log session expiration event
    }

private:
    std::unique_ptr<ActiveSessionsSet> activeSessions_;
    ExpirationQueue expirationQueue_;
    size_t cacheSize_;
    std::unique_ptr<SessionMap> localCache_;

    void expireSession(int userID) {
        auto it = localCache_->find(userID);
        if (it != localCache_->end()) {
            // Remove session from local cache and active sessions set
            localCache_->erase(it);
            activeSessions_->erase(&(*it).second);

            // Update session management service
        }
    }
};
