void init_nfapicrcpool() {
    pthread_mutex_init(&nfapicrcpool.lock, NULL);
    nfapicrcpool.count = 0;
    nfapicrcpool.rnti_range_end = RNTI_VALID_RANGE;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the pool
void add_to_nfapicrcpool(NFAPI_CRC_INDICATION_PDU_T* new_structure) {
    pthread_mutex_lock(&nfapicrcpool.lock);

