        *maxConnections -= (int)(cpuUsage * 10);
        *cleanupInterval += 100;
    } else if (memoryUsage > 0.9f) {
        *maxConnections -= (int)(memoryUsage * 5);
        *cleanupInterval -= 50;
    }
}

// Periodically clean up inactive connections
void cleanupConnections(int* maxConnections, int* cleanupInterval, NetworkConnectionStatus** networkConnections) {
    // Simulate periodic cleanup
    for (int i = 0; i < *maxConnections; i++) {
        if (!isActiveConnection(networkConnections[i])) {
            free(networkConnections[i]);
            networkConnections[i] = NULL;
            (*maxConnections)--;
            break;
        }
    }
}

