// Define a struct to represent an event log entry
typedef struct {
    time_t timestamp;
    int source_ip;
    int dest_ip;
    int packet_size;
    int latency;
} EventLogEntry;

// Define a struct to store summary information about events
typedef struct {
    int count;
    float mean_latency;
    float mean_packet_size;
    float std_dev_latency;
    float std_dev_packet_size;
} EventSummary;

void process_events(int sock, char* metadata_service_url) {
    // Initialize event summaries and parsed logs
    EventSummary* summaries = NULL;
    size_t summary_count = 0;
    size_t total_bytes = 0;
    EventLogEntry* events = NULL;
    size_t event_count = 0;

    while (1) {
        char buffer[1024];
        int bytes_received = recv(sock, buffer, sizeof(buffer), MSG_DONTWAIT);
        if (bytes_received == -1) {
            // Handle socket errors
            perror("recv");
            break;
        }
        else if (bytes_received == 0) {
            // End of file reached; exit loop
            break;
        }

        // Parse log entries from buffer
        EventLogEntry* event = NULL;
        char* token = strtok(buffer, " ");
        while (token != NULL) {
            // Validate and enrich log entry using metadata service
            if (metadata_service_url != NULL && strlen(metadata_service_url) > 0) {
                // Call external metadata service to validate and enrich event
                EventLogEntry* enriched_event = get_enriched_event(token);
                if (enriched_event != NULL) {
                    event = enriched_event;
                    break;
                }
            }

            token = strtok(NULL, " ");
        }

        if (event != NULL) {
            // Calculate anomaly score for event
            float anomaly_score = calculate_anomaly_score(event);

            // Update event summary statistics
            EventSummary* current_summary = malloc(sizeof(EventSummary));
            current_summary->count++;
            current_summary->mean_latency += event->latency;
            current_summary->mean_packet_size += event->packet_size;
            current_summary->std_dev_latency += (event->latency - current_summary->mean_latency) * (event->latency - current_summary->mean_latency);
            current_summary->std_dev_packet_size += (event->packet_size - current_summary->mean_packet_size) * (event->packet_size - current_summary->mean_packet_size);

            // Reallocate event summaries if necessary
            if (summaries == NULL || summary_count >= 1000) {
                size_t new_size = summary_count + 1000;
                EventSummary** new_summaries = realloc(summaries, sizeof(EventSummary*) * new_size);
                if (new_summaries != NULL) {
                    summaries = new_summaries;
                }
            }

            // Add new event to summaries
            if (summaries != NULL && summary_count < 1000) {
                EventSummary* current_summary = &summaries[summary_count];
                current_summary->count++;
                current_summary->mean_latency /= current_summary->count;
                current_summary->mean_packet_size /= current_summary->count;
                current_summary->std_dev_latency /= (current_summary->count - 1);
                current_summary->std_dev_packet_size /= (current_summary->count - 1);

                if (summaries[summary_count].count >= 1000) {
                    // Filter out events with anomaly scores below threshold
                    float threshold = 2.5;
                    for (int i = 0; i < summary_count + 1; i++) {
                        if (calculate_anomaly_score(&events[i * sizeof(EventLogEntry)]) < threshold) {
                            free(events + i * sizeof(EventLogEntry));
                            summaries[summary_count].count--;
                        }
                    }
                }

                summaries[summary_count].count++;
            }

            // Log event and anomaly summary
            log_event(event, current_summary);

            free(event);
        }
    }

    // Clean up
    for (int i = 0; i < event_count; i++) {
        free(events + i * sizeof(EventLogEntry));
    }
    free(summaries);
}
