#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_CONCURRENT_CONNECTIONS 10000
#define IP_ADDRESS_RANGE 256
#define PORT_NUMBER_RANGE 65536

typedef struct {
    char ip_address[16];
    int port;
    int status; // 0 - closed, 1 - open
} TCP_CONNECTION_INFO;

TCP_CONNECTION_INFO* connection_list = NULL;
int current_connections = 0;

void add_connection(TCP_CONNECTION_INFO* new_conn) {
    if (current_connections >= MAX_CONCURRENT_CONNECTIONS) {
        // Fallback mechanism: Reduce the rate of generating new connections when address space is nearly exhausted
        printf("Address space nearly exhausted. Reducing connection rate.\n");
    }

    new_conn->status = 1; // Set status to open by default

    if (connection_list == NULL || strcmp(connection_list[current_connections-1].ip_address, new_conn->ip_address) != 0 
        || connection_list[current_connections-1].port != new_conn->port) {
        connection_list = realloc(connection_list, (current_connections+2)*sizeof(TCP_CONNECTION_INFO));
        memcpy(&connection_list[current_connections], new_conn, sizeof(TCP_CONNECTION_INFO));
        current_connections++;
    } else {
        printf("Error: Two consecutive connections cannot share the same IP address and port combination.\n");
    }
}

void remove_connection(int conn_index) {
    if (conn_index >= 0 && conn_index < current_connections) {
        connection_list[conn_index].status = 0; // Set status to closed
    } else {
        printf("Error: Connection index out of range.\n");
    }
}

int validate_ip_address(char* ip) {
    in_addr addr;
    if (inet_pton(AF_INET, ip, &addr)) {
        return 1;
    } else {
        return 0; // Invalid IP address
    }
}

int validate_port(int port) {
    if (port >= 0 && port <= PORT_NUMBER_RANGE) {
        return 1;
    } else {
        return 0; // Invalid port number
    }
}

void monitor_memory_usage() {
    printf("Current memory usage: %ld MB\n", (long)(getrusage(RUSAGE_SELF).ru_maxrss / 1024));
}

int main() {
    // Initialize connection list and validate IP addresses and port numbers
    if (connection_list == NULL) {
        connection_list = malloc(sizeof(TCP_CONNECTION_INFO)*2);
        current_connections = 0;
    }

    while (1) {
        // Read input from external network monitoring tool
        TCP_CONNECTION_INFO new_conn;
        strcpy(new_conn.ip_address, "192.168.1.100"); // Replace with actual IP address
        new_conn.port = 12345; // Replace with actual port number

        if (!validate_ip_address(new_conn.ip_address) || !validate_port(new_conn.port)) {
            printf("Invalid IP address or port number.\n");
            continue;
        }

        add_connection(&new_conn);

        // Monitor memory usage and performance metrics in real-time
        monitor_memory_usage();

        // Measure execution time using the `time` module
        clock_t start_time = clock();
        for (int i = 0; i < current_connections; i++) {
            if (!connection_list[i].status) {
                remove_connection(i);
            }
        }
        clock_t end_time = clock();
        printf("Execution time: %f seconds\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);
    }

    return 0;
}
