typedef struct LTE_PHY_TransportChannel {
    int TX_RX_STREAM_ID;
    int RNTI;
    char TRANSPORT_CHANNEL_TAG[16];
    int channelType;
} TransportChannel;

// Define a structure for the dynamic array
typedef struct {
    TransportChannel* data;
    size_t capacity, used;
} TransportChannelArray;

// Initialize the dynamic array
TransportChannelArray* init_TransportChannelArray() {
    TransportChannelArray* arr = (TransportChannelArray*) malloc(sizeof(TransportChannelArray));
    if (!arr) return NULL;

    arr->data = (TransportChannel*) malloc(sizeof(TransportChannel));
    arr->capacity = 1;
    arr->used = 0;
    return arr;
}

// Free the dynamic array
void free_TransportChannelArray(TransportChannelArray* arr) {
    if (!arr) return;

    free(arr->data);
    free(arr);
}

// Insert a new transport channel into the array
int insert_TransportChannel(TransportChannelArray* arr, TransportChannel* ch) {
    // Handle memory reallocation if necessary
    if (arr->used >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        arr->data = realloc(arr->data, new_capacity * sizeof(TransportChannel));
        arr->capacity = new_capacity;
    }

    arr->data[arr->used++] = *ch;
    return 0;
}

// Delete a transport channel from the array
int remove_TransportChannel(TransportChannelArray* arr, int idx) {
    if (idx < 0 || idx >= arr->used) return -1;

    // Shift elements to fill the gap
    for (size_t i = idx; i < arr->used - 1; ++i)
        arr->data[i] = arr->data[i + 1];

    --arr->used;
    return 0;
}

// Lookup a transport channel by its index
TransportChannel* lookup_TransportChannel(TransportChannelArray* arr, int idx) {
    if (idx < 0 || idx >= arr->used) return NULL;

    return &arr->data[idx];
}
