typedef struct LTE_PHY_TransportChannel {
    int TX_RX_STREAM_ID;
    int RNTI;
    int TRANSPORT_CHANNEL_TAG;
    int channelType;
} LTE_PHY_TransportChannel;

int transport_channel_size = 0;
LTE_PHY_TransportChannel* transport_channels = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* create_transport_channel(int TX_RX_STREAM_ID, int RNTI, int TRANSPORT_CHANNEL_TAG, int channelType) {
    pthread_mutex_lock(&lock);

    LTE_PHY_TransportChannel* new_channel = (LTE_PHY_TransportChannel*)malloc(sizeof(LTE_PHY_TransportChannel));
    if (new_channel == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    new_channel->TX_RX_STREAM_ID = TX_RX_STREAM_ID;
    new_channel->RNTI = RNTI;
    new_channel->TRANSPORT_CHANNEL_TAG = TRANSPORT_CHANNEL_TAG;
    new_channel->channelType = channelType;

    if (transport_channels == NULL) {
        transport_channels = (LTE_PHY_TransportChannel*)malloc(sizeof(LTE_PHY_TransportChannel));
        transport_channel_size++;
    } else {
        LTE_PHY_TransportChannel** new_array = (LTE_PHY_TransportChannel**)realloc(transport_channels, sizeof(LTE_PHY_TransportChannel*) * ++transport_channel_size);
        if (new_array == NULL) {
            printf("Memory reallocation failed.\n");
            free(new_channel);
            return NULL;
        }
        transport_channels = new_array;
    }

    transport_channels[transport_channel_size - 1] = new_channel;

    pthread_mutex_unlock(&lock);

    return new_channel;
}

void log_transport_channel(LTE_PHY_TransportChannel* channel) {
    printf("Transport Channel Created: TX_RX_STREAM_ID = %d, RNTI = %d, TRANSPORT_CHANNEL_TAG = %d, channelType = %d\n", 
           channel->TX_RX_STREAM_ID, channel->RNTI, channel->TRANSPORT_CHANNEL_TAG, channel->channelType);
}

void free_transport_channel(LTE_PHY_TransportChannel* channel) {
    pthread_mutex_lock(&lock);

    if (channel != NULL) {
        int i;
        for (i = 0; i < transport_channel_size; i++) {
            if (transport_channels[i] == channel) {
                break;
            }
        }

        if (i < transport_channel_size) {
            free(channel);
            for (int j = i; j < --transport_channel_size; j++) {
                transport_channels[j] = transport_channels[++j];
            }
            transport_channels[transport_channel_size] = NULL;
        } else {
            printf("Transport Channel not found.\n");
        }
    }

    pthread_mutex_unlock(&lock);
}

void print_transport_channels() {
    pthread_mutex_lock(&lock);

    int i;
    for (i = 0; i < transport_channel_size; i++) {
        LTE_PHY_TransportChannel* channel = transport_channels[i];
        printf("Transport Channel: TX_RX_STREAM_ID = %d, RNTI = %d, TRANSPORT_CHANNEL_TAG = %d, channelType = %d\n", 
               channel->TX_RX_STREAM_ID, channel->RNTI, channel->TRANSPORT_CHANNEL_TAG, channel->channelType);
    }

    pthread_mutex_unlock(&lock);
}

void compact_transport_channels() {
    int i;
    for (i = 0; i < transport_channel_size; i++) {
        if (transport_channels[i] == NULL) {
            break;
        }
    }

    LTE_PHY_TransportChannel** new_array = (LTE_PHY_TransportChannel**)realloc(transport_channels, sizeof(LTE_PHY_TransportChannel*) * i);
    if (new_array != NULL) {
        transport_channels = new_array;
        transport_channel_size = i;
    } else {
        printf("Memory reallocation failed.\n");
    }
}

void* destroy_transport_channels(void* arg) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < transport_channel_size; i++) {
        free(transport_channels[i]);
    }

    free(transport_channels);
    transport_channel_size = 0;
    transport_channels = NULL;

    pthread_mutex_unlock(&lock);
}
