#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>

class UserSession {
public:
    int userId;
    std::chrono::system_clock::time_point sessionStartTime;
    std::chrono::system_clock::time_point lastActivityTime;
    bool sessionStatus;

    UserSession(int userId, std::chrono::system_clock::time_point sessionStartTime, 
                std::chrono::system_clock::time_point lastActivityTime, bool sessionStatus)
        : userId(userId), sessionStartTime(sessionStartTime), 
          lastActivityTime(lastActivityTime), sessionStatus(sessionStatus) {}
};

class SessionManager {
public:
    using SessionList = std::vector<UserSession>;
    using Logger = std::function<void(const UserSession&)>;

    SessionManager(Logger logger);
    ~SessionManager();

    void addUserSession(UserSession session);
    void removeUserSession(int userId);
    UserSession* getUserSession(int userId);

private:
    mutable std::mutex mtx;
    SessionList sessions;
    Logger logFunc;

    void logSession(const UserSession& session) {
        logFunc(session);
    }
};

SessionManager::SessionManager(Logger logger)
    : logFunc(logger), sessions() {}

SessionManager::~SessionManager() {
    for (const auto& session : sessions) {
        logSession(session);
    }
}

void SessionManager::addUserSession(UserSession session) {
    std::lock_guard<std::mutex> lock(mtx);

    sessions.push_back(session);

    logSession(session);
}

void SessionManager::removeUserSession(int userId) {
    std::lock_guard<std::mutex> lock(mtx);

    for (auto it = sessions.begin(); it != sessions.end();) {
        if (it->userId == userId) {
            it = sessions.erase(it);
            logSession(*it);
        } else {
            ++it;
        }
    }
}

UserSession* SessionManager::getUserSession(int userId) {
    std::lock_guard<std::mutex> lock(mtx);

    for (const auto& session : sessions) {
        if (session.userId == userId) {
            return &session;
        }
    }

    return nullptr;
}
