    struct record* records = (struct record*)malloc(num_instances * sizeof(struct record));

    // Read integers from standard input and store in auxiliary array
    int i, temp;
    scanf("%d", &temp);
    for (i = 0; i < num_instances; i++) {
        scanf("%d", &temp);
        keys[i] = temp;
    }

    // Find largest integer in the array using a helper function
    int max_key = find_max_key(keys, num_instances);

    // Initialize NFAPI_CRC_INDICATION_PDU_T structures
    for (i = 0; i < num_instances; i++) {
        records[i].RX_UE_INFORMATION_TAG = rand();
        records[i].RNTI = i + 1;
        records[i].CRC_INDICATION_REL8_TAG = rand();
        records[i].CRCFLAG = rand();
    }

    // Print the largest integer and the initialized structures
    printf("Largest key: %d\n", max_key);
    for (i = 0; i < num_instances; i++) {
        printf("RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", records[i].RNTI, records[i].CRC_INDICATION_REL8_TAG, records[i].CRCFLAG);
    }

    // Free allocated memory
    free(offset_values);
    free(keys);
    free(records);

    return 0;
}

int find_max_key(int* keys, int num_instances) {
    int max_key = keys[0];
    int i;
    for (i = 1; i < num_instances; i++) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }
    return max_key;
}
