typedef enum {
    EVENT_TYPE_INFO,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_ERROR
} EventType;

typedef struct EventNode {
    EventType type;
    int severity;
    time_t time_occurred;
    struct EventNode* next;
} EventNode;

typedef struct Monitor {
    time_t timestamp;
    int status;
    pthread_mutex_t lock;
    EventNode* head;
    EventNode* tail;
} Monitor;

Monitor* allocate_monitor(void) {
    Monitor* monitor = (Monitor*) malloc(sizeof(Monitor));
    if (!monitor) {
        return NULL; // Handle allocation failure
    }
    monitor->timestamp = 0;
    monitor->status = 0;
    pthread_mutex_init(&monitor->lock, NULL);
    monitor->head = NULL;
    monitor->tail = NULL;
    return monitor;
}

EventNode* allocate_event(void) {
    EventNode* event = (EventNode*) malloc(sizeof(EventNode));
    if (!event) {
        return NULL; // Handle allocation failure
    }
    event->type = EVENT_TYPE_INFO;
    event->severity = 0;
    event->time_occurred = time(NULL);
    event->next = NULL;
    return event;
}

void monitor_event(Monitor* monitor, EventType type, int severity) {
    pthread_mutex_lock(&monitor->lock);
    EventNode* new_node = allocate_event();
    if (!new_node) {
        // Handle allocation failure
    }
    new_node->type = type;
    new_node->severity = severity;
    new_node->time_occurred = time(NULL);

    if (monitor->tail) {
        monitor->tail->next = new_node;
        monitor->tail = new_node;
    } else {
        monitor->head = new_node;
        monitor->tail = new_node;
    }
    pthread_mutex_unlock(&monitor->lock);
}

void periodic_garbage_collection(Monitor* monitor) {
    // Implementation omitted for brevity
}

// Example usage:
int main() {
    Monitor* monitor = allocate_monitor();
    if (!monitor) {
        // Handle allocation failure
    }

    monitor_event(monitor, EVENT_TYPE_INFO, 0);
    monitor_event(monitor, EVENT_TYPE_WARNING, 1);

    periodic_garbage_collection(monitor);

    return 0;
}
