typedef struct {
    char* filename;
    long fileSize;
    time_t lastModified;
} FileMetadata;

FileMetadata* manageFileMetadata(int numFiles) {
    FileMetadata* metadata = (FileMetadata*)malloc(numFiles * sizeof(FileMetadata));
    if (!metadata) return NULL;

    for (int i = 0; i < numFiles; i++) {
        char buffer[256];
        fgets(buffer, 256, stdin);
        metadata[i].filename = malloc(strlen(buffer) + 1);
        strcpy(metadata[i].filename, buffer);
        metadata[i].fileSize = strlen(buffer);
        metadata[i].lastModified = time(NULL);
    }

    // Helper function to print the file with the largest size
    long maxFileSize = 0;
    for (int i = 0; i < numFiles; i++) {
        if (metadata[i].fileSize > maxFileSize) {
            maxFileSize = metadata[i].fileSize;
        }
    }
    printf("File with largest size: %s\n", metadata[maxFileSize - 1].filename);

    // Sort file metadata by size in descending order
    for (int i = 0; i < numFiles; i++) {
        for (int j = i + 1; j < numFiles; j++) {
            if (metadata[i].fileSize > metadata[j].fileSize) {
                FileMetadata temp = metadata[i];
                metadata[i] = metadata[j];
                metadata[j] = temp;
            }
        }
    }

    // Print file details
    for (int i = 0; i < numFiles; i++) {
        printf("File: %s, Size: %ld, Last Modified: %lu\n", 
               metadata[i].filename, metadata[i].fileSize, metadata[i].lastModified);
        free(metadata[i].filename);
    }
    free(metadata);

    return NULL;
}
