    int interface_id;
    int error_code;
    struct {
        int id;
        int status;
    } *tags;
    struct Metric **metrics;
} NetworkEvent;

// Function to manage and initialize complex data structures
void init_network_interface_status_updates(int num_interfaces) {
    // Initialize semaphores for synchronization
    sem_t *semaphore = sem_open("/my_semaphore", O_CREAT | O_RDWR, 0644, 1);
    if (semaphore == SEM_FAILED) {
        printf("Error initializing semaphore\n");
        return;
    }

    // Dynamically allocate memory for data structures
    long **offset_values = (long **)malloc(num_interfaces * sizeof(long *));
    int **keys = (int **)malloc(num_interfaces * sizeof(int *));
    Record **records = (Record **)malloc(num_interfaces * sizeof(Record *));
    NFAPI_CRC_INDICATION_PDU_T **pdu_tags = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_interfaces * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    NetworkEvent **events = (NetworkEvent **)malloc(num_interfaces * sizeof(NetworkEvent *));
    for (int i = 0; i < num_interfaces; i++) {
        offset_values[i] = (long *)malloc(sizeof(long));
        keys[i] = (int *)malloc(sizeof(int));
        records[i] = (Record *)malloc(sizeof(Record));
        pdu_tags[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        events[i] = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    }

    // Initialize data structures
    for (int i = 0; i < num_interfaces; i++) {
        *offset_values[i] = i;
        *keys[i] = i;
        records[i]->value = i;
        records[i]->timestamp = time(NULL);
        strcpy(records[i]->status_message, "initialized");
        pdu_tags[i]->rx_ue_info_tag = (RX_UE_INFORMATION_TAG *)malloc(sizeof(RX_UE_INFORMATION_TAG));
        pdu_tags[i]->rnti = i;
        pdu_tags[i]->crcflag = rand() % 2;
        events[i]->timestamp = time(NULL);
        events[i]->interface_id = i;
        events[i]->error_code = 0;

        // Initialize linked list of performance metrics
        Metric **metrics = (Metric **)malloc(sizeof(Metric *));
        for (int j = 0; j < 10; j++) {
            Metric *metric = (Metric *)malloc(sizeof(Metric));
            metric->type = METRIC_TYPE_CPU_USAGE;
            metric->value = i + j;
            strcpy(metric->description, "CPU usage");
            metrics[j] = metric;
        }
        events[i]->metrics = metrics;

        // Initialize list of event tags
        EventTag **tags = (EventTag **)malloc(sizeof(EventTag *));
        for (int j = 0; j < 5; j++) {
            EventTag *tag = (EventTag *)malloc(sizeof(EventTag));
            tag->id = i + j;
            tag->status = rand() % 2;
            tags[j] = tag;
        }
        events[i]->tags = tags;
    }

    // Serialize data structures
    serialize_data_structures(events, num_interfaces);

    // Release semaphores and deallocate memory
    sem_close(semaphore);
    for (int i = 0; i < num_interfaces; i++) {
        free(offset_values[i]);
        free(keys[i]);
        free(records[i]);
        free(pdu_tags[i]);
        free(events[i]->metrics);
        free(events[i]->tags);
    }
    free(semaphore);
}

// Function to serialize data structures
void serialize_data_structures(NetworkEvent **events, int num_interfaces) {
    // Open a file for writing
    FILE *file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Write serialized data to file
    for (int i = 0; i < num_interfaces; i++) {
        NetworkEvent *event = events[i];
        fwrite(&event->timestamp, sizeof(double), 1, file);
        fwrite(&event->interface_id, sizeof(int), 1, file);
        fwrite(&event->error_code, sizeof(int), 1, file);

        // Serialize linked list of performance metrics
        for (int j = 0; event->metrics[j]; j++) {
            Metric *metric = event->metrics[j];
            fwrite(&metric->type, sizeof(enum Metric_Type), 1, file);
            fwrite(&metric->value, sizeof(double), 1, file);
            strcpy(metric->description, "CPU usage");
            fwrite(metric->description, sizeof(char), strlen(metric->description) + 1, file);
        }

        // Serialize list of event tags
        for (int j = 0; event->tags[j]; j++) {
            EventTag *tag = event->tags[j];
            fwrite(&tag->id, sizeof(int), 1, file);
            fwrite(&tag->status, sizeof(int), 1, file);
        }
    }

    // Close the file
    fclose(file);
}

// Function to deserialize data structures
void deserialize_data_structures() {
    // Open a file for reading
    FILE *file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Read serialized data from file
    NetworkEvent **events = (NetworkEvent **)malloc(sizeof(NetworkEvent *));
    int num_interfaces;
    fread(&num_interfaces, sizeof(int), 1, file);

    for (int i = 0; i < num_interfaces; i++) {
        NetworkEvent *event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
        fread(&event->timestamp, sizeof(double), 1, file);
        fread(&event->interface_id, sizeof(int), 1, file);
        fread(&event->error_code, sizeof(int), 1, file);

        // Deserialize linked list of performance metrics
        Metric **metrics = (Metric **)malloc(sizeof(Metric *));
        for (int j = 0; ; j++) {
            Metric *metric = (Metric *)malloc(sizeof(Metric));
            fread(&metric->type, sizeof(enum Metric_Type), 1, file);
            fread(&metric->value, sizeof(double), 1, file);
            metric->description[127];
            fread(metric->description, sizeof(char), strlen(metric->description) + 1, file);

            // Check if we reached the end of the list
            if (fread(&j, sizeof(int), 1, file) != 1) {
                break;
            }

            metrics[j] = metric;
        }
        event->metrics = metrics;

        // Deserialize list of event tags
        EventTag **tags = (EventTag **)malloc(sizeof(EventTag *));
        for (int j = 0; ; j++) {
            EventTag *tag = (EventTag *)malloc(sizeof(EventTag));
            fread(&tag->id, sizeof(int), 1, file);
            fread(&tag->status, sizeof(int), 1, file);

            // Check if we reached the end of the list
            if (fread(&j, sizeof(int), 1, file) != 1) {
                break;
            }

            tags[j] = tag;
        }
        event->tags = tags;
    }

    // Close the file
    fclose(file);
}
