#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 50000
#define MAX_EVENTS 1000
#define BUFFER_SIZE 1024

typedef struct {
    double timestamp;
    long interface_id;
    int error_code;
    short *event_tags;
} NetworkInterfaceStatus;

NetworkInterfaceStatus* interfaces = NULL;
int num_interfaces = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_status(NetworkInterfaceStatus* status) {
    pthread_mutex_lock(&mutex);
    interfaces = realloc(interfaces, (num_interfaces + 1) * sizeof(NetworkInterfaceStatus));
    interfaces[num_interfaces] = *status;
    num_interfaces++;
    pthread_mutex_unlock(&mutex);
}

void update_status(long interface_id, int error_code, short *event_tags) {
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < num_interfaces; i++) {
        if(interfaces[i].interface_id == interface_id) {
            interfaces[i].error_code = error_code;
            interfaces[i].event_tags = event_tags;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int get_num_interfaces_with_errors() {
    int count = 0;
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < num_interfaces; i++) {
        if(interfaces[i].error_code > 0) {
            count++;
        }
    }
    pthread_mutex_unlock(&mutex);
    return count;
}
