#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define enum for event types
enum EventType {
    EVENT_TYPE_1,
    EVENT_TYPE_2,
    // Add more event types as needed
};

// Define structure for Event data
typedef struct {
    int timestamp;
    enum EventType type;
    char message[64];  // Initial message size, can grow as needed
} Event;

// Define structure for Item data
typedef struct {
    int value;
    double precision_value;
} Item;

// Custom memory pool to manage allocated memory blocks
void* pool_malloc(size_t size) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static char* pool_start = NULL;
    static char* pool_end = NULL;
    static int num_blocks = 0;

    pthread_mutex_lock(&lock);
    if (pool_start == NULL) {
        // Initialize the memory pool
        size_t initial_pool_size = 1024 * 1024;  // 1MB initial pool size
        pool_start = malloc(initial_pool_size);
        pool_end = pool_start + initial_pool_size;
        num_blocks = 0;
    }

    if (pool_end - pool_start < size) {
        // Need to allocate a new block
        size_t new_block_size = 1024 * 64;  // 64KB new block size
        char* new_block = realloc(pool_end, pool_end - pool_start + new_block_size);
        pool_start = new_block;
        pool_end = pool_start + new_block_size;
    }

    void* result = pool_start;
    pool_start += size;
    num_blocks++;

    pthread_mutex_unlock(&lock);

    return result;
}

// Custom memory pool to free allocated memory blocks
void pool_free(void* ptr) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    // Update the memory pool start pointer and number of blocks
    if (pool_start == ptr) {
        pool_start += ((char*)ptr - pool_start) + 1024 * 64;  // Adjust for new block size
    }
    num_blocks--;
    pthread_mutex_unlock(&lock);

    free(ptr);
}

// Function to manage dynamic allocation and initialization of data structures
void* allocate_and_init(void** item_ptr, void** event_ptr) {
    int random_value = rand() % 100 + 1;  // Random integer within range [1, 100]
    Item* item = (Item*)pool_malloc(sizeof(Item));
    item->value = random_value;
    item->precision_value = (double)random_value;

    Event* event = (Event*)pool_malloc(sizeof(Event));
    event->timestamp = time(NULL);
    event->type = EVENT_TYPE_1;  // Default event type
    strcpy(event->message, "Initial message");  // Initial message size

    *item_ptr = item;
    *event_ptr = event;

    return NULL;
}

// Function to release allocated memory blocks
void deallocate(void* ptr) {
    pool_free(ptr);
}
