NFAPI_CRC_INDICATION_PDU_T* create_NFAPI_CRC_INDICATION_PDU(int N) {
    if (N <= 0) {
        printf("Invalid number of elements. N must be greater than zero.\n");
        return NULL;
    }

    int max_N = 10000; // predefined maximum value
    if (N > max_N) {
        printf("Number of elements exceeds the maximum allowed (%d). Limiting to %d.\n", N, max_N);
        N = max_N;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // seed for random number generation
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 100;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        array[i].CRCFLAG = rand() % 2; // random binary flag
    }

    return array;
}

void free_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
