record* create_database(int unique_keys_size) {
    // Define a magic number for size calculation
    const int MAGIC_NUMBER = 16;  // Adjust according to the dataset

    // Calculate the actual size based on the magic number
    int memory_offsets_size = (unique_keys_size * MAGIC_NUMBER);
    record* records = (record*) malloc(unique_keys_size * sizeof(record));
    long* memory_offsets = (long*) malloc(memory_offsets_size * sizeof(long));

    if (!records || !memory_offsets) {
        free(records);
        free(memory_offsets);
        return NULL;  // Out of memory
    }

    FILE* file = fopen("your_file.txt", "r");
    if (file == NULL) {
        fclose(file);
        free(records);
        free(memory_offsets);

        printf("Failed to open the file.\n");
        return NULL;  // File not found or unable to open
    }

    int record_index = 0;
    for (int i = 0; i < unique_keys_size; i++) {
        fscanf(file, "%d\n", &records[i].value);
    }

    fclose(file);

    // Initialize memory offsets and unique keys
    for (int i = 0; i < memory_offsets_size; i += MAGIC_NUMBER) {
        memory_offsets[i / MAGIC_NUMBER] = i;
    }

    return records;
}

void free_database(record* database) {
    if (!database) {
        return;  // No database to free
    }

    free((long*) (database + sizeof(record)));
    free(database);
}
