int init_memory(long num_offsets, int num_keys, int max_value) {
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) return 1; // Allocation failure

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) return 2; // Allocation failure

    record_t* records = (record_t*)malloc((num_offsets / num_keys) * sizeof(record_t));
    if (!records) return 3; // Allocation failure

    srand(time(NULL)); // Initialize random number generator
    for (int i = 0; i < num_offsets / num_keys; i++) {
        for (int j = 0; j < num_keys; j++) {
            int value = rand() % max_value;
            if (value > max_value) return 4; // Out-of-bounds error
            records[i * num_keys + j].value = value;
        }
    }

    free(offsets);
    free(keys);

    return 0; // Success
}

void free_memory(long* offsets, int* keys, record_t* records, long num_offsets, int num_keys) {
    free(records);
}

int main() {
    long num_offsets = 100;
    int num_keys = 5;
    int max_value = 255;

    if (init_memory(num_offsets, num_keys, max_value)) {
        printf("Error: %d\n", init_memory(num_offsets, num_keys, max_value));
        return 1; // Exit with error
    }

    // Use the allocated memory here...

    free_memory(NULL, NULL, NULL, num_offsets, num_keys);

    return 0;
}
