        message->enb_rrc_msg_type_tag = (int)(rand() % 100);
        message->s1ap_message_id = i;
        message->enb_rrc_message_rel14_tag = (int)(rand() % 200) + 10;
        message->paging_flag = rand() & 0x1;

        messages[i] = message;
        count++;
    }

    return count;
}

