    for (i = 0; i < n; i++) {
        char sequence[CHAR_SEQUENCE_SIZE];

        // Generate random sequence
        for (j = 0; j < CHAR_SEQUENCE_SIZE; j++) {
            int r = rand() % CHAR_SEQUENCE_COUNT;
            sprintf(&sequence[j], "%c", 'A' + r);
        }

        records[i].l = (long)rand();
        records[i].i = rand() % INT_MAX;
        strcpy(records[i].c, sequence);
    }

    return records;
}

void free_records(record_t* records, int n) {
    if (!records || n <= 0) {
        return;
    }

    free(records);
