        statuses[i] = s;

        // Update arrays and log messages
        doubles[i] = static_cast<double>(dp.value);
        timestamps[i] = timestamp;
        data_points[i] = dp;
        log_messages[i] = dp.log_message;
    }

    // Implement callback mechanism for error handling
    void (*error_handler)(const char*) = nullptr;

    if (error_handler != nullptr) {
        error_handler("Error occurred during array allocation");
    }

    free(doubles);
    free(timestamps);
    free(data_points);
    free(statuses);
    free(log_messages);

    // Release allocated memory and log messages
    for (size_t i = 0; i < max_size; ++i) {
        free(log_messages[i]);
    }
}

