#define MAX_PHY_TASKS 1024
#define POOL_SIZE 128
#define LOCK_GRANULARITY 16

typedef struct {
    char tx_frame_info_tag[32];
    char rx_frame_info_tag[32];
    int phy_channel_state_tag;
} PHY_TASK_T;

void* pool[POOL_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int alloc_phy_tasks(int N) {
    if (N > MAX_PHY_TASKS) {
        printf("Error: Maximum number of tasks exceeded. Limit is %d.\n", MAX_PHY_TASKS);
        return -1;
    }

    void* ptr = NULL;
    for (int i = 0; i < POOL_SIZE && !ptr; i++) {
        pthread_mutex_lock(&lock);
        if (!pool[i]) {
            pool[i] = malloc(N * sizeof(PHY_TASK_T));
            if (!pool[i]) {
                printf("Error: Memory allocation failed.\n");
                return -1;
            }
        } else {
            ptr = pool[i];
        }
        pthread_mutex_unlock(&lock);
    }

    if (!ptr) {
        for (int i = 0; i < N; i++) {
            PHY_TASK_T* task = (PHY_TASK_T*)malloc(sizeof(PHY_TASK_T));
            if (!task) {
                printf("Error: Memory allocation failed.\n");
                return -1;
            }
            // Set frequency band and bandwidth parameters
            strcpy(task->tx_frame_info_tag, "TX FRAME INFO TAG");
            strcpy(task->rx_frame_info_tag, "RX FRAME INFO TAG");
            task->phy_channel_state_tag = 0;  // Set frequency band and bandwidth parameters
            free(task);
        }
    } else {
        for (int i = 0; i < N; i++) {
            PHY_TASK_T* task = (PHY_TASK_T*)ptr;
            // Set frequency band and bandwidth parameters
            strcpy(task[i].tx_frame_info_tag, "TX FRAME INFO TAG");
            strcpy(task[i].rx_frame_info_tag, "RX FRAME INFO TAG");
            task[i].phy_channel_state_tag = 0;  // Set frequency band and bandwidth parameters
        }
    }

    return ptr;
}

void free_phy_tasks(void* ptr) {
    if (!ptr)
        return;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < POOL_SIZE; i++) {
        if (pool[i] == ptr) {
            free(ptr);
            pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* get_phy_task(void* ptr, int N) {
    void* task = ptr;
    for (int i = 0; i < N; i++) {
        // Return the ith PHY_TASK_T structure
        return (void*)task;
    }
    return NULL;
}
