#include <stdio.h>
#include <stdlib.h>
#include <float.h>

typedef enum {
    PENDING,
    SUCCESS,
    FAILURE
} OperationStatus;

typedef struct {
    double value;
    float x, y;
    OperationStatus status;
} Operation;

Operation* create_operation(double value, float x, float y) {
    Operation* op = (Operation*)malloc(sizeof(Operation));
    if (!op) {
        return NULL;  // Out of memory
    }
    op->value = value;
    op->x = x;
    op->y = y;
    op->status = PENDING;
    return op;
}

void process_operation(Operation* op) {
    if (op == NULL) {
        return;  // Invalid operation
    }

    // Simulate processing operation
    int status_code = rand() % 3;
    switch (status_code) {
        case 0:
            op->status = SUCCESS;
            break;
        case 1:
            op->status = FAILURE;
            break;
        default:
            op->status = PENDING;  // Operation is still pending
    }
}

void free_operation(Operation* op) {
    if (op == NULL) {
        return;  // No operation to free
    }

    free(op);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    int num_operations = 5;
    Operation** operations = (Operation**)malloc(num_operations * sizeof(Operation*));
    for (int i = 0; i < num_operations; i++) {
        Operations[i] = create_operation(i, (float)i, (float)i);

        // Process each operation
        process_operation(operations[i]);

        printf("Operation %d: Value %.2f, Coordinates (%.2f, %.2f), Status %s\n", 
               i, operations[i]->value, operations[i]->x, operations[i]->y, 
               (operations[i]->status == PENDING) ? "Pending" : 
               ((operations[i]->status == SUCCESS) ? "Success" : "Failure"));

        free_operation(operations[i]);
    }

    for (int i = 0; i < num_operations; i++) {
        free_operation(operations[i]);
    }

    free(operations);

    return 0;
}
