    if (arr->capacity <= 0) {
        // Handle out-of-memory condition or resize the array
        printf("Error: Out of memory!\n");
        exit(1);
    }
    // Insert new pdu at the end of the array
    memcpy(&arr->arr[arr->capacity - 1], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity++;
    pthread_mutex_unlock(&arr->lock);
}

// Function to periodically clean up unused structures
void* nfaapi_crc_indication_pdu_array_cleanup(void* arg) {
