                // Remove the structure
                memmove(&arr->arr[i], &arr->arr[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                i--;
                arr->capacity--;
            }
            i++;
        }
        pthread_mutex_unlock(&arr->lock);
        // Signal cleanup completion
        pthread_cond_signal(&arr->clean_up_signal);
    }
}

// Function to signal cleanup completion and wake up the cleaner thread
void nfaapi_crc_indication_pdu_array_clean_up_signal(DynamicArray* arr) {
    pthread_cond_signal(&arr->clean_up_signal);
