typedef struct {
    int value;
} record_t;

record_t* initialize_records(int num_keys) {
    // Initialize memory for unique keys
    int *unique_keys = (int *)malloc(sizeof(int) * num_keys);
    if (!unique_keys) {
        return NULL;
    }

    // Initialize memory for records
    record_t *records = (record_t *)malloc(sizeof(record_t) * num_keys);
    if (!records) {
        free(unique_keys);
        return NULL;
    }

    // Initialize unique keys and records
    for (int i = 0; i < num_keys; i++) {
        unique_keys[i] = i;
        records[i].value = i;
    }

    // Return memory pointers
    return records;
}

void* allocate_memory(size_t size) {
    void *memory = malloc(size);
    if (!memory) {
        return NULL;
    }
    return memory;
}

int main() {
    int num_keys = 10; // configurable parameter

    record_t *records = initialize_records(num_keys);

    for (int i = 0; i < num_keys; i++) {
        printf("%d: %d\n", i, records[i].value);
    }

    free(records);
    return 0;
}

