void processImageRequests() {
    // Read image file paths from standard input
    FILE* f = stdin;
    char line[256];
    while (fgets(line, sizeof(line), f)) {
        // Trim newline character at the end
        int len = strlen(line);
        if (line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }

        // Check image file existence and readability
        struct stat sb;
        if (!stat(line, &sb) && S_ISREG(sb.st_mode) && sb.st_mode & S_IRUSR) {
            // Verify required command-line tool installation
            const char* cmd_tool_path = getenv("CMD_TOOL_PATH");
            if (cmd_tool_path != NULL) {
                // Determine whether image needs conversion to PDF
                const char* output_format = "PDF";
                if (strcasecmp(output_format, sb.st_mode & S_IRUSR)) {
                    // Convert image to PDF using command-line tool
                    int fd = open(line, O_RDONLY);
                    if (fd >= 0) {
                        FILE* outf = fopen("output.pdf", "w");
                        if (outf != NULL) {
                            // Execute command-line tool and redirect output to file
                            system(cmd_tool_path);

                            // Deserialize byte buffer containing image metadata
                            char* buf = malloc(MAX_CACHE_SIZE);
                            int bytes_read = fread(buf, 1, MAX_CACHE_SIZE, outf);
                            struct {
                                int x;
                                int y;
                            } meta;
                            memmove(&meta, buf, sizeof(meta));

                            // Log success message upon successful conversion and deserialization
                            printf("Image converted successfully.\n");

                            free(buf);
                        }
                        close(fd);
                    }

                }
            }
        }
    }
}
