    session_data = realloc(session_data, (num_sessions + 1) * sizeof(SessionData));
    session_data[num_sessions] = *new_session;
    num_sessions++;
    free(new_session);
    pthread_mutex_unlock(&lock);
    return &session_data[num_sessions - 1];
}

void* delete_session(void* id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_sessions; i++) {
        if (((SessionData*)id == &session_data[i])) {
            // Reclaim memory here
            memmove(&session_data[i], &session_data[i + 1], (num_sessions - i - 1) * sizeof(SessionData));
            num_sessions--;
            free(id);
            return NULL;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
