// Structure to represent log entries
typedef struct {
    int id;
    long timestamp;
    int level;
    char* message;
} LogEntry;

// Memory pool for dynamic memory management
void** memory_pool = NULL;
int memory_pool_size = 0;
int memory_pool_max_size = 0;
int memory_pool_threshold = 16; // growth threshold

// Function to allocate log entries dynamically
LogEntry* allocate_log_entry() {
    if (memory_pool_size == memory_pool_max_size) {
        int new_size = memory_pool_max_size + memory_pool_threshold;
        void** new_memory = realloc(memory_pool, sizeof(void*) * new_size);
        if (!new_memory) return NULL; // out of memory
        memory_pool = new_memory;
        memory_pool_max_size = new_size;
    }
    return (LogEntry*)memory_pool[memory_pool_size++];
}

// Function to deallocate log entries dynamically
void free_log_entry(LogEntry* entry) {
    if (!entry) return;
    int index = (int)(long)(entry - memory_pool);
    if (index >= 0 && index < memory_pool_size) {
        memset(entry, 0, sizeof(*entry));
        memory_pool[index] = NULL;
        if (index == (memory_pool_size -= 1)) memory_pool[memory_pool_size] = NULL;
    }
}

// Function to resize the log entries dynamically
void resize_log_entries(int new_size) {
    void** new_memory = realloc(memory_pool, sizeof(void*) * new_size);
    if (!new_memory) return; // out of memory
    memory_pool = new_memory;
    memory_pool_max_size = new_size;
}

// Function to access individual log entries
LogEntry* get_log_entry(int index) {
    if (index >= 0 && index < memory_pool_size) {
        return (LogEntry*)memory_pool[index];
    }
    return NULL;
}
