    int* keys = (int*)malloc(sizeof(int) * 100);
    record_t* records = (record_t*)malloc(sizeof(record_t) * 100);

    // Read integers from standard input and store in auxiliary array
    int aux[100];
    int count = 0;
    while (scanf("%d", &aux[count]) == 1) {
        if (count >= sizeof(aux) / sizeof(int)) {
            printf("Error: Input size exceeds allocated memory.\n");
            break;
        }
        count++;
    }

    // Helper function to find and print smallest, largest, duplicates
    void analyzeArray() {
        int min = aux[0], max = aux[0];
        int* seen = (int*)malloc(sizeof(int) * sizeof(aux));
        for (int i = 1; i < count; i++) {
            if (aux[i] < min)
                min = aux[i];
            else if (aux[i] > max)
                max = aux[i];
            int found = 0;
            for (int j = 0; j < i; j++) {
                if (aux[j] == aux[i]) {
                    seen[i]++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                seen[i] = 1;
            }
        }

        // Print results
        printf("Smallest: %d\n", min);
        printf("Largest: %d\n", max);
        for (int i = 0; i < count; i++) {
            if (seen[i] > 1)
                printf("%d appears %d times.\n", aux[i], seen[i]);
        }
    }

    // Call helper function to analyze input array
    analyzeArray();

    // Free dynamically allocated memory
    free(offsets);
    free(keys);
    free(records);

    return;
}
