// Thread-safe dynamic array of user sessions
UserSession* g_sessions = NULL;
int g_session_count = 0;

// Thread-safe mutex for updating and cleaning up sessions
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_session(int UserID, char* SessionToken, time_t LastActivityTime) {
    pthread_mutex_lock(&session_mutex);
    if (g_session_count >= MAX_SESSIONS) {
        // Handle full array case
    }
    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->UserID = UserID;
    strcpy(new_session->SessionToken, SessionToken);
    new_session->LastActivityTime = LastActivityTime;
    new_session->SessionState = 1; // assume logged in initially
    if (g_session_count == 0) {
        g_sessions = new_session;
    } else {
        UserSession* current_session = g_sessions;
        while (current_session) {
            current_session->LastActivityTime = LastActivityTime;
            current_session = current_session->next;
        }
    }
    g_session_count++;
    pthread_mutex_unlock(&session_mutex);
}

void update_session(int UserID, int SessionState) {
    pthread_mutex_lock(&session_mutex);
    UserSession* session = g_sessions;
    while (session) {
        if (session->UserID == UserID) {
            session->SessionState = SessionState;
            break;
        }
        session = session->next;
    }
    pthread_mutex_unlock(&session_mutex);
}

int get_active_session_count() {
    pthread_mutex_lock(&session_mutex);
    int count = 0;
    UserSession* session = g_sessions;
    while (session) {
        if (session->SessionState == 1) {
            count++;
        }
        session = session->next;
    }
    pthread_mutex_unlock(&session_mutex);
    return count;
}

void clean_up_expired_sessions() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&session_mutex);
    UserSession* session = g_sessions;
    while (session) {
        if ((current_time - session->LastActivityTime) > SESSION_TIMEOUT) {
            // mark as logged out
            session->SessionState = 2; // assume logged out initially
        }
        session = session->next;
    }
    pthread_mutex_unlock(&session_mutex);
}

