#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define NetworkConnectionStatus structure
typedef struct {
    char* ipAddress;
    int portNumber;
    enum {
        ConnectionStateDisconnected,
        ConnectionStateConnecting,
        ConnectionStateConnected,
        ConnectionStateError
    } connectionState;
} NetworkConnectionStatus;

// Define dynamic array type
typedef struct {
    NetworkConnectionStatus** connections;
    int capacity;
    int size;
    // Load metric for each server instance
    double* serverLoads;
    int serverCount;
} DynamicArray;

DynamicArray* createDynamicArray(int initialCapacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->connections = (NetworkConnectionStatus**)malloc(initialCapacity * sizeof(NetworkConnectionStatus*));
    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->serverLoads = (double*)malloc(initialCapacity * sizeof(double));
    arr->serverCount = 1; // Start with a single server instance
    return arr;
}

void freeDynamicArray(DynamicArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->connections[i]->ipAddress);
        free(arr->connections[i]);
    }
    free(arr->connections);
    free(arr->serverLoads);
    free(arr);
}

NetworkConnectionStatus* addConnection(DynamicArray* arr, char* ipAddress, int portNumber) {
    NetworkConnectionStatus* newConn = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    newConn->ipAddress = strdup(ipAddress);
    newConn->portNumber = portNumber;
    newConn->connectionState = ConnectionStateDisconnected;

    // Dynamically distribute connections across server instances
    int targetServer = 0;
    for (int i = 0; i < arr->serverCount; i++) {
        if (arr->serverLoads[i] < 0.5) { // Target load level
            targetServer = i;
            break;
        }
    }

    // Update connection distribution and server loads
    int connIndex = arr->size++;
    arr->connections[connIndex] = newConn;

    // Rebalance connections if necessary
    for (int i = 0; i < arr->serverCount; i++) {
        if (arr->serverLoads[i] > 0.7) { // High load threshold
            // Evict connection from this server instance
            int evictedIndex = i;
            for (int j = 0; j < arr->size - 1; j++) {
                if (j >= evictedIndex && arr->connections[j]->connectionState == ConnectionStateDisconnected) {
                    evictedIndex++;
                    break;
                }
            }

            // Move connections to the target server
            NetworkConnectionStatus* temp = arr->connections[evictedIndex];
            arr->connections[evictedIndex] = NULL;
            for (int j = 0; j < connIndex; j++) {
                if (arr->connections[j]->connectionState == ConnectionStateDisconnected) {
                    arr->connections[j] = temp;
                    break;
                }
            }

            // Rebalance server loads
            double loadDiff = arr->serverLoads[evictedIndex] - arr->serverLoads[targetServer];
            for (int i = 0; i < arr->serverCount; i++) {
                if (i == evictedIndex) {
                    arr->serverLoads[i] = 0.5;
                } else if (loadDiff > 0) {
                    arr->serverLoads[i]++;
                }
            }

            // Update target server load
            arr->serverLoads[targetServer] += loadDiff;
        }
    }

    return newConn;
}

void updateConnection(DynamicArray* arr, int connIndex, NetworkConnectionStatus* connection) {
    if (connection->connectionState == ConnectionStateConnected) {
        // Rebalance connections if necessary
        for (int i = 0; i < arr->serverCount; i++) {
            if (arr->serverLoads[i] > 0.7) { // High load threshold
                int evictedIndex = i;
                for (int j = 0; j < arr->size - 1; j++) {
                    if (j >= evictedIndex && arr->connections[j]->connectionState == ConnectionStateDisconnected) {
                        evictedIndex++;
                        break;
                    }
                }

                // Move connections to the target server
                NetworkConnectionStatus* temp = arr->connections[evictedIndex];
                arr->connections[evictedIndex] = NULL;
                for (int j = 0; j < connIndex; j++) {
                    if (arr->connections[j]->connectionState == ConnectionStateDisconnected) {
                        arr->connections[j] = temp;
                        break;
                    }
                }

                // Rebalance server loads
                double loadDiff = arr->serverLoads[evictedIndex] - arr->serverLoads[targetServer];
                for (int i = 0; i < arr->serverCount; i++) {
                    if (i == evictedIndex) {
                        arr->serverLoads[i] = 0.5;
                    } else if (loadDiff > 0) {
                        arr->serverLoads[i]++;
                    }
                }

                // Update target server load
                arr->serverLoads[targetServer] += loadDiff;
            }
        }
    }
}

int getActiveConnections(DynamicArray* arr) {
    int activeCount = 0;
    for (int i = 0; i < arr->size; i++) {
        if (arr->connections[i]->connectionState == ConnectionStateConnected) {
            activeCount++;
        }
    }
    return activeCount;
}

// Example usage:
int main() {
    DynamicArray* arr = createDynamicArray(10);

    // Add connections
    NetworkConnectionStatus* conn1 = addConnection(arr, "192.168.1.100", 8080);
    NetworkConnectionStatus* conn2 = addConnection(arr, "192.168.1.101", 8081);
    NetworkConnectionStatus* conn3 = addConnection(arr, "192.168.1.102", 8082);

    // Update connection states
    updateConnection(arr, 0, conn1);
    updateConnection(arr, 1, conn2);
    updateConnection(arr, 2, conn3);

    int activeCount = getActiveConnections(arr);
    printf("Active connections: %d\n", activeCount);

    freeDynamicArray(arr);
    return 0;
}
