#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the enum for session status
typedef enum {
    ACTIVE,
    INACTIVE,
    EXPIRED
} SessionStatus;

// Define the structure for a user session
typedef struct {
    int UserID;
    char* SessionToken;
    time_t LastActiveTime;
    SessionStatus Status;
} UserSession;

// Function to initialize and manage the dynamic array of sessions
UserSession** initSessions(int capacity) {
    return (UserSession**)malloc(capacity * sizeof(UserSession*));
}

// Add a new session to the array
void addSession(UserSession** sessions, int capacity, int userID, char* token) {
    UserSession* newSession = (UserSession*)malloc(sizeof(UserSession));
    newSession->UserID = userID;
    newSession->SessionToken = token;
    newSession->LastActiveTime = time(NULL);
    newSession->Status = ACTIVE;

    // Insert the session at the end of the array
    int i;
    for(i = 0; i < capacity; i++) {
        if(sessions[i] == NULL) {
            sessions[i] = newSession;
            break;
        }
    }
}

// Update an existing session
void updateSession(UserSession** sessions, int capacity, int userID, SessionStatus status) {
    // Find the session with the given user ID
    for(int i = 0; i < capacity; i++) {
        if(sessions[i] != NULL && sessions[i]->UserID == userID) {
            sessions[i]->Status = status;
            return;
        }
    }
}

// Get the number of active sessions
int getActiveSessions(UserSession** sessions, int capacity) {
    int count = 0;
    for(int i = 0; i < capacity; i++) {
        if(sessions[i] != NULL && sessions[i]->Status == ACTIVE) {
            count++;
        }
    }
    return count;
}

// Periodically expire inactive sessions
void expireInactiveSessions(UserSession** sessions, int capacity, time_t timeoutInterval) {
    time_t currentTime = time(NULL);
    for(int i = 0; i < capacity; i++) {
        if(sessions[i] != NULL && sessions[i]->Status == INACTIVE) {
            if(currentTime - sessions[i]->LastActiveTime > timeoutInterval) {
                sessions[i]->Status = EXPIRED;
            }
        }
    }
}

// Free the memory allocated for the session array
void freeSessions(UserSession** sessions, int capacity) {
    for(int i = 0; i < capacity; i++) {
        if(sessions[i] != NULL) {
            free(sessions[i]);
        }
    }
    free(sessions);
}
