// Define a structure to hold network connection status information
typedef struct {
    char ipAddress[16];
    int portNumber;
    enum {CONNECTED, DISCONNECTED} connectionState;
} NetworkConnectionStatus;

// Function prototypes
void* cleanupThread(void*);
int addConnection(NetworkConnectionStatus);
int updateConnection(int, NetworkConnectionStatus);
int getActiveConnections();
NetworkConnectionStatus getConnection(int);

// Global variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe access
NetworkConnectionStatus* connections = NULL;
int numConnections = 0;
int timeoutThreshold = 30000; // Default timeout threshold (30 seconds)
pthread_t cleanupThreadID; // ID of the cleanup thread

// Function to periodically clean up inactive connections
void cleanupThreadFunc() {
    while (1) {
        pthread_mutex_lock(&mutex); // Lock mutex for exclusive access
        int i;
        for (i = 0; i < numConnections; i++) {
            NetworkConnectionStatus* connection = &connections[i];
            if (connection->connectionState == DISCONNECTED && time(NULL) - connection->lastActivity > timeoutThreshold / 1000.0) {
                // Remove inactive connections
                memmove(&connections[i], &connections[i + 1], sizeof(NetworkConnectionStatus) * (numConnections - i));
                numConnections--;
                i--; // Decrement 'i' because the loop continues with a smaller range
            }
        }
        pthread_mutex_unlock(&mutex); // Unlock mutex for other threads

        sleep(timeoutThreshold / 1000.0); // Sleep for the configured timeout interval
    }
}

// Create and start the cleanup thread
void startCleanupThread() {
    pthread_create(&cleanupThreadID, NULL, cleanupThreadFunc, NULL);
}

int main() {
    // Initialize global variables
    connections = (NetworkConnectionStatus*)malloc(1 * sizeof(NetworkConnectionStatus));
    numConnections = 0;

    startCleanupThread();

    return 0;
}
