            printf("cURL error: %s\n", curl_easy_strerror(res));
            break;
        }

        // Parse JSON response
        json_memory = json_tokener_parse(curl_easyGetString(curl, -1, NULL));

        log_json = json_object_object_get(json_memory, "logs");
        for (i = 0; i < json_object_array_length(log_json); i++) {
            log_entry_json = json_object_array_get(log_json, i);
            // Process each audit log entry
            process_log_entry(log_entry_json);
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();
