```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char ipAddress[16];
    int portNumber;
    enum { CONNECTED, DISCONNECTED } connectionState;
} NetworkConnectionStatus;

// Custom memory allocator for fixed-size and variable-sized allocations
void* custom_malloc(size_t size) {
    // Allocate memory from a shared heap or pool of free blocks
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Hash table (map) to store connections, with bucket index based on hash value
typedef struct {
    int capacity;
    NetworkConnectionStatus** connections;
} ConnectionMap;

ConnectionMap* connection_map_create(int initialCapacity) {
    ConnectionMap* map = (ConnectionMap*) custom_malloc(sizeof(ConnectionMap));
    map->capacity = initialCapacity;
    map->connections = (NetworkConnectionStatus**) custom_malloc(initialCapacity * sizeof(NetworkConnectionStatus*));
    return map;
}

void connection_map_free(ConnectionMap* map) {
    for (int i = 0; i < map->capacity; i++) {
        if (map->connections[i] != NULL)
            custom_free(map->connections[i]);
    }
    custom_free(map->connections);
    custom_free(map);
}

// Function to add a new connection
void connection_map_add(ConnectionMap* map, NetworkConnectionStatus* connection) {
    // Hash function for connection ID (e.g., IP address and port number)
    int index = (connection->portNumber ^ strlen(connection->ipAddress)) % map->capacity;
    if (map->connections[index] == NULL) {
        map->connections[index] = connection;
    } else {
        printf("Connection with the same ID already exists. No update performed.\n");
    }
}

// Function to update an existing connection
void connection_map_update(ConnectionMap* map, NetworkConnectionStatus* connection) {
    // Find the connection by IP address and port number
    int index = (connection->portNumber ^ strlen(connection->ipAddress)) % map->capacity;
    if (map->connections[index] != NULL && memcmp(map->connections[index], connection, sizeof(NetworkConnectionStatus)) == 0) {
        memcpy(map->connections[index], connection, sizeof(NetworkConnectionStatus));
    } else {
        printf("No connection found with the given ID. No update performed.\n");
    }
}

// Function to remove a connection by its IP address and port number
void connection_map_remove(ConnectionMap* map, NetworkConnectionStatus* connection) {
    int index = (connection->portNumber ^ strlen(connection->ipAddress)) % map->capacity;
    if (map->connections[index] != NULL && memcmp(map->connections[index], connection, sizeof(NetworkConnectionStatus)) == 0) {
        map->connections[index] = NULL;
    } else {
        printf("No connection found with the given ID.\n");
    }
}

// Function to check if a connection is present
int connection_map_contains(ConnectionMap* map, NetworkConnectionStatus* connection) {
    int index = (connection->portNumber ^ strlen(connection->ipAddress)) % map->capacity;
    return map->connections[index] != NULL && memcmp(map->connections[index], connection, sizeof(NetworkConnectionStatus)) == 0;
}

// Function to mark a connection as disconnected
void connection_mark_disconnected(ConnectionMap* map, NetworkConnectionStatus* connection) {
    int index = (connection->portNumber ^ strlen(connection->ipAddress)) % map->capacity;
    if (map->connections[index] != NULL && memcmp(map->connections[index], connection, sizeof(NetworkConnectionStatus)) == 0) {
        map->connections[index]->connectionState = DISCONNECTED;
    }
}

// Periodic cleanup mechanism for inactive connections
void connection_map_cleanup(ConnectionMap* map, int inactivityTimeout) {
    for (int i = 0; i < map->capacity; i++) {
        if (map->connections[i] != NULL && (map->connections[i]->connectionState == DISCONNECTED &&
                                            time(NULL) - (struct tm*)custom_malloc(sizeof(struct tm)).tm_sec > inactivityTimeout)) {
            custom_free(map->connections[i]);
            map->connections[i] = NULL;
        }
    }
}

// Serialize the connection status collection to a file
void connection_map_serialize(ConnectionMap* map, const char* filename) {
    // Write the connection count and array size to the file
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        fwrite(&map->capacity, sizeof(int), 1, file);
        fwrite(map->connections, sizeof(NetworkConnectionStatus*), map->capacity, file);
        fclose(file);
    }
}

// Deserialize the connection status collection from a file
ConnectionMap* connection_map_deserialize(const char* filename) {
    ConnectionMap* map = (ConnectionMap*) custom_malloc(sizeof(ConnectionMap));
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        fread(&map->capacity, sizeof(int), 1, file);
        map->connections = (NetworkConnectionStatus**) custom_malloc(map->capacity * sizeof(NetworkConnectionStatus*));
        fread(map->connections, sizeof(NetworkConnectionStatus*), map->capacity, file);
        fclose(file);
    }
    return map;
}

// Web API endpoints for updating and deleting connections

void update_connection(int portNumber, const char* ipAddress) {
    // Find the connection by IP address and port number
    int index = (portNumber ^ strlen(ipAddress)) % map->capacity;
    if (map->connections[index] != NULL && memcmp(map->connections[index], &connection, sizeof(NetworkConnectionStatus)) == 0) {
        // Update the connection state
        map->connections[index]->connectionState = CONNECTED;
    } else {
        printf("No connection found with the given ID. No update performed.\n");
    }
}

void delete_connection(int portNumber, const char* ipAddress) {
    int index = (portNumber ^ strlen(ipAddress)) % map->capacity;
    if (map->connections[index] != NULL && memcmp(map->connections[index], &connection, sizeof(NetworkConnectionStatus)) == 0) {
        // Reset the connection state and log deletion
        map->connections[index]->connectionState = DISCONNECTED;
        printf("Connection deleted.\n");
    } else {
        printf("No connection found with the given ID.\n");
    }
}

// Main function to demonstrate the API endpoints

int main() {
    ConnectionMap* map = connection_map_create(10);

    // Add connections
    NetworkConnectionStatus connection1;
    strcpy(connection1.ipAddress, "192.168.0.100");
    connection1.portNumber = 8080;
    connection1.connectionState = CONNECTED;
    connection_map_add(map, &connection1);

    NetworkConnectionStatus connection2;
    strcpy(connection2.ipAddress, "192.168.0.101");
    connection2.portNumber = 8081;
    connection2.connectionState = DISCONNECTED;
    connection_map_add(map, &connection2);

    // Update a connection
    update_connection(8081, "192.168.0.101");

    // Delete a connection
    delete_connection(8080, "192.168.0.100");

    // Serialize and deserialize the connection status collection
    connection_map_serialize(map, "connections.bin");
    ConnectionMap* deserializedMap = connection_map_deserialize("connections.bin");

    // Clean up inactive connections
    connection_map_cleanup(map, 60); // Inactivity timeout of 1 minute

    return 0;
}

