    char RNTI[16];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} ListNode;

ListHandle CreateList(int n) {
    ListHandle list = (ListHandle)malloc(sizeof(ListNode));
    if (!list) return NULL;

    list->data.RX_UE_INFORMATION_TAG = rand();
    strcpy(list->data.RNTI, "RNTI");
    list->data.CRC_INDICATION_REL8_TAG = rand();
    list->data.CRCFLAG = (rand() % 2);

    ListHandle curr = list;
    for (int i = 1; i < n; i++) {
        ListHandle newNode = CreateNode();
        if (!newNode) break;

        curr->next = newNode;
        curr = newNode;
    }

    return list;
}

ListHandle CreateNode() {
    ListHandle node = (ListHandle)malloc(sizeof(ListNode));
    if (!node) return NULL;

