    strcpy(node->data.RNTI, "RNTI");
    node->data.CRC_INDICATION_REL8_TAG = rand();
    node->data.CRCFLAG = (rand() % 2);

    return node;
}

void PrintList(ListHandle list) {
    ListHandle curr = list;
    while (curr) {
        printf("RX_UE_INFORMATION_TAG: %d\nRNTI: %s\nCRC_INDICATION_REL8_TAG: %d\nCRCFLAG: %d\n", 
               curr->data.RX_UE_INFORMATION_TAG, curr->data.RNTI, 
               curr->data.CRC_INDICATION_REL8_TAG, curr->data.CRCFLAG);
        curr = curr->next;
    }
}

void DestroyList(ListHandle list) {
    ListHandle curr = list;
    while (curr) {
        ListHandle next = curr->next;
        free(curr);
        curr = next;
    }
}
