#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent a node in the graph
typedef struct {
    char ip_address[16];
    int port_number;
    int connection_state;
} Node;

// Define a structure to represent an edge in the graph
typedef struct {
    Node* source;
    Node* target;
} Edge;

// Define a structure to represent the graph
typedef struct {
    pthread_mutex_t lock;
    int node_count;
    Node** nodes;
    Edge** edges;
} Graph;

// Function to initialize and populate the graph
Graph* create_graph(int node_count) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->node_count = node_count;
    graph->nodes = (Node**)malloc(node_count * sizeof(Node*));
    graph->edges = (Edge**)malloc(0); // Initialize edge array with 0 size
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

// Function to add a new node to the graph
void add_node(Graph* graph, Node* node) {
    pthread_mutex_lock(&graph->lock);
    graph->nodes[graph->node_count++] = node;
    pthread_mutex_unlock(&graph->lock);
}

// Function to add an edge between two nodes in the graph
void add_edge(Graph* graph, Node* source, Node* target) {
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    edge->source = source;
    edge->target = target;
    pthread_mutex_lock(&graph->lock);
    graph->edges = (Edge**)realloc(graph->edges, (graph->node_count + 1) * sizeof(Edge*));
    graph->edges[graph->node_count] = edge;
    pthread_mutex_unlock(&graph->lock);
}

// Function to update the connection state of a node
void update_node_state(Graph* graph, Node* node, int new_state) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        if (graph->nodes[i] == node) {
            graph->nodes[i]->connection_state = new_state;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

// Function to retrieve the connection state of a node
int get_node_state(Graph* graph, Node* node) {
    int state = -1; // Initialize with invalid state
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        if (graph->nodes[i] == node) {
            state = graph->nodes[i]->connection_state;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
    return state;
}

// Function to free the resources allocated by the graph
void free_graph(Graph* graph) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        free(graph->nodes[i]);
    }
    free(graph->edges);
    free(graph);
    pthread_mutex_unlock(&graph->lock);
}

// Example usage:
int main() {
    Graph* graph = create_graph(5); // Create a graph with 5 nodes
    Node node1 = {"192.168.1.1", 8080, 1};
    Node node2 = {"192.168.1.2", 8081, 0};
    add_node(graph, &node1);
    add_node(graph, &node2);
    add_edge(graph, &node1, &node2);
    update_node_state(graph, &node1, 2);
    int state = get_node_state(graph, &node1);
    printf("Node 1's connection state: %d\n", state);
    free_graph(graph); // Free the resources allocated by the graph
    return 0;
}
