['```c
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    char* str;
    int key;
    float val;
    struct Entry* next;
} Entry;

typedef struct DynamicList {
    Entry* head;
    size_t size;
    void (*print)(Entry*);
} DynamicList;

DynamicList* dynamic_list_create(void) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    list->print = NULL;
    return list;
}

void dynamic_list_free(DynamicList** list) {
    if (!*list) return;
    DynamicList* l = *list;
    Entry* current = l->head;
    Entry* next;
    while (current) {
        next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    free(l);
    *list = NULL;
}

int dynamic_list_insert(DynamicList* list, char* str, int key, float val) {
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return -1;  // Memory allocation failed
    new_entry->str = strdup(str);
    new_entry->key = key;
    new_entry->val = val;
    new_entry->next = list->head;
    list->head = new_entry;
    list->size++;
    return 0;
}

void dynamic_list_remove(DynamicList* list, int target_key) {
    if (list->head == NULL) return;  // List is empty
    Entry* current = list->head;
    Entry* previous = NULL;
    while (current && current->key != target_key) {
        previous = current;
        current = current->next;
    }
    if (!current) return;  // Not found
    if (previous) previous->next = current->next;
    else list->head = current->next;
    free(current->str);
    free(current);
    list->size--;
}

void dynamic_list_sort(DynamicList* list) {
    Entry* current = list->head;
    Entry* next;
    while (current && (next = current->next)) {
        if (current->key > next->key) {
            // Swap
            int temp_key = current->key;
            float temp_val = current->val;
            char* temp_str = current->str;
            current->key = next->key;
            current->val = next->val;
            current->str = next->str;
            next->key = temp_key;
            next->val = temp_val;
            next->str = temp_str;
        }
        current = next;
    }
}

void dynamic_list_print(DynamicList* list) {
    Entry* current = list->head;
    while (current) {
        printf("%s: %d - %.2f\n", current->str, current->key, current->val);
        current = current->next;
    }
}

size_t dynamic_list_get_size(const DynamicList* list) {
    return list->size;
}
