#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FRAMES 10000
#define MAX_PACKET_DATA 1024
#define LOGGING_FPS 10 // logging frequency in frames per second

typedef struct FrameInfo {
    UEIdentifier identifier;
    Timestamp timestamp;
    PacketData packet_data;
} FrameInfo;

FrameInfo** frame_array = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_frames = 0;
FILE* log_file = fopen("frame_log.txt", "a");

void init_frame_array(int capacity) {
    if (capacity > MAX_FRAMES) {
        printf("Error: Exceeding maximum frames.\n");
        return;
    }
    frame_array = (FrameInfo**)malloc(capacity * sizeof(FrameInfo*));
    for (int i = 0; i < capacity; i++) {
        frame_array[i] = (FrameInfo*)malloc(sizeof(FrameInfo));
    }
}

void update_packet_data(UEIdentifier identifier, Timestamp timestamp, PacketData new_packet_data) {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < num_frames; i++) {
        if (frame_array[i]->identifier == identifier && frame_array[i]->timestamp == timestamp) {
            memcpy(frame_array[i]->packet_data, &new_packet_data, sizeof(PacketData));
            break;
        }
    }
    if (i >= num_frames) {
        printf("Error: Frame not found.\n");
    }
    pthread_mutex_unlock(&lock);
}

int get_num_frames() {
    return num_frames;
}

void serialize_frame_array(char* output) {
    int i, offset = 0;
    for (i = 0; i < num_frames; i++) {
        FrameInfo frame = *frame_array[i];
        // Serialize the FrameInfo structure
        *(uint32_t*)(output + offset) = htons(frame.identifier);
        *(Timestamp*) (output + offset + sizeof(uint32_t)) = frame.timestamp;
        *(PacketData)(output + offset + sizeof(Timestamp) + sizeof(uint32_t)) = frame.packet_data;
        offset += sizeof(Timestamp) + sizeof(uint32_t) + sizeof(PacketData);
    }
}

void deserialize_frame_array(char* input) {
    int i, offset = 0;
    for (i = 0; i < num_frames; i++) {
        FrameInfo* frame = &frame_array[i]->identifier;
        // Deserialize the FrameInfo structure
        frame->identifier = ntohs(*(uint32_t*)(input + offset));
        frame->timestamp = *(Timestamp*) (input + offset + sizeof(uint32_t));
        frame->packet_data = *(PacketData)(input + offset + sizeof(Timestamp) + sizeof(uint32_t));
        offset += sizeof(Timestamp) + sizeof(uint32_t) + sizeof(PacketData);
    }
}

void clear_frame_array() {
    for (int i = 0; i < num_frames; i++) {
        free(frame_array[i]);
    }
    free(frame_array);
}

void log_frame_update(UEIdentifier identifier, Timestamp timestamp, PacketData packet_data) {
    if (LOGGING_FPS > 0 && (num_frames % LOGGING_FPS == 0)) {
        fprintf(log_file, "Updated frame with identifier: %d, timestamp: %lu, and packet data.\n", identifier, timestamp);
    }
}

void* thread_function(void* arg) {
    while (1) {
        // Simulate network jitter and variable data packet sizes
        usleep(rand() % 1000 + 500);
        UEIdentifier identifier = rand() % 100;
        Timestamp timestamp = time(NULL);
        PacketData packet_data = malloc(sizeof(PacketData));
        // Generate random packet data
        for (int i = 0; i < MAX_PACKET_DATA; i++) {
            ((char*)packet_data)[i] = (char)rand();
        }
        update_packet_data(identifier, timestamp, *packet_data);
        free(packet_data);
    }
}

void start_logging() {
    pthread_t thread;
    pthread_create(&thread, NULL, &thread_function, NULL);
}

int main() {
    init_frame_array(MAX_FRAMES);
    // Start logging
    start_logging();
    return 0;
}
