    if (count <= 0) return;

    // Initialize random number generator for efficient generation of values
    srand(time(NULL));

    // Allocate memory for the DataPoint array
    DataPoint* dataPoints = malloc(count * sizeof(DataPoint));
    if (!dataPoints) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(dataPoints);
        return NULL;
    }

    // Initialize metadata pool and reuse strings across multiple DataPoint instances
    const char* metadataPool[] = {"String1", "String2", "String3"};
    size_t metadataCount = sizeof(metadataPool) / sizeof(metadataPool[0]);
    size_t metadataIndex = 0;

    for (size_t i = 0; i < count; ++i) {
        dataPoints[i].value = (double)rand() / RAND_MAX;
        if (metadataIndex >= metadataCount - 1) {
            // Handle exhaustion of metadata pool
            // For demonstration purposes, stop creating new DataPoint instances when the pool is exhausted
            return;
        }
        dataPoints[i].metadata = metadataPool[metadataIndex++];
    }

    free(dataPoints);
}

void freeDataPoints(DataPoint* dataPoints, size_t count) {
    if (!dataPoints || count <= 0) return;

    for (size_t i = 0; i < count; ++i) {
        free(dataPoints[i].metadata);
    }
    free(dataPoints);
}
