#include <time.h>
#include "shared_library.h"

typedef struct {
    double value;
    char* metadata;
} DataPoint;

DataPoint* manageDataPoints(int numPoints, int minValue, int maxValue, const char** metadataOptions, int optMetadataSize, int logLevel) {
    DataPoint* dataPoints = NULL;
    size_t totalBytes = sizeof(DataPoint) * numPoints;
    char* pool = NULL;
    size_t poolSize = 0;

    if (logLevel > 0) {
        printf("Initializing data point management...\n");
    }

    // Initialize random number generator
    srand(time(NULL));

    // Dynamically allocate memory for the array of DataPoint structures
    dataPoints = malloc(totalBytes);
    if (!dataPoints) {
        return NULL;
    }

    // Allocate a fixed pool for metadata strings, dynamically expandable as needed
    char* tempPool = (char*)malloc(1024);  // Initialize with a small size to start
    pool = tempPool;
    poolSize = 1024;

    // Iterate through the data points and initialize their values and metadata
    for (int i = 0; i < numPoints; i++) {
        DataPoint* dp = &dataPoints[i];
        double value = ((double)rand() / RAND_MAX * (maxValue - minValue)) + minValue;
        dp->value = value;

        // Use a shared pool of metadata strings to minimize memory usage
        char* metadata = NULL;
        size_t metadataSize = 0;
        for (int j = 0; j < optMetadataSize; j++) {
            if (!metadataOptions[j]) continue;
            if (strlen(metadataOptions[j]) > metadataSize) {
                metadata = (char*)realloc(pool, poolSize + strlen(metadataOptions[j]));
                poolSize += strlen(metadataOptions[j]);
                metadata = strcpy(metadata, metadataOptions[j]);
                break;
            }
        }

        dp->metadata = metadata;

        // Free any allocated memory for the previous data point's metadata
        if (metadata) free(metadata);
    }

    // Return the dynamically allocated array of DataPoint structures
    return dataPoints;
}

void releaseDataPoints(DataPoint* dataPoints, int numPoints) {
    for (int i = 0; i < numPoints; i++) {
        if (dataPoints[i].metadata) free(dataPoints[i].metadata);
    }
    free(dataPoints);
}
