// Define record structure
typedef struct {
    long offset;
    int key;
    char data[50];
} record;

// Function to initialize record array with random values and ASCII characters
void initRecords(record *records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = rand() % 2000000L;
        records[i].key = rand() % 2001 - 1000;
        for (int j = 0; j < 50; j++) {
            records[i].data[j] = (char)(rand() % 128);
            if (records[i].data[j] == '\0') break;
        }
    }
}

// Function to print record details
void printRecords(record *records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        printf("Record %d: Offset = %ld, Key = %d, Data = %s\n", i + 1, records[i].offset, records[i].key, records[i].data);
    }
}

// Function to free dynamically allocated memory
void freeMemory(record *records, int numRecords) {
    if (records != NULL) {
        for (int i = 0; i < numRecords; i++) {
            if (records[i].data != NULL) free(records[i].data);
        }
        free(records);
    }
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int numOffsets, numKeys, numRecords;

    printf("Enter the number of offset values: ");
    scanf("%d", &numOffsets);

    if (numOffsets > 1000000) {
        printf("Error: Too many offset values. Maximum allowed is 1 million.\n");
        return -1;
    }

    printf("Enter the number of key values: ");
    scanf("%d", &numKeys);

    if (numKeys > 1000000) {
        printf("Error: Too many key values. Maximum allowed is 1 million.\n");
        return -1;
    }

    record *offsetRecords = (record *)malloc(numOffsets * sizeof(record));
    record *keyRecords = (record *)malloc(numKeys * sizeof(record));

    if (offsetRecords == NULL || keyRecords == NULL) {
        printf("Error: Memory allocation failed.\n");
        freeMemory(offsetRecords, numOffsets);
        return -1;
    }

    // Initialize offset records with random values
    initRecords(offsetRecords, numOffsets);

    // Initialize key records with random values and ASCII characters
    record *records = (record *)malloc((numOffsets + numKeys) * sizeof(record));
    if (records == NULL) {
        printf("Error: Memory allocation failed.\n");
        freeMemory(offsetRecords, numOffsets);
        return -1;
    }

    // Initialize remaining records with random values and ASCII characters
    for (int i = 0; i < numKeys; i++) {
        int j = i % numOffsets;
        records[j].offset = offsetRecords[j].offset;
        records[j].key = rand() % 2001 - 1000;
        for (int k = 0; k < 50; k++) {
            records[j].data[k] = (char)(rand() % 128);
            if (records[j].data[k] == '\0') break;
        }
    }

    // Print record details
    printRecords(records, numOffsets + numKeys);

    // Free dynamically allocated memory
    freeMemory(offsetRecords, numOffsets);
    freeMemory(keyRecords, numKeys);
    freeMemory(records, numOffsets + numKeys);

    return 0;
}

