        context->ueId = i;
        context->rnti = rand() % 1000; // generate a random RNTI value
        context->crcIndication = rand() % 2; // randomly set CRC indication to 0 or 1

        if (ue_contexts == NULL) {
            ue_contexts = (UEContext **)malloc((total_ue_contexts + 1) * sizeof(UEContext *));
            ue_contexts[total_ue_contexts] = context;
        } else {
            UEContext **temp = (UEContext **)realloc(ue_contexts, (total_ue_contexts + 2) * sizeof(UEContext *));
            temp[total_ue_contexts] = context;
            temp[total_ue_contexts + 1] = NULL; // mark the end of the array
            ue_contexts = temp;
        }

        total_ue_contexts++;
    }

    return ue_contexts;
}
