// Order structure definition
typedef struct {
    int id;
    int customer_id;
    time_t date;
    double total_amount;
    enum { PENDING, PROCESSED, CANCELED } status;
} Order;

// Custom allocator for orders
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) return NULL;
    memset(ptr, 0, size);
    return ptr;
}

// In-memory order collection implementation
typedef struct {
    Order** orders;
    int count;
} OrderCollection;

OrderCollection in_memory_collection() {
    OrderCollection coll;
    coll.count = 0;
    coll.orders = (Order**)custom_alloc(sizeof(Order*) * 10);
    return coll;
}

void in_memory_add_order(OrderCollection* collection, Order order) {
    if (collection->count >= sizeof(collection->orders) / sizeof(collection->orders[0])) {
        // Reallocate array
        collection->orders = (Order**)realloc(collection->orders, sizeof(Order*) * 2 * (collection->count + 1));
    }
    collection->orders[collection->count++] = &order;
}

void in_memory_update_order(OrderCollection* collection, int id, Order new_order) {
    for (int i = 0; i < collection->count; i++) {
        if (collection->orders[i]->id == id) {
            memcpy(collection->orders + i, &new_order, sizeof(Order));
            return;
        }
    }
}

void in_memory_void_order(OrderCollection* collection, int id) {
    for (int i = 0; i < collection->count; i++) {
        if (collection->orders[i]->id == id) {
            free(collection->orders[i]);
            memcpy(collection->orders + i, collection->orders + i + 1, sizeof(Order*) * (collection->count - i - 1));
            collection->count--;
            return;
        }
    }
}

// File-based order collection implementation
typedef struct {
    FILE* file;
    Order** orders;
    int count;
} FileOrderCollection;

FileOrderCollection file_collection(const char* filename) {
    FileOrderCollection coll;
    coll.count = 0;
    coll.orders = NULL;
    if ((coll.file = fopen(filename, "ab+")) == NULL) return coll; // Open file in append mode
    fseek(coll.file, 0, SEEK_END); // Move to end of file
    size_t size = ftell(coll.file);
    coll.orders = (Order**)custom_alloc(sizeof(Order*) * (size / sizeof(Order) + 1));
    fread(&coll.orders[0], sizeof(Order*), size / sizeof(Order), coll.file);
    return coll;
}

void file_add_order(FileOrderCollection* collection, Order order) {
    // Append new order to end of file
    fwrite(&order, sizeof(Order), 1, collection->file);
    collection->orders[collection->count++] = &order;
}

