// Caching layer for order retrieval
typedef struct {
    Order** orders;
    int count;
} Cache;

Cache cache = {NULL, 0};

void cache_set_order(Cache* cache, int id, Order order) {
    cache->orders[cache->count++] = &order;
}

Order cache_get_order(Cache* cache, int id) {
    // Search cached orders
    for (int i = 0; i < cache->count; i++) {
        if (cache->orders[i]->id == id) return *cache->orders[i];
    }
    return Order{}; // Return default order if not found
}

// Main function to manage orders
void manage_orders(OrderCollection* collection, Cache* cache) {
    while (1) {
        int choice;
        printf("Enter 1 to add an order, 2 to update an order, 3 to void an order, or 4 to retrieve all orders:\n");
        scanf("%d", &choice);
