    IN_PROGRESS,
    COMPLETED,
    PENDING
} TaskStatus;

typedef struct {
    int id;
    char* description;
    TaskStatus status;
} Task;

// Function to manage dynamic memory allocation for job scheduling system
void init_job_scheduling_system(int num_workers, int num_tasks) {
    // Initialize array of workers
    Worker* workers = (Worker*)malloc(sizeof(Worker) * num_workers);
    for (int i = 0; i < num_workers; i++) {
        workers[i].name = (char*)malloc(strlen("Worker ") + 1);
        strcpy(workers[i].name, "Worker ");
        workers[i].id = i;
        workers[i].tasks = NULL;
    }

    // Initialize array of tasks
    Task* tasks = (Task*)malloc(sizeof(Task) * num_tasks);
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].id = i;
        tasks[i].description = (char*)malloc(strlen("Task ") + 1);
        strcpy(tasks[i].description, "Task ");
        tasks[i].status = rand() % 3; // Randomly initialize status flag
    }

    // Initialize worker-task associations and update task statuses accordingly
    for (int i = 0; i < num_workers; i++) {
        workers[i].tasks = (struct Task**)malloc(sizeof(struct Task*) * num_tasks);
        for (int j = 0; j < num_tasks; j++) {
            tasks[j].id == i ? (workers[i].tasks)[j] = &tasks[j] : NULL;
        }
    }

    // Periodically receive updates from external data sources
    while (1) {
        // Simulate receiving updates
        printf("Received update: ");
        for (int i = 0; i < num_workers; i++) {
            printf("%s", workers[i].name);
        }
        printf("\n");

        // Update task statuses based on new information
        for (int i = 0; i < num_tasks; i++) {
            tasks[i].status = rand() % 3; // Randomly update status flag
        }

        // Sleep for some time to simulate periodic updates
        sleep(1);
    }
}

// Free memory allocated by job scheduling system
void free_job_scheduling_system(int num_workers, int num_tasks) {
    // Free worker structures
    for (int i = 0; i < num_workers; i++) {
        if (workers[i].tasks != NULL) {
            for (int j = 0; j < num_tasks; j++) {
                free((void*)workers[i].tasks[j]->description);
                workers[i].tasks[j] = NULL;
            }
            free(workers[i].name);
            free(workers[i].tasks);
        }
    }

    // Free task structures
    for (int i = 0; i < num_tasks; i++) {
        free((void*)tasks[i]->description);
    }
    free(tasks);

    // Free array of workers
    free(workers);
}

// Main function to test job scheduling system
int main() {
    int num_workers = 10;
    int num_tasks = 50;

    init_job_scheduling_system(num_workers, num_tasks);

    while (1) {
        printf("System running...\n");
        sleep(1);
    }

    free_job_scheduling_system(num_workers, num_tasks);

    return 0;
}
