typedef enum {
    CS_DISCONNECTED,
    CS_CONNECTED
} ConnectionState;

typedef struct {
    char* ipAddress;
    int portNumber;
    ConnectionState connectionState;
} NetworkConnectionStatus;

// Array of connections
NetworkConnectionStatus** connections = NULL;
int connCount = 0;

void addConnection(char* ip, int port) {
    // Allocate memory for new connection
    NetworkConnectionStatus* newConn = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    if (newConn == NULL) return; // Handle allocation error

    newConn->ipAddress = (char*)malloc(strlen(ip) + 1);
    strcpy(newConn->ipAddress, ip);
    newConn->portNumber = port;
    newConn->connectionState = CS_DISCONNECTED;

    connections[connCount++] = newConn;
}

void updateConnection(int index, ConnectionState state) {
    if (index < 0 || index >= connCount) return; // Handle out-of-bounds error

    connections[index]->connectionState = state;
}

int getActiveConnections() {
    int active = 0;
    for (int i = 0; i < connCount; i++) {
        if (connections[i]->connectionState == CS_CONNECTED) active++;
    }
    return active;
}
