#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* data;
    size_t length;
} Node;

Node* head = NULL;
size_t list_size = 0;

void init_list(Node** head, const char** keywords, int num_keywords) {
    *head = NULL;
    for (int i = 0; i < num_keywords; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        new_node->data = strdup(keywords[i]);
        new_node->length = strlen(keywords[i]);
        if (*head) {
            for (Node* current = *head; current; current = current->next) {
                current->next = malloc(sizeof(Node));
                current->next->data = strdup(keywords[(i+1)%num_keywords]);
                current->next->length = strlen(keywords[(i+1)%num_keywords]);
                if (!current->next->data || !current->next->length) {
                    free(current->next->data);
                    free(current->next->length);
                    free(current->next);
                    current->next = NULL;
                    return;
                }
            }
        } else {
            new_node->next = NULL;
        }
        *head = new_node;
    }
}

void add_node(Node** head, const char* data, size_t length) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = strdup(data);
    new_node->length = length;
    if (*head) {
        for (Node* current = *head; current->next; current = current->next) {
            continue;
        }
        current->next = new_node;
    } else {
        *head = new_node;
    }
}

void remove_node(Node** head, size_t index) {
    if (!*head || index >= list_size) {
        return;
    }
    Node* current = *head;
    for (size_t i = 0; i < index - 1; ++i) {
        current = current->next;
    }
    Node* next_node = current->next;
    if (next_node) {
        free(next_node->data);
        free(next_node);
    } else {
        *head = NULL;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}
