void process_dataset(record_t *dataset, int num_records) {
    int max_value = 0;
    uint32_t crcflag = 0;

    for (int i = 0; i < num_records; i++) {
        if (dataset[i].value > max_value) {
            max_value = dataset[i].value;
        }
        crcflag |= (uint32_t)(dataset[i].value << ((i % 8) * 8));
    }

    printf("Max value: %d, CRCFLAG: 0x%x\n", max_value, crcflag);
}

void cleanup_dataset(record_t *dataset, int num_records) {
    if (!dataset) return;

    free(dataset);
}

int main() {
    srand(time(NULL)); // seed random number generator

    record_t *dataset = init_dataset(100); // initialize dataset with 100 records
    process_dataset(dataset, 100); // process and analyze the dataset
    cleanup_dataset(dataset, 100); // release resources and maintain thread safety

    return 0;
}
