        return -INFINITY; // Return negative infinity for empty list
    }

    float min = numbers[0];
    for (int i = 1; i < size; i++) {
        if (numbers[i] < min && !isinf(numbers[i])) { // Validate and update minimum
            min = numbers[i];
        }
    }
    return min;
