// Define the record structure
typedef struct {
    int key;
    double value;
} Record;

// Function to initialize and manage the dynamic dataset
void* initialize_dataset(int num_records) {
    // Initialize arrays for offset values, keys, and data points
    long* offsets = (long*)malloc(sizeof(long) * num_records);
    int* keys = (int*)malloc(sizeof(int) * num_records);
    double* data_points = (double*)malloc(sizeof(double) * num_records);

    // Initialize the array of record structures
    Record* records = (Record*)malloc(sizeof(Record) * num_records);

    for (int i = 0; i < num_records; i++) {
        // Generate a random double value within a specified range
        data_points[i] = (double)(rand() / (RAND_MAX / 10000.0));

        // Set the key and offset values
        keys[i] = i;
        offsets[i] = i * sizeof(Record);

        // Initialize each record's double field
        records[i].key = keys[i];
        records[i].value = data_points[i];
    }

    return records;
}

// Custom overflow detection mechanism to prevent floating-point precision issues
void detect_overflow(double value) {
    if (isnan(value)) {
        printf("Overflow detected!\n");
    }
}

// Function to set the value of each record's double field to a random value within a given range
void set_record_values(Record* records, int num_records, double min_value, double max_value) {
    for (int i = 0; i < num_records; i++) {
        // Generate a random double value within the specified range
        double random_value = (double)(rand() / (RAND_MAX / (max_value - min_value))) + min_value;

        detect_overflow(random_value);

        // Set the value of each record's double field
        records[i].value = random_value;
    }
}

// Robust cleanup procedure to release resources and maintain thread safety
void cleanup(void* ptr) {
    free(ptr);
}

int main() {
    srand(time(NULL));

    // Example usage:
    int num_records = 1000;
    double min_value = -10.0, max_value = 10.0;

    Record* records = initialize_dataset(num_records);

    set_record_values(records, num_records, min_value, max_value);

    cleanup((void*)records);

    return 0;
}
