// Structure definition
typedef struct {
    int value;
} record;

// Function to manage the dynamic dataset
void manage_dataset(int num_records, int max_active, int min_value, int max_value) {
    // Initialize arrays for offset values and keys
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize array of record structures
    record* records = (record*)malloc(num_records * sizeof(record));

    // Populate each record's int field with a random integer
    for (int i = 0; i < num_records; i++) {
        // Custom overflow detection mechanism to prevent integer overflows
        long val = (long)rand() % ((max_value - min_value + 1) * sizeof(long));
        if (val > max_value || val < min_value) {
            printf("Overflow detected! Adjusting value.\n");
            val = (long)(rand() % (max_value - min_value + 1)) + min_value;
        }
        records[i].value = (int)val;

        // Assign random values to each record's int field within the given range
        offsets[i] = (long)i;
        keys[i] = i;
    }

    // Implement a queue-based mechanism to control the number of active structures
    int* queue = (int*)malloc(max_active * sizeof(int));
    int front = 0, rear = 0;

    // Support configuration options to enable or disable logging
    int log_enabled = 1; // Set to 1 for enabled and 0 for disabled

    // Robust cleanup procedure to release resources and maintain thread safety
    void cleanup() {
        free(offsets);
        free(keys);
        free(records);
        if (log_enabled) {
            printf("Resources released.\n");
        }
