void manage_memory(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Initialize variables to track total number of records and memory allocation
    int num_records = 0;
    record **records = NULL;

    // Read file contents and initialize record array dynamically
    while (1) {
        long offset;
        int key;
        if (fscanf(fp, "%ld %d", &offset, &key) != 2) {
            break; // End of file reached or error reading data
        }

        // Allocate memory for a new record structure and increment total count
        record *new_record = (record *) malloc(sizeof(record));
        if (new_record == NULL) {
            printf("Memory allocation failed\n");
            fclose(fp);
            return;
        }
        num_records++;

        // Reallocate array of records as needed to accommodate growing dataset
        int *new_capacity = num_records ? num_records : 1;
        record **new_array = (record **) realloc(records, new_capacity * sizeof(record *));
        if (new_array == NULL) {
            printf("Memory allocation failed\n");
            fclose(fp);
            return;
        }
        records = new_array;

        // Store the new record in the dynamically resized array
        records[num_records - 1] = new_record;
    }

    // Perform any necessary cleanup or processing before exiting
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);

    fclose(fp);
}
