// Structure to hold the pool of NFAPICRCINDICATIONPDU structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NFAPICRCINDICATIONPDU_POOL_T;

NFAPICRCINDICATIONPDU_POOL_T nfapicrcindicationpdu_pool = {0};

// Function to initialize the pool
void init_nfapicrcindicationpdu_pool() {
    // Initialize the mutex
    pthread_mutex_init(&nfapicrcindicationpdu_pool.lock, NULL);

    // Allocate memory for the initial capacity
    nfapicrcindicationpdu_pool.pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapicrcindicationpdu_pool.size = 0;
    nfapicrcindicationpdu_pool.capacity = MAX_POOL_SIZE;
}

// Function to add a new structure to the pool
void add_nfapicrcindicationpdu_to_pool(NFAPI_CRC_INDICATION_PDU_T* new_structure) {
    // Acquire the lock
    pthread_mutex_lock(&nfapicrcindicationpdu_pool.lock);

    // Check if the pool is full
    if (nfapicrcindicationpdu_pool.size >= nfapicrcindicationpdu_pool.capacity) {
        // Reallocate memory with double the capacity
        NFAPI_CRC_INDICATION_PDU_T* new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfapicrcindicationpdu_pool.pool, 2 * nfapicrcindicationpdu_pool.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Update the pool pointers
        nfapicrcindicationpdu_pool.pool = new_pool;
        nfapicrcindicationpdu_pool.capacity *= 2;
    }

    // Add the new structure to the pool
    nfapicrcindicationpdu_pool.pool[nfapicrcindicationpdu_pool.size] = *new_structure;
    nfapicrcindicationpdu_pool.size++;

    // Release the lock
    pthread_mutex_unlock(&nfapicrcindicationpdu_pool.lock);
}

// Function to retrieve a structure from the pool
NFAPI_CRC_INDICATION_PDU_T* get_nfapicrcindicationpdu_from_pool() {
    // Acquire the lock
    pthread_mutex_lock(&nfapicrcindicationpdu_pool.lock);

    // Check if the pool is empty
    if (nfapicrcindicationpdu_pool.size == 0) {
        // Release the lock and return NULL
        pthread_mutex_unlock(&nfapicrcindicationpdu_pool.lock);
        return NULL;
    }

    // Retrieve a structure from the pool
    NFAPI_CRC_INDICATION_PDU_T* retrieved_structure = &nfapicrcindationpdu_pool.pool[nfapicrcindicationpdu_pool.size - 1];
    nfapicrcindicationpdu_pool.size--;

    // Release the lock
    pthread_mutex_unlock(&nfapicrcindicationpdu_pool.lock);

    return retrieved_structure;
}

// Function to handle packet loss and latency monitoring
void monitor_packet_loss_and_latency() {
    // Check if packet loss exceeds threshold or latency surpasses threshold
    if (packet_loss > PACKET_LOSS_THRESHOLD || latency > LATENCY_THRESHOLD) {
        // Temporarily reduce the generation rate of new structures
        nfapicrcindicationpdu_pool.capacity /= 2;

        // Adjust the pool size based on real-time monitoring
        adjust_pool_size();
    }
}

