    StreamConfig **streams;
} ConfigurationManager;

ConfigManager* create_config_manager() {
    ConfigurationManager *manager = (ConfigurationManager*) malloc(sizeof(ConfigurationManager));
    manager->num_streams = 0;
    manager->streams = NULL;
    return (ConfigManager*) manager;
}

StreamConfig* create_stream_config(PGconn *connection, Config config) {
    StreamConfig *stream_config = (StreamConfig*) malloc(sizeof(StreamConfig));
    stream_config->connection = connection;
    stream_config->config = config;
    return stream_config;
}

void add_stream_to_manager(ConfigurationManager *manager, PGconn *connection, Config config) {
    manager->num_streams++;
    manager->streams = (StreamConfig**) realloc(manager->streams, sizeof(StreamConfig*) * manager->num_streams);
    manager->streams[manager->num_streams - 1] = create_stream_config(connection, config);
}

void destroy_manager(ConfigurationManager *manager) {
    for(int i = 0; i < manager->num_streams; i++) {
        PQfinish(manager->streams[i]->connection);
        free(manager->streams[i]);
    }
    free(manager->streams);
    free(manager);
}
