    NetworkConnectionStatus* connections;  // dynamically allocated array of connections
    int offset;  // current offset in the array
    int size;  // initial and maximum capacity of the array
    pthread_mutex_t mutex;  // mutex for concurrent access
} ConnectionMetadata;

// Initialize connection metadata structure
void init_connection_metadata(ConnectionMetadata* meta) {
    meta->offset = 0;
    meta->size = 1000;  // initialize with a small size
    pthread_mutex_init(&meta->mutex, NULL);
}

// Dynamically resize the connection array when needed
void resize_connections(ConnectionMetadata* meta) {
    int new_size = meta->size * 2;  // double the current size
    NetworkConnectionStatus* new_connections = (NetworkConnectionStatus*) realloc(
        meta->connections,
        new_size * sizeof(NetworkConnectionStatus)
