#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define struct for record
typedef struct {
    int value;
} Record;

// Define struct for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Add necessary fields here
    Record rx_ue_info_tag;
    int rnti;
    Record crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define memory pool structure
typedef struct {
    void **pool;  // Array to hold pointers to allocated records
    size_t size;   // Current size of the pool
    pthread_mutex_t lock;  // Mutex for synchronization
} MemoryPool;

// Function to initialize memory pool
MemoryPool* init_memory_pool(size_t initial_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (void**)calloc(initial_size, sizeof(void*));
    mp->size = initial_size;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

// Function to free memory pool
void free_memory_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->size; i++) {
        if (mp->pool[i] != NULL)
            free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to allocate memory from the pool
void* allocate_memory(MemoryPool* mp, size_t size) {
    void* ptr = NULL;

    // Acquire lock
    pthread_mutex_lock(&mp->lock);

    for (size_t i = 0; i < mp->size; i++) {
        if (mp->pool[i] == NULL) {
            mp->pool[i] = (void*)malloc(size);
            ptr = mp->pool[i];
            break;
        }
    }

    // Release lock
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

// Function to deallocate memory from the pool
void deallocate_memory(MemoryPool* mp, void* ptr) {
    size_t i;

    // Acquire lock
    pthread_mutex_lock(&mp->lock);

    for (i = 0; i < mp->size; i++) {
        if (mp->pool[i] == ptr) {
            free(ptr);
            mp->pool[i] = NULL;
            break;
        }
    }

    // Release lock
    pthread_mutex_unlock(&mp->lock);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(MemoryPool* mp, int num_puds) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;

    // Allocate memory for the PDU list
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(mp, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_puds);

    if (pdu_list != NULL) {
        // Populate the PDU list with random values
        for (int i = 0; i < num_puds; i++) {
            pdu_list[i].rx_ue_info_tag.value = rand();
            pdu_list[i].rnti = rand();
            pdu_list[i].crc_indication_rel8_tag.value = rand();
        }
    }

    return pdu_list;
}

// Function to handle error during memory allocation
void* allocate_memory_with_error_handling(MemoryPool* mp, size_t size) {
    void* ptr = NULL;

    while (1) {
        // Acquire lock
        pthread_mutex_lock(&mp->lock);

        for (size_t i = 0; i < mp->size; i++) {
            if (mp->pool[i] == NULL) {
                mp->pool[i] = (void*)malloc(size);
                ptr = mp->pool[i];
                break;
            }
        }

        // Release lock
        pthread_mutex_unlock(&mp->lock);

        if (ptr != NULL)
            break;

        // Handle memory allocation failure
        printf("Memory allocation failed. Trying again...\n");
    }

    return ptr;
}

int main() {
    // Initialize memory pool
    MemoryPool* mp = init_memory_pool(100);

    // Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    int num_puds = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_pdu_list(mp, num_puds);

    // Free memory pool
    free_memory_pool(mp);

    return 0;
}

