    size_t capacity; // maximum number of records allowed
    size_t size; // current number of records
} RecordCollection;

// Function to create and initialize an empty record collection
RecordCollection* createRecordCollection(size_t capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    collection->records = (Record*)calloc(capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    collection->capacity = capacity;
    collection->size = 0;
    return collection;
}

// Function to add a new record to the collection
int addRecord(RecordCollection* collection, int key, long offset) {
    if (collection->size >= collection->capacity) {
        // Resize the array when it reaches its maximum capacity
        size_t newCapacity = 2 * collection->capacity;
        Record* newRecords = (Record*)realloc(collection->records, newCapacity * sizeof(Record));
        if (!newRecords) {
            printf("Error: Memory allocation failed.\n");
            return -1;
        }

        collection->records = newRecords;
        collection->capacity = newCapacity;
    }

    Record* record = &collection->records[collection->size];
    record->key = key;
    record->offset = offset;

    collection->size++;
    return 0;
}

// Function to free the memory allocated for a record collection
void destroyRecordCollection(RecordCollection* collection) {
    if (!collection)
        return;

    free(collection->records);
    free(collection);
}
