import zlib
import hashlib
import threading

class CompressedFileStreamer:
    def __init__(self):
        self.streams = {}
        self.lock = threading.Lock()
        self.in_flight_bytes = 0
        self.total_compressed_size = 0

    def add_stream(self, name, stream):
        self.streams[name] = stream

    def get_all_streams(self):
        return self.streams.keys()

    def start_ingestion(self):
        threads = []
        for name, stream in self.streams.items():
            t = threading.Thread(target=self.ingest_stream, args=(name, stream))
            t.start()
            threads.append(t)

        for thread in threads:
            thread.join()

    def ingest_stream(self, name, stream):
        with self.lock:
            while True:
                chunk = stream.read(4096)
                if not chunk:
                    break
                compressed_chunk = zlib.compress(chunk)
                self.total_compressed_size += len(compressed_chunk)
                self.in_flight_bytes += len(compressed_chunk)

        with self.lock:
            del self.streams[name]

    def get_current_size(self):
        return self.total_compressed_size

    def check_for_data_loss(self):
        if self.total_compressed_size != sum(len(zlib.compress(s.read(4096))) for s in self.streams.values()):
            raise Exception("Data loss detected during ingestion")

class ArchiveWriter:
    def __init__(self, filename):
        self.filename = filename
        self.lock = threading.Lock()
        self.writer_thread = None

    def start_writing(self):
        if not self.writer_thread:
            t = threading.Thread(target=self.write_archive)
            t.start()
            self.writer_thread = t

    def write_archive(self):
        with open(self.filename, 'wb') as f:
            for stream in CompressedFileStreamer().get_all_streams():
                while True:
                    chunk = zlib.decompress(f.read(4096))
                    if not chunk:
                        break
                    f.write(chunk)
                    self.check_integrity()

    def check_integrity(self):
        if hashlib.md5(open(self.filename, 'rb').read()).hexdigest() != "expected_hash":
            raise Exception("Archive integrity compromised")

class ArchiveReader:
    def __init__(self, filename):
        self.filename = filename
        self.lock = threading.Lock()
        self.reader_thread = None

    def start_reading(self):
        if not self.reader_thread:
            t = threading.Thread(target=self.read_archive)
            t.start()
            self.reader_thread = t

    def read_archive(self):
        with open(self.filename, 'rb') as f:
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                print(chunk.decode())
                self.check_integrity()

    def check_integrity(self):
        if hashlib.md5(open(self.filename, 'rb').read()).hexdigest() != "expected_hash":
            raise Exception("Archive integrity compromised")

if __name__ == "__main__":
    fs = CompressedFileStreamer()
    fs.add_stream('stream1', open('file1', 'rb'))
    fs.add_stream('stream2', open('file2', 'rb'))

    aw = ArchiveWriter('archive')
    aw.start_writing()

    ar = ArchiveReader('archive')
    ar.start_reading()
