['```javascript
class DOMTraversal {
  constructor(root, selector) {
    this.root = root;
    this.selector = selector;
    this.callback = null;
    this.maxDepth = Infinity;
    this.paused = false;
    this.queue = [root];
    this.visited = new Set();
  }

  setCallback(cb) {
    this.callback = cb;
  }

  setMaxDepth(limit) {
    this.maxDepth = limit;
  }

  startTraversal() {
    this.paused = false;
    this.traverse(this.root);
  }

  pauseTraversal() {
    this.paused = true;
  }

  resumeTraversal() {
    this.paused = false;
    if (this.queue.length > 0) {
      this.traverse(this.queue.shift());
    }
  }

  traverse(node, depth = 0) {
    if (!node || !this.selector.test(node)) return;

    if (depth >= this.maxDepth) return;

    if (this.paused) {
      this.queue.push(node);
      return;
    }

    node.parentNode && this.traverse(node.parentNode, depth - 1);

    for (let child of node.children) {
      if (!this.visited.has(child)) {
        this.visited.add(child);
        this.queue.push(child);
        this.traverse(child, depth + 1);
      }
    }

    this.callback(node);
  }
}
