import java.io.*;
import java.lang.ProcessBuilder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class ConcurrentJavaCompilation {
    private static final int SEMAPHORE_VALUE = 5; // adjust this value as needed
    private static Semaphore semaphore = new Semaphore(SEMAPPHORE_VALUE);

    public void compileAndRunFiles(String[] files) throws IOException, InterruptedException {
        for (String file : files) {
            try {
                if (semaphore.tryAcquire()) { // acquire the semaphore
                    Path tempDir = Files.createTempDirectory("compiled-classes");
                    ProcessBuilder processBuilder = new ProcessBuilder("javac", "-cp", tempDir.toString(), file);

                    processBuilder.directory(tempDir.toFile());
                    processBuilder.start();
                    int exitValue = processBuilder.waitFor();

                    if (exitValue == 0) {
                        // run the compiled class
                        String className = file.substring(0, file.length() - 5); // remove .java extension
                        ProcessBuilder runner = new ProcessBuilder("java", "-cp", tempDir.toString(), className);
                        Process process = runner.start();
                        int exitValue2 = process.waitFor();

                        if (exitValue2 == 0) {
                            System.out.println("File " + file + " compiled and run successfully.");
                        } else {
                            System.out.println("File " + file + " compilation or execution failed with exit value " + exitValue2);
                        }
                    } else {
                        System.out.println("File " + file + " compilation failed with exit value " + exitValue);
                    }

                    semaphore.release(); // release the semaphore
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new InterruptedException(e.getMessage());
            } finally {
                // clean up temporary directory after a specified duration to optimize disk space usage
                // adjust this timeout as needed
                new Timer().schedule(new TimerTask() {
                    @Override
                    public void run() {
                        try {
                            Files.walk(tempDir).forEach(Files::delete);
                            System.out.println("Temporary compilation directory cleaned up.");
                        } catch (IOException e) {
                            System.err.println("Error cleaning up temporary compilation directory: " + e.getMessage());
                        }
                    }
                }, 10000); // adjust this timeout as needed
            }
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        ConcurrentJavaCompilation compiler = new ConcurrentJavaCompilation();
        String[] files = {"File1.java", "File2.java", "File3.java"}; // add your Java source files here

        compiler.compileAndRunFiles(files);
    }
}
