        try (FileInputStream fileInput = new FileInputStream(file.toFile());
             FileOutputStream fileOutput = new FileOutputStream("statusUpdates.bin")) {
            ZipOutputStream zipOutput = new ZipOutputStream(new FileOutputStream("statusUpdates.zip"));

            // serialize network interface status updates into binary format
            byte[] buffer = new byte[1000]; // adjust this size as needed
            for (int i = 0; i < 10; i++) { // adjust this count as needed
                fileInput.read(buffer);
                zipOutput.putNextEntry(new ZipEntry("statusUpdate" + i));
                zipOutput.write(buffer);
                zipOutput.closeEntry();
            }

            fileOutput.write(buffer);
        } catch (IOException e) {
            System.err.println("Error serializing network interface status updates: " + e.getMessage());
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        NetworkInterfaceSerializer serializer = new NetworkInterfaceSerializer();
