using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public class Config
{
    public string TripleDesKey { get; set; }
    public string InitializationVector { get; set; }
}

public class MemoryPool
{
    private Dictionary<int, byte[]> _pool = new Dictionary<int, byte[]>();
    private int _maxSize;
    private int _minSize;

    public MemoryPool(int maxSize, int minSize)
    {
        _maxSize = maxSize;
        _minSize = minSize;
    }

    public byte[] Allocate(int size)
    {
        if (_pool.ContainsKey(size))
        {
            return _pool[size].Clone() as byte[];
        }
        else
        {
            byte[] buffer = new byte[size];
            _pool.Add(size, buffer);
            return buffer;
        }
    }

    public void Deallocate(byte[] buffer)
    {
        int size = buffer.Length;
        if (_pool.ContainsKey(size))
        {
            _pool[size] = buffer;
        }
        else
        {
            _pool.Add(size, buffer);
        }
    }
}

public class ProcessAndManageDataStream
{
    private readonly MemoryPool _memoryPool;
    private readonly Dictionary<int, byte[]> _cachedMemory;
    private readonly Dictionary<string, Aes> _encryptionModes;

    public ProcessAndManageDataStream(Config config)
    {
        _memoryPool = new MemoryPool(1024 * 1024, 4096);
        _cachedMemory = new Dictionary<int, byte[]>();
        _encryptionModes = new Dictionary<string, Aes>();

        Aes aes = Aes.Create();
        aes.Key = Encoding.UTF8.GetBytes(config.TripleDesKey);
        aes.IV = Encoding.UTF8.GetBytes(config.InitializationVector);

        _encryptionModes.Add("CBC", aes);
        aes = Aes.Create();
        aes.Key = Encoding.UTF8.GetBytes(config.TripleDesKey);
        aes.IV = Encoding.UTF8.GetBytes(config.InitializationVector);
        aes.Mode = CipherMode.CFB;
        _encryption Modes.Add("CFB", aes);
    }

    public string ProcessAndDecryptStream(Stream stream)
    {
        string decryptedMessage = "";
        using (stream)
        {
            byte[] buffer = new byte[1024];
            int bytesRead;

            while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                byte[] segment = new byte[bytesRead];
                Array.Copy(buffer, segment, bytesRead);

                byte[] decryptedSegment;
                using (MemoryStream ms = new MemoryStream())
                {
                    CryptoStream cs = new CryptoStream(ms, _encryptionModes["CBC"].CreateDecryptor().TransformFinalBlock(segment, 0, bytesRead));
                    cs.Flush();
                    decryptedSegment = ms.ToArray();
                }

                decryptedMessage += Encoding.UTF8.GetString(decryptedSegment);
            }
        }

        return decryptedMessage;
    }
}
