import java.io.*;
import java.lang.reflect.Constructor;
import java.util.*;

public class ObjectDeserializer {
    private static final Map<ByteArrayKey, Object> cache = new HashMap<>();
    private static final Logger logger = LoggerFactory.getLogger(ObjectDeserializer.class);

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws DeserializationException {
        ByteArrayKey key = new ByteArrayKey(data);
        if (cache.containsKey(key)) {
            return (T) cache.get(key);
        }

        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new CustomObjectInputStream(bais)) {
            T obj = (T) ois.readObject();
            cache.put(key, obj);
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new DeserializationException("Error deserializing object: " + e.getMessage());
        }
    }

    private static class CustomObjectInputStream extends ObjectInputStream {
        public CustomObjectInputStream(ByteArrayInputStream bais) throws IOException {
            super(bais);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClassDesc desc) throws IOException, ClassNotFoundException {
            // Handle nested objects and collections here
            return super.resolveClass(desc);
        }
    }

    private static class ByteArrayKey {
        private final byte[] data;

        public ByteArrayKey(byte[] data) {
            this.data = data;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof ByteArrayKey)) return false;
            ByteArrayKey that = (ByteArrayKey) o;
            return Arrays.equals(data, that.data);
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(data);
        }
    }

    public static class DeserializationException extends Exception {
        public DeserializationException(String message) {
            super(message);
        }
    }
}
