element_t** allocate_arrays(size_t size, int min_int, int max_int) {
    size_t array_size = sizeof(element_t*) * size;
    element_t** arr1 = (element_t**)malloc(array_size);
    if (!arr1) return NULL;

    double* arr2 = (double*)malloc(sizeof(double) * size);
    if (!arr2) {
        free(arr1);
        return NULL;
    }

    char* arr3 = (char*)malloc(sizeof(char) * size);
    if (!arr3) {
        free(arr1);
        free(arr2);
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        element_t* e = &((element_t*)malloc(sizeof(element_t)));
        if (!e) {
            for (int j = 0; j < i; ++j) {
                free(((element_t*)arr1)[j]);
            }
            free(arr1);
            free(arr2);
            free(arr3);
            return NULL;
        }

        e->i = min_int + rand() % (max_int - min_int + 1);
        arr2[i] = (double)rand() / RAND_MAX;

        // Validate and preprocess char* fields
        size_t len = sprintf(e->c, "string_%zu", i);
        memcpy(arr3 + i * sizeof(char), e->c, len + 1);

        arr1[i] = e;
    }

    return arr1;
}

void free_arrays(element_t** arr1, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(((element_t*)arr1)[i]);
    }
    free(arr1);
    free((double*)malloc(sizeof(double) * size));
    free((char*)malloc(sizeof(char) * size));
}
