typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void largest_integer(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("Largest integer: %d\n", max);
}

void print_array(int* arr, int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int main() {
    const int THRESHOLD = 100000;
    const int RANGE_MIN = -10000;
    const int RANGE_MAX = 10000;

    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu = NULL;
    int* arr = NULL;
    int sum = 0;
    int size = 0;
    int max_rnti = -1;

    FILE* input_file = fopen("input.txt", "r");
    if (input_file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    while (!feof(input_file)) {
        int val;
        if (fscanf(input_file, "%d", &val) != 1) {
            break;
        }
        if (val < RANGE_MIN || val > RANGE_MAX) {
            printf("Invalid input: %d\n", val);
            continue;
        }
        sum += val;

        if (sum > THRESHOLD) {
            printf("Sum exceeds threshold. Terminating.\n");
            break;
        }

        size++;
    }

    fclose(input_file);

    if (size == 0) {
        printf("No valid integers found.\n");
        return 1;
    }

    arr = malloc(sizeof(int) * size);
    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    int* p_arr = arr;
    for (int i = 0; i < size; i++) {
        if (fscanf(input_file, "%d", &val) != 1) {
            break;
        }
        *p_arr++ = val;
    }
    fclose(input_file);

    print_array(arr, size);
    largest_integer(arr, size);

    // Initialize NFAPI_CRC_INDICATION_PDU_T structures
    srand(time(NULL));
    nfapi_crc_indication_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
    if (nfapi_crc_indication_pdu == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }
    for (int i = 0; i < 10; i++) {
        nfapi_crc_indication_pdu[i].RX_UE_INFORMATION_TAG = rand() % RANGE_MAX + RANGE_MIN;
        nfapi_crc_indication_pdu[i].RNTI = rand() % RANGE_MAX + RANGE_MIN;
        nfapi_crc_indication_pdu[i].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;
    }

    // Free memory
    free(arr);
    free(nfapi_crc_indication_pdu);

    return 0;
}
