    list<event_tag_t> event_tags;
    list<performance_metrics_t> metrics;
} network_event_t;

void init_network_interface_status_update_and_performance_metrics(int num_interfaces) {
    sem_t semaphore;
    pthread_mutex_t mutex;

    if (sem_init(&semaphore, 0, num_interfaces) == -1)
