typedef struct {
    int key;
} record_t;

record_t* generateRandomRecords(size_t size, int minValue, int maxValue) {
    record_t* records = NULL;
    long* offsets = NULL;
    char* md5Hashes = NULL;

    try {
        // Allocate memory for arrays
        records = (record_t*)malloc(size * sizeof(record_t));
        if (!records) {
            printf("Error: Failed to allocate memory for records.\n");
            return NULL;
        }

        offsets = (long*)malloc(size * sizeof(long));
        if (!offsets) {
            free(records);
            printf("Error: Failed to allocate memory for offsets.\n");
            return NULL;
        }

        md5Hashes = (char*)malloc(size * MD5_DIGEST_LENGTH);
        if (!md5Hashes) {
            free(offsets);
            free(records);
            printf("Error: Failed to allocate memory for MD5 hashes.\n");
            return NULL;
        }

        // Initialize each record's int field with a random value
        for (size_t i = 0; i < size; i++) {
            records[i].key = rand() % ((maxValue - minValue) + 1) + minValue;

            // Compute the MD5 hash of "UniqueRecords" and store it in md5Hashes
            MD5_CTX ctx;
            MD5_Init(&ctx);
            const char* str = "UniqueRecords";
            size_t len = strlen(str);
            unsigned char hash[MD5_DIGEST_LENGTH];
            MD5_Update(&ctx, str, len);
            MD5_Final(hash, &ctx);

            // Copy the hash into md5Hashes
            memcpy(md5Hashes + i * MD5_DIGEST_LENGTH, hash, MD5_DIGEST_LENGTH);
        }
    } catch (int e) {
        free(offsets);
        free(records);
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Return the records array
    return records;
}
