NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int N, int chunkSize) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    size_t totalSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    // Allocate memory in chunks to minimize fragmentation
    size_t remainingBytes = totalSize;
    while (remainingBytes > 0) {
        size_t chunk = (remainingBytes < chunkSize) ? remainingBytes : chunkSize;
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (N / chunkSize + 1));
        if (array == NULL) {
            printf("Allocation failure. exiting...\n");
            free(array);
            exit(-1);
        }
        for (int i = 0; i < N / chunkSize && remainingBytes >= sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
            NFAPI_CRC_INDICATION_PDU_T* p = allocChunk(chunk * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (p == NULL) {
                printf("Allocation failure. exiting...\n");
                free(array);
                free(p);
                exit(-1);
            }
            // Populate the structure
            p->RX_UE_INFORMATION_TAG = malloc(strlen("RX_UE_INFORMATION_TAG") + 1);
            strcpy(p->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
            p->RNTI = rand();
            p->CRC_INDICATION_REL8_TAG = malloc(strlen("CRC_INDICATION_REL8_TAG") + 1);
