            if (rand() % 2) {
                p->CRCFLAG = 0x01;
            } else {
                p->CRCFLAG = 0x00;
            }
            // Free memory after use
            free(p->RX_UE_INFORMATION_TAG);
            free(p->CRC_INDICATION_REL8_TAG);
        }
        remainingBytes -= chunk * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    return array;
}

int main() {
    int N = 10; // Number of structures to allocate
    int chunkSize = 2; // Size of memory allocation in chunks

