        printf("RX_UE_INFORMATION_TAG: %s, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: 0x%x\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG, array[i].CRCFLAG);
