pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* append_log_entry(int initial_allocation_size) {
    size_t total_size = sizeof(log_entry*) + sizeof(log_entry);
    for (int i = 0; i < initial_allocation_size; i++) {
        total_size += sizeof(int) + strlen("dummy message") + 1;
    }

    log_entry** new_log_entries = realloc(log_entries, total_size);
    if (!new_log_entries) return NULL;

    log_entry* new_entry = (log_entry*)malloc(total_size - sizeof(log_entry*) - sizeof(log_entry));
    if (!new_entry) {
        free(new_log_entries);
        return NULL;
    }

    // initialize new entry fields
    new_entry->timestamp = 0;
    new_entry->message = "dummy message";
    int* user_ids = (int*)malloc((initial_allocation_size + 1) * sizeof(int));
    for (int i = 0; i <= initial_allocation_size; i++) {
        user_ids[i] = -1; // initialize with invalid value
    }
    new_entry->user_ids = user_ids;

    pthread_mutex_lock(&mutex);
    log_entries = new_log_entries;
    num_log_entries++;
    pthread_mutex_unlock(&mutex);

    return (void*)new_entry;
}

int main() {
    // configure initial allocation size and verbosity level
    int initial_allocation_size = MAX_INITIAL_ALLOCATION;
    int verbosity_level = VERBOSITY_LEVELS;

