        if (!new_log_entry) break; // handle reallocation failure

        // validate and preprocess message field
        if (!validate_message(new_log_entry->message)) {
            free(new_log_entry);
            continue;
        }

        // interface with external logging service
        log_to_external_service(new_log_entry);

        free(new_log_entry);
    }
}
