#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the types for offset_t, key_t, and record_t
typedef int offset_t;
typedef int key_t;
typedef struct {
    int value;
    offset_t offset;
    key_t key;
} record_t;

// Function to initialize arrays with dynamic memory allocation
void initArrays(int* size, offset_t*** offsets, key_t*** keys, record_t**** records) {
    // Initialize the size variable
    *size = 1024; // Minimum size of arrays

    // Allocate memory for each array
    *offsets = (offset_t**)malloc(*size * sizeof(offset_t));
    *keys = (key_t**)malloc(*size * sizeof(key_t));
    *records = (record_t***)malloc(*size * sizeof(record_t));

    for(int i = 0; i < *size; i++) {
        // Initialize each array element
        (*offsets)[i] = (offset_t)malloc(1 * sizeof(offset_t));
        (*keys)[i] = (key_t)malloc(1 * sizeof(key_t));
        (*records)[i] = (record_t*)malloc(1 * sizeof(record_t));

        // Initialize record values with random numbers
        srand(time(NULL)); // Seed the random number generator
        int value = rand() % 100; // Random number between 0 and 99
        ((*records)[i])->value = value;
        ((*records)[i])->offset = i; // Assign offset index
        ((*records)[i])->key = i; // Assign key index

        // Ensure unique keys across different record instances
        int conflict = 0;
        for(int j = 0; j < *size; j++) {
            if((*keys)[j] == ((*records)[i])->key) {
                conflict++;
                break;
            }
        }

        if(conflict > 0) {
            // Handle duplicate key conflicts
            printf("Duplicate key detected! Conflict resolved.\n");
            for(int k = *size - 1; k >= 0; k--) {
                if((*keys)[k] == ((*records)[i])->key) {
                    free((*offsets)[k]);
                    free((*keys)[k]);
                    free((*records)[k]);
                    (*keys)[k] = ((*records)[i])->key;
                    break;
                }
            }
        }
    }

    // Free any allocated memory when done
}

// Function to deallocate arrays and their elements
void deinitArrays(int* size, offset_t*** offsets, key_t*** keys, record_t**** records) {
    for(int i = 0; i < *size; i++) {
        free((*offsets)[i]);
        free((*keys)[i]);
        free((*records)[i]);
    }

    free(*offsets);
    free(*keys);
    free(*records);

    // Reset the size variable
    *size = 0;
}

// Main function to test and simulate usage
int main() {
    int size = 1024; // Initial array size
    offset_t** offsets;
    key_t** keys;
    record_t**** records;

