// Structure definition for storing data
typedef struct {
    char* str;
    double value;
    long int_num;
    int int_val;
} DataStructure;

void manage_memory(int n, int m) {
    // Allocate memory for array of long integers with size 'n'
    long* long_array = (long*)malloc(n * sizeof(long));
    if (!long_array) {
        printf("Memory allocation failed for long array\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        long_array[i] = 0;
    }

    // Allocate memory for array of int integers with size 'm'
    int* int_array = (int*)malloc(m * sizeof(int));
    if (!int_array) {
        printf("Memory allocation failed for int array\n");
        free(long_array);
        return;
    }
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        int_array[i] = rand() % 100 + 1;
    }

    // Allocate memory for array of DataStructure with size 'n'
    DataStructure* data_array = (DataStructure*)malloc(n * sizeof(DataStructure));
    if (!data_array) {
        printf("Memory allocation failed for data array\n");
        free(long_array);
        free(int_array);
        return;
    }
    for (int i = 0; i < n; i++) {
        data_array[i].str = malloc(257); // +1 for null termination
        data_array[i].value = 0.0;
        data_array[i].int_num = long_array[i];
        data_array[i].int_val = int_array[i % m]; // cycle through int_array

        while (rand() % 100 == 0) {
            data_array[i].int_val = rand() % 100 + 1; // handle overflow
        }
    }

    // Periodic memory usage logging and adjustment
    size_t total_memory = n * sizeof(long) + m * sizeof(int) + n * sizeof(DataStructure);
    printf("Total allocated memory: %zu bytes\n", total_memory);

    // Serialize data to file
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        printf("Failed to open file for serialization\n");
        free(long_array);
        free(int_array);
        free(data_array);
        return;
    }
    fwrite(long_array, sizeof(long), n, file);
    fwrite(int_array, sizeof(int), m, file);
    fwrite(&n, sizeof(int), 1, file); // serialize array sizes
    for (int i = 0; i < n; i++) {
        fwrite(data_array[i].str, 1, strlen(data_array[i].str) + 1, file);
        fwrite(&data_array[i].value, sizeof(double), 1, file);
        fwrite(&data_array[i].int_num, sizeof(long), 1, file);
        fwrite(&data_array[i].int_val, sizeof(int), 1, file);
    }
    fclose(file);

    // Deserialize data from file
    file = fopen("data.bin", "rb");
    if (!file) {
        printf("Failed to open file for deserialization\n");
        free(long_array);
        free(int_array);
        free(data_array);
        return;
    }
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    // Resize arrays based on file size
    int newSize = (fileSize / sizeof(long)) + ((fileSize % sizeof(long) > 0) ? 1 : 0);
    long_array = realloc(long_array, newSize * sizeof(long));
    int_array = realloc(int_array, newSize * sizeof(int));
    data_array = realloc(data_array, newSize * sizeof(DataStructure));

    // Deserialize data
    fread(long_array, sizeof(long), newSize, file);
    fread(int_array, sizeof(int), newSize, file);
    int nRead = (int)fread(&n, sizeof(int), 1, file); // read array sizes
    if (nRead < 1) {
        printf("Failed to read array sizes from file\n");
        free(long_array);
        free(int_array);
        free(data_array);
        return;
    }
    for (int i = 0; i < n; i++) {
        char buffer[257];
        fread(buffer, 1, strlen(data_array[i].str) + 1, file);
        data_array[i].str = malloc(strlen(buffer));
        strcpy(data_array[i].str, buffer);
        fread(&data_array[i].value, sizeof(double), 1, file);
        fread(&data_array[i].int_num, sizeof(long), 1, file);
        fread(&data_array[i].int_val, sizeof(int), 1, file);
    }
    fclose(file);

    // Handle concurrent allocations
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    void* concurrent_allocation(void* arg) {
        int* int_ptr = (int*)malloc(10 * sizeof(int)); // example allocation
        if (!int_ptr) {
            printf("Memory allocation failed in concurrent thread\n");
            return NULL;
        }
        pthread_mutex_unlock(&lock); // release lock on exit
        free(int_ptr);
    }

    pthread_t threads[n];
    for (int i = 0; i < n; i++) {
        pthread_create(&threads[i], NULL, concurrent_allocation, NULL);
        pthread_join(threads[i], NULL);
    }
}

int main() {
    manage_memory(100, 50);
    return 0;
}
