#include <stdlib.h>
#include <string.h>

typedef struct {
    char ip_address[16];
    int port_number;
    enum { DISCONNECTED, CONNECTED } connection_state;
} NetworkConnectionStatus;

void network_connections_init(NetworkConnectionStatus** connections, size_t* capacity) {
    *connections = NULL;
    *capacity = 0;
}

int network_connections_add(NetworkConnectionStatus** connections, size_t* capacity, const char* ip_address, int port_number, enum { DISCONNECTED, CONNECTED } connection_state) {
    if (*capacity == 0) {
        *connections = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
        ++(*capacity);
    } else if (*capacity < *capacity + 1) {
        NetworkConnectionStatus* new_connections = (NetworkConnectionStatus*)realloc(*connections, sizeof(NetworkConnectionStatus) * (*capacity * 2 + 1));
        *connections = new_connections;
        *capacity *= 2;
    }

    NetworkConnectionStatus* connection = &((*connections)[*capacity - 1]);
    strcpy(connection->ip_address, ip_address);
    connection->port_number = port_number;
    connection->connection_state = connection_state;

    return *capacity - 1;
}

int network_connections_update(NetworkConnectionStatus** connections, size_t capacity, int index, enum { DISCONNECTED, CONNECTED } new_connection_state) {
    if (index >= capacity || !connections) {
        return -1;
    }

    NetworkConnectionStatus* connection = &((*connections)[index]);
    connection->connection_state = new_connection_state;

    return 0;
}

int network_connections_get_active_count(NetworkConnectionStatus** connections, size_t capacity) {
    int active_count = 0;
    for (size_t i = 0; i < capacity; ++i) {
        if ((*connections)[i].connection_state == CONNECTED) {
            ++active_count;
        }
    }

    return active_count;
}

void network_connections_cleanup(NetworkConnectionStatus** connections, size_t* capacity) {
    NetworkConnectionStatus* connection_to_remove = NULL;
    for (size_t i = 0; i < *capacity; ++i) {
        if ((*connections)[i].connection_state == DISCONNECTED) {
            connection_to_remove = &((*connections)[i]);
        } else {
            break;
        }
    }

    if (connection_to_remove != NULL) {
        size_t new_capacity = *capacity - 1;
        NetworkConnectionStatus* new_connections = (NetworkConnectionStatus*)realloc(*connections, sizeof(NetworkConnectionStatus) * new_capacity);

        for (size_t i = connection_to_remove - (*connections); i < *capacity; ++i) {
            (*connections)[i] = (*connections)[i + 1];
        }

        free(&((*connections)[*capacity - 1]));
        *connections = new_connections;
        *capacity = new_capacity;
    }
}

void network_connections_periodic_scan(NetworkConnectionStatus** connections, size_t* capacity) {
    int inactive_count = 0;
    for (size_t i = 0; i < *capacity; ++i) {
        if ((*connections)[i].connection_state == DISCONNECTED) {
            ++inactive_count;
        }
    }

    if (inactive_count > (*capacity / 2)) {
        network_connections_cleanup(connections, capacity);
    }
}

