    time_t timestamp;
    int signalStrength;
    struct band* freqBands;
    int numBands;
} MeasurementReport;

typedef struct {
    int frequency;
} Band;

void addMeasurementReport(UEContext* ue, MeasurementReport* report) {
    // Add the new report to the existing list
    if (ue->numReports < MAX_REPORTS) {
        ue->reports[ue->numReports] = report;
        ue->numReports++;
    } else {
        printf("UEContext is full. Cannot add more reports.\n");
    }
}

void updateSignalStrength(UEContext* ue, int newReportId) {
    // Find the last N reports (where N is the specified size limit)
    for (int i = 0; i < MAX_UERC - 1; i++) {
        MeasurementReport* report = &ue->reports[i];
        // Calculate the updated signal strength based on recent measurements
        int newSignalStrength = 0;
        for (int j = 0; j < MAX_REPORTS - 1; j++) {
            if (i - j >= 0) {
                newSignalStrength += report[j].signalStrength;
            }
        }
        // Update the signal strength with the average value
        ue->reports[i + 1].signalStrength = newSignalStrength / (MAX_UERC - 1);
    }
}

void deleteOldReports(UEContext* ue, int sizeLimit) {
    // Remove old reports when the UEContext reaches the specified size limit
    if (ue->numReports > sizeLimit) {
        for (int i = sizeLimit; i < MAX_REPORTS; i++) {
            free(&ue->reports[i]);
        }
        ue->numReports = sizeLimit;
    }
