    size_t total_memory_needed = (offset_size + key_size) * sizeof(long) + num_records * sizeof(Record);

    // Check if the total memory needed exceeds 50% of available system memory
    size_t available_memory = sysconf(_SC_PAGESIZE) * sysconf(_SC_PHYSICAL_MEMORY_SIZE) / 2;
