    int* key_array = malloc(key_size * sizeof(int));
    if (!offset_array || !key_array) {
        printf("Error: Memory allocation failed during array initialization.\n");
        free(offset_array);
        free(key_array);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < offset_size; i++) {
        offset_array[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        key_array[i] = i;
    }

    // Allocate memory for records
    Record* record_array = malloc(num_records * sizeof(Record));
    if (!record_array) {
        printf("Error: Memory allocation failed during record initialization.\n");
        free(offset_array);
        free(key_array);
        return NULL;
