        if (array[i] > max_val)
            max_val = array[i];
    }

    while (size <= THRESHOLD) {
        handleArrayOverflow(&array, &size);
    }

    printf("Largest integer: %d\n", max_val);

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

