// Initialize a new graph instance
Graph* create_graph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->num_vertices = 0;
    graph->vertices = NULL;
    graph->num_edges = 0;
    graph->edges = NULL;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

// Add a vertex to the graph
void add_vertex(Graph* graph, int id, const char* label, double weight) {
    Vertex* new_vertex = (Vertex*)malloc(sizeof(Vertex));
    new_vertex->id = id;
    strcpy(new_vertex->label, label);
    new_vertex->weight = weight;

    pthread_mutex_lock(&graph->lock);
    if (graph->num_vertices >= MAX_VERTICES) {
        // Automatic re-sizing
        graph->vertices = realloc(graph->vertices, sizeof(Vertex) * 2 * MAX_VERTICES);
        MAX_VERTICES *= 2;
    }
    graph->vertices[graph->num_vertices++] = new_vertex;
    pthread_mutex_unlock(&graph->lock);
}

// Add an edge to the graph
void add_edge(Graph* graph, int from_id, int to_id, int type, double capacity) {
    Edge* new_edge = (Edge*)malloc(sizeof(Edge));
    new_edge->id = graph->num_edges++;
    new_edge->type = type;
    new_edge->capacity = capacity;
    new_edge->from_vertex_id = from_id;
    new_edge->to_vertex_id = to_id;

    pthread_mutex_lock(&graph->lock);
    if (graph->num_edges >= MAX_EDGES) {
        // Automatic re-sizing
        graph->edges = realloc(graph->edges, sizeof(Edge) * 2 * MAX_EDGES);
        MAX_EDGES *= 2;
    }
    graph->edges[graph->num_edges - 1] = new_edge;
    pthread_mutex_unlock(&graph->lock);
}

// Remove a vertex from the graph
void remove_vertex(Graph* graph, int id) {
    // Find and remove the vertex
    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->vertices[i]->id == id) {
            free(graph->vertices[i]);
            memmove(&graph->vertices[i], &graph->vertices[i + 1], sizeof(Vertex) * (graph->num_vertices - i - 1));
            graph->num_vertices--;
            break;
        }
    }

    // Update edge references
    for (int i = 0; i < graph->num_edges; i++) {
        if (graph->edges[i]->from_vertex_id == id || graph->edges[i]->to_vertex_id == id) {
            free(graph->edges[i]);
            memmove(&graph->edges[i], &graph->edges[i + 1], sizeof(Edge) * (graph->num_edges - i - 1));
            graph->num_edges--;
        }
    }
}

// Periodic garbage collection to free up unused memory
void collect_garbage(Graph* graph) {
    // Compact the vertex array and update edge references
    Vertex* new_vertices = (Vertex*)malloc(sizeof(Vertex) * (graph->num_vertices - 1));
    int new_vertex_count = 0;
    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->vertices[i]->id != 0) { // Ignore removed vertices
            new_vertices[new_vertex_count++] = *graph->vertices[i];
        }
    }
    free(graph->vertices);
    graph->vertices = new_vertices;
    graph->num_vertices--;

    // Compact the edge array and update edge references
    Edge* new_edges = (Edge*)malloc(sizeof(Edge) * (graph->num_edges - 1));
    int new_edge_count = 0;
    for (int i = 0; i < graph->num_edges; i++) {
        if ((graph->edges[i]->from_vertex_id != 0 && graph->edges[i]->to_vertex_id != 0) ||
            (graph->edges[i]->from_vertex_id == id && graph->edges[i]->to_vertex_id == id)) { // Ignore removed edges
            new_edges[new_edge_count++] = *graph->edges[i];
        }
    }
    free(graph->edges);
    graph->edges = new_edges;
    graph->num_edges--;
}

// Logging mechanism to monitor system performance and resource usage
void log_system_info(Graph* graph) {
    printf("Vertices: %d, Edges: %d, Memory Usage: %.2f MB\n", graph->num_vertices, graph->num_edges, (double)(graph->num_vertices + graph->num_edges) * sizeof(Vertex) / 1024);
}

// Main function to demonstrate thread-safe operations
int main() {
    Graph* graph = create_graph();

    // Example usage: add vertices and edges concurrently
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, (void*)thread_function, graph);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i]);
    }

    // Perform periodic garbage collection and logging
    while (1) {
        collect_garbage(graph);
        log_system_info(graph);
        sleep(60); // Periodic interval in seconds
    }

    return 0;
}

// Thread function to simulate concurrent vertex and edge additions
void* thread_function(void* arg) {
    Graph* graph = (Graph*)arg;

    for (int i = 0; i < 1000; i++) {
        add_vertex(graph, i + 1, "Label", 2.5);
        add_edge(graph, i + 1, i + 2, 1, 3.14);
        sleep(10); // Simulate concurrency delay
    }

    return NULL;
}
