function runTests(moduleName, testCases, callback) {
  const blueslip = require('blueslip');
  let totalExecutionTime = 0;

  for (const testCase of testCases) {
    try {
      // Load the module
      const module = require(`./${moduleName}`);

      // Reset blueslip before each test
      blueslip.reset();

      // Execute the test
      const startTime = process.hrtime()[0] * 1000;
      const result = testCase.testCase();
      const endTime = process.hrtime()[0] * 1000;

      // Log the test result and execution time
      console.log(`Module: ${moduleName}, Test: ${testCase.label}, Result: ${result ? 'Passed' : 'Failed'}, Execution Time: ${endTime - startTime}ms`);

      totalExecutionTime += endTime - startTime;
    } catch (error) {
      // Handle errors during module loading or test execution
      console.error(`Error executing test: ${moduleName} > ${testCase.label}`, error);
    }
  }

  callback(totalExecutionTime, result); // Pass the total execution time and the overall result to the callback
}
