#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <zlib.h>

// Define the possible data unit types
enum DataUnitType { MESSAGE, ALERT, STATUS };

// Define the 'dataUnit' structure to represent a single data stream input
typedef struct {
    int timestamp;
    char payload[256];
    enum DataUnitType type;
} dataUnit;

// Define the 'processAndOptimizeDataStreams' function
void processAndOptimizeDataStreams(int numDataUnits, dataUnit *dataUnits) {
    // Create a priority queue to store unique payloads for deduplication
    void **pq_elements = NULL;
    int pq_size = 0;

    int start_time = time(NULL);

    printf("Processing and optimizing data streams...\n");
    for (int i = 0; i < numDataUnits; i++) {
        // Initialize a random payload from the predefined list of messages
        const char *payloads[] = {"Message 1", "Message 2", "Alert!", "Status Update"};
        srand(time(NULL));
        int payload_idx = rand() % sizeof(payloads) / sizeof(payloads[0]);
        strcpy(dataUnits[i].payload, payloads[payload_idx]);

        // Generate a random timestamp within the specified range
        dataUnits[i].timestamp = (rand() % 10000);

        // Set the type identifier randomly
        int type_idx = rand() % 4;
        switch (type_idx) {
            case 0:
                dataUnits[i].type = MESSAGE;
                break;
            case 1:
                dataUnits[i].type = ALERT;
                break;
            case 2:
                dataUnits[i].type = STATUS;
                break;
            default:
                printf("Invalid type identifier.\n");
                return;
        }

        // Compress the payload using zlib
        unsigned char *compressed_payload = NULL;
        int compressed_length;
        compress(&compressed_payload, &compressed_length, (void *)dataUnits[i].payload);
        dataUnits[i].payload[0] = '\0';
        memcpy(dataUnits[i].payload, compressed_payload, compressed_length);
        free(compressed_payload);

        // Measure and log the compression ratio
        int uncompressed_size = strlen(dataUnits[i].payload);
        double compression_ratio = (double)compressed_length / uncompressed_size;
        printf("Compression ratio: %f\n", compression_ratio);

        // Decompress the payload for storage
        unsigned char *decompressed_payload = malloc(compressed_length + 1);
        decompress(decompressed_payload, compressed_length, (void *)dataUnits[i].payload);
        decompressed_payload[compressed_length] = '\0';
        strcpy(dataUnits[i].payload, (char *)decompressed_payload);

        // Deduplicate consecutive data units with identical payloads
        if (!pq_elements) {
            pq_elements = malloc(sizeof(void *) * 1);
            pq_size = 1;
        } else {
            for (int j = 0; j < pq_size; j++) {
                if (!strcmp((char *)pq_elements[j], (char *)dataUnits[i].payload)) {
                    // Data unit is a duplicate, skip processing
                    continue;
                }
            }
            pq_elements[pq_size++] = &dataUnits[i];
        }

        printf("Data unit processed.\n");
    }

    int end_time = time(NULL);
    printf("Total processing time: %d seconds.\n", (end_time - start_time));

    // Print the priority queue elements for deduplication
    for (int i = 0; i < pq_size; i++) {
        printf("%s\n", (char *)pq_elements[i]);
    }
}
