void* aligned_malloc(size_t size, int alignment) {
    void* ptr = malloc(size + (alignment - 1));
    char* aligned_ptr = ((char*)ptr + (alignment - 1)) & ~(alignment - 1);
    return aligned_ptr;
}

void compact_arrays(void** arrays, int num_arrays) {
    for (int i = 0; i < num_arrays; i++) {
        void* prev_end = NULL;
        for (void* ptr = arrays[i]; ptr != NULL; ) {
            size_t new_size = strlen((char*)ptr);
            if (new_size > *(size_t*)ptr) {
                // reallocate with new size
                void* new_ptr = realloc(ptr, new_size * sizeof(char));
                if (new_ptr == NULL) {
                    printf("Memory allocation failed for array %d\n", i);
                    return;
                }
                ptr = new_ptr;
            } else {
                *(size_t*)ptr -= 1;
            }
            prev_end = ptr + new_size;
        }
    }
}

void real_time_analysis(void** arrays, int num_arrays) {
