            maxOffset = offsets[i];
    }

    // Sort records by offset in descending order
    record* sortedRecords = malloc(numRecords * sizeof(record));
    memcpy(sortedRecords, records, numRecords * sizeof(record));
    qsort(sortedRecords, numRecords, sizeof(record), (int (*)(const void *, const void *))compareRecords);

    // Return the largest integer and a pointer to the sorted array of records
    return (record*)malloc(sizeof(record) + 1);
}

int compareRecords(const void* a, const void* b) {
    record* recA = *(record**)a;
    record* recB = *(record**)b;

    if (recA->offset > recB->offset)
        return -1;
    else if (recA->offset < recB->offset)
        return 1;
    else
