// Function to generate random values within a specified range, ensuring no duplicates among records
int get_random_value(int min, int max) {
    static int last_value = -1;
    while (last_value >= 0 || (rand() % (max - min + 1)) < 1) {
        last_value = rand() % (max - min + 1) + min;
    }
    return last_value;
}

// Function to dynamically allocate and initialize the requested data structures
int init_data_structures(size_t max_records, int concurrency) {
    if (max_records < 0 || concurrency <= 0) {
        printf("Error: Invalid input parameters.\n");
        return -1; // Return error code for invalid inputs
    }

    size_t record_count = 0;
    while (record_count < max_records && get_random_value(0, 100) > 50) {
        record_count++;
    }

    // Dynamically allocate memory for data structures based on the maximum number of records and concurrency level
    if ((max_records + concurrency) * sizeof(int) > 1024*1024 || record_count > max_records) {
        printf("Error: Memory allocation failed.\n");
        return -1; // Return error code for memory allocation failure
    }

    keys = (int*)malloc(record_count * sizeof(int));
    if (!keys) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    offsets = (long*)malloc((record_count + 1) * sizeof(long));
    if (!offsets) {
        free(keys);
        keys = NULL; // Free memory when an error occurs
        return -1;
    }

    records = (record_t*)malloc(record_count * sizeof(record_t));
    for (size_t i = 0; i < record_count; i++) {
        records[i].value = get_random_value(0, 100);
    }

    return 0; // Return status code indicating success
}

int main() {
    max_records = 1024;
    concurrency = 8;

    if (init_data_structures(max_records, concurrency) == -1) {
        printf("Error: Failed to initialize data structures.\n");
    } else {
        printf("Data structures initialized successfully.\n");
    }

    return 0; // Return status code indicating success
}
