#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
} Record;

// Function to create a new record with unique integer key and offset value.
Record* createRecord(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if(record == NULL) {
        return NULL; // Handle memory allocation failure
    }
    record->key = key;
    record->offset = offset;
    return record;
}

// Function to insert a new record into the collection.
int insertRecord(Record** records, int* count, int key, long offset) {
    Record* record = createRecord(key, offset);
    if(record == NULL) {
        return -1; // Handle memory allocation failure
    }

    // Add new record to the end of the array
    *count += 1;
    records = (Record**)realloc(*records, (*count) * sizeof(Record*));
    if(records == NULL) {
        free(record);
        return -2; // Handle memory allocation failure
    }
    records[*count-1] = record;
    return 0;
}

// Function to delete a record from the collection by its key.
int deleteRecord(Record** records, int* count, int key) {
    for(int i=0; i<*count; i++) {
        if(records[i]->key == key) {
            free(records[i]);
            // Shift elements after deletion
            memmove(&records[i], &records[i+1], (*count-1-i)*sizeof(Record*));
            *count -= 1;
            return 0;
        }
    }
    return -1; // Record not found
}

// Function to iterate over the records in the collection.
void iterateRecords(Record** records, int count) {
    for(int i=0; i<count; i++) {
        printf("Key: %d Offset: %ld\n", records[i]->key, records[i]->offset);
    }
}

int main() {
    Record* records = NULL;
    int count = 0;

    // Create and insert records
    if(insertRecord(&records, &count, 1, 100) == -1) {
        printf("Memory allocation failed\n");
        return -1;
    }
    if(insertRecord(&records, &count, 2, 200) == -1) {
        printf("Memory allocation failed\n");
        return -1;
    }
    if(insertRecord(&records, &count, 3, 300) == -1) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Delete a record
    if(deleteRecord(&records, &count, 2) == -1) {
        printf("Record not found\n");
    }

    // Iterate over records
    iterateRecords(records, count);

    // Free resources
    for(int i=0; i<count; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}

