typedef enum {
    SESSION_ACTIVE,
    SESSION_IDLE,
    SESSION_EXPIRED
} SessionState;

typedef struct UserSession {
    int UserID;
    time_t LastActiveTime;
    SessionState State;
} UserSession;

UserSession* session_array = NULL;
int num_sessions = 0;
time_t gc_last_run = 0;

void gc(void) {
    if (difftime(time(NULL), gc_last_run) >= GC_INTERVAL) {
        for (int i = 0; i < num_sessions; i++) {
            if (session_array[i].State == SESSION_EXPIRED) {
                free(&session_array[i]);
                session_array[i] = session_array[--num_sessions];
                i--;
            }
        }
        gc_last_run = time(NULL);
    }
}

int add_session(int userID, SessionState state) {
    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    if (new_session != NULL) {
        new_session->UserID = userID;
        new_session->LastActiveTime = time(NULL);
        new_session->State = state;
        if (num_sessions < MAX_SESSIONS) {
            session_array[num_sessions++] = *new_session;
            return num_sessions - 1;
        } else {
            free(new_session);
            return -1; // out of space
        }
    } else {
        return -2; // memory error
    }
}

int update_session(int index, SessionState state) {
    if (index >= 0 && index < num_sessions) {
        session_array[index].State = state;
        gc();
        return 1;
    } else {
        return -1; // invalid index
    }
}

int get_active_sessions(void) {
    int active_count = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (session_array[i].State == SESSION_ACTIVE) {
            active_count++;
        }
    }
    return active_count;
}
