typedef struct {
    char* filePath;
    size_t bufferSize;
    int concurrencyLevel;
    int maxOpenFDs;
} Config;

void processFilesAdvanced(Config config, void (*callback)(const char*, const char*)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Initialize hash map and logging
    HashMap* hashMap = hashMapCreate(100);
    Logging* logger = loggingCreate("processFilesAdvanced");

    int openFDs = 0;
    size_t memoryUsage = 0;

    FILE* file = fopen(config.filePath, "r");
    if (!file) {
        logger->error("Failed to open file: %s", config.filePath);
        return;
    }

    char** lines = (char**)malloc(config.bufferSize * sizeof(char*));
    for (int i = 0; i < config.bufferSize; i++) {
        lines[i] = (char*)malloc(config.bufferSize * sizeof(char));
    }

    pthread_t threads[config.concurrencyLevel];

    int currentLine = 0;
    size_t bytesRead = 0;
    char buffer[config.bufferSize + 1];

    while (fscanf(file, "%s\n", buffer) == 1 && bytesRead < config.bufferSize) {
        // Process line
        size_t len = strlen(buffer);
        if (len > 0) {
            buffer[len] = '\0'; // null-terminate the line
            lines[currentLine++] = strdup(buffer);
            memoryUsage += len + 1; // account for newline and null terminator

            // Invoke callback function
            callback(lines[currentLine - 1], ""); // pass an empty key value pair

            // Monitor resource usage
            if (openFDs >= config.maxOpenFDs) {
                logger->warning("Maximum number of open file descriptors reached");
                break;
            }
        }

        bytesRead += len + 1; // account for newline and null terminator

        // Spawn threads to process lines concurrently
        for (int i = 0; i < config.concurrencyLevel; i++) {
            if (currentLine >= config.bufferSize) {
                break;
            }

            pthread_create(&threads[i], NULL, processLineCallback, (void*)hashMap);
            openFDs++;
        }

        // Wait for threads to finish
        for (int i = 0; i < config.concurrencyLevel; i++) {
            pthread_join(threads[i], NULL);
            openFDs--;
        }
    }

    fclose(file);

    // Free resources
    for (int i = 0; i < currentLine; i++) {
        free(lines[i]);
    }
    free(lines);

    hashMapDestroy(hashMap);
    loggingDestroy(logger);
}

