Record* generate_records(int num_packets, int* offsets) {
    srand(time(NULL));
    Record* records = (Record*)malloc(num_packets * sizeof(Record));

    for (int i = 0; i < num_packets; i++) {
        Record record;

        // Randomly select packet size and protocol type
        record.packet_size = rand() % 100 + 1;
        record.protocol_type = rand() % 10 + 1;

        // Generate random IP addresses
        char src_ip[16];
        char dst_ip[16];

        for (int j = 0; j < 12; j++) {
            src_ip[j] = 'a' + rand() % 26;
            dst_ip[j] = 'a' + rand() % 26;
        }
        src_ip[12] = '\0';
        dst_ip[12] = '\0';

        // Ensure no collisions
        while (1) {
            int collided = 0;

            for (int j = i - 1; j >= 0 && !collided; j--) {
                if (strcmp(src_ip, records[j].src_ip) == 0 ||
                    strcmp(dst_ip, records[j].dst_ip) == 0)
                    collided = 1;
            }

            if (!collided)
                break;

            for (int j = 0; j < 12; j++) {
                src_ip[j] = 'a' + rand() % 26;
                dst_ip[j] = 'a' + rand() % 26;
            }
        }

        // Set random timestamp
        record.timestamp = rand() % 10000;

        records[i].timestamp = record.timestamp;
        strcpy(records[i].src_ip, src_ip);
        strcpy(records[i].dst_ip, dst_ip);
        records[i] = record;
    }

    for (int i = 0; i < num_packets; i++) {
        int offset = offsets[i % 3];
        records[offset].timestamp = records[i].timestamp;
        strcpy((char*)records[offset].src_ip, src_ip);
        strcpy((char*)records[offset].dst_ip, dst_ip);
    }

    return records;
}

void free_records(Record* records) {
    if (records != NULL)
        free(records);
}

int main() {
    int num_packets = 100;
    Record* records = generate_records(num_packets, NULL);

    // Use the generated records

    free_records(records);

    return 0;
}
