```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DataProcessor
{
    private readonly int _limit;
    private readonly Dictionary<int, DataPoint> _dataPoints;
    private readonly Queue<DataPoint> _activePoints;
    private readonly HashSet<string> _logs = new HashSet<string>();

    public DataProcessor(int limit)
    {
        _limit = limit;
        _dataPoints = new Dictionary<int, DataPoint>();
        _activePoints = new Queue<DataPoint>();
    }

    public void AddDataPoint(DataPoint dataPoint)
    {
        if (_dataPoints.ContainsKey(dataPoint.Id))
            _dataPoints[dataPoint.Id] = dataPoint;
        else
            _dataPoints.Add(dataPoint.Id, dataPoint);

        UpdateActivePoints();
    }

    private void UpdateActivePoints()
    {
        while (_activePoints.Count >= _limit)
            _activePoints.Dequeue();

        foreach (var point in _dataPoints.Values.Where(p => !_activePoints.Contains(p)))
            _activePoints.Enqueue(point);
    }

    public DataPoint UniformSample(int count)
    {
        var result = new List<DataPoint>();
        Random random = new Random();
        for (int i = 0; i < count && _activePoints.Count > 0; i++)
        {
            int index = random.Next(0, _activePoints.Count);
            DataPoint point = _activePoints.Dequeue();
            result.Add(point);
        }
        return result.Aggregate((a, b) => a).Id;
    }

    public void StratifiedSample(double[] bins, int count)
    {
        var result = new List<DataPoint>();
        for (int i = 0; i < bins.Length - 1 && _activePoints.Count > 0; i++)
        {
            double threshold = bins[i];
            int sampleCount = (int)Math.Ceiling(bins[i] * count);
            for (int j = 0; j < sampleCount && _activePoints.Count > 0; j++)
            {
                DataPoint point = _activePoints.Dequeue();
                if (point.Value <= threshold)
                    result.Add(point);
            }
        }
    }

    public void CompressAndStore(int[] data, string path)
    {
        using (var stream = File.Open(path, FileMode.Create))
        {
            using (var writer = new BinaryWriter(stream))
            {
                foreach (int value in data)
                    writer.Write(value);
            }
        }
    }

    public void Normalize()
    {
        var min = _activePoints.Min(p => p.Value);
        var max = _activePoints.Max(p => p.Value);

        foreach (var point in _dataPoints.Values)
            point.Value = (point.Value - min) / (max - min);
    }

    public void LogPerformance(string message, bool enableLogging = true)
    {
        if (enableLogging && !_logs.Contains(message))
        {
            Console.WriteLine(message);
            _logs.Add(message);
        }
    }
}

public class DataPoint
{
    public int Id { get; set; }
    public double Value { get; set; }

    public DataPoint(int id, double value)
    {
        Id = id;
        Value = value;
    }
}
