#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a record structure
typedef struct {
    int key;
    long offset;
} Record;

// Function to dynamically manage memory for a collection of records
Record** createRecords(int capacity) {
    Record** records = (Record**)malloc((capacity + 1)*sizeof(Record*));
    if (!records) return NULL; // Handle allocation error

    for (int i = 0; i <= capacity; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            free(records);
            return NULL; // Handle allocation error
        }
        records[i]->key = rand() % 10000;
        records[i]->offset = (long)rand();
    }

    return records;
}

// Function to dynamically resize the array of records
void resizeRecords(Record** records, int newCapacity) {
    Record** temp = (Record**)malloc((newCapacity + 1)*sizeof(Record*));
    if (!temp) return; // Handle allocation error

    for (int i = 0; i <= *records->size; i++) {
        temp[i] = (*records)[i];
        free((*records++)); // Free the original record
    }

    *records = temp;
}

// Function to serialize the records array into a file
void serializeRecords(Record** records, FILE* file) {
    int size = *records->size;
    fwrite(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        Record record = (*records)[i];
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.offset, sizeof(long), 1, file);
    }
}

// Function to deserialize the records array from a file
Record** deserializeRecords(FILE* file) {
    Record** records;
    int size;

    fread(&size, sizeof(int), 1, file);

    records = (Record**)malloc((size + 1)*sizeof(Record*));
    if (!records) return NULL; // Handle allocation error

    for (int i = 0; i < size; i++) {
        Record record;
        fread(&record.key, sizeof(int), 1, file);
        fread(&record.offset, sizeof(long), 1, file);

        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) return NULL; // Handle allocation error

        *records++ = &record;
    }

    return records;
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    Record** records = createRecords(100);

    serializeRecords(records, fopen("records.bin", "wb"));

    free(*records);

    return 0;
}
