    }

    system->keys = (int*)malloc(maxKeys * sizeof(int));
    if (!system->keys) {
        free(system->offsets);
        free(system);
        return NULL;
    }

    for (int i = 0; i < maxKeys; i++) {
        system->keys[i] = keyStart + i * keyInc;
    }

    system->records = (int**)malloc(maxRecords * sizeof(int*));
    if (!system->records) {
        free(system->offsets);
        free(system->keys);
        free(system);
        return NULL;
    }

    for (int i = 0; i < maxRecords; i++) {
        system->records[i] = (int*)malloc(sizeof(int));
