    // Initialize arrays and record structures
    for (int i = 0; i < max_records; i++) {
        offset_values[i] = i;
        keys[i] = i;
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->timestamp = i;
        records[i]->interface_id = i;
        records[i]->error_code = i;
        records[i]->event_tags = (char *)malloc((i + 1) * sizeof(char)); // dynamically allocate memory for event tags
        strcpy(records[i]->event_tags, "Event Tag"); // initialize with default value
    }

    return (void*)records;
