    // Initialize array of double values with variable size
    TimeStampedEvent* events = (TimeStampedEvent*)malloc(n * sizeof(TimeStampedEvent));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < max_size; j++) {
            events[i].values[j] = (double)rand() / RAND_MAX;
        }
        // Populate message text with random characters
        int len = rand() % 10 + 1;
        events[i].message = malloc(len);
        for (int k = 0; k < len; k++) {
            events[i].message[k] = (char)('a' + (rand() % 26));
        }
        events[i].message[len] = '\0';
    }

    // Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
    int rnti_range = 0x10000;
    for (int i = 0; i < n; i++) {
        TimeStampedEvent* event = &events[i];
        // Ensure each contains a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
