        // Set CRC_INDICATION_REL8_TAG based on CRCFLAG
        if (crcflag) {
            // Set CRC_INDICATION_REL8_TAG for lossy compression mode
            event->values[0] += 0.1; // Simulate lossy compression effect
        } else {
            // Set CRC_INDICATION_REL8_TAG for lossless compression mode
