    int status;
    time_t start_time;
    time_t completion_time;
};

struct project_list {
    struct project* projects;
    atomic_int size;
};

void init_project(struct project* p) {
    p->priority = rand() % MAX_PRIORITY;
    p->status = rand() % MAX_STATUS;
    p->start_time = time(NULL);
}

int create_project_list(struct project_list* list, int initial_size) {
    if (initial_size > PROJECT_MAX)
        return -1;

    list->projects = (struct project*)malloc(initial_size * sizeof(struct project));
    if (!list->projects)
        return -2;

    list->size.store(0);
    for (int i = 0; i < initial_size; i++)
        init_project(&list->projects[i]);

    return 1;
}

void add_project(struct project_list* list, int new_size) {
    if (!new_size)
        return;

    struct project* new_projects = (struct project*)malloc(new_size * sizeof(struct project));
    if (!new_projects)
        return;

    // Copy existing projects to new memory
    for (int i = 0; i < list->size.load(); i++) {
        new_projects[i] = list->projects[i];
        init_project(&list->projects[i]);
    }

    // Free old projects
    free(list->projects);

    list->projects = new_projects;
    list->size.store(new_size);
}

void remove_completed_projects(struct project_list* list) {
    int new_size = 0;

    for (int i = 0; i < list->size.load(); i++) {
        if (list->projects[i].completion_time != 0)
            continue;

        new_size++;
    }

    // Update size and reallocate memory
    list->size.store(new_size);
    add_project(list, list->size.load());
}

