    int result = create_project_list(&projects, 10);
    if (result < 0)
        printf("Failed to initialize project list.\n");

    // Add and remove projects...
    add_project(&projects, 5);
    remove_completed_projects(&projects);

    update_project_completion_times(&projects);

    return 0;
