#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>

// Define a project structure
typedef struct {
    int priority;
    char status[16];
    time_t timestamp;
    int estimated_duration;
    time_t actual_completion_time;
} Project;

// Function to manage the dynamic list of projects
void* manage_projects(void* args) {
    // Initialize the project list and current time
    Project** projects = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int num_projects = 0, capacity = 16; // Initial capacity is 16

    // Allocate memory for the first batch of projects
    projects = (Project**)malloc(sizeof(Project*) * capacity);
    if (!projects) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    while (1) {
        // Periodically clean up completed projects
        pthread_mutex_lock(&lock);
        int i, j = 0;
        for (i = 0; i < num_projects; i++) {
            if (projects[i]->actual_completion_time > 0) { // Project is complete
                free(projects[i]);
                projects[i] = NULL;
                num_projects--;
            } else {
                projects[j++] = projects[i];
            }
        }
        for (i = j; i < num_projects; i++) {
            projects[i - j] = projects[i];
        }
        num_projects -= j;

        // Manage new project requests
        int max_priority = 0, status_length = 0;
        pthread_mutex_unlock(&lock);
        for (int i = 0; i < capacity; i++) {
            if (!projects[i]) break;
            if (projects[i]->priority > max_priority) max_priority = projects[i]->priority;
            if (strlen(projects[i]->status) + 1 > status_length) status_length = strlen(projects[i]->status) + 1;
        }
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_projects; i++) {
            // Initialize project fields
            projects[i]->timestamp = time(NULL); // Current timestamp
            projects[i]->priority = rand() % max_priority + 1; // Random priority within range
            strcpy(projects[i]->status, ""); // Initialize status to empty string

            if (rand() % 2) { // With 50% chance
                int estimated_duration = rand() % 10 + 1; // Estimated duration between 1 and 11 days
                projects[i]->estimated_duration = estimated_duration;
                time_t actual_completion_time = time(NULL); // Set to current time for now
                projects[i]->actual_completion_time = actual_completion_time;
            }
        }

        pthread_mutex_unlock(&lock);
    }
}
