        perror("sem_open");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offset values
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        sem_close(semaphore);
        free(offsets);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize offset values with random numbers within the specified range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % max_value;
    }

    // Allocate memory for key values
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        sem_close(semaphore);
        free(offsets);
        free(keys);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize key values with random numbers within the specified range
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % max_value;
    }

    // Allocate memory for record structures
