Entity* initEntity() {
    // Initialize a new entity structure.
    Entity* entity = (Entity*)allocate(sizeof(Entity));

    // Generate a random name and assign it to the entity.
    char* name = (char*)allocate(strlen("Entity") + 1);
    strcpy(name, "Entity");
    entity->name = name;

    // Assign a unique ID to the entity.
    entity->id = rand();

    // Initialize the status of the entity as active.
    entity->status = ACTIVE;

    // Allocate memory for metadata and initialize it with random data.
    size_t metadataSize = 1024;
    void* metadataPtr = allocate(metadataSize);
    memset(metadataPtr, 'X', metadataSize - 1);
    ((char*)metadataPtr)[metadataSize - 1] = '\0';
    entity->metadata = metadataPtr;

    // Initialize the last active time of the entity.
    entity->lastActiveTime = time(NULL);

    return entity;
}

// Function to update an entity's status and metadata.
void updateEntity(Entity* entity, enum EntityStatus newStatus, void* newMetadata) {
    entity->status = newStatus;
    deallocate(entity->metadata);
    entity->metadata = newMetadata;
}

// Function to retrieve the number of entities.
int getNumEntities() {
    return MAX_ENTITIES; // Initialize with a maximum capacity for now.
}

// Function to terminate an inactive entity after a specified period.
void terminateInactiveEntities(int timeout) {
    // Iterate over all entities and check their status and last active time.
    for (int i = 0; i < getNumEntities(); i++) {
        Entity* entity = &entities[i];
        if (entity->status == INACTIVE && time(NULL) - entity->lastActiveTime > timeout) {
            deallocate(entity->name);
            deallocate(entity->metadata);
            // Update the status of the entity as terminated.
            entity->status = TERMINATED;
        }
    }
}

// Function to log detailed lifecycle events for each entity.
void logEntityLifecycleEvents() {
    // Iterate over all entities and log their lifecycle events.
    for (int i = 0; i < getNumEntities(); i++) {
        Entity* entity = &entities[i];
        printf("Entity %u: Created on %s, status is %s.\n", entity->id, ctime(&entity->lastActiveTime), entity->status == ACTIVE ? "Active" : entity->status == INACTIVE ? "Inactive" : "Terminated");
    }
}

int main() {
    // Initialize the entities array.
    Entity* entities[MAX_ENTITIES];

    // Initialize and add some random entities to the array.
    for (int i = 0; i < MAX_ENTITIES; i++) {
        entities[i] = initEntity();
    }

    // Update some entity statuses and metadata.
    updateEntity(&entities[1], INACTIVE, "New Metadata");
    updateEntity(&entities[5], TERMINATED, NULL);

    // Terminate inactive entities after a specified period.
    terminateInactiveEntities(60); // 1 minute timeout.

    // Log detailed lifecycle events for each entity.
    logEntityLifecycleEvents();

    return 0;
}
