#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RECORDS 1000
#define MAX_CONCURRENT_ACCESS 10
#define BLOCK_SIZE 1024

typedef enum { NON_CRITICAL, CRITICAL } EventType;

typedef struct {
    int key;
    char buffer[BLOCK_SIZE];
    EventType type;
    int metadata;
} EventRecord;

EventRecord* records[MAX_RECORDS];
sem_t semaphore;

void* custom_allocator(int size) {
    void* block = malloc(size);
    if (block == NULL) {
        return NULL;
    }
    // Initialize the block with random data
    for (int i = 0; i < BLOCK_SIZE - 1; i++) {
        ((char*)block)[i] = rand() % 256;
    }
    ((char*)block)[BLOCK_SIZE - 1] = '\0'; // Null terminator
    return block;
}

void custom_free(void* ptr) {
    free(ptr);
}

EventRecord* allocate_event_record(int key, int type, int metadata) {
    EventRecord* record = (EventRecord*)custom_allocator(sizeof(EventRecord));
    record->key = key;
    record->type = (EventType)type;
    record->metadata = metadata;
    return record;
}

void deallocate_event_record(EventRecord* record) {
    custom_free((void*)record);
}

int get_available_memory() {
    int available = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i] == NULL) {
            available += BLOCK_SIZE;
        }
    }
    return available;
}

void cleanup_records(int threshold) {
    for (int i = threshold; i >= 0; i--) {
        if (records[i] != NULL) {
            deallocate_event_record(records[i]);
            records[i] = NULL;
        }
    }
}

void* thread_function(void* arg) {
    // Access event records using the semaphore
    sem_wait(&semaphore);
    int record_index = rand() % MAX_RECORDS;
    if (records[record_index] == NULL) {
        // Allocate a new event record
        EventRecord* record = allocate_event_record(rand(), NON_CRITICAL, 0);
        records[record_index] = record;
    } else {
        // Reuse an existing event record
        EventRecord* record = records[record_index];
        // Update the record's metadata
        record->metadata++;
    }
    sem_post(&semaphore);

    return NULL;
}

int main() {
    srand(time(NULL)); // Initialize random seed

    // Initialize the semaphore with maximum number of concurrent accesses
    sem_init(&semaphore, 0, MAX_CONCURRENT_ACCESS);

    pthread_t threads[MAX_CONCURRENT_ACCESS];
    for (int i = 0; i < MAX_CONCURRENT_ACCESS; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    // Periodically clean up unused event records
    cleanup_records(MAX_RECORDS - 10);

    return 0;
}
