        records[i]->value = rand() % 100 + 1;
    }

    // Function to reallocate memory when needed
    void* reallocateMemory(void** ptr, size_t new_size) {
        if (*ptr != NULL) {
            free(*ptr);
        }
        *ptr = realloc(*ptr, new_size * sizeof(long));
        return *ptr;
    }

    // Function to periodically reorganize data structures for better cache locality
    void reorganizeDataStructures() {
        // Reorganize offset values and keys arrays
        long* temp_offsets = (long*)malloc(max_size * sizeof(long));
        int* temp_keys = (int*)malloc(max_size * sizeof(int));

        for (int i = 0; i < max_size; i++) {
            temp_offsets[i] = offsets[i];
            temp_keys[i] = keys[i];
        }

        free(offsets);
        free(keys);

        offsets = temp_offsets;
        keys = temp_keys;

        // Reorganize records array
        Record** temp_records = (Record**)calloc(max_size, sizeof(Record*));

        for (int i = 0; i < max_size; i++) {
            temp_records[i] = records[i];
        }

        free(records);

        records = temp_records;
