void init_cache(int size) {
    if (cache != NULL) {
        free(cache);
    }
    cache_size = size;
    cache = (record **)malloc(CACHE_SIZE * sizeof(record *));
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i] = NULL;
    }
}

void insert_cache(record *record) {
    int hash = record->value % CACHE_SIZE;
    if (cache[hash] != NULL) {
        // Record already in cache, just update reference count
        cache[hash]->ref_count++;
    } else {
        cache[hash] = record;
        cache[hash]->ref_count = 1;
    }
}

record *find_cache(int key) {
    int hash = key % CACHE_SIZE;
    if (cache[hash] != NULL && cache[hash]->value == key) {
        return cache[hash];
    }
    return NULL;
}

void free_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        record *record = cache[i];
        while (record != NULL) {
            record *next = record->next;
            free(record);
            record = next;
        }
    }
    free(cache);
