    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(keySize * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(recordCount * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Read integers from standard input and store them in an auxiliary array
    int maxVal = 0;
    for (int i = 0; i < recordCount; i++) {
        int val;
        scanf("%d", &val);
        if (val > maxVal) maxVal = val;
    }

    // Print the largest integer using a helper function
    printf("Largest integer: %d\n", maxVal);

    // Initialize and validate the records
    for (int i = 0; i < recordCount; i++) {
        records[i].value = maxVal - i;
    }
    int checksum = 0;
    for (int i = 0; i < recordCount; i++) {
        checksum += records[i].value;
    }
    printf("Checksum: %d\n", checksum);

    return records;
