void addProcess(int processID, double memoryConsumption, double cpuUtilization, double diskIOActivity) {
    // Find the first available slot in the array.
    int emptySlot = 0;
    while (resourceArray[emptySlot][0] != 0) {
        emptySlot++;
    }

    // Update the metrics for the new process.
    resourceArray[emptySlot][1] = memoryConsumption;
    resourceArray[emptySlot][2] = cpuUtilization;
    resourceArray[emptySlot][3] = diskIOActivity;

    // Update the ProcessID with the provided value.
    resourceArray[emptySlot][0] = processID;
}

void updateMetrics(int processID, double memoryConsumption, double cpuUtilization, double diskIOActivity) {
    for (int i = 0; i < maxProcesses; i++) {
        if (resourceArray[i][0] == processID) {
            resourceArray[i][1] = memoryConsumption;
            resourceArray[i][2] = cpuUtilization;
            resourceArray[i][3] = diskIOActivity;
            break;
        }
    }
}

