Record* table[TABLE_SIZE];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int ref_count[MAX_KEY] = {0};
time_t last_gc_time = time(NULL);

void gc_thread_func(void* arg) {
    while(1) {
        pthread_mutex_lock(&lock);
        if(record_count > 0 && time(NULL) - last_gc_time > 10) {
            for(int i = 0; i < TABLE_SIZE; i++) {
                for(Record* rec = table[i]; rec; rec = rec->next) {
                    if(--rec->ref_count <= 0) {
                        record_count--;
                        free(rec);
                    }
                }
            }
            last_gc_time = time(NULL);
        }
        pthread_mutex_unlock(&lock);
        sleep(1);
    }
}

void init_table() {
    for(int i = 0; i < TABLE_SIZE; i++) {
        table[i] = NULL;
    }
}

Record* find_record(int key) {
    int bucket = key % BUCKET_COUNT;
    Record** bucket_records = &table[bucket];
    for(Record* rec = *bucket_records; rec; rec = rec->next) {
        if(rec->key == key) {
            return rec;
        }
    }
    return NULL;
}

void insert_record(int key, long offset, time_t timestamp, int value) {
    Record* rec = malloc(sizeof(Record));
    rec->key = key;
    rec->offset = offset;
    rec->timestamp = timestamp;
    rec->value = value;
    rec->ref_count = 1;

    int bucket = key % BUCKET_COUNT;
    Record** bucket_records = &table[bucket];
    rec->next = *bucket_records;
    *bucket_records = rec;
    record_count++;
}

void delete_record(int key) {
    Record* rec = find_record(key);
    if(rec) {
        rec->ref_count--;
        if(rec->ref_count <= 0) {
            int bucket = rec->key % BUCKET_COUNT;
            Record** bucket_records = &table[bucket];
            rec->next = *bucket_records;
            *bucket_records = rec->next;
            free(rec);
            record_count--;
        }
    }
}

int main() {
    pthread_t gc_thread;
    init_table();
    pthread_create(&gc_thread, NULL, gc_thread_func, NULL);
    // Sample unsafe code snippet
    int* values = malloc(sizeof(int) * 1024);
    for(int i = 0; i < 100; i++) {
        insert_record(i, i * 10, time(NULL), values[i]);
    }
    sleep(5);
    free(values);
    pthread_join(gc_thread, NULL);
    return 0;
}
