// Function to manage memory allocation and initialization
record* init_records(int n, int min_key, int max_key) {
    // Allocate memory for array of 'long' offsets with length n
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) return NULL;  // Handle memory allocation failure

    // Initialize another array of 'int' keys with the same length n
    int* keys = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for array of record structures, each with a long offset and int key
    record* records = (record*)malloc(n * sizeof(record));
    for (int i = 0; i < n; i++) {
        records[i].offset = i;  // Initialize offset with the index
        records[i].key = keys[i];  // Set key to the corresponding value in keys array
    }

    // Free allocated memory in reverse order of allocation
    free(keys);
    free(offsets);

    return records;
}

int main() {
    int n = 10000;  // Set the desired length for the record array
    int min_key = 0, max_key = 100000;  // Define the range for int keys

    // Initialize and return the record array with its length
    record* records = init_records(n, min_key, max_key);
    printf("Record Array Length: %d\n", n);

