    int* keys = (int*)malloc(num_records * sizeof(int));
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    event_tag_t* event_tags = (event_tag_t*)malloc(num_records * sizeof(event_tag_t));
    network_interface_status_update_t* interface_updates = (network_interface_status_update_t*)malloc(1 * sizeof(network_interface_status_update_t));

    // Initialize semaphores
    sem_t semaphore;
    if (sem_open(&semaphore, O_CREAT | O_RDWR, 0644, 0) == -1) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }

    // Initialize database validation period
    time_t validation_period = time(NULL);

    // Process network data
    for (size_t i = 0; i < num_records; i++) {
