            strcpy(interface_updates->source_ip, "192.168.1.100");
            strcpy(interface_updates->protocol_type, "TCP");
        }

        // Update interface updates
        network_interface_status_update_t* current_interface_update = interface_updates;
        for (size_t j = 0; j < i + 1; j++) {
            current_interface_update->events = realloc(current_interface_update->events, (j + 1) * sizeof(event_tag_t));
            current_interface_update->events[j] = event_tags[i];
        }
    }

    // Export interface updates to analytics service
    printf("Exporting network interface status updates...\n");
    for (size_t i = 0; i < num_records; i++) {
        printf("%ld %d %s\n", records[i].offset, keys[i], interface_updates->events[i].status ? "Active" : "Inactive");
    }

    // Free memory
    free(offsets);
    free(keys);
    free(records);
    free(event_tags);
    free(interface_updates);

    // Close semaphore
    if (sem_close(&semaphore) == -1) {
        perror("sem_close");
        exit(EXIT_FAILURE);
    }
}
