int manage_memory(int size, int* offsets, int* keys, int* records) {
    // Validate user-provided size
    if (size <= 0 || size > 10000) {
        return -1; // Error: invalid size
    }

    // Allocate memory for long offset array
    long* offsets_array = (long*)malloc(size * sizeof(long));
    if (!offsets_array) {
        return -2; // Error: memory allocation failed
    }

    // Initialize int key array with unique values within a given range
    srand(time(NULL)); // Initialize random number generator
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 1000; // Generate unique int key within range [0, 999]
    }

    // Allocate memory for record structures and initialize offset and key fields
    record* records_array = (record*)malloc(size * sizeof(record));
    if (!records_array) {
        return -2; // Error: memory allocation failed
    }
    for (int i = 0; i < size; i++) {
        records_array[i].offset = offsets_array[i];
        records_array[i].key = keys[i];
    }

    // Deallocate memory in reverse order of allocation to prevent dangling pointers
    free(records_array);
    free(offsets_array);

    return 0; // Success: memory managed efficiently
}
