import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class TaskManager {
    private final Map<TaskID, TaskExecution> tasks = new HashMap<>();
    private final AtomicInteger pendingTasks = new AtomicInteger(0);
    private final AtomicInteger inProgressTasks = new AtomicInteger(0);
    private final AtomicInteger completedTasks = new AtomicInteger(0);

    public void addTask(TaskExecution task) {
        tasks.put(task.getTaskID(), task);
        if (task.getState() == TaskState.PENDING) {
            pendingTasks.incrementAndGet();
        } else if (task.getState() == TaskState.IN_PROGRESS) {
            inProgressTasks.incrementAndGet();
        } else if (task.getState() == TaskState.COMPLETED) {
            completedTasks.incrementAndGet();
        }
    }

    public void updateTask(TaskID taskID, TaskState newState) {
        TaskExecution task = tasks.get(taskID);
        if (task != null) {
            task.setState(newState);
            if (newState == TaskState.PENDING) {
                pendingTasks.incrementAndGet();
                inProgressTasks.decrementAndGet();
            } else if (newState == TaskState.IN_PROGRESS) {
                inProgressTasks.incrementAndGet();
                completedTasks.decrementAndGet();
            } else if (newState == TaskState.COMPLETED) {
                completedTasks.incrementAndGet();
                inProgressTasks.decrementAndGet();
            }
        }
    }

    public int getPendingTaskCount() {
        return pendingTasks.get();
    }

    public int getInProgressTaskCount() {
        return inProgressTasks.get();
    }

    public int getCompletedTaskCount() {
        return completedTasks.get();
    }
}
