```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <uuid/uuid.h>

typedef struct {
    uint128_t id;
    float value;
    char* string_data;
    int ref_count;
} custom_data;

typedef struct node {
    custom_data data;
    struct node* prev;
    struct node* next;
} node;

typedef struct bucket {
    node* head;
    node* tail;
} bucket;

typedef struct hash_table {
    int size;
    bucket** buckets;
    uint128_t* keys;
    int num_entries;
    int max_entries;
    int pool_size;
    int max_concurrent_accesses;
} hash_table;

void init_hash_table(hash_table* ht, int size, int pool_size, int max_entries) {
    ht->size = size;
    ht->buckets = (bucket**)malloc(size * sizeof(bucket));
    ht->keys = (uint128_t*)malloc(size * sizeof(uint128_t));
    ht->num_entries = 0;
    ht->max_entries = max_entries;
    ht->pool_size = pool_size;
}

void free_hash_table(hash_table* ht) {
    for (int i = 0; i < ht->size; i++) {
        bucket* b = &ht->buckets[i];
        node* n = b->head;
        while (n != NULL) {
            custom_data* data = &n->data;
            free(data->string_data);
            // Free the custom data struct
            // ...
            n = n->next;
        }
    }
    free(ht->keys);
    free(ht->buckets);
}

int hash_function(uint128_t key, int size) {
    return key % size;
}

void insert_hash_table(hash_table* ht, uint128_t key, custom_data data) {
    int index = hash_function(key, ht->size);
    bucket* b = &ht->buckets[index];
    node* n = (node*)malloc(sizeof(node));
    n->data = data;
    n->prev = NULL;
    n->next = b->head;
    if (b->head != NULL) {
        b->head->prev = n;
    } else {
        b->tail = n;
    }
    b->head = n;
}

void remove_hash_table(hash_table* ht, uint128_t key) {
    int index = hash_function(key, ht->size);
    bucket* b = &ht->buckets[index];
    node* n = b->head;
    while (n != NULL && n->data.id != key) {
        n = n->next;
    }
    if (n == NULL) return; // Key not found
    if (n->prev != NULL) {
        n->prev->next = n->next;
    } else {
        b->head = n->next;
    }
    if (n->next != NULL) {
        n->next->prev = n->prev;
    } else {
        b->tail = n->prev;
    }
    free(n);
}
