    if (!fileProc->file) {
        // Handle error and log the issue
        printf("Error opening file: %s\n", config->filePath);
        return NULL;
    }

    fileProc->buffer = malloc(config->bufferSize);
    fileProc->bytesRead = 0;

    while (1) {
        // Read from file and process data
        int bytesRead = fread(fileProc->buffer, 1, config->bufferSize, fileProc->file);

        if (bytesRead < config->bufferSize) {
            break; // End of file reached
        }

        // Validate and transform data as needed

        // Send processed data to external service for analysis
    }

    fclose(fileProc->file);
    free(fileProc->buffer);
    free(fileProc);
}

