record **offset_pool = NULL;
int *key_pool = NULL;
double *value_pool = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t offset_count = 0, key_count = 0, value_count = 0;

void* init_resources(size_t num_records) {
    size_t i;

    // Initialize pools
    record **offsets = (record **)malloc(num_records * sizeof(record *));
    int *keys = (int *)malloc(num_records * sizeof(int));
    double *values = (double *)malloc(num_records * sizeof(double));

    pthread_mutex_lock(&lock);

    for (i = 0; i < num_records; ++i) {
        offsets[i] = (record *)malloc(sizeof(record));
        keys[i] = i;
        values[i] = (double)rand() / RAND_MAX;
    }

    offset_pool = offsets;
    key_pool = keys;
    value_pool = values;

    pthread_mutex_unlock(&lock);

    return NULL;
}

void free_resources(size_t num_records) {
    size_t i;

    pthread_mutex_lock(&lock);

    for (i = 0; i < num_records; ++i) {
        if (offset_pool[i] != NULL)
            free(offset_pool[i]);
    }

    free(key_pool);
    free(value_pool);
    free(offset_pool);

    pthread_mutex_unlock(&lock);
}
