#define RECORD_LIMIT 1000
#define OFFSET_ARRAY_SIZE 100
#define KEY_RANGE 10000

typedef struct {
    int value;
    int* offset;
    int key;
} record_t;

record_t* records = NULL;
int record_count = 0;
int peak_memory_usage = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* create_record(int value, int* offset) {
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    new_record->value = value;
    new_record->offset = offset;
    new_record->key = rand() % KEY_RANGE;
    return new_record;
}

void init_record(record_t* record, int value, int* offset) {
    record->value = value;
    record->offset = offset;
    record->key = rand() % KEY_RANGE;
}

int track_memory_usage(int bytes_allocated) {
    pthread_mutex_lock(&lock);
    if (bytes_allocated > peak_memory_usage)
        peak_memory_usage = bytes_allocated;
    int current_usage = (peak_memory_usage + record_count * sizeof(record_t));
    pthread_mutex_unlock(&lock);
    return current_usage;
}

void log_record_init(record_t* record) {
    printf("Record %d initialized with value %d, offset %p, and key %d.\n", 
           record_count, record->value, record->offset, record->key);
}

void* create_records(int limit) {
    int i = 0;
    while (i < limit && record_count < RECORD_LIMIT) {
        int value = rand() % KEY_RANGE;
        int* offset = (int*)malloc(sizeof(int));
        *offset = rand() % OFFSET_ARRAY_SIZE;
        pthread_mutex_lock(&lock);
        if ((records = realloc(records, sizeof(record_t) * (record_count + 1))) != NULL)
            init_record(&records[record_count], value, offset);
        else {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        record_count++;
        pthread_mutex_unlock(&lock);
        log_record_init(&records[record_count - 1]);
    }
    return NULL;
}

void free_records() {
    for (int i = 0; i < record_count; i++)
        free(((record_t*)records) + i)->offset;
    free(records);
    records = NULL;
    record_count = 0;
}
