    if (num_records > MAX_RECORDS) {
        printf("Error: Too many records.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        record_t* record = (record_t*)malloc(sizeof(record_t));
        record->value = rand() % max_length;
        record->buffer = malloc(RECORD_BUFFER_SIZE);
        metadata_t* metadata_record = (metadata_t*)malloc(sizeof(metadata_t));
        metadata_record->metadata_value = rand();
        metadata_record->array = malloc(METADATA_ARRAY_SIZE * sizeof(long));

        for (int j = 0; j < METADATA_ARRAY_SIZE; j++) {
            metadata_record->array[j] = j;
        }

        record->metadata = metadata_record;
        if (!records) {
            records = &record;
        } else {
            record_t* prev_record = records;
            while (prev_record->next) {
                prev_record = prev_record->next;
            }
            prev_record->next = record;
        }
    }
}

