['Here is the C function that manages dynamic memory allocation for multiple data structures under resource-constrained conditions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

Record* initRecords(int size, int min_range, int max_range, const char* data_source) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        return NULL;  // Handle memory allocation failure
    }

    FILE* file = fopen(data_source, "r");
    if (!file) {
        fclose(file);
        return NULL;  // Handle file opening error
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < size; i++) {
        Record* record = &records[i];
        fseek(file, 0L, SEEK_END);  // Move to the end of the file
        long offset = ftell(file);
        fclose(file);

        int key = (getpid() * (int)offset) % INT_MAX;
        int value = rand() % (max_range - min_range + 1) + min_range;

        record->offset = offset;
        record->key = key;
        record->value = value;

        pthread_mutex_lock(&lock);
        // Check for memory alignment and data consistency
        if (!record || memcmp(record, &records[0], sizeof(Record))) {
            free(records);
            return NULL;  // Handle memory allocation failure or corruption
        }
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return records;
}
