#include <unistd.h>

// Define the record structure
typedef struct {
    int value;
} record_t;

// Function to initialize and allocate memory for three data structures
int init_memory_allocation(const char* config_file_path) {
    // Open the configuration file
    int fd = open(config_file_path, O_RDONLY);
    if (fd < 0) {
        printf("Failed to open configuration file: %s\n", config_file_path);
        return -1;
    }

    // Initialize arrays of offsets and keys
    long* offsets = malloc(1024 * sizeof(long));
    int* keys = malloc(1024 * sizeof(int));

    // Read configuration file and initialize data structures
    if (pread(fd, &offsets[0], 1024 * sizeof(long), 0) < 0 || 
        pread(fd, &keys[0], 1024 * sizeof(int), 1024 * sizeof(long)) < 0) {
        printf("Failed to read configuration file: %s\n", config_file_path);
        free(offsets);
        free(keys);
        close(fd);
        return -1;
    }

    // Close the file
    close(fd);

    // Initialize and allocate memory for record structures
    int num_records = 1024;
    record_t* records = mmap(NULL, num_records * sizeof(record_t), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        printf("Failed to allocate memory for record structures: %s\n", config_file_path);
        free(offsets);
        free(keys);
        return -1;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    // Reset records to initial state
    void reset_records(record_t* records) {
        // Atomic operation without re-allocation
        int i;
        __sync_lock_test_and_set(&records, 0);
        for (i = 0; i < num_records; i++) {
            records[i].value = rand() % 100;
        }
    }

    // Export data structures to binary format
    void export_data(const char* file_path) {
        FILE* file = fopen(file_path, "wb");
        if (!file) {
            printf("Failed to open output file: %s\n", file_path);
            return;
        }

        fwrite(&offsets[0], 1024 * sizeof(long), 1, file);
        fwrite(&keys[0], 1024 * sizeof(int), 1, file);
        fwrite(records, num_records * sizeof(record_t), 1, file);

        fclose(file);
    }

    // Clean up and return
    free(offsets);
    free(keys);
    munmap(records, num_records * sizeof(record_t));
    return 0;
}

int main() {
    const char* config_file_path = "config.txt";
    init_memory_allocation(config_file_path);
    export_data("output.bin");
    reset_records(records);
    return 0;
}
