#define MAX_RECORDS 1000 // Maximum number of records to be allocated
#define RECORD_SIZE sizeof(struct Record)

typedef struct {
    long offset;
    int key;
    int value;
} struct Record;

struct Record* record_pool = NULL; // Memory pool for record allocation
pthread_mutex_t record_pool_lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe access

int num_records = 0; // Number of allocated records
int current_size = 0; // Current size of the memory pool

void* record_alloc(size_t size) {
    void* ptr = NULL;

    pthread_mutex_lock(&record_pool_lock);
    if (current_size + size > MAX_RECORDS * RECORD_SIZE) {
        // Reallocate the entire pool
        record_pool = realloc(record_pool, (MAX_RECORDS + 1) * RECORD_SIZE);
        current_size = MAX_RECORDS * RECORD_SIZE;
    }

    ptr = record_pool + num_records * RECORD_SIZE;
    num_records++;
    pthread_mutex_unlock(&record_pool_lock);

    return ptr;
}

void* record_realloc(void* ptr, size_t size) {
    void* new_ptr = realloc(ptr, size);

    if (new_ptr == NULL) {
        // If reallocation fails, try to deallocate and free the original memory
        free(new_ptr);
        new_ptr = ptr;
    }

    return new_ptr;
}

void record_free(void* ptr) {
