enum Status { ERROR, INFO, DEBUG };

typedef struct {
    char* message;
    int timestamp;
    enum Status status;
} LogEntry;

LogEntry** manageMemory(int numEntries) {
    // Allocate memory for an array of LogEntry pointers
    LogEntry** logEntries = (LogEntry**)malloc(numEntries * sizeof(LogEntry*));

    if (!logEntries) {
        printf("Error allocating memory for log entries.\n");
        return NULL;
    }

    // Initialize each LogEntry with a timestamp and copy the input string into its message buffer
    for (int i = 0; i < numEntries; i++) {
        logEntries[i] = (LogEntry*)malloc(sizeof(LogEntry));

        if (!logEntries[i]) {
            printf("Error allocating memory for log entry %d.\n", i);
            // Handle error and clean up resources before returning
            while (i > 0) {
                free(logEntries[--i]->message);
                free(logEntries[i]);
            }
            free(logEntries);
            return NULL;
        }

        time_t currentTimestamp = time(NULL);
        logEntries[i]->timestamp = (int)currentTimestamp;

        // Initialize message buffer with input string
        char* messageBuffer = (char*)malloc(strlen(inputString) + 1);

        if (!messageBuffer) {
            printf("Error allocating memory for message buffer.\n");
            // Handle error and clean up resources before returning
            free(logEntries[i]->message);
            free(logEntries[i]);
            return NULL;
        }

        strcpy(messageBuffer, inputString);
        logEntries[i]->message = messageBuffer;
        logEntries[i]->status = ERROR; // Initialize with default status
    }

    return logEntries;
}
