#define MAX_RECORDS 1000000
#define RECORD_SIZE sizeof(struct record)

struct record {
    int value;
};

typedef struct {
    long offset;
    int key;
} record_offset_key;

// Function to manage data processing pipeline
void* process_pipeline(void* arg) {
    // Initialize memory allocation
    record_offset_key** offsets = (record_offset_key**)malloc(MAX_RECORDS * sizeof(record_offset_key*));
    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    struct record* records = (struct record*)malloc(MAX_RECORDS * RECORD_SIZE);

    // Process data in batches of 1000
    for (int i = 0; i < MAX_RECORDS; i += 1000) {
        int batch_size = (i + 1000 <= MAX_RECORDS) ? 1000 : MAX_RECORDS - i;
        pthread_spinlock_init(&offsets[i].lock);
        // Process records in the batch
        for (int j = 0; j < batch_size; j++) {
            // Allocate memory for record offset and key
            offsets[i + j] = (record_offset_key*)malloc(sizeof(record_offset_key));
            offsets[i + j]->offset = i + j;
            offsets[i + j]->key = i % 10;
            pthread_spin_unlock(&offsets[i].lock);
        }
    }

