entry** init_entry_array(int initial_capacity) {
    // Allocate memory for the array of pointers to 'entry' structs
    entry** entries = (entry**)malloc(initial_capacity * sizeof(entry*));

    // Initialize each entry in the array
    for (int i = 0; i < initial_capacity; i++) {
        entries[i] = (entry*)malloc(sizeof(entry));
        entries[i]->key = NULL;
        entries[i]->value = 0.0;
    }

    return entries;
}

// Define a function to dynamically resize the array of 'entry' structures
void resize_entry_array(entry** entries, int new_capacity) {
    // Calculate the size of memory needed for the new array
    size_t new_size = new_capacity * sizeof(entry*);

    // Check if we need to reallocate memory
    if (new_size > 0) {
        entry** temp_entries = (entry**)realloc(entries, new_size);

        // If reallocation was successful, update the 'entries' pointer
        if (temp_entries != NULL) {
            entries = temp_entries;
        } else {
            free(entries); // Free original array to prevent memory leak
            return; // Return immediately if reallocation failed
        }
    }
}

// Define a function to iterate over the entries and print their details
void print_entry_array(entry** entries, int capacity) {
    for (int i = 0; i < capacity; i++) {
        printf("Entry %d: key - %s, value - %.2f\n", i + 1, entries[i]->key ? entries[i]->key : "NULL", entries[i]->value);
    }
}

// Define a function to free the memory allocated for the array of 'entry' structures
void free_entry_array(entry** entries, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (entries[i] != NULL) {
            free(entries[i]->key);
            free(entries[i]);
        }
    }

    free(entries); // Free the array of pointers to 'entry' structs
