#include <time.h>

typedef struct {
    long offset;
    int key;
    struct record* next;
} record;

typedef struct {
    int value;
    long* arr;
} metadata;

record* createRecords(int numRecords, int growthFactor) {
    record* head = NULL;
    int i;
    for (i = 0; i < numRecords; i++) {
        record* newRecord = (record*)malloc(sizeof(record));
        if (!newRecord) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        newRecord->offset = rand() % 10000;
        newRecord->key = rand() % 1000;
        // initialize the next pointer
        newRecord->next = (i < numRecords - 1) ? &head[i] : NULL;
        if (i > 0) {
            record* prev = &head[i-1];
            prev->next = newRecord;
        } else {
            head = newRecord;
        }
    }
    return head;
}

metadata* createMetadata(int numElements, int growthFactor) {
    metadata* md = NULL;
    int i;
    for (i = 0; i < numElements; i++) {
        metadata* newMetadata = (metadata*)malloc(sizeof(metadata));
        if (!newMetadata) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        newMetadata->value = rand() % 10000;
        long* newArr = (long*)malloc((growthFactor*(i+1))*sizeof(long));
        if (!newArr) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        int j;
        for (j = 0; j < growthFactor*(i+1); j++) {
            newArr[j] = i;
        }
        newMetadata->arr = newArr;
        // initialize the next pointer
        if (i > 0) {
            metadata* prev = &md[i-1];
            prev->next = newMetadata;
        } else {
            md = newMetadata;
        }
    }
    return md;
}
