using System;
using System.Xml.Linq;
using System.Threading.Tasks;

public class XmlProcessor
{
    public XElement ProcessXmlFeed(string xmlFeed, string attributeName = null)
    {
        var doc = XDocument.Parse(xmlFeed);
        var rootElement = doc.Root;

        if (rootElement == null) return null;

        var result = new List<XElement>();

        Parallel.ForEach(rootElement.Elements(), element =>
        {
            if (attributeName != null && !element.Attributes().Any(a => a.Name.LocalName == attributeName))
                return;

            var filteredElements = GetFilteredElements(element);

            foreach (var child in filteredElements)
            {
                result.Add(child);
            }
        });

        return result;
    }

    private IEnumerable<XElement> GetFilteredElements(XElement element)
    {
        if (element.HasAttributes && element.Attributes().Any())
        {
            var attributeValue = element.Attributes().Single(a => a.Name.LocalName == attributeName).Value;

            if (!string.IsNullOrEmpty(attributeValue))
            {
                return element.Elements();
            }
        }

        return Enumerable.Empty<XElement>();
    }
}
