        if (records[i] != NULL) {
            (**records[i]).access_count = access_counts[i];
        }
    }
}

int get_frequent_records(int*** keys, RecordMetadata** records, int threshold, int* order) {
    int frequent_record_index = -1;
    int max_access_count = 0;

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i] != NULL && (**records[i]).access_count > max_access_count) {
            max_access_count = (**records[i]).access_count;
            frequent_record_index = i;
        }
    }

    if (frequent_record_index != -1 && max_access_count >= threshold) {
        *order = 0;
        return frequent_record_index;
    } else {
        return -1;
    }
}

int query_frequent_records(int*** keys, RecordMetadata** records, int threshold, int sort_order) {
    int most_frequent_record_index = get_frequent_records(keys, records, threshold, &sort_order);

    if (most_frequent_record_index != -1) {
        printf("Most frequent record with key %d and offset %d accessed %d times.\n", **(*keys)[most_frequent_record_index], (**records[most_frequent_record_index]).record[0], max_access_count);
    } else {
        printf("No records meet the access threshold of %d.\n", threshold);
    }

    return 0;
}
