    SensorMetadata *sensor_metadata = (SensorMetadata *)malloc(num_sensors * sizeof(SensorMetadata));

    // Allocate memory for secondary array to track location frequency
    Summary *location_frequency = (Summary *)malloc(max_events * sizeof(Summary));

    // Initialize and populate data structures

