typedef struct {
    int UserID;
    char* SessionToken;
    time_t LastActivityTime;
    enum { ACTIVE, EXPIRED } SessionState;
} UserSession;

// Define the maximum number of active sessions and the timeout period in seconds
#define MAX_ACTIVE_SESSIONS 1000
#define TIMEOUT_PERIOD 300 // 5 minutes

// Function prototypes
void cleanupExpiredSessions();
void logSessionExpiration(UserSession* session);
int countActiveSessions();
UserSession* getUserSession(int userID);
int addSession(int userID, char* sessionToken);
void updateSession(int userID, enum { ACTIVE, EXPIRED } new_state);
void saveSessionsToFile(const char* filename);
UserSession* loadSessionsFromFile(const char* filename);

// Global variables
static UserSession** sessions;
static int num_sessions = 0;
static time_t last_cleanup_time;

// Function to manage a dynamic list of `UserSession` structures
void user_session_manager_init() {
    // Initialize the array of user session pointers
    sessions = (UserSession**)calloc(MAX_ACTIVE_SESSIONS, sizeof(UserSession*));
}

// Function to add a new user session
int addSession(int userID, char* sessionToken) {
    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->UserID = userID;
    new_session->SessionToken = sessionToken;
    new_session->LastActivityTime = time(NULL);
    new_session->SessionState = ACTIVE;

    // Add the new session to the array and update the count
    if (num_sessions >= MAX_ACTIVE_SESSIONS) {
        printf("Maximum number of active sessions reached.\n");
        return -1;
    }
    sessions[num_sessions] = new_session;
    num_sessions++;

    // Schedule cleanup operation after a short delay to allow for potential concurrent session updates
    struct timespec ts = {0, 1000000}; // 1 second
    nanosleep(&ts, NULL);
    cleanupExpiredSessions();

    return 0;
}

// Function to update an existing user session
void updateSession(int userID, enum { ACTIVE, EXPIRED } new_state) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]->UserID == userID) {
            sessions[i]->SessionState = new_state;
            if (new_state == EXPIRED) {
                // Schedule cleanup operation to run after a short delay
                struct timespec ts = {0, 1000000}; // 1 second
                nanosleep(&ts, NULL);
                cleanupExpiredSessions();
            }
        }
    }
}

// Function to count the number of active user sessions
int countActiveSessions() {
    int active_sessions = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]->SessionState == ACTIVE) {
            active_sessions++;
        }
    }
    return active_sessions;
}

// Function to clean up expired user sessions
void cleanupExpiredSessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_sessions; i++) {
        if ((current_time - sessions[i]->LastActivityTime) > TIMEOUT_PERIOD && sessions[i]->SessionState == ACTIVE) {
            updateSession(sessions[i]->UserID, EXPIRED);
        }
    }

    // Periodically log session expiration events to the external logging service
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]->SessionState == EXPIRED) {
            logSessionExpiration(sessions[i]);
        }
    }
}

// Function to log a user session expiration event
