#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int* key;
    long offset;
} record;

record* process_records(int num_records, int min_key, int max_key) {
    if (num_records <= 0) return NULL;

    // Allocate memory for the arrays
    int* keys = (int*)malloc((num_records + 1) * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));
    long* offsets = (long*)malloc((num_records + 1) * sizeof(long));

    if (!keys || !records || !offsets) {
        free(keys);
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize the keys array with unique random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key;
        do {
            key = rand() % ((max_key - min_key) + 1) + min_key;
        } while (key == 0); // Avoid zero keys
        if (keys[i] != 0) { // Check for duplicates
            for (int j = 0; j < i; j++) {
                if (key == keys[j]) {
                    i--; // Backtrack and try again
                    break;
                }
            }
        }
        keys[i] = key;
    }

    // Initialize the records array with correct pointers and offsets
    for (int i = 0; i < num_records; i++) {
        records[i].key = &keys[i];
        records[i].offset = offsets[i] = (long)i * sizeof(int);
    }

    return records;
}
