#include <string.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void process_input_and_generate_structures(int** input_array, int nfaapi_crc_indication_pdu_count) {
    int* max_element = NULL;
    NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_indication_pdu_array = NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < nfaapi_crc_indication_pdu_count; i++) {
        int random_crcflag = rand() % 2;
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i + 1;
        pdu.RNTI = (int) clock();
        pdu.CRC_INDICATION_REL8_TAG = random_crcflag;

        pthread_mutex_lock(&lock);
        if (!nfaapi_crc_indication_pdu_array) {
            nfaapi_crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1000);
            max_element = &nfaapi_crc_indication_pdu_array[0].RX_UE_INFORMATION_TAG;
        }

        if (*max_element < pdu.RX_UE_INFORMATION_TAG) {
            *max_element = pdu.RX_UE_INFORMATION_TAG;
        }
        pthread_mutex_unlock(&lock);
    }

    // Handle concurrent access
    for (int i = 0; i < nfaapi_crc_indication_pdu_count; i++) {
        pthread_mutex_lock(&lock);
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
               nfaapi_crc_indication_pdu_array[i].RX_UE_INFORMATION_TAG,
               nfaapi_crc_indication_pdu_array[i].RNTI,
               nfaapi_crc_indication_pdu_array[i].CRC_INDICATION_REL8_TAG);
        pthread_mutex_unlock(&lock);
    }

    // Free allocated resources
    free(nfaapi_crc_indication_pdu_array);

    // Handle errors and logging
    if (nfaapi_crc_indication_pdu_count <= 0) {
        fprintf(stderr, "Error: Input array size is invalid.\n");
        return;
    }
}
