#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_DATA 1000
#define HASH_TABLE_SIZE 1024
#define SLEEP_TIME 1 // milliseconds

typedef struct {
    int i;
    float f;
    char c;
    union {
        double d;
        int j;
    } u;
} data_t;

data_t *data[MAX_DATA];
int hash_table[HASH_TABLE_SIZE];

void init_data(int id) {
    data[id]->i = rand() % 1001;
    data[id]->f = (float)rand() / RAND_MAX;
    data[id]->c = (char)(32 + rand() % 95);
    data[id]->u.d = (double)rand() / RAND_MAX;
}

void hash_data(data_t *d, int id) {
    hash_table[(id * 31 + d->i) % HASH_TABLE_SIZE] = (int)d;
}

void free_data(int id) {
    if (data[id]) {
        free(data[id]);
        data[id] = NULL;
    }
}

void clean_up() {
    for (int i = 0; i < MAX_DATA; i++) {
        free_data(i);
    }
}

int main() {
    srand(time(NULL));

    // Initialize and allocate memory
    for (int i = 0; i < MAX_DATA; i++) {
        data[i] = (data_t*)malloc(sizeof(data_t));
        init_data(i);
        hash_data(data[i], i);
    }

    // Test concurrency handling and scalability
    int num_threads = 4;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, &thread_func, NULL);
    }

    // Clean up resources when done
    clean_up();

    return 0;
}

void* thread_func(void* arg) {
    // Concurrency handling and scalability testing code
    for (int i = 0; i < MAX_DATA; i++) {
        data_t *d = hash_table[i];
        if (d) {
            printf("Thread %d: accessed data at address %p\n", pthread_self(), d);
            usleep(SLEEP_TIME * 1000); // simulate work
        }
    }
}
